-- English texts of the regional pack kalimdor_darnassus (content wave W01). The rules are in AzerothUnspoken_Kalimdor/Darnassus.lua.
local AU = AzerothUnspoken

AU:RegisterRegionalTexts("teldrassil", "enUS", "kalimdor_darnassus", [==[
	["dar.journey.arrival.01"] = {
		"steps out of the portal's glow at the edge of Darnassus, the hippogryph flight below already feeling like another day.",
		"comes through the shimmer of the portal from Rut'theran, blinking, and finds the city spread out under the leaves.",
		"arrives at the top of the tree in a wash of pink light, legs still swaying from the flight, and takes in the pale towers.",
	},
	["dar.journey.arrival.02"] = {
		"A hippogryph to the roots, a portal to the crown. From the sea to the top of a tree in one breath, and the city waiting as if there had never been any doubt.",
		"Down below there were waves and salt. Up here there are lanterns and leaves, and the flight already feels like a dream told by someone else.",
		"The flight ended at the foot of the tree, but the journey only ends here, among the white terraces. The climb was the shortest part.",
	},
	["dar.journey.arrival.03"] = {
		"A flight, a portal, and I still have to walk to the bank.",
		"Hippogryph, then a glowing doorway, then a long stroll under the leaves. Darnassus makes you earn it.",
		"Made it. My stomach is somewhere between Rut'theran and here; it'll catch up.",
	},
	["dar.journey.arrival.04"] = {
		"Off the hippogryph, through the portal, and under our own branches. Even the air smells of home.",
		"The hippogryph at the roots, the portal to the top. Home is the quiet that comes after the wings, and the leaves overhead.",
	},
	["dar.journey.arrival.05"] = {
		"stands still a moment after the long way up, letting the hush of Darnassus and its running water replace the rush of the flight.",
		"lingers by the portal while the beat of wings fades from {g:his|her} ears and the murmur of water takes its place.",
	},
	["dar.journey.arrival.06"] = {
		"A flight, a portal and a city in a treetop. I keep waiting for someone to tell me it's a joke played on visitors.",
		"Every capital I know has a gate. This one has a hippogryph, a glowing ring and a great many leaves.",
	},
	["dar.muse.calm.01"] = {
		"Water runs everywhere in this city, slow and clear, and the lamps shine back from it. Darnassus is quiet the way a held breath is quiet.",
		"Pale stone, still pools, lanterns glowing violet among the willows. Nobody hurries here; perhaps nobody ever learned how.",
		"The city drinks the light from the leaves above and gives it back softer. I find myself slowing down without deciding to.",
	},
	["dar.muse.distance.01"] = {
		"Bank's just over there, they said. That was a while ago.",
		"Beautiful city. Enormous city. Did I mention enormous?",
		"I've walked from one end of Darnassus to the other. My boots would like a word with the architect.",
	},
	["dar.muse.druids.01"] = {
		"The druids of the Cenarion Enclave talk about this tree the way healers talk about a patient: fondly, carefully, and never in front of it.",
		"A druid passed me with leaves in her hair and soil on her hands, deep in an argument with someone I couldn't see. Possibly the tree.",
	},
	["dar.muse.guest.01"] = {
		"The kaldorei are allies, and strangers too. In their city I mind my manners and keep stopping to stare at everything.",
		"Not a single shout in the whole market. Where I come from, that would mean something terrible had happened.",
	},
	["dar.muse.home.01"] = {
		"A young city on a young tree. We are learning to live in it the way we are learning to grow old: slowly, and with some surprise.",
		"So much of what we were went with the old forests. But the lamps are lit in Darnassus, and they are ours.",
		"I hear our tongue spoken on every terrace, unhurried, and something in my chest that has been braced for years lets go a little.",
	},
	["dar.muse.owls.01"] = {
		"looks up at an owl perched on a carved arch; it looks back down, entirely unimpressed.",
		"hears a soft hoot from the branches above the city and stops to find the owl, which seems to have been watching for some time.",
	},
	["dar.muse.sentinels.01"] = {
		"steps aside for a Sentinel riding a great striped cat along the terrace, its paws making no sound on the stone.",
		"watches two Sentinels pass on their rounds, glaives at their backs, speaking in the low voices of people who have kept many watches.",
	},
	["dar.muse.temple.01"] = {
		"From the Temple of the Moon comes a silence that is not empty. The priestesses of Elune move through it as if it were a garment.",
		"Elune's priestesses walk softly, and near the temple even strangers lower their voices. I find I want to.",
	},
	["dar.muse.trade.01"] = {
		"Even the haggling here is soft-spoken. I lowered my voice to name a price and still felt rude.",
		"Merchants who don't call out to passers-by. Out of pure habit, I keep checking that my coin purse is still there.",
	},
	["dar.npc.banker.01"] = {
		"Everything I own, please. It's lighter than it looks, and the coin is lighter still.",
		"I'd like to leave my coin somewhere it won't have to walk across this city again.",
	},
	["dar.npc.innkeeper.01"] = {
		"is welcomed by the innkeeper with a soft word and a gesture toward a quiet corner.",
		"nods to the innkeeper, who answers with a smile that asks for nothing and promises a warm bed.",
	},
	["dar.npc.trainer.01"] = {
		"A kaldorei trainer. Centuries of practice behind every small correction, and not a word wasted, like an old tree that grows without hurry.",
		"The trainer watches me the way an old tree might watch a sapling: patiently, and from very far above.",
	},
	["dar.quest.01"] = {
		"Done, and thanked in a voice so soft I almost missed it. In Darnassus that counts as a celebration.",
		"Another task closed. The kaldorei have long memories; I suspect this one will be remembered too.",
		"Finished. The city goes on as calm as ever, and maybe I helped keep it that way.",
	},
	["dar.quest.02"] = {
		"receives the reward with both hands, just as it was offered.",
		"inclines {g:his|her} head to the one who set the task, and receives the same small gesture in answer.",
		"sets the proof of the work down on the pale stone of the terrace, then steps back into the quiet.",
	},
	["dar.quest.03"] = {
		"Done. Now, if anyone knows a shortcut to anywhere in this city, I'm listening.",
		"There. And I only had to cross the city three times to do it.",
	},
	["dar.rest.01"] = {
		"lets {g:his|her} shoulders drop at last, with the sound of running water somewhere close by.",
		"sets the pack down, sits on a bench of pale wood and, for a while, does nothing at all.",
	},
	["dar.rest.inn.01"] = {
		"A low room, soft lamps, the smell of herbs. Even the inn in Darnassus speaks in a whisper.",
		"Somewhere to sit at last, and not one loud voice in the room. I could sleep for a week.",
		"Indoors, out of the green light. The bed looks as if it was grown rather than made.",
	},
	["dar.ret.01"] = {
		"The same pools, the same violet lamps, the same unhurried voices. Darnassus has not moved an inch since last time; if anything changed, it was me.",
		"I remember these terraces. The city remembers nothing of me, and somehow that is restful.",
	},
	["dar.sub.enclave.01"] = {
		"The Cenarion Enclave. The buildings here look grown more than built, roots and all, and the druids speak to each other in pauses.",
		"Roots climb the walls of the Enclave as if the place were still deciding what shape to be.",
	},
	["dar.sub.temple.01"] = {
		"passes beneath the arches of the Temple of the Moon, where a pale light rests on the still water of the well.",
		"enters the Temple of the Moon; the noise of the city stops at the threshold, leaving soft footsteps and water that holds the moon.",
	},
	["dar.sub.trade.01"] = {
		"Tradesmen's Terrace. Stalls under the willows, coins changing hands without a sound.",
		"Goods, coin, a fair price named in a low voice. Here on the Tradesmen's Terrace, Darnassus comes closest to bustle.",
	},
	["dar.sub.warrior.01"] = {
		"Warrior's Terrace. Even the sparring here is graceful. Hardly fair on the blades.",
		"Ah, the clatter of practice blades. So somebody in this city does make noise.",
	},
	["dar.wc.rain.01"] = {
		"watches the rain dimple the city's pools, each ring spreading until it meets another.",
		"turns {g:his|her} face up as rain filters down through the great leaves, soft and slow, onto the pale stone.",
		"listens to the rain whispering on the streams of the city; Darnassus barely seems to notice it.",
	},
	["dar.greet.w02.01"] = {
		"Peace to you, under the leaves.",
		"Greetings. Quiet roads and clear water to you.",
	},
	["dar.muse.w02.01"] = {
		"Leaves overhead as big as sails. The sky is up there beyond them, but down here the sky is green.",
		"I've never seen leaves this size. When the wind moves through the crown, the whole city fills with a sound like a far-off tide.",
	},
	["dar.muse.w02.02"] = {
		"I wished a Sentinel good day. She considered it carefully, and I believe she's considering it still.",
		"Everyone here walks as if there's all the time in the world. Some of them have already seen ten thousand years of it.",
	},
	["dar.muse.w02.03"] = {
		"stops on a curved bridge of pale wood and watches lantern light tremble on the water below.",
		"follows the path along the lake's edge, where willows trail their branches in water so clear it seems not to be there.",
		"pauses at the water's edge, where the reflection of the white towers lies so still it looks as if one could walk on it.",
	},
	["dar.muse.w02.04"] = {
		"The kaldorei raised this city in a few short years, after losing so much in the war. It is lovely, and it is very new, and they know it.",
		"Behind the calm of these terraces there's a whole people that had to begin again. You can see it in how carefully everything is tended.",
	},
	["dar.quest_complete.w02.01"] = {
		"Done. The thanks came with a long look, as if someone were choosing to remember me.",
		"Finished. In a city with a memory this long, even a small favor may be remembered longer than I'd guess.",
	},
	["dar.quest_complete.w02.02"] = {
		"All done. I'll tell the owls; they seem to keep the records here.",
		"Finished. Should I whisper it? Everything else in this city is whispered.",
	},
	["dar.weather_change.w02.01"] = {
		"looks up as the clouds thin over the crown of the tree, and a paler light slips down through the leaves onto the terraces.",
		"notices the green light of the city brighten by a shade as the sky clears, somewhere far above the leaves.",
	},
	["dar.dawn.w05.001"] = {
		"watches the dawn find its way down through the leaves, one pale shaft at a time, until the lake holds a little of every one.",
		"sees the lanterns grow pale against the coming dawn, while the Sentinels of the last watch hand over to fresh ones.",
		"hears the birds of the crown start up before any light reaches the terraces; up here the dawn begins as a sound.",
	},
	["dar.dusk.w05.001"] = {
		"Dusk in Darnassus. The lanterns were never really out, and now they simply win.",
		"The light under the leaves turns from green to violet at dusk, and the city seems to settle more comfortably into itself.",
		"Dusk. For the kaldorei this is when the day properly begins; I can feel the city waking just as I start to tire.",
	},
	["dar.farewell.w05.001"] = {
		"Go gently. The paths here will keep your footsteps for you.",
		"Safe roads down the tree, and further.",
		"Walk softly, and come back up the tree when the road allows.",
	},
	["dar.farewell.w05.002"] = {
		"Farewell. Take the portal, not the shortcut; there is no shortcut.",
		"Off you go. If you find a quicker way across this city, write to me.",
	},
	["dar.farewell.w05.003"] = {
		"Take care out there. It's a long way down, and a longer way back.",
		"Until the next time. I'll be somewhere near the water, most likely.",
	},
	["dar.greet.w05.001"] = {
		"Well met! Lost, or just admiring the view? Both are allowed here.",
		"Hello there. Did you take the long way across the city too?",
		"Greetings! Isn't it strange, talking out loud in a place this quiet?",
	},
	["dar.greet.w05.002"] = {
		"May your path here be gentle, and your rest long.",
		"Be welcome under these branches.",
		"Well met, in the city of the moon.",
	},
	["dar.jest.w05.001"] = {
		"How do you know you've been in Darnassus too long? You start calling a hundred years 'a little while'.",
		"In this city, 'I'll be right with you' means sometime next season. Bring a book.",
		"A druid, a priestess and a Sentinel walk into the inn. An hour later, someone finally says hello.",
	},
	["dar.journey.w05.001"] = {
		"blinks the portal's glare out of {g:his|her} eyes and finds a Sentinel at the edge of the path, already looking this way.",
		"steps clear of the portal and meets the steady gaze of a Sentinel posted nearby, one who has plainly watched a great many arrivals.",
	},
	["dar.journey.w05.002"] = {
		"My ears are still ringing from the portal. One step at the roots, the next at the crown; my body hasn't agreed to any of it.",
		"Down there, a trunk like a cliff. Up here, not a trunk in sight, only paths and water. My legs haven't caught up with a climb they never made.",
		"The portal took the climb off my hands and gave me a headache in exchange. A fair trade, I suppose.",
	},
	["dar.journey.w05.003"] = {
		"There's still salt in my cloak from the crossing, and up here it smells wrong among the moss and the flowers. Give it an hour.",
		"I brought the sea up with me: salt on my sleeves, wind in my hair. Darnassus will rinse it all off soon enough.",
	},
	["dar.journey.w05.004"] = {
		"Somebody tell the portal I wasn't finished being dizzy from the hippogryph.",
		"Wings, then magic, to get here, and both of them left me queasy. Lovely city, though.",
		"First feathers, then sparkles. Next time I'd settle for a dull old staircase.",
	},
	["dar.journey.w05.005"] = {
		"picks a stray hippogryph feather off {g:his|her} shoulder, turns it once in the portal light, and lets the breeze take it.",
		"finds a long feather from the flight caught in a strap, and tucks it away rather than drop it on such clean stone.",
	},
	["dar.journey.w05.006"] = {
		"From Rut'theran the tree is a wall of bark without end. From the crown you can't see it at all. Maybe that's how the kaldorei live with it.",
		"All that height under my boots, and nothing to show for it but a path and a pool. The tree hides itself best from the ones who live in it.",
		"Beneath this path, somewhere, the trunk goes down and down to the sea. I try not to think about it, and fail.",
	},
	["dar.journey.w05.007"] = {
		"A long flight, and every feather of it is in my back. A city made for walking is a cruel thing to arrive in.",
		"A good while in the saddle over water and forest. Then the portal, and now Darnassus asking me to cross it on legs that think they're still flying.",
	},
	["dar.journey.w05.008"] = {
		"comes out of the portal into the night air of Darnassus, cool and still, and waits for {g:his|her} eyes to learn the dark.",
		"arrives at night, the portal's glow fading behind, and the city ahead is all soft violet light and the hush of people asleep or on watch.",
		"arrives in the dark between two lanterns, and for a moment the only thing clearly visible is the portal's ring dimming behind.",
	},
	["dar.journey.w05.009"] = {
		"Dawn, just past the portal. The first light comes down through the leaves in long threads, and the city is only beginning to stir.",
		"I arrive with the dawn. Up here the morning comes slowly, filtered through a roof of leaves, as if asking permission.",
	},
	["dar.journey.w05.010"] = {
		"comes through the portal wet from the flight, and finds that under the great leaves the rain arrives only as slow, heavy drops.",
		"shakes the rain of the crossing off {g:his|her} cloak; here beneath the canopy it falls more gently, a drop at a time on the pale stone.",
	},
	["dar.journey.w05.011"] = {
		"Back where my hearth is. The portal hums behind me, and the paths ahead know my feet, even if they'd never admit it.",
		"Home ground, or the nearest thing I have to it. The road can keep its dust; I'm going to sit by the water and do nothing at all.",
	},
	["dar.journey.w05.012"] = {
		"Nobody at the roots asked my business. Up here nobody asks either, but I feel the question in every unhurried glance.",
		"A guest in the kaldorei's own tree. They were courteous at the portal; I'm going to be twice as courteous back.",
	},
	["dar.journey.w05.013"] = {
		"Darnassus! Right. Bank, then trainer, then a bench by the lake. In that order, if my feet allow.",
		"Made it to the top of the world. Well, the top of a tree. Close enough.",
	},
	["dar.journey.w05.014"] = {
		"steps off the portal's path at once to make room for whoever comes through next, and only then looks around.",
		"moves aside from the portal out of plain courtesy, as someone else shimmers into being right where {g:he|she} stood a moment ago.",
	},
	["dar.journey.w05.015"] = {
		"Gulls and creaking docks at the roots; up here, a hush so deep I can hear my own boots. The portal swaps one world for another.",
		"Below, the shouts of the boat crews and the slap of waves. Here, birdsong and water. It took one step to trade them.",
		"One step, and the smell of tar and fish is gone, replaced by moss and still water.",
	},
	["dar.journey.w05.016"] = {
		"Whatever news I carry from the mainland can wait the length of one walk across this city. The kaldorei won't mind; nobody waits better.",
		"I bring the mainland's hurry with me, and Darnassus quietly refuses to take it. Fine. I'll hurry later.",
	},
	["dar.journey.w05.017"] = {
		"glances back at the portal once, as if to be sure it will still be there for the way down.",
		"looks over {g:his|her} shoulder at the shimmering ring, measuring it the way one measures a door before trusting it a second time.",
	},
	["dar.journey.w05.018"] = {
		"Across the water, Darkshore's gray coast and its ruins. Up here, everything is tended, swept and lit. It's hard not to feel the distance between the two.",
		"The mainland I flew over is full of broken elven stone. Here the stone is new and whole, and the people walk on it as if trying not to wake an old grief.",
		"Behind me and below, a coast full of what the kaldorei lost. Ahead, what they've built since. The portal stands right between the two.",
	},
	["dar.journey.w05.019"] = {
		"Everyone through? Count heads; the portal doesn't.",
		"Is that all of us? Good. Nobody wander off; this city is bigger than it looks.",
	},
	["dar.journey.w05.020"] = {
		"A people who measure their lives in centuries, and they put a portal at the foot of their tree to save a climb. Even the patient have limits.",
		"Ten thousand years of patience, and still they built themselves a shortcut to the top. I like them better for it.",
		"They've watched empires rise and drown, and they still didn't fancy climbing a tree every day. Sensible people.",
	},
	["dar.journey.w05.021"] = {
		"inclines {g:his|her} head toward the city on coming through the portal, a small courtesy to a place that seems to expect one.",
		"pauses at the threshold of Darnassus and bows slightly, without quite knowing to whom.",
	},
	["dar.journey.w05.022"] = {
		"Moss, damp bark, a sweetness I can't put a name to. One breath of this and the air of the road feels borrowed.",
		"The first breath on this side of the portal is green. That's the only word I have for it.",
	},
	["dar.journey.w05.023"] = {
		"Right. Which way is anything? Every path here curves politely away from where I want to go.",
		"Lovely. Now, which of these winding paths leads somewhere I actually need to be?",
	},
	["dar.memory_return.w05.001"] = {
		"Darnassus once more, and my feet find the paths before my head does. Something of this place stayed with me.",
		"The same hush, the same water underfoot. I'd forgotten how quickly this city slows me down, and here it is, doing it again.",
	},
	["dar.memory_return.w05.002"] = {
		"walks back into Darnassus a little more carefully than before, as if the calm of the place were something that could break.",
		"returns to the city with a guarded step, though nothing on these quiet terraces seems to remember how the last visit ended.",
		"comes back among the pale terraces and lets the stillness settle over whatever went wrong the time before.",
	},
	["dar.muse.w05.001"] = {
		"Every so often I forget that the ground here is a branch, and that under all this moss and stone the sea is a very long way down.",
		"Grass, paths, a lake with islands in it. It takes an effort to remember that all of this sits in the crown of a tree.",
		"Darnassus has lawns. On a tree. I have stopped trying to make that make sense.",
	},
	["dar.muse.w05.002"] = {
		"Now and then the air brings up a breath of salt from the sea around the roots. It reminds me that this whole city is an island on an island.",
		"A smell of salt, faint and out of place among the leaves. The sea is down there still, all around Teldrassil, waiting at the bottom of the tree.",
		"When the air turns just so, I catch the sea on it, salt and cold, risen all the way up the trunk to find me.",
	},
	["dar.muse.w05.003"] = {
		"No mage hangs a sign anywhere in Darnassus. The kaldorei remember what the arcane cost them once, and they have had ten thousand years to think about it.",
		"Ask in Darnassus where to study the arcane and you get a long, polite silence. Whatever befell this people in the old days, magic was at the heart of it, and they have not forgotten.",
		"Bows, blades, herbs, the rites of the temple: Darnassus will teach any of them. Spellbooks you'll have to find elsewhere, and nobody here will be sorry.",
	},
	["dar.muse.w05.004"] = {
		"The druids still speak of Malfurion Stormrage as if he had only stepped out of the room. He dreams somewhere far away, and Fandral Staghelm keeps his chair warm.",
		"Their greatest druid is asleep in the Dream, they say, and has been for a long while. In the Enclave they lower their voices at his name, the way you do near someone sleeping.",
		"Fandral Staghelm leads the druids now, in the long absence of their master. People say his name with respect; Malfurion's they say with longing.",
	},
	["dar.muse.w05.005"] = {
		"For ages the druids slept and the Sentinels kept the forests alone. You can see it in how the guards here stand: like people who never expected anyone else to do it.",
		"The women in armor at every corner have been keeping watch since before most kingdoms had names. They do not look tired of it. They look used to it.",
		"Sentinels never seem to rest, only to change places. I have yet to see one sit down.",
	},
	["dar.muse.w05.006"] = {
		"watches a dark cat pad up the steps of the Enclave and, at the top, rise up into an elf brushing off her sleeves.",
		"steps aside for a large cat in a hurry, then turns in time to see it shake itself into a druid halfway across the path.",
		"sees a bear amble out of the Cenarion Enclave, sit down heavily on the grass, and become an elderly druid rubbing his knees.",
	},
	["dar.muse.w05.007"] = {
		"sees a sleek gray shape slip through the lake, surface by the bank and climb out on two legs, wringing water from a long braid.",
		"watches something like a seal break the surface of the lake, look around, and turn into a druid who walks off dripping as if nothing had happened.",
	},
	["dar.muse.w05.008"] = {
		"A druid just tried the bank door as a bear. The door won.",
		"Rule of the Enclave, I'd guess: no bears indoors. Somebody had to learn it the hard way.",
	},
	["dar.muse.w05.009"] = {
		"From the Warrior's Terrace comes the dry knock of arrows into straw targets, one after another, hardly a breath between them. Nobody up there seems to miss.",
		"The archers on the terrace loose, walk, pull their arrows, walk back, and loose again. They have done it so long the motion looks like breathing.",
		"Thock, thock, thock: arrows into a target somewhere above the path. Patient practice, the only kind that lasts.",
	},
	["dar.muse.w05.010"] = {
		"There's a hunter's bear asleep across the path, and the whole city is politely walking around it.",
		"Half the pets in this city are bigger than their owners. And better groomed.",
		"A cat the size of a pony just sniffed me over and decided I wasn't food. I'll take that as a welcome.",
	},
	["dar.muse.w05.011"] = {
		"At the auction house here, people bid as if they had a century to wait for the price to come down. Some of them do.",
		"A kaldorei buyer at the auction house looked at the same cloak for a long time, nodded, and walked away. I suspect she'll be back next season.",
		"Prices at the auction house here move the way the tree grows: slowly, and in a direction nobody can argue with.",
	},
	["dar.muse.w05.012"] = {
		"My savings are kept inside a tree. I'm told that's the safest place in Kalimdor.",
		"Coin in a vault, vault in a tree, tree in the sea. Nobody's robbing this bank in a hurry.",
		"If the bank ever loses my things, I'll have to take it up with a tree.",
	},
	["dar.muse.w05.013"] = {
		"I dropped a pan. Every elf on the terrace turned around. I may have to leave the city.",
		"Sneezed on the bridge. A Sentinel looked at me as if I'd blown a war horn.",
		"Laughed out loud on the terrace. An owl left.",
	},
	["dar.muse.w05.014"] = {
		"The kaldorei: the newest members of the Alliance and by far the oldest people in it.",
		"Stormwind signs treaties. Darnassus remembers the world before there was anything to sign.",
	},
	["dar.muse.w05.015"] = {
		"While the city drowses by its pools, Sentinels in Ashenvale are watching orc axes bite into the old trees. The peace here is paid for somewhere else.",
		"Nobody in Darnassus mentions Ashenvale over dinner, but every Sentinel I see could be on her way there. The war with the Warsong is never far from their faces.",
		"Wounded Sentinels come up the tree to heal and go down again too soon. Ashenvale keeps calling them, one by one.",
	},
	["dar.muse.w05.016"] = {
		"The druids say Teldrassil grew fast, very fast. Some of them say it the way you'd praise a child; a few say it the way you'd mention a fever.",
		"Ask a druid how old Teldrassil is and you get a proud answer. Ask how it grew so quickly and you get a pause, and then a different subject.",
	},
	["dar.muse.w05.017"] = {
		"In a city this quiet my own thoughts sound loud. I didn't know I'd been carrying so many of them.",
		"There is no noise here to hide behind. Every worry I dragged up the tree is sitting right next to me on the bench.",
		"Darnassus does not drown anything out. Whatever I came in with, I'll have to listen to.",
	},
	["dar.muse.w05.018"] = {
		"walks the long curve of the terrace and notices that {g:his|her} footsteps make no echo at all, as if the living wood were swallowing them.",
		"listens to {g:his|her} own steps on the path and hears almost nothing; the city takes every sound in and gives none back.",
	},
	["dar.muse.w05.019"] = {
		"I haven't seen a straight line since the portal. Roofs curl, paths bend, even the railings look as if they grew that way out of habit.",
		"Everything here curves: the arches, the stairs, the eaves like folded leaves. A dwarf with a builder's square would weep.",
		"Corners are rare in Darnassus. I've started to miss them, and I never thought a corner was something a person could miss.",
	},
	["dar.muse.w05.020"] = {
		"A dwarf just asked me where the loud tavern is. I didn't have the heart to tell him.",
		"Saw a dwarf order ale here. They brought him something pale and fragrant. His face was a whole saga.",
		"A dwarf on the bridge is explaining to a druid what this tree would fetch as lumber. The druid has stopped blinking.",
	},
	["dar.muse.w05.021"] = {
		"A gnome was demonstrating some clicking gadget on the Tradesmen's Terrace. The kaldorei watched it the way you'd watch a wasp on your sleeve.",
		"Gears and steam are not much loved in Darnassus. A gnome's toy whistled on the terrace and three people stepped back from it at once, very politely.",
	},
	["dar.muse.w05.022"] = {
		"Tyrande Whisperwind leads this people from a temple, and not because she is gentle. She went to war ten thousand years ago and came back with her bow in her hand.",
		"The High Priestess is no quiet figure lost in prayer. Every soldier in Darnassus seems to stand a little taller within sight of her temple.",
	},
	["dar.muse.w05.023"] = {
		"The water of the moonwell doesn't look like water. It looks like something a priestess could pour light from, and I suppose that's the point.",
		"Priestesses kneel at the moonwell as if listening to it. I can't hear what it says, but I stop talking all the same.",
	},
	["dar.muse.w05.024"] = {
		"stands still where a gap in the leaves lets the moonlight down, and watches the city turn silver around {g:him|her}.",
		"looks up through the crown of the tree at a sliver of moon, small and very far, and the kaldorei on the path below look up too.",
	},
	["dar.muse.w05.025"] = {
		"Dawn, and the kaldorei are winding down the way everyone else winds down at the end of the day. I seem to be up at the wrong end of their day.",
		"First light through the leaves, and half the city yawning on its way home. For a people who keep the dark hours, morning is the end of the shift.",
	},
	["dar.muse.w05.026"] = {
		"As the light goes, Darnassus comes awake. Voices that were drowsy all afternoon sharpen, and the Sentinels change watch with something like relief.",
		"Dusk, and the city stretches. This is the hour the kaldorei seem to have been waiting for all day.",
	},
	["dar.muse.w05.027"] = {
		"Midday, and the terraces are half asleep. Even the merchants have the heavy-lidded look of cats in a warm window.",
		"Broad day, and the kaldorei treat it the way other folk treat the small hours: a few errands, a lot of sitting very still.",
		"The sun is high, and the kaldorei walk through it like a draft they're too polite to mention.",
	},
	["dar.muse.w05.028"] = {
		"The rain takes its time getting down here. It falls on the crown, runs leaf to leaf for a long while, and lands on my shoulders in big, slow, deliberate drops.",
		"Up in the crown it must be pouring. Down here the rain comes through one fat drop after another, as if the tree were rationing it.",
		"Rain somewhere far above, and the whole city under a slow patter, like fingers drumming on a table while their owner thinks of something else.",
	},
	["dar.muse.w05.029"] = {
		"watches the mist lie on the lake so thick that the far shore seems to float on nothing, its pale arches the only solid thing in sight.",
		"follows a path into the fog that has settled among the terraces, and hears voices a few steps away without seeing who speaks.",
	},
	["dar.muse.w05.030"] = {
		"Kaldorei, they call themselves: children of the stars. Watching them walk, unhurried and a little apart from everything, I can believe it.",
		"A people named for the stars, living in a tree. It explains the way they look up whenever they stop.",
		"Children of the stars, the name means. Looking at the faint glow in their eyes, I'm almost ready to take it literally.",
	},
	["dar.muse.w05.031"] = {
		"Hyjal burned, the old forests went, and still we planted something. Every time I walk under these branches I feel a little proud and a little afraid, both at once.",
		"We could have wandered forever after the war. Instead we raised a tree out of the sea and taught it to hold a city. Stubborn people, mine.",
		"Under these leaves I don't have to explain myself to anyone. That is a deeper rest than any bed.",
	},
	["dar.muse.w05.032"] = {
		"Darnassus. Whatever else the world does, this much of it is ours.",
		"No matter how far the road goes, this tree keeps a place for me.",
	},
	["dar.muse.w05.033"] = {
		"The kaldorei look at me kindly and a little sadly, the way you'd look at a mayfly. Next to them, I suppose I am one.",
		"Somebody here was already old before my people had written anything down. It's hard to feel important in Darnassus, and oddly pleasant.",
		"Everyone here has time. I'm the only one walking as if the day might run out.",
	},
	["dar.muse.w05.034"] = {
		"Druids come and go here with the look of people who have just been somewhere very green and very far. Moonglade, someone said, though nobody said how.",
		"A druid stepped out from behind a tree smelling of wet earth from under a different sky. They have roads of their own, the druids, and they don't lend out the maps.",
	},
	["dar.muse.w05.035"] = {
		"pauses by the Craftsmen's Terrace to watch a tailor hold a length of cloth up to the light, turn it once, and set it aside without a word.",
		"lingers near a workbench where an elf is stitching leather with stitches so small they seem to vanish into the hide.",
		"watches an alchemist on the Craftsmen's Terrace crush a leaf between two fingers, smell it, and nod as if it had told her something.",
	},
	["dar.muse.w05.036"] = {
		"Good herbs growing in the corners of the paths, and nobody picking them. In any other city they'd be gone within the hour.",
		"My fingers twitch at every flowerbed. Picking anything here would feel like stealing from a temple.",
	},
	["dar.muse.w05.037"] = {
		"Does this tree ever lose its leaves? I can't picture an autumn up here. Darnassus seems to live in one long green afternoon that never changes.",
		"No falling leaves, no bare branches, no sign of the year turning. I wonder whether the kaldorei miss the seasons, or whether ten thousand years of them were enough.",
		"Teldrassil keeps one season, and a gentle one. I'm not sure I'd trust a place that never sheds anything.",
	},
	["dar.muse.w05.038"] = {
		"passes an old priestess sitting on the grass with her eyes closed, and when {g:he|she} passes again much later she has not moved at all.",
		"notices an elf on a bench who seems to have been looking at the same branch for a very long time, with the calm of someone who has decided there's no hurry, ever.",
	},
	["dar.muse.w05.039"] = {
		"Stand still long enough and you feel it: a slow creak deep in the wood, the whole city easing a little, like a ship riding at anchor.",
		"Now and then the bark under my boots gives a long low groan, too deep to be anything but the tree itself shifting its weight.",
		"The tree is alive under all of this. Sometimes, in the stillness, I think I can feel it thinking.",
	},
	["dar.muse.w05.040"] = {
		"Ishnu-alah. I think. If I just insulted someone's tree, I apologize.",
		"Every time I try the local greeting, the elf answers in Common. Kindly. Which is worse.",
	},
	["dar.muse.w05.041"] = {
		"One step into that pink shimmer and I'd be at the roots, among salt and boats and hippogryphs. It feels like a door that shouldn't be allowed to be that easy.",
		"The portal down to Rut'theran hums at the edge of the city. Darnassus keeps the sea exactly one step away and never mentions it.",
	},
	["dar.muse.w05.042"] = {
		"runs a hand along a wall and finds not stone but bark, worn smooth as a banister by many hands before {g:his|hers}.",
		"rests a palm against a pillar of living wood and feels, or imagines {g:he|she} feels, something slow moving inside it.",
	},
	["dar.muse.w05.043"] = {
		"Indoors here means inside the tree, more or less. The walls curve, the floor has a grain, and the whole room smells faintly of sap.",
		"Every room in Darnassus feels like the inside of a seed: smooth, rounded, and certain of what it means to become.",
	},
	["dar.muse.w05.044"] = {
		"Violet roofs, violet banners, violet robes. If I stand still long enough I'll turn violet too.",
		"I've counted eleven shades of purple since breakfast. The kaldorei have opinions about color.",
		"Darnassus has a color, and it isn't green. It's whatever purple dreams of being.",
	},
	["dar.muse.w05.045"] = {
		"Some of the elders here walked the old world before it broke, when the sea was not where it is now. They must look at every shoreline as a wound that closed badly.",
		"Ten thousand years ago this people watched their homeland sink into the sea. Then they planted a tree in that same sea. I don't know whether that is courage or grief, and perhaps they don't either.",
	},
	["dar.muse.w05.046"] = {
		"Of all the Alliance capitals, this is the one at the end of the longest road: a boat across the sea, a hippogryph, a portal, and then a walk. Allies at a distance, in every sense.",
		"A sea between Darnassus and Stormwind, and more than a sea between their ways. The Alliance holds together across a great deal of water.",
	},
	["dar.muse.w05.047"] = {
		"Peaceful up here. Good. Trouble waits at the foot of the tree, and I know where to find it.",
		"Rest while the city lets you. Darkshore won't be this kind.",
	},
	["dar.muse.w05.048"] = {
		"Too pretty, all of it. A place this calm makes me check behind the willows for the catch.",
		"Everything here is graceful, ageless and serene. I'd trade some of it for a loud tavern and a bench with a wobble.",
		"Serene. Graceful. Endless. I'd give a silver piece for one honest pothole.",
	},
	["dar.muse.w05.049"] = {
		"Kaldorei voices carry a faint ring, as if each word were spoken in a larger room than the one it's in.",
		"Even a merchant naming a price sounds, to my ears, like someone speaking from the bottom of a well of moonlight.",
	},
	["dar.muse.w05.050"] = {
		"makes way for a young priestess hurrying toward the temple with an armful of clean bandages, the only person in Darnassus who seems to be in a rush.",
		"watches a priestess kneel beside a limping Sentinel on the path, lay a hand on the wound, and send her on her way without a word.",
		"steps off the path for a pair of priestesses carrying a stretcher toward the temple, their faces calm and their pace anything but.",
	},
	["dar.muse.w05.051"] = {
		"Druids leave the Enclave for Silithus with grave faces. Something under the sand down there has the Cenarion Circle worried, and they are not a people who worry loudly.",
		"Every so often a druid here mentions the Scarab Wall, and the conversation goes quiet. Whatever sleeps behind it, they remember it better than they'd like.",
	},
	["dar.muse.w05.052"] = {
		"A gardener on the terrace is pressing a seedling into the earth with great care. It will still be growing when everyone I know is dust, and she seems content with that.",
		"The kaldorei plant things they will not see grown. Here that isn't sad. It's simply how you build.",
	},
	["dar.muse.w05.053"] = {
		"A dwarf, a gnome and a human queuing at a kaldorei bank, all whispering out of respect. The Alliance at its most polite.",
		"Visitors of every Alliance race walk these paths on tiptoe, as if afraid to wake the tree. It's the most united I've ever seen them.",
		"Kaldorei, humans, dwarves, gnomes, all bent over the same map by the bank. Whatever else the Alliance is, it's a great many people asking each other for directions.",
	},
	["dar.muse.w05.054"] = {
		"catches a pair of pale eyes shining under the willows in the dark, and a moment later a Sentinel steps onto the path, nods, and is gone.",
		"notices that half the faces on the terrace at night have eyes that glow faintly, like coals banked for the morning.",
	},
	["dar.muse.w05.055"] = {
		"The food here is beautiful. Small, fragrant, arranged like a garden. I could eat four plates and still go looking for bread.",
		"Fruit, fish, something green with a flower on top. Kaldorei cooking feeds the eyes first and the stomach some time later.",
		"A kaldorei meal: a leaf, three berries and the finest view in Kalimdor. I'll want a second meal.",
	},
	["dar.muse.w05.056"] = {
		"A city this calm is a good place to say a few names under your breath.",
		"Quiet enough here to hear the names I don't say aloud anywhere else.",
	},
	["dar.muse.w05.057"] = {
		"tries to walk as softly as the kaldorei around {g:him|her}, and succeeds only in sounding like a careful cart of pots.",
		"attempts the unhurried kaldorei stride for a few steps, then gives up and goes back to {g:his|her} own.",
	},
	["dar.muse.w05.058"] = {
		"Darnassus feels like a city that is listening. Not to me in particular. Just listening, all the time, to something under the quiet.",
		"There's an attention in this place, as if the trees and the water and the old faces were all waiting for a sound that hasn't come yet.",
		"Nothing here is loud, but nothing is asleep either. The whole city has the stillness of a deer that has heard something.",
	},
	["dar.muse.w05.059"] = {
		"Not a single person has shoved me all day. I could get used to Darnassus.",
		"No crowds, no shoving, no one selling me the same thing twice. This city spoils a traveler.",
	},
	["dar.muse.w05.060"] = {
		"Don't mistake the quiet here for softness. Every one of those calm faces has an arrow ready, and knows exactly where to put it.",
		"Gentle city, hard people. The kaldorei threw back the Burning Legion when the world was young; speaking softly doesn't make them weak.",
		"Soft voices, sharp arrows. That's Darnassus in four words.",
	},
	["dar.muse.w05.061"] = {
		"overhears a druid and a Sentinel arguing in fierce whispers by the path, both of them smiling politely at everyone who passes.",
		"watches two kaldorei have what is clearly a furious row without once raising their voices, then part with a perfectly courteous bow.",
	},
	["dar.muse.w05.062"] = {
		"At night the priestesses seem easier, more themselves, as if the moon above the leaves were an old friend looking in at the window.",
		"The kaldorei say Elune watches at night. Under these branches, with the city hushed and silvered, I could almost believe she's paying attention.",
	},
	["dar.muse.w05.063"] = {
		"kneels to tighten a strap and finds the step under {g:his|her} knee carved with a pattern of leaves so fine it must have taken a lifetime.",
		"stops to look closely at a railing and sees that every inch of it has been shaped into vines, patient work that no one passing seems to notice.",
		"runs a thumb over a carved archway and finds owls, moons and leaves hidden in the grain, so finely made they vanish if {g:he|she} steps back.",
	},
	["dar.npc_meet.w05.001"] = {
		"A Sentinel, glaive at the back, standing so still I took her for a statue until the eyes moved.",
		"A Sentinel on watch, still as the trunk of a tree. I wonder how many centuries of watches are folded into that stillness.",
		"The Sentinel doesn't stop me, doesn't greet me, doesn't look away either. I've rarely been watched so politely.",
	},
	["dar.npc_meet.w05.002"] = {
		"Quiet watch to you. Not that this city seems to offer any other kind.",
		"Good watch, Sentinel. I'll try not to be the most interesting thing you see today.",
		"Don't mind me. I'm only lost in the most beautiful way possible.",
	},
	["dar.npc_meet.w05.003"] = {
		"slows down as a Sentinel turns to look, and receives a short nod that somehow says welcome, careful and move along all at once.",
		"meets a Sentinel's eyes for a moment and gets back a measured look, the kind given to every passer-by and then filed away.",
	},
	["dar.npc_meet.w05.004"] = {
		"The merchant looks up from a ledger kept in a flowing hand and waits, unhurried, as if this sale could take a decade and that would be fine.",
		"Goods laid out neatly on cloth, prices spoken softly, nobody pulling at my sleeve. I suspect I'll spend more here, not less.",
		"Even the goods are arranged like an offering. The prices, sadly, are arranged like prices.",
	},
	["dar.npc_meet.w05.005"] = {
		"Do you have anything that keeps the damp out? Everything in this city seems to sit right next to water.",
		"I'll take whatever the Sentinels buy. They look like they know what lasts.",
	},
	["dar.npc_meet.w05.006"] = {
		"The innkeeper has the calm of someone nothing has surprised in a few centuries, and I'm not about to be the first.",
		"An innkeeper who speaks softly and remembers everything. I'll be on my best behavior.",
		"An innkeeper whose welcome is a small nod and an open hand toward the room. I think I've just been offered everything.",
	},
	["dar.npc_meet.w05.007"] = {
		"watches the deposit being written into a ledger in slow, beautiful letters, as though the coins deserved calligraphy.",
		"waits at the counter while long, careful fingers count the coins, and nobody looks up until the sum is right.",
		"glances around the hushed bank while the coins are counted, half expecting to be asked to breathe more quietly.",
	},
	["dar.npc_meet.w05.008"] = {
		"I'm ready to learn. Slowly, if that's how it's done here.",
		"Teach me something. I promise to take less than a century over it.",
		"I've come to learn. Correct me as often as you like; I'm told you have the time.",
	},
	["dar.npc_meet.w05.009"] = {
		"Someone here has a task and has clearly been waiting, patiently, for the right pair of hands. Mine will have to do.",
		"Work on offer. The request will come politely, carefully, and it will be harder than it sounds.",
		"Someone waves me over with a slow, deliberate gesture. Whatever this is, it's been thought about for a long time.",
	},
	["dar.npc_meet.w05.010"] = {
		"listens to the request without interrupting, matching the speaker's slow pace, and only nods once the last word has settled.",
		"stands patiently through a long, careful account of what is needed, and finds no word in it wasted.",
	},
	["dar.npc_meet.w05.011"] = {
		"One of the city's folk stops to let me pass, with a small bow. I bow back, a little too low.",
		"A resident of the city answers my question with great care, then adds a second answer to a question I hadn't asked yet.",
	},
	["dar.npcd_flightmaster_open.w05.001"] = {
		"The hippogryphs are restless today. Speak gently near them, and they will carry you anywhere on this coast.",
		"Wings for the mainland? Mind the beak, and hold on when they bank over the water.",
	},
	["dar.npcd_guard_bye.w05.001"] = {
		"Go in peace. The paths will bring you back, if you let them.",
		"Walk well. And do not linger at the portal's edge; it is no place to stand about.",
	},
	["dar.npcd_guard_directions.w05.001"] = {
		"The bank and the auction house? The Tradesmen's Terrace, by the lake. Follow the merchants' awnings.",
		"Warriors train on the Warrior's Terrace, among the Sentinels. Druids keep to the Cenarion Enclave; priests, to the Temple of the Moon.",
		"Leatherworkers, tailors, alchemists: the Craftsmen's Terrace. Ask anyone there; they will answer slowly, but well.",
	},
	["dar.npcd_guard_open.w05.001"] = {
		"Darnassus welcomes you. Walk softly, and leave your blade where it rests.",
		"Peace, traveler. The Sentinels keep the watch here; you need only keep the quiet.",
	},
	["dar.npcd_guard_open.w05.002"] = {
		"The mainland is far from here. Ask if you need the way; we would rather guide you now than search for you later.",
		"Elune's light on you. Mind the water's edge; the lake is deeper than it looks.",
	},
	["dar.npcd_innkeeper_bye.w05.001"] = {
		"Go well. The bed will keep your shape a while, and the door stays open.",
		"Safe paths. Come back when the road has worn you thin again.",
	},
	["dar.npcd_innkeeper_news.w05.001"] = {
		"A boat from Auberdine came in heavy with travelers. Half of them still haven't found the bank.",
		"The druids of the Enclave have been arguing for days. About what, they won't say, but they've stopped coming in for supper.",
	},
	["dar.npcd_innkeeper_open.w05.001"] = {
		"Come in, and leave the road at the door. The beds are soft, and the room is quiet.",
		"Welcome. Sit where you like; nobody here will hurry you.",
	},
	["dar.npcd_innkeeper_open.w05.002"] = {
		"You look as if the tree was a long climb. Rest; there's water, bread and a blanket for you.",
		"Ah, a traveler. There's moonberry juice on the table and a bed waiting, if your legs will still carry you.",
	},
	["dar.npcd_merchant_bye.w05.001"] = {
		"Go well, and may what you bought outlast the road.",
		"Farewell. If it breaks, bring it back; if it doesn't, tell your friends.",
	},
	["dar.npcd_merchant_news.w05.001"] = {
		"Leather from Ashenvale is scarce. The orcs at the lumber camps make the hunting hard.",
		"The boat to the mainland is full every crossing. Everyone wants to come to Darnassus, and then everyone wants to leave it.",
	},
	["dar.npcd_merchant_open.w05.001"] = {
		"Look as long as you like. Good things should be chosen slowly.",
		"Everything you see here was made in Darnassus, by hands with a great deal of practice.",
	},
	["dar.npcd_merchant_open.w05.002"] = {
		"A customer from far away, by the look of those boots. What does the road need from me?",
		"Take your time. I have kept this stall longer than some kingdoms have stood.",
	},
	["dar.npcd_merchant_wares.w05.001"] = {
		"Bows of good wood, arrows fletched with owl feathers, and cloaks that keep off the damp of the coast.",
		"Herbs from the glades of Teldrassil, dried slowly. Good for the road, better for a fever.",
	},
	["dar.npcd_trainer_open.w05.001"] = {
		"You came to learn. Good. Patience first, then the rest.",
		"Hold still a moment and let me look at you. Hm. There is more in you than you think, and less than you hope.",
	},
	["dar.pray.w05.001"] = {
		"Elune, whose light this city keeps: watch over the Sentinels on the shore, and over everyone still out on the roads.",
		"Elune, keep the peace of this tree, and lend a little of it to me.",
		"Whatever light watches over Teldrassil: keep its roots sound and its people safe.",
	},
	["dar.quest_complete.w05.001"] = {
		"is thanked first in the kaldorei's own tongue, then again in Common, slowly, so that nothing is lost.",
		"hears the thanks spoken in the old language of the night elves, and does not need the words to understand them.",
	},
	["dar.quest_complete.w05.002"] = {
		"To someone whose life is counted in centuries, my errand lasted a breath. To me it was the whole day. We both seem satisfied.",
		"My day's legwork, their passing moment. Odd how gratitude bridges that gap anyway.",
	},
	["dar.quest_complete.w05.003"] = {
		"Done. Take your time with the reward; I hear patience is a local specialty.",
		"All finished. No rush on the payment. I gather nobody here has rushed in a few thousand years.",
		"There. Pay me whenever. This century, ideally.",
	},
	["dar.quest_complete.w05.004"] = {
		"The kaldorei gave up their immortality at Hyjal and lost a great deal besides. Helping them keep what's left doesn't feel like small work.",
		"A people who traded forever for a single victory. Whatever I just did for them, I'm glad it was done well.",
	},
	["dar.quest_complete.w05.005"] = {
		"takes the reward while a Sentinel's nightsaber, lying nearby, yawns enormously, which seems to settle the matter.",
		"accepts the payment under the lazy gaze of a great striped cat stretched out on the terrace, the only witness who looks unimpressed.",
	},
	["dar.quest_complete.w05.006"] = {
		"Small work, and my road has only just begun. Even here, among people with centuries behind them, everyone once started with small work.",
		"A modest task for a modest purse. Everyone in this city started somewhere; some of them just started a very long time ago.",
		"Not much of a deed. Then again, the World Tree was a seed once.",
	},
	["dar.quest_complete.w05.007"] = {
		"Work of this weight comes with silence around it. The one who set it asked only whether it was done, not what it cost.",
		"Nobody asked how it went. Past a certain point the answer is written on you, and here they know how to read it.",
	},
	["dar.quest_complete.w05.008"] = {
		"Handed in by lantern light, with half the city asleep. I counted the coins without letting them clink.",
		"A task closed in the middle of the night. Even the reward seemed to change hands softly, so as not to wake anyone.",
	},
	["dar.quest_complete.w05.009"] = {
		"completes the business as the first light comes down through the leaves, and steps away into a city only just waking.",
		"receives the reward at dawn, when the terraces are still empty and the water holds the pale color of the sky.",
	},
	["dar.quest_complete.w05.010"] = {
		"takes the reward under the dripping leaves, and tucks it away fast before the rain finds a way into the pouch.",
		"concludes the task beneath an archway while the rain patters on the pools of the city.",
		"steps under the nearest leaf big enough to serve as a roof to hear the thanks, while the rain drums softly overhead.",
	},
	["dar.quest_complete.w05.011"] = {
		"The coin they pay with here is ordinary coin. I don't know why I expected something silver and leaf-shaped.",
		"Plain coin, the same as anywhere. Somehow I'd half expected to be paid in moonlight.",
		"They pay in good copper and silver, like anyone else. Oddly, that's the most surprising thing I've seen in this city.",
	},
	["dar.quest_complete.w05.012"] = {
		"Thanks here come after a pause, as if the words were taken down from a long shelf and dusted first.",
		"There was a silence before the thanks, long enough to worry me. Then I understood: it was care, not doubt.",
		"Every word of thanks in this city seems weighed before it's spoken. It makes the ones that come heavier, in the good way.",
	},
	["dar.quest_complete.w05.013"] = {
		"It is done. May it serve your people well.",
		"Finished, and gladly. May your city keep its quiet.",
		"The work is yours now. Use it well.",
	},
	["dar.quest_complete.w05.014"] = {
		"I never learn where the work goes once it leaves my hands. Here I like to think it settles somewhere, like a leaf finding the ground.",
		"Whatever I brought will be put away somewhere, slowly and with care. That's how everything in this city seems to find its place.",
	},
	["dar.quest_complete.w05.015"] = {
		"Here. All of it, in one piece. Mostly in one piece.",
		"Everything you asked for. Count it; I'd hate to disappoint anyone who remembers things for a thousand years.",
		"There you are, everything you wanted. Nothing fell in the lake, I promise.",
	},
	["dar.quest_complete.w05.016"] = {
		"Not on the first try, but it's done. Nobody here so much as raised an eyebrow at the delay. Time weighs differently on them.",
		"It took me more than one attempt. In this city, that seems to count as perfectly prompt.",
	},
	["dar.quest_complete.w05.017"] = {
		"Well done, all of you. Let's split it under a tree; there's no shortage here.",
		"That was good work, together. Sit, rest, share it out. The city isn't going anywhere.",
	},
	["dar.quest_complete.w05.018"] = {
		"sits for a moment on the low wall by the water once the matter is settled, and lets the quiet of the city take the edge off the day.",
		"walks down to the edge of the lake after the reward is given, and skims a flat pebble across it before moving on.",
	},
	["dar.quest_complete.w05.019"] = {
		"One more thread between the Alliance's farthest city and the rest of us. Thin, but threads add up.",
		"Darnassus sits at the far edge of the Alliance, up a tree, across the sea. Every task done here pulls it a little closer.",
		"Every errand finished here is a stitch between this tree and the kingdoms across the sea. I've added mine.",
	},
	["dar.quest_complete.w05.020"] = {
		"lets the thanks settle, then turns away down the curving path, the purse a welcome weight at the belt.",
		"nods once at the words of thanks and moves off along the water, feeling the day's walking at last now that it's over.",
		"rolls {g:his|her} shoulders once the work is handed over, and sets off along the shore path without looking back.",
	},
	["dar.quest_complete.w05.021"] = {
		"Reward in hand. Now: food, a whetstone, and whatever the Tradesmen's Terrace will give me for the rest of what's in my pack.",
		"Paid. The Tradesmen's Terrace is about to have a visit from me, with lighter bags and a heavier purse.",
	},
	["dar.quest_complete.w05.022"] = {
		"Done! If anyone has another task, I'm feeling unusually light on my feet. It's the air up here.",
		"Finished, and I'm not even tired. Must be the water in this city.",
		"That's done! Who knew a city this calm could put such a spring in my step?",
	},
	["dar.quest_complete.w05.023"] = {
		"counts the coins of the reward once, then a second time, because in a city this quiet there is nothing to hurry the counting.",
		"counts the reward out on the edge of a stone basin, where the coins lie bright against the pale rock.",
	},
	["dar.quest_complete.w05.024"] = {
		"In the city of the moon, even a plain errand feels as if it was done under someone's gaze. I kept my back straighter the whole way.",
		"Elune's temple is only a short walk away. Strange, how that made me want to do even this small task properly.",
	},
	["dar.quest_complete.w05.025"] = {
		"No speeches, no crowd, no fuss. A nod, the payment, and the matter closed. I could get used to this.",
		"Not one speech about how grateful everyone is. Just the reward and a quiet nod. My kind of city.",
	},
	["dar.reputation_change.w05.001"] = {
		"Someone has decided to think better of me. Here, that kind of decision is made slowly, and kept for a very long time.",
		"My name sits a little higher in a memory that counts in centuries. I'll try to deserve the length of it.",
	},
	["dar.rest_enter.w05.001"] = {
		"Inside, the walls curve like the inside of a seed pod, and the light is low and violet. Sleep is going to come easily.",
		"A room shaped from living wood, a blanket that smells of herbs. Whatever the road did to me today, it stops at this door.",
		"The bed is low, the room is warm, and the only sound is water moving somewhere past the window. I won't last long.",
	},
	["dar.rest_enter.w05.002"] = {
		"settles on the grass at the water's edge, back against a smooth root, and lets the city's quiet do the rest.",
		"stretches out beneath one of the city's great trees, boots off, listening to the leaves high above brush against each other.",
		"unbuckles the heaviest straps and lies back on the moss beside a pool, one arm over the eyes.",
	},
	["dar.rest_enter.w05.003"] = {
		"Night over Darnassus. The city hardly changes; it only grows quieter, and I grow quieter with it.",
		"The night is soft here, lit low, never truly dark. A good night to put the pack down and not pick it up again until morning.",
	},
	["dar.rest_enter.w05.004"] = {
		"That's it, I'm done walking. Wake me if the tree moves.",
		"Somewhere soft, please. My legs have filed a complaint against the whole city.",
		"Rest at last. If anyone needs me, I'll be the lump under a very large leaf.",
	},
	["dar.rest_enter.w05.005"] = {
		"Water nearby, a breath of wind in the leaves, and nobody needing anything from me. I could stay exactly like this.",
		"For once nothing is pulling at me. The city breathes slowly, and I find my breathing falling in with it.",
		"The water keeps talking to itself, and I've stopped interrupting it. That's rest, I think.",
	},
	["dar.rest_enter.w05.006"] = {
		"sits with back to the wall and the way in clearly in view, even here, and only slowly lets the hand drift from the weapon's grip.",
		"rests, but keeps glancing toward the path, as if the road had followed through the portal.",
	},
	["dar.subzone_enter.w05.001"] = {
		"Craftsmen's Terrace. Hides stretched on frames, herbs hung up to dry, and someone's anvil doing its best to be polite.",
		"The Craftsmen's Terrace: tanners, tailors, alchemists, each at work without raising a voice. Even the hammering here sounds considered.",
	},
	["dar.subzone_enter.w05.002"] = {
		"walks onto the Craftsmen's Terrace, past racks of drying leather and the faint green smell of an alchemist's work.",
		"crosses into the Craftsmen's Terrace, where every workbench is tidy and everyone at work seems to have all the time there is.",
	},
	["dar.subzone_enter.w05.003"] = {
		"steps onto the Warrior's Terrace, where the trainers of more than one fighting trade keep their corners and a sharp eye on the path.",
		"comes up onto the Warrior's Terrace and passes beneath the eyes of the Sentinels, whose watch here seems sharper than anywhere else in the city.",
	},
	["dar.subzone_enter.w05.004"] = {
		"Tradesmen's Terrace. The bank, the auction house, and sooner or later every purse in the city.",
		"Ah, the Tradesmen's Terrace. If Darnassus ever raises its voice, it'll be here, over a price.",
		"The Tradesmen's Terrace, where the auctioneers call out bids barely louder than a conversation.",
	},
	["dar.subzone_enter.w05.005"] = {
		"enters the Cenarion Enclave, where a bear lumbers past on the path and, a few steps later, rises as a druid and walks on.",
		"comes into the Cenarion Enclave and steps aside for a druid in the shape of a bear, who nods in thanks, oddly gracefully.",
		"passes a druid kneeling among the roots that wind through the Enclave, one palm flat against the bark, eyes closed, listening.",
	},
	["dar.subzone_enter.w05.006"] = {
		"Fandral Staghelm keeps his seat somewhere above this Enclave. The druids below speak of him carefully, the way you speak of a river after the thaw.",
		"The Arch Druid's Enclave. Everyone here seems to be listening for something: the tree, the wind, or the voice of Fandral Staghelm from above.",
	},
	["dar.subzone_enter.w05.007"] = {
		"The Temple of the Moon. The priestesses glide past the great fountain as if their feet had never learned to hurry.",
		"Inside the temple the light is silver and the voices are few. The statue at its heart looks down with a patience older than this tree.",
		"Tyrande Whisperwind is somewhere in this temple. Even the air seems to stand at attention.",
	},
	["dar.subzone_enter.w05.008"] = {
		"wanders into the Temple Gardens, where the paths turn back on themselves among flowers and still water, as if no one here ever needed to arrive anywhere.",
		"slows down in the Temple Gardens, among tended hedges and slow fountains, where even the birds seem to sing at half voice.",
	},
	["dar.subzone_enter.w05.009"] = {
		"Another terrace, another curved bridge, another place I'd happily sit down in for an hour.",
		"Every corner of this city seems to have been planned around a view. This one is no exception.",
	},
	["dar.subzone_enter.w05.010"] = {
		"The quarters here don't begin or end; they flow into each other along the water. I only notice I've changed districts when the sounds change.",
		"No walls between the quarters of Darnassus, only a bridge, a turn in the path, a different smell on the air. Leather, then incense, then nothing but leaves.",
		"Between one quarter and the next, the sound of hammering gives way to running water. That's the only border Darnassus seems to need.",
	},
	["dar.subzone_enter.w05.011"] = {
		"crosses a curved bridge into another part of the city and pauses at its crest, where the whole lake opens out below.",
		"follows the path around the water into a new quarter, glancing up at the great boughs that roof this side of the city.",
	},
	["dar.thanks.w05.001"] = {
		"Thank you. That was kind, and in this city kindness seems to come with good manners attached.",
		"Thanks. I'll pass it on to the next lost traveler I find on these paths.",
		"My thanks. You've saved me at least one more lap of the lake.",
	},
	["dar.thanks.w05.002"] = {
		"You have my thanks, made to last as long as I can manage.",
		"I'm grateful. I'll remember this, if not for ten thousand years.",
	},
	["dar.toast.w05.001"] = {
		"To the World Tree, and to its very patient tenants!",
		"Raise your cups: to quiet water and long lives.",
		"To Darnassus, where even a toast is made softly. Cheers, but no shouting!",
	},
	["dar.travel.w05.001"] = {
		"Green light, willows, still water, then the hearthstone's pull behind my ribs. Darnassus thins out like a dream at waking.",
		"One last look at the water and the willows, then the stone takes me. The city won't even ripple.",
	},
	["dar.travel.w05.002"] = {
		"glances at the long path back to the portal while the hearthstone warms, as if comparing the two roads.",
		"lets the hearthstone's glow gather in the hand beneath the leaves, and is gone before a passing Sentinel has finished turning to look.",
	},
	["dar.weather_change.w05.001"] = {
		"pulls up the hood as the rain begins, and watches the great leaves overhead tip their gathered water down in sudden silver strands.",
		"steps under an archway as the rain comes on, while the broad leaves above fill, bend and pour like tilted bowls.",
		"watches the rain stipple the lake, while the Sentinels on the bridges carry on as if it were nothing.",
	},
	["dar.weather_change.w05.002"] = {
		"Rain in Darnassus. Nobody runs for cover; the kaldorei just walk on, a little slower, as if it were a guest to be greeted.",
		"The rain has come, and the city doesn't seem to mind. A Sentinel walks past with water running off her armor and no change in her pace.",
	},
	["dar.weather_change.w05.003"] = {
		"The sky has cleared above the crown. Sunlight finds the gaps in the leaves and lays bright coins on the water.",
		"Sun again, somewhere above. Patches of it slip down through the canopy and wander slowly across the terraces.",
		"The clouds roll off, and the sun comes back in pieces, scattered through the leaves like something spilled.",
	},
	["dar.weather_change.w05.004"] = {
		"looks up as the clouds part, and through a gap in the leaves catches a handful of stars over the city.",
		"notices the night sky clearing between the high branches, the stars appearing one by one as if the Sentinels were lighting them.",
	},
	["dar.weather_change.w05.005"] = {
		"Fog has crept up the tree. The far terraces are gone, the lamps are just smudges of violet, and voices come from nowhere.",
		"Mist drifts across the lake and swallows the islands. Darnassus was quiet already; now it's quiet and half invisible.",
		"Fog over the city. I can hear the water but not see it, and every bridge seems to lead into a cloud.",
	},
	["dar.weather_change.w05.006"] = {
		"Thunder up in the crown! Hold on to something; the whole tree is listening.",
		"A storm over Teldrassil, and the boughs of the city creak like the timbers of a ship.",
	},
	["dar.muse.w23.ancient.001"] = {
		"Nobody in Darnassus says Azshara's name the way storytellers do. They say it flatly, like the name at the bottom of a debt that will never be paid.",
		"When a kaldorei says 'Azshara' there is no thrill in it, none of the shiver a tale would put there. Only the tone of someone reading out an old, unpaid account.",
	},
	["dar.muse.w23.ancient.002"] = {
		"Somewhere in this city walks someone who saw the Well of Eternity with open eyes. I keep looking at faces and wondering which one.",
		"Some of the elders on these paths stood on the shore of the Well of Eternity once. Not in a song: in person, with sand in their shoes.",
		"I passed a kaldorei feeding fish at the water's edge and thought: she might have seen the Well itself. She tossed another crumb and said nothing.",
	},
	["dar.muse.w23.ancient.003"] = {
		"stops near an elder who is describing the palaces of the Highborne to two younger elves, one hand tracing towers in the air that are no longer anywhere.",
		"lingers within earshot of an old kaldorei explaining how high the Highborne built, her hand rising and rising until her listeners look up too.",
	},
	["dar.muse.w23.ancient.004"] = {
		"A people who once had the most dazzling magic in the world now look at a conjured spark the way you'd look at a dog that bit you as a child.",
		"Show a kaldorei a trick of the arcane and watch the face go still. Not fear exactly. More like recognizing an old acquaintance who ruined everything.",
	},
	["dar.muse.w23.ancient.005"] = {
		"The Burning Legion first came into this world through a door the night elves' own queen held open. They don't hide that here. They simply don't add anything to it.",
		"It was their own court that called the Legion in, long before any orc had heard the word. The kaldorei tell it plainly and leave the shame lying where it fell.",
	},
	["dar.muse.w23.ancient.006"] = {
		"Imagine having a queen so bad your whole people still talks about her a hundred centuries later.",
		"Every kingdom has a ruler it would rather forget. Here they just can't, because some of them remember her face.",
	},
	["dar.muse.w23.ancient.007"] = {
		"The old elven stone I've seen elsewhere in Kalimdor is all sharp spires and pride. The stone here curves and bows. It looks like a lesson learned.",
		"Ruins across Kalimdor show what the kaldorei built when they were proud: needles of stone reaching for the sky. Darnassus is lower, softer, deliberately humble.",
	},
	["dar.muse.w23.ancient.008"] = {
		"The priestesses here keep a temple to a goddess who, they say, watched her people tear the world apart and did not leave them. They speak of that with a steadiness I envy.",
		"In the Temple of the Moon they talk of the old war without heat. Elune stayed, the priestesses say, even when her children gave her every reason not to.",
	},
	["dar.muse.w23.ancient.009"] = {
		"watches an elderly kaldorei stop at the edge of a pool and stare into it far longer than any reflection deserves, as if checking the water for something that once rose out of another one.",
		"notices an old elf who will not stand too close to the water's edge, and who looks into it from a careful distance, the way one looks at a sleeping animal.",
	},
	["dar.muse.w23.ancient.010"] = {
		"Ask a human about a war from three hundred years back and you get dates. Ask a kaldorei about one from a hundred centuries back and you get who was rude to whom at dinner.",
		"Human history is kings and dates. Kaldorei history, from what I overhear, is mostly who said what to whom, and how it was taken.",
	},
	["dar.muse.w23.ancient.011"] = {
		"Not every Highborne followed their queen into ruin, a druid told me. Some turned at the last hour. He said it carefully, like someone defending a relative.",
		"There were Highborne who broke with Azshara before the end, I'm told. The kaldorei mention it rarely and quickly, as if afraid the good part might be taken away from them.",
	},
	["dar.muse.w23.ancient.012"] = {
		"A crafter here mends a strap with a stitch that, she says, was old when Azshara was a girl. The stitch outlived the empire. Most small things do.",
		"The leatherworker at the next bench learned the knot she is tying before the world broke. Empires go down; a good knot just carries on.",
	},
	["dar.muse.w23.ancient.013"] = {
		"I asked an elf what the old war was like. She said 'loud' and went back to her tea.",
		"Asked a kaldorei about the War of the Ancients. Got one word, 'long', and a very polite silence.",
	},
	["dar.muse.w23.ancient.014"] = {
		"Before most of the peoples now walking this world even had names, the kaldorei stood alone against the Legion and did not break. It shows in how they stand still.",
		"They fought the Burning Legion when no one else on this world could have, and they won at a price nobody has finished paying. You can feel that weight under the courtesy.",
	},
	["dar.muse.w23.ancient.015"] = {
		"watches a kaldorei scholar unroll a brittle map on a ledge; half the coastline drawn on it ends in the open sea, and the scholar smooths that half with particular care.",
		"glances at an old map spread out beside the path, its coasts running out into water where no land is anymore, and at the elf weighing its corners down with small stones.",
	},
	["dar.muse.w23.ancient.016"] = {
		"The Highborne drank power from the Well until they could not stop. Watching the kaldorei refuse even small comforts of magic, I think they still remember how good it tasted.",
		"What frightens them about the arcane is not that it is weak. It's that it was wonderful, and they remember exactly how wonderful.",
	},
	["dar.muse.w23.ancient.017"] = {
		"Kaldorei elders sometimes stop mid-sentence and finish in an older form of their language, as if the thought had been born before the words changed.",
		"An old elf telling a story switched, halfway, to a way of speaking the young ones around him only half followed. Some things apparently can only be said in the language they happened in.",
	},
	["dar.muse.w23.ancient.018"] = {
		"Some of us were Highborne once, or the children of Highborne. We don't speak of it in the street, but you learn to recognize the hands: too fine, too still, waiting for a power that isn't there.",
		"There are old ones among us who served at court before the fall. They tend gardens now. The gardens are perfect, and they never smile at them.",
	},
	["dar.muse.w23.ancient.019"] = {
		"In most cities 'ancient history' means your grandfather's day. Here someone might correct your details.",
		"Careful what you say about the old war around here. There may be a witness listening.",
	},
	["dar.muse.w23.ancient.020"] = {
		"The kaldorei sometimes say 'before' with no other word, and every one of them knows exactly which before they mean.",
		"There's a way they say 'before' here that needs nothing after it. Before the Well, before the sea, before everything. Everyone understands.",
	},
	["dar.muse.w23.ancient.021"] = {
		"overhears two elders disagreeing gently over the color of a banner that last flew before the world broke, both completely certain and neither willing to raise a voice.",
		"listens as a pair of old kaldorei argue, with exquisite politeness, about which side of a vanished street a certain fountain stood on.",
	},
	["dar.muse.w23.ancient.022"] = {
		"Tyrande Whisperwind fought in the War of the Ancients, the priestesses say, and has led her people ever since. Whatever a kaldorei calls 'a long time', it starts there.",
		"The High Priestess was already a priestess when Azshara still ruled, the Sentinels say. Their orders come from someone who saw it all begin. It must make them very hard to frighten.",
	},
	["dar.muse.w23.ancient.023"] = {
		"The stones of the oldest kaldorei buildings, across in Darkshore and Ashenvale, are fitted without mortar. The new ones here are too. Some skills outlive the cities that needed them.",
		"Kaldorei masons still cut stone to fit without mortar, the old way, as if the old cities might want to recognize their grandchildren.",
	},
	["dar.muse.w23.ancient.024"] = {
		"Beat the Burning Legion once and never mention it. I'd have it carved over my door.",
		"If I'd thrown back the Burning Legion, I'd bring it up at every dinner. Here nobody does.",
	},
	["dar.muse.w23.bench.001"] = {
		"sits on a low stone ledge, pulls off one boot, and shakes out a pebble that has been along for three terraces.",
		"stops at the edge of a path to tug off a boot, tips out a tiny stone, and puts the boot back on with a look of betrayal at the stone.",
	},
	["dar.muse.w23.bench.002"] = {
		"sits down on a step and counts what's left in the purse into neat little piles on one knee, then does it over in case the piles were wrong.",
		"spreads the coin on {g:his|her} knee, sorts copper from silver, and sighs at how little sorting it takes.",
	},
	["dar.muse.w23.bench.003"] = {
		"Sitting still is apparently an art here. I sit, and within moments I'm fidgeting with a strap. The kaldorei on the next ledge hasn't moved since I came.",
		"I am trying to do nothing, the way the people here do it. My hands keep finding things to fix.",
	},
	["dar.muse.w23.bench.004"] = {
		"sits down on a broad root that curves up out of the path at just the height of a seat, and wonders if anyone planned that.",
		"settles onto a curl of living wood at the edge of the path; it fits so well {g:he|she} half expects it to adjust.",
	},
	["dar.muse.w23.bench.005"] = {
		"Sit long enough on a step here and the city starts to flow around you, the way water goes round a stone. Nobody minds. Nobody asks.",
		"I've been sitting so long the passers-by have stopped noticing me. I think I'm part of the terrace now.",
	},
	["dar.muse.w23.bench.006"] = {
		"Two minutes sitting down. Then the bank. Then the trainer. Then possibly two more minutes.",
		"Just resting my legs. They'll be back on duty shortly. They've been told.",
	},
	["dar.muse.w23.bench.007"] = {
		"sits with chin on fist and watches a merchant fold the same length of cloth three different ways before settling on the first.",
		"rests on a ledge and watches a stallholder rearrange a few jars, step back, and rearrange them once more, at great and peaceful length.",
	},
	["dar.muse.w23.bench.008"] = {
		"The kaldorei sit down as if they mean to stay a season. I sit down like someone who expects to be called away any moment.",
		"When an elf sits, the sitting is the whole point. When I sit, it's only a pause between two other things.",
	},
	["dar.muse.w23.bench.009"] = {
		"sits on the grass to mend a fraying strap, needle in hand, and keeps glancing up as if expecting to be told off for it.",
		"finds a quiet step to restitch a loose seam on the pack, working slowly while the city goes about its business all around.",
	},
	["dar.muse.w23.bench.010"] = {
		"sits down for a moment, closes {g:his|her} eyes for a moment longer, and wakes with a start to find that nothing at all has changed.",
		"dozes off sitting against a pillar and jerks awake, looking round guiltily, but the city hasn't so much as noticed.",
	},
	["dar.muse.w23.bench.011"] = {
		"My armor is being mended somewhere behind me, slowly and very well. I've nothing to do but wait and feel undressed.",
		"Waiting on repairs is the strangest errand: you hand over the thing that keeps you whole, then stand about trying to look casual.",
	},
	["dar.muse.w23.bench.012"] = {
		"Of all my errands in this city, sitting down is the only one I do well.",
		"I've a list of things to do on every terrace. Sitting is on none of them, and it's the only one I've finished.",
	},
	["dar.muse.w23.bench.013"] = {
		"sits on the low wall of a flowerbed and eats a plain roll from the pack, very carefully, so as not to drop crumbs on anything so tidy.",
		"eats a little from the pack on a step beside the path, brushing every crumb into a cupped palm.",
	},
	["dar.muse.w23.bench.014"] = {
		"Waiting in Darnassus is different. Nobody sighs, nobody shifts their weight, nobody checks anything. I'm the only clock on the terrace.",
		"I waited my turn at the counter for a while and noticed I was the only one in line who seemed to know that time was passing.",
	},
	["dar.muse.w23.bench.015"] = {
		"Nice spot. I'm keeping it. Anyone who wants it can wait. Patiently. Like a local.",
		"Don't mind me. I'm just sitting here waiting for my feet to start talking to me.",
	},
	["dar.muse.w23.bench.016"] = {
		"Sitting down here, the ache in my legs finally gets my full attention. It has a great deal to say.",
		"The moment I sit, every terrace I crossed comes back up to me through the soles of my feet.",
	},
	["dar.muse.w23.bench.017"] = {
		"sits off to one side and watches other visitors hurry from stall to bank to stall, recognizing every one of their mistakes.",
		"perches on a step and watches a dwarf ask three different people for the same directions, and feels an enormous fondness for him.",
	},
	["dar.muse.w23.bench.018"] = {
		"No rush. I'll just stand here and age gracefully. Well. Age.",
		"Take your time. I've got... well, considerably less of it than you, but go on.",
	},
	["dar.muse.w23.bench.019"] = {
		"lingers at the edge of Tradesmen's Terrace with nothing left to buy, watching other people's purses grow thin.",
		"waits at the side of the terrace while a long, careful sale unfolds at the nearest stall, and loses all interest in {g:his|her} own errand.",
	},
	["dar.muse.w23.bench.020"] = {
		"The Temple Gardens are the one place in the city where I stop pretending to have errands. I sit, and the list in my pocket can wait.",
		"Nobody in these gardens is going anywhere in particular, so for once neither am I.",
	},
	["dar.muse.w23.bench.021"] = {
		"waits under a broad arch for the rain to ease, and watches a kaldorei stroll past through it as if it were not there.",
		"sits out the rain beneath an overhang, pack on knees, counting the drops that make it through the leaves.",
	},
	["dar.muse.w23.bench.022"] = {
		"Sitting still is the hardest part of being in this city. Walking, I look like anyone with an errand. Sitting, I look like what I am: Horde, in an elven capital.",
		"I'd rest my legs, but resting means being looked at. So I keep walking, slowly, like anyone else with business at the bank.",
	},
	["dar.muse.w23.bench.023"] = {
		"An ally here, and made welcome at every counter. I still apologize at each one, for my boots, my bags and my voice.",
		"The kaldorei have been nothing but courteous at the bank and the stalls. I keep thanking them twice, as if courtesy could run out.",
	},
	["dar.muse.w23.bloom.001"] = {
		"A pale flower grows along the railings that never opens more than halfway. I asked an elf why. She said it was being modest, and I couldn't tell whether she was joking.",
		"One flower by the paths stays half closed whatever you do. A gardener told me it opens fully only for those who don't stare. I stopped staring. It didn't open.",
	},
	["dar.muse.w23.bloom.002"] = {
		"pauses by a bank of flowers humming with bees, and notes that the bees, unlike anything else in the city, are in a tremendous hurry.",
		"stops beside a flowerbed loud with bees, the busiest sound for some distance, and watches them work the blossoms as if the whole tree were about to close.",
		"follows the drone of bees to a bush so thick with blossom that the branches can't be seen, and the bees can't be counted.",
	},
	["dar.muse.w23.bloom.003"] = {
		"A sweet, heavy scent finds its way into every corner of the city, even the bank. I've stopped noticing it. I'll notice it on the road, when it's gone.",
		"Some flower, I can't tell which, has a scent that reaches everywhere: the bank, the stalls, the bridges. I've never found the plant. I'm beginning to think it's the whole tree.",
	},
	["dar.muse.w23.bloom.004"] = {
		"That flower is bigger than my head and smells better than my whole pack.",
		"I'd sniff that blossom, but it looks like it might sniff back.",
	},
	["dar.muse.w23.bloom.005"] = {
		"On the Craftsmen's Terrace the herbalists hang bunches of flowers upside down to dry, and the stalls smell like a meadow being slowly remembered.",
		"The drying racks of the herbalists over on the Craftsmen's Terrace are heavy with flowers hung head down. Walk past and the scent follows you halfway across the city.",
	},
	["dar.muse.w23.bloom.006"] = {
		"sees a single violet petal drift down onto the open book of a passing scribe, who goes on reading around it rather than brush it away.",
		"glances up at a Sentinel on her post just as a petal settles on her shoulder; she leaves it there, and it stays.",
	},
	["dar.muse.w23.bloom.007"] = {
		"Flowers grow out of the joints in the stonework, where any human city would have weeds. Maybe there's no difference. Maybe here they're just better spoken.",
		"Every crack in the pale stone has a flower in it. In Stormwind that would be a job for someone with a hoe. Here it seems to be the point.",
		"A flower is growing out of a crack in the steps of the bank, and everyone going in steps around it, clerks and customers alike.",
	},
	["dar.muse.w23.bloom.008"] = {
		"Some of these flowers came from Hyjal, the druids say: seed carried up out of the ashes and planted here. I don't know if it's true. I stop and look at them anyway.",
		"A druid once pointed out a bed of small white blossoms and said they grew on the slopes of Hyjal before the fire. I visit them sometimes. They don't know what they survived.",
	},
	["dar.muse.w23.bloom.009"] = {
		"Smell that? No, the other one. No, the purple one. ...They're all purple, aren't they.",
		"Which flower is that scent coming from? Never mind. I've just noticed they're every one of them violet.",
	},
	["dar.muse.w23.bloom.010"] = {
		"There are fruit trees along the water that nobody seems to harvest. The birds do it for them, noisily, and leave the stones on the bridges for everyone else to step on.",
		"Small fruit hangs over the paths in clusters, ripe and unpicked. Either the kaldorei aren't hungry, or they're waiting for it to be exactly right, which could take a while.",
	},
	["dar.muse.w23.bloom.011"] = {
		"kneels at the edge of a bed in the Temple Gardens where one bent flower has been staked up with a twig and a strip of cloth, tended like a patient.",
		"notices, here in the gardens, a single drooping stem tied gently to a splint of reed, and leaves it a wide berth, as one would a sickbed.",
	},
	["dar.muse.w23.bloom.012"] = {
		"I've brushed past so many flowerbeds that my boots are dusted gold with pollen. I'm leaving a faint trail wherever I go, like a very careless thief.",
		"My sleeves are yellow to the elbow from leaning on railings wound with blossoms. Anyone could follow me across the city by the pollen alone.",
	},
	["dar.muse.w23.bloom.013"] = {
		"The flowers near the lamps all lean toward them, every one, as if the lamps were all the sky they need.",
		"Plant a flower by a lamp in Darnassus and it turns its face to the glow and keeps it there. I've seen people do the same with a fire after a long road.",
		"A lamp by the path has a ring of flowers around its foot, every face turned up to it like children listening to a story.",
	},
	["dar.muse.w23.bloom.014"] = {
		"An herbalist was gathering leaves along the path, one from each plant and never two. It took a long while. It will take the plants no time at all to forgive.",
		"I watched a kaldorei herbalist work down a row of plants, taking a single leaf from each and thanking none of them aloud, though it looked very much like thanks.",
	},
	["dar.muse.w23.bloom.015"] = {
		"Here on the Craftsmen's Terrace some of the tailors keep pots of crushed petals for dye, and every hand at work is stained some shade of violet up to the wrist.",
		"The dye pots on this terrace smell like a garden left to steep. A tailor dipped a length of cloth and lifted it out the color of the lamps.",
	},
	["dar.muse.w23.bloom.016"] = {
		"bends to smell a blossom as big as a pair of cupped hands, and straightens up with a nose dusted yellow and an air of great dignity.",
		"leans in toward a huge pale flower, sneezes once, and walks on as if nothing at all had happened, while a passing Sentinel very nearly smiles.",
	},
	["dar.muse.w23.bloom.017"] = {
		"Every flower in this city is a first generation of sorts: seed that never knew any ground but a branch high above the sea. They seem to manage.",
		"The flowers here have only ever grown on a tree. No field, no hillside, no valley in their past. It doesn't show. They bloom as if they'd been told nothing.",
	},
	["dar.muse.w23.bloom.018"] = {
		"Lilies float in the still corners of the streams, closed tight. A Sentinel told me they open only when nobody is in a hurry nearby. That may explain why I've never seen one open.",
		"Some of the blossoms here close up when you lean over them and open again once you've gone. I've decided not to take it personally.",
		"A flower beside me was a bud when I sat down, and it's open now. In this city I could believe it was only waiting for me to look away.",
	},
	["dar.muse.w23.bloom.019"] = {
		"I've been sneezing since the last bridge. Some flower in this city is very pleased with itself.",
		"Every flowerbed in Darnassus has made me sneeze at least once. They're very thorough.",
	},
	["dar.muse.w23.bough.001"] = {
		"The great boughs don't just hold the city up; they divide it. One below, one above, and a whole terrace living in the space between, like a shelf in a cupboard.",
		"Darnassus sits on the tree the way books sit on shelves: a bough under each terrace, another bough over it, and the city filed neatly in between.",
		"Every part of this city has a ceiling of branch and a floor of branch. I've stopped thinking of them as levels. They're more like drawers.",
	},
	["dar.muse.w23.bough.002"] = {
		"follows the underside of a great bough with {g:his|her} eyes, from where it leaves the trunk to where it vanishes, and counts three different mosses along the way.",
		"studies the belly of a bough high overhead, pale and ridged like the underside of a whale, and notices small ferns rooted in its creases.",
	},
	["dar.muse.w23.bough.003"] = {
		"A bough that size has nests on it bigger than my last rented room. I assume the birds pay less.",
		"There are nests up on that bough the size of a farm cart. Somebody up there is living better than I am.",
		"Birds on Teldrassil build in proportion. One nest overhead could stable a pony.",
	},
	["dar.muse.w23.bough.004"] = {
		"A leatherworker told me her doorway was a finger's width narrower this year than last. She didn't seem annoyed. The bough was 'settling in', she said, as you'd say of a guest.",
		"One of the crafters swears her door has shifted since she moved in: the bough it hangs from has been leaning, a hair a season. She speaks of it fondly, like a cat that sleeps on the wrong chair.",
		"Doors here are not quite fixed things, I've learned. A crafter showed me where she had to shave the frame because the wood around it had grown. She seemed proud of the wood.",
	},
	["dar.muse.w23.bough.005"] = {
		"Nobody tell the bough how much they've piled on it. It seems happy not knowing.",
		"A whole city leaning on one branch, and the branch hasn't complained once. I could learn from that.",
		"Bank, inn, temple, all on a branch. Somebody trusted this wood a great deal.",
	},
	["dar.muse.w23.bough.006"] = {
		"watches a Sentinel walk out along a bough broad as a street to where it narrows, look at something far off, and walk back without hurry.",
		"notices a figure far out on a bough overhead, small as a thumbnail against the leaves, and realizes after a while that it is a Sentinel on her round.",
		"spots, high on a branch where no path seems to lead, a Sentinel sitting with her legs over the edge, as easy up there as on a garden wall.",
	},
	["dar.muse.w23.bough.007"] = {
		"parts a curtain of vine hanging from a bough above the path; behind {g:him|her}, a kaldorei does the same with the back of a hand, without looking up.",
		"ducks under a fringe of hanging vine and gets a leaf down the collar for {g:his|her} trouble.",
		"brushes aside a long trailing creeper and finds it has small pale flowers all along it, open on the side away from the path.",
	},
	["dar.muse.w23.bough.008"] = {
		"I've started steering by the boughs. The thick one runs toward the bank, the forked one points somewhere I haven't been. It's the only map this city offers.",
		"Every bough overhead runs out from the trunk like a spoke. Follow one far enough with your eyes and you know where the middle of the world is, up here at least.",
	},
	["dar.muse.w23.bough.009"] = {
		"Two boughs crossed over the path long ago and simply grew into one another. Nobody planned it, or somebody planned it very patiently.",
		"There's a place overhead where two boughs met and fused, the seam still showing like a mended sleeve. I look up at it each time I pass, the way you'd look at an old couple still holding hands.",
		"Branches that touch here don't rub; they join. I've seen three places now where two limbs became one, and none of them looks as if it minded.",
	},
	["dar.muse.w23.bough.010"] = {
		"Don't stare upward too long in this city. You find one bough, then another above it, and you're standing here till next season.",
		"Look up once, fine. Look up twice and you've lost an hour counting branches.",
		"Never look up in Darnassus if you've somewhere to be. There's always one more branch.",
	},
	["dar.muse.w23.bough.011"] = {
		"Every bough here could hide a bow. In Ashenvale I'd count that a threat. Here it's simply a reason to keep the hood low and the mouth shut.",
		"Down in Ashenvale the Warsong cut trees like this one for timber. Under a living bough this size, deep in their city, I keep that thought very quiet.",
	},
	["dar.muse.w23.bough.012"] = {
		"Lie on your back here and stare long enough, and the boughs above start to turn, slowly, like a ceiling after the third cup. It's me moving, of course. Almost certainly.",
		"I lay back on the grass and watched the boughs until they seemed to drift. Nothing up there was moving. Nothing I could prove.",
	},
	["dar.muse.w23.bough.013"] = {
		"That bough's got an owl, two squirrels and a Sentinel on it, and it isn't even one of the big ones.",
		"Every branch here could hold a house. Some of them do.",
	},
	["dar.muse.w23.bough.014"] = {
		"I picked a bough overhead and decided it was mine for the length of a rest. Nobody objected. I don't think anyone here ever objects to that sort of thing.",
		"Under that one bough there's a patch of floor I've started thinking of as my spot. The tree doesn't know. The tree, I hope, wouldn't mind.",
		"Everyone needs a favorite branch in Darnassus. Mine is crooked, low, and nothing special, which is exactly why nobody else has claimed it.",
	},
	["dar.muse.w23.bough.015"] = {
		"follows a bough that dips low enough to touch the roof of a hall, where it has simply grown into the roof and become part of it.",
		"notices that one of the halls has no clear line where its roof ends and the bough above it begins.",
		"traces the line of a roof up and finds it turning, without a seam, into the branch that holds it.",
	},
	["dar.muse.w23.bough.016"] = {
		"spots a bird hopping along a bough far overhead, so small against it that it looks like a crumb walking across a table.",
		"catches sight of a squirrel running the length of a great bough, and still running long after any squirrel elsewhere would have reached the end.",
		"tracks a squirrel along a branch overhead until it simply runs out of sight, still on the same branch.",
	},
	["dar.muse.w23.bough.017"] = {
		"Fine branch, this. Holds a city, doesn't sag. I've known bridges with less character.",
		"Somebody should thank this branch. Officially. With a plaque.",
		"If I ever build a house, I want it built by whoever convinced this branch to hold a city.",
	},
	["dar.muse.w23.courtesy.001"] = {
		"returns a kaldorei's small bow and makes it a little too deep; the elf, kindly, bows a fraction deeper, so that neither of them is left wrong.",
		"answers a passing nod with a bow that goes too low, and sees the elf adjust with the faintest dip of the head, meeting the guest halfway.",
		"bows back to a passing elf, then wonders whether that was a greeting or a farewell, and bows once more to cover both.",
	},
	["dar.muse.w23.courtesy.002"] = {
		"Nobody stares in Darnassus. They look, briefly and fully, and then they look away, which is somehow more thorough.",
		"The kaldorei never gawk. One clear look, the way you'd read a sign on a door, and they're done. I have been read, and filed.",
	},
	["dar.muse.w23.courtesy.003"] = {
		"A human merchant held out a hand to a kaldorei. She looked at it, then at him, and laid two fingers on his wrist for an instant. A handshake, translated.",
		"I watched an elf receive a dwarf's handshake the way one takes a strange gift: gently, briefly, and with visible thought about what to do next.",
	},
	["dar.muse.w23.courtesy.004"] = {
		"Forgive me. I'm told I walk like a whole troop of cavalry. I'll try to tread softer.",
		"Pardon the noise. My boots weren't made for a city this careful.",
		"Sorry. Was that me? It was me. I'll be quieter.",
	},
	["dar.muse.w23.courtesy.005"] = {
		"Every kaldorei refusal I've met comes wrapped as advice. 'Perhaps the Tradesmen's Terrace would serve you better.' It would. It always does.",
		"No one here says no to a visitor. They say 'perhaps elsewhere' with such warmth that I thank them before I notice I've been sent on my way.",
	},
	["dar.muse.w23.courtesy.006"] = {
		"is offered a cup of cool water by an elf at a doorway, for no reason that is given, and drinks it under a patient, approving gaze.",
		"accepts a shallow bowl of water from a kaldorei who asks nothing in return, and only after drinking understands that this was the whole point.",
	},
	["dar.muse.w23.courtesy.007"] = {
		"The kaldorei wait a moment after anyone finishes speaking, in case there's more. Visitors keep rushing to fill that pause, and the elves keep politely letting them.",
		"There's a little silence left after every sentence here, held open like a door for whatever else you meant to say. Most guests walk right past it.",
	},
	["dar.muse.w23.courtesy.008"] = {
		"Thank you. Thank you again. I'll stop; I think I've thanked you into next season.",
		"I've thanked you three times and you've nodded three times. Shall we call it even?",
		"There I go, thanking you once more. Anyone would think I'd discovered manners five minutes ago.",
	},
	["dar.muse.w23.courtesy.009"] = {
		"A Sentinel stepped off the path to let me by. I stepped off the other side to let her by. The path stood empty between us until she smiled first.",
		"Two people giving way at once leave the path empty. That's how I spent a long moment on the moss, facing a very courteous druid doing the same.",
	},
	["dar.muse.w23.courtesy.010"] = {
		"follows a gnome's attempt at the open-palmed gesture the kaldorei use for thanks, and produce, with great sincerity, something closer to waving off a wasp.",
		"catches a dwarf trying the slow hand-to-chest thanks of the elves around him, get it backward, and be thanked for the effort in exactly the same gesture, done properly.",
	},
	["dar.muse.w23.courtesy.011"] = {
		"Nobody here has asked my name. Not from coldness: I think in Darnassus a name is something you offer, and nobody would dream of taking it.",
		"Strangers in other cities want your name, your business and your road. Here they want nothing at all, and wait, in case you'd like to give something.",
	},
	["dar.muse.w23.courtesy.012"] = {
		"In all my time here no kaldorei has invited me anywhere, and none has shut me out of anywhere either. It's a strange freedom, and a lonely one.",
		"They'll help a guest find anything, explain anything, carry anything. What they don't do is ask you to sit down. Their tables are their own.",
	},
	["dar.muse.w23.courtesy.013"] = {
		"Lower your voice. No, lower. I said it like that and a priestess turned around.",
		"Whisper. Everyone here whispers. Yes, even about the price of cheese.",
		"Shh. Even the fountain is keeping it down, and it's a fountain.",
	},
	["dar.muse.w23.courtesy.014"] = {
		"stops at the foot of a narrow footbridge to let an elderly kaldorei cross first, and is thanked with a nod so slow it seems to last the whole crossing.",
		"waits beside a narrow bridge while an old elf makes the crossing in no hurry at all, and earns, at the far end, a long and approving look.",
		"lets a priestess go first on a narrow stair and is rewarded with a murmur in Darnassian that sounds a great deal like approval.",
	},
	["dar.muse.w23.courtesy.015"] = {
		"When the priestesses kneel I never know whether to kneel with them or step away. I settle for standing very still, which seems to offend no one.",
		"A priestess at her devotions, and me beside her with hands that don't know where to go. In the end I folded them and waited, a guest at someone else's quiet.",
	},
	["dar.muse.w23.courtesy.016"] = {
		"I tried to give a coin to the elf who'd shown me the way. She looked at it as if I'd handed her a pebble out of my boot, and gave it back with enormous kindness.",
		"Offer a kaldorei money for a kindness and you'll get it back, along with a look that makes the coin seem very small indeed.",
	},
	["dar.muse.w23.courtesy.017"] = {
		"picks up a spool of thread that has rolled off a stall and hands it back, and is thanked so gravely and so fully that the small deed seems to grow in {g:his|her} hands.",
		"returns a basket an elf set down and forgot, and receives a bow that would suit a far larger favor.",
	},
	["dar.muse.w23.courtesy.018"] = {
		"Do you bow to a druid who is currently a cat? I did. The cat seemed to accept it.",
		"I nodded to a stag beside the path, just in case it was someone. It nodded back, which settles nothing.",
	},
	["dar.muse.w23.courtesy.019"] = {
		"Excuse me, sorry, pardon. That's my whole Darnassian, and it's all in Common.",
		"Is it rude to ask the way twice? Asking for a friend. The friend is me.",
		"Pardon me, could you point me to the bank? And then perhaps point again, more slowly?",
	},
	["dar.muse.w23.courtesy.020"] = {
		"Mind the flowers. And the moss. And, honestly, everything.",
		"Don't sit there. I don't know why not, but nobody else is sitting there.",
		"Follow my lead. I'm copying the elf just ahead, so it's a lead of sorts.",
	},
	["dar.muse.w23.courtesy.021"] = {
		"Thank you for not laughing. Or for laughing so quietly I couldn't hear it.",
		"You've been very patient with me. I suspect you've had a great deal of practice.",
	},
	["dar.muse.w23.courtesy.022"] = {
		"reaches out from habit to hold a door for the elf behind, finds only an open archway, and turns the gesture into a sort of welcoming sweep.",
		"makes to hold a door that turns out to be an open arch of living wood, and is thanked for the gesture anyway.",
	},
	["dar.muse.w23.courtesy.023"] = {
		"Kaldorei courtesy wasn't made for guests. It was made for a people who'd live beside the same neighbors for thousands of years. Visitors only borrow it.",
		"When you'll share a street with someone for a few thousand years, you learn never to say the thing that can't be unsaid. That's what all this politeness is, I think.",
	},
	["dar.muse.w23.courtesy.024"] = {
		"keeps to the edge of the temple floor, out of the priestesses' way, the way a guest keeps to the wall at the rites of another people.",
		"stops just within the Temple of the Moon and goes no farther, unsure how far a visitor may walk, until a priestess's small gesture invites {g:him|her} on.",
	},
	["dar.muse.w23.courtesy.025"] = {
		"Here in the Gardens a kaldorei gardener moved a pot an inch so a gnome could pass without brushing the petals. Neither of them said a word about it.",
		"Every visitor in the Temple Gardens walks as if carrying a full bowl: elbows in, eyes down, careful of every stem.",
	},
	["dar.muse.w23.crown.001"] = {
		"Kings wear crowns with jewels in them. This tree wears one with a bank, an auction house and an inn in it. I'd call that the better bargain.",
		"They call this the crown of Teldrassil. If the tree ever takes it off, I'd like some warning.",
		"A crown, they call the city. Most crowns weigh on the head that wears them. This tree doesn't seem to notice.",
	},
	["dar.muse.w23.crown.002"] = {
		"Through a gap at the city's edge I saw a bird flying below me, far below, its back to me. It took a moment to understand why that felt so wrong.",
		"There are hawks down there, circling beneath the city. I'm used to looking up at hawks. Looking down on them puts my knees in a mood.",
		"Below the edge of the terrace, birds go about their business with their backs to me. I watched them for a long time, feeling oddly like I was spying.",
	},
	["dar.muse.w23.crown.003"] = {
		"leans on a railing at the edge of the crown and looks down, and keeps looking down, past leaf and bough and leaf again, until the eye gives up on finding the bottom.",
		"peers over the edge of a terrace into the green depths of the tree, where the boughs below go on and on, each one smaller and bluer than the last.",
	},
	["dar.muse.w23.crown.004"] = {
		"The city is in the crown, but the crown doesn't stop at the city. Above the highest terrace the tree goes on climbing, and nobody I've asked has been up there.",
		"I asked a Sentinel what's above the highest bough. She looked up with me for a long moment and said, 'More tree.' I think it was a joke.",
		"There's more Teldrassil above Darnassus than anyone talks about. The city is a guest in the crown, not its whole household.",
	},
	["dar.muse.w23.crown.005"] = {
		"I'd appreciate it if people stopped mentioning how far down the sea is.",
		"A city at the top of a tree, they tell me, proudly. As if that were a comfort.",
		"Fine view. I just won't be looking straight down at it.",
	},
	["dar.muse.w23.crown.006"] = {
		"Fandral Staghelm wanted the city in the crown, I'm told, high above anything that walks. After Hyjal I can't say I blame him.",
		"Put a city in a treetop and anything that wants to burn it must first climb a very long way. The kaldorei learned something at Hyjal, and they learned it hard.",
		"A capital out of reach of every army that marches. Whoever chose the crown for Darnassus was thinking about fire, I'd wager.",
	},
	["dar.muse.w23.crown.007"] = {
		"looks up from the terrace and, for once, cannot see a single branch of the tree that holds {g:him|her}: only leaves, and the city resting among them like an egg in a nest.",
		"stands at a turn of the path and takes in how the terraces sit cupped in the crown, each one held as carefully as an egg.",
	},
	["dar.muse.w23.crown.008"] = {
		"We put our city where the owls live and the axes cannot reach. Some call it pride. I call it remembering.",
		"Up here the Warsong's axes are a whole sea and a forest away. Our crown is the one place in Kalimdor I rest without listening for them.",
	},
	["dar.muse.w23.crown.009"] = {
		"From the edge of the city you can see other parts of the crown, green islands of leaves with nobody living in them, and I find myself wondering who they're being kept for.",
		"Darnassus takes up only part of the crown. The rest is empty, green and patient, like rooms in a house built for a family that hasn't arrived.",
		"So much of the crown stands empty. Either the kaldorei mean to grow, or they like to keep a great deal of quiet around them. Possibly both.",
	},
	["dar.muse.w23.crown.010"] = {
		"Lovely view. I'd enjoy it more if I couldn't remember what it's standing on.",
		"If I ever fall out of this city, tell them it was the tree's fault.",
		"Up here, every dropped coin is a long goodbye.",
	},
	["dar.muse.w23.crown.011"] = {
		"The priestesses say the city was raised this high to stand nearer to Elune. I don't know how a goddess measures distance, but they walk here as if she were close.",
		"A priestess told me, without a trace of a smile, that the crown of a tree is the proper place for a temple: as far from the dust as a people can climb.",
	},
	["dar.muse.w23.crown.012"] = {
		"cranes {g:his|her} neck to find the top of the crown and finds only more of it, leaf over leaf like the scales of something very large asleep.",
		"gives up trying to see the top of the tree after a while and rubs the back of {g:his|her} neck, beaten.",
		"tilts {g:his|her} head further and further back, looking for the end of the leaves, until a passing kaldorei glances up too, politely, to see what the trouble is.",
	},
	["dar.muse.w23.crown.013"] = {
		"Living in a treetop makes everything below feel like rumor. Darkshore, Ashenvale, the whole of Kalimdor: a green blur and a few stories.",
		"Up in the crown, the rest of the world turns into hearsay. I have to remind myself there are roads down there, and people walking them.",
		"From up here the troubles of Kalimdor sound very far off, like an argument in another house. I know better. It's still pleasant.",
	},
	["dar.muse.w23.crown.014"] = {
		"A crown is a strange place for a beginning. Most cities start at a river or a ford. This one started at the top, and everything else had to be climbed to.",
		"Every city I know grew up from its foundations. Darnassus grew down from its roof, if you think about it, and nobody bothered much with the ground.",
	},
	["dar.muse.w23.crown.015"] = {
		"looks out from the edge of the city at the next great bough of the crown, an island of leaves hanging in the air with nothing at all beneath it.",
		"follows with {g:his|her} eyes a bough that leaves the city's edge and reaches out over nothing, on and on, as though the tree were stretching an arm toward Darkshore.",
		"rests both hands on a railing and studies a far limb of the crown, so distant that the leaves on it blur into a single soft green cloud.",
	},
	["dar.muse.w23.crown.016"] = {
		"Top of the tree. Everything in Kalimdor is downhill from here, which is cheering until you think about the walk back.",
		"Mind the edge, friend. It's a long way to the bottom of this tree, and no soft way to get there.",
		"Highest seat in the house. Shame about the climb.",
	},
	["dar.muse.w23.custom.001"] = {
		"A Sentinel told me they don't speak the names of the fallen while on watch. Afterward, off duty, they say them all, in order, and it takes a long time now.",
		"There's a custom among the Sentinels, I'm told: the names of the dead are kept for after the watch. Ashenvale has made that list long.",
	},
	["dar.muse.w23.custom.002"] = {
		"A druid told me some old kaldorei still spill a drop of water for the tree before they drink. She said it as if it were a little embarrassing, and as if she did it too.",
		"Some of the elders tip a little water onto the ground before drinking, a druid said: the tree drinks first. I noticed she did it herself, quickly, when I wasn't supposed to be looking.",
	},
	["dar.muse.w23.custom.003"] = {
		"Nobody lights a careless fire in Darnassus. A Sentinel put it plainly: in a city made of tree, a spark is treated like a drawn blade.",
		"Cook fires here are small, walled in stone and watched. When I asked, a merchant reminded me gently what the whole city is standing on.",
		"Lamps, yes. Torches, rarely. Bonfires, never. A Sentinel explained it with one glance at the floor.",
	},
	["dar.muse.w23.custom.004"] = {
		"Gifts among the kaldorei, a priestess told me, are given with both hands and received with both. One hand, she said, is for things that don't matter.",
		"Both hands to give, both to receive. I learned that from a kaldorei who waited, smiling, until I put my second hand out.",
	},
	["dar.muse.w23.custom.005"] = {
		"Kaldorei woodworkers take only fallen wood, a druid told me. Hard to believe until I looked at their bows, every one of them a slightly different curve.",
		"Nothing in the crafters' stores was cut from a living tree, I'm assured. Fallen branches only. The druids seem to check.",
	},
	["dar.muse.w23.custom.006"] = {
		"Whatever a kaldorei promises, a merchant warned me, will be kept long after you've forgotten asking. Be careful what you order in this city.",
		"Kaldorei promises don't expire, a trader told me, and then mentioned an order she's still filling for someone she hasn't seen in two centuries.",
	},
	["dar.muse.w23.custom.007"] = {
		"Some kaldorei have begun to mark the passing years, a priestess told me, a thing they never troubled to do before Hyjal. She didn't say it was sad. She didn't have to.",
		"Counting years is a new habit here, I'm told. For most of their history the kaldorei had no reason to. Now a few have started, quietly, the way you start checking a roof after the first leak.",
	},
	["dar.muse.w23.custom.008"] = {
		"spots a kaldorei setting a single flower at the foot of a carved pillar, touching it once, and walking on without looking back.",
		"notices small offerings tucked into a niche along the path, a feather, a pressed leaf, a smooth stone, and a passing kaldorei adding one without breaking stride.",
		"pauses at a small niche where someone has left a polished acorn and a sprig of green, and leaves them exactly as they were.",
	},
	["dar.muse.w23.custom.009"] = {
		"Do I take my boots off? Bow? Both? Someone here must have a list.",
		"There's a right way to do everything in this city, and I'm finding out each one by doing it wrong.",
		"If I've broken a custom, tell me which. I'll break the rest in order.",
	},
	["dar.muse.w23.custom.010"] = {
		"Among the kaldorei, a traveler told me, a host offers water before anything else. I was handed a cup of it at a stall and only understood later that it had been a welcome.",
		"Water first: that's how a kaldorei greets a guest, I've heard. A stallholder passed me a cup without a word, and I drank it without knowing I'd been greeted.",
		"The cup of water came before the price. Only afterward did I realize which of the two the merchant thought mattered.",
	},
	["dar.muse.w23.errand.001"] = {
		"The list in my head said bank, trainer, inn. Darnassus rearranged it by whichever terrace I happened to drift into first.",
		"I had an order for my errands. The paths had a different one, and the paths won.",
	},
	["dar.muse.w23.errand.002"] = {
		"counts the errands off on {g:his|her} fingers while walking, loses track at the fourth, and starts over from the thumb.",
		"ticks off a short list on {g:his|her} fingers, frowns at the one finger left over, and cannot remember what it stood for.",
	},
	["dar.muse.w23.errand.003"] = {
		"I came here for one thing. I'm leaving with three, and the one thing is still on the list.",
		"One errand. That was the plan. The plan has since grown leaves.",
		"I needed one thing. Darnassus sold me three others first, very softly.",
	},
	["dar.muse.w23.errand.004"] = {
		"The elf ahead of me at the bank studies each item before handing it over, as if saying goodbye. I now know that pair of gloves better than my own.",
		"Ahead of me at the bank, a kaldorei is parting with a ring, a cloak and a little box, slowly, with a long look for each. I've started to feel like a mourner.",
	},
	["dar.muse.w23.errand.005"] = {
		"Nothing in the mailbox but a note saying I've been outbid. Even the bad news arrives politely here.",
		"One letter in the post: somebody bid more than I did. Quietly, no doubt.",
	},
	["dar.muse.w23.errand.006"] = {
		"I sold a sack of odds and ends to a merchant who examined a cracked tooth as if it were a gem, and paid me copper for it with real courtesy.",
		"The merchant turned my broken buckle over twice, named a price of three copper, and thanked me. Nobody has ever thanked me for junk.",
	},
	["dar.muse.w23.errand.007"] = {
		"Every visit to a trainer goes the same way: lighter purse, fuller head, and a long walk to think it all over.",
		"Whatever I just learned cost me most of my silver. The walk across the city is free, at least, and long enough to go over it all in my head.",
	},
	["dar.muse.w23.errand.008"] = {
		"Put a pair of boots up at the auction house. The clerk wrote them down as if recording a treaty.",
		"Three things listed at auction, and a separate thank-you for each. My old boots have never been treated so well.",
	},
	["dar.muse.w23.errand.009"] = {
		"I walked all the way to the bank and stood at the counter with no idea what I'd come for. The banker waited. Of course the banker waited.",
		"Halfway across the city I forgot what I was going to the bank for. I kept walking anyway. The walk had earned it.",
	},
	["dar.muse.w23.errand.010"] = {
		"stands at the bank with an open bag, a chipped cup in one hand and a rusty key in the other, unable to decide which to keep.",
		"sorts the contents of {g:his|her} bags on the bank counter into keep, sell and why-do-I-have-this, and the third pile is the tallest.",
	},
	["dar.muse.w23.errand.011"] = {
		"Repairs, a meal, a lesson, and my purse is flat. Darnassus is gentle about everything except how much it all adds up to.",
		"My coin ran out two errands before my list did. I'll leave the last two to some richer version of myself.",
	},
	["dar.muse.w23.errand.012"] = {
		"No need to count the change twice. Oh. Three times, then. Thank you.",
		"Keep counting, I've nowhere to be. Which is a lie, but a polite one.",
		"Count it as slowly as you like. I'll just stand here and put down roots.",
	},
	["dar.muse.w23.errand.013"] = {
		"The map I bought shows every terrace in lovely ink and not one of the paths between them. I suspect it's an honest map of Darnassus.",
		"I've a map of this city now. It's beautiful, and about as useful as a painting of a staircase.",
	},
	["dar.muse.w23.errand.014"] = {
		"reaches the bank, remembers that the thing to deposit was left behind at the trainer's, and turns around with a long, quiet sigh.",
		"arrives at the auction house, pats every pocket twice, and realizes the item to sell is still sitting in the bank.",
	},
	["dar.muse.w23.errand.015"] = {
		"Errands are the best way to see a city. Nobody looks twice at someone who is plainly off to see the banker.",
		"I like having small business here. It gives me a reason to cross the terraces that isn't only gaping at them.",
	},
	["dar.muse.w23.errand.016"] = {
		"If this city had an inn that rented chairs by the hour, I'd never leave it.",
		"I'm off to the inn. Not to sleep. Just to sit under a roof and pretend I know where everything is.",
	},
	["dar.muse.w23.errand.017"] = {
		"Two bundles of cloth, a bag of thread and a new pair of gloves, all to be carried across the city by hand. Somebody should invent a smaller city.",
		"My arms are full of shopping, and every path in Darnassus has chosen this moment to be scenic.",
	},
	["dar.muse.w23.errand.018"] = {
		"buys a little of everything at a stall, then stands aside to fit it all into bags that were already full.",
		"stops at a stall for water and travel food, and spends a good while making it all fit in the pack.",
	},
	["dar.muse.w23.errand.019"] = {
		"Bank, trainer, stall, and back. Every errand done. Somebody write that down; it won't happen twice.",
		"All my errands done in one go. I'd like a small ceremony, please. A nod will do.",
		"Every errand finished. I'm going to stand here a moment and be insufferable about it.",
	},
	["dar.muse.w23.errand.020"] = {
		"The bank and the auction house share this terrace, and still I manage to walk between them three times on every visit.",
		"Here on Tradesmen's Terrace everything I need is within a few dozen paces. It has never once stopped me forgetting something at the other end.",
	},
	["dar.muse.w23.errand.021"] = {
		"Trainer's busy. Fine. I'll watch the drills and pretend I'm learning by looking.",
		"Here to learn, and already sore from watching other people practice.",
	},
	["dar.muse.w23.errand.022"] = {
		"At night the city is busier, if anything. I'm the one yawning through my errands while the kaldorei are only getting started.",
		"Past midnight, and the stalls are still open, the trainers still patient. My errands keep the kaldorei's hours now, not mine.",
	},
	["dar.muse.w23.errand.023"] = {
		"As the light fades, the paths fill up. It seems dusk is when the kaldorei run their errands, and I've picked the same hour as all of them.",
		"Dusk, and suddenly there's a line at every stall. The locals are starting their day; I'm trying to finish mine.",
	},
	["dar.muse.w23.errand.024"] = {
		"A gnome could solve this city in a week with some brass rails and a lift or two. Nobody here has asked me, and I've decided not to offer.",
		"I've drafted three ways to halve the walk from the bank to the trainers. All of them involve gears, so all of them stay in my notebook.",
	},
	["dar.muse.w23.grain.001"] = {
		"crouches at the foot of a stair and follows the grain with one finger: it flows out of the step below into the step above without a seam, as if the whole flight had grown in one piece.",
		"pauses on a staircase and notices that the grain bends to follow each step, curving up and over like water over stones.",
		"runs a fingertip up the edge of a stair and feels the grain rise with it, step after step, never once broken.",
	},
	["dar.muse.w23.grain.002"] = {
		"I've been looking for a nail in Darnassus. A peg, a joint, a saw mark, anything. Nothing. A Stormwind carpenter would starve here, and then be buried in a very beautiful box.",
		"Not one saw mark in the whole city. The wood was talked into shape, not cut, and you can tell: every edge is the edge it wanted.",
		"Somewhere in Ironforge there's a guild of joiners who would weep to see this place. Not one dovetail. Not one.",
	},
	["dar.muse.w23.grain.003"] = {
		"There's a knot in the wall by the path shaped like a half-closed eye. I've gone past it four times now. I suspect it has noticed.",
		"Knots in the living wood, here and there, each with the grain swirling round it like a crowd round a speaker. The tree keeps its own small landmarks.",
		"I've started to know the knots. One by the stair like a thumbprint, one over a door like a frown. Hardly a map, but better than none.",
	},
	["dar.muse.w23.grain.004"] = {
		"You can't count the rings of a tree you're living in. The druids give its age in years instead, a small number, and say it with a look that dares you to be surprised.",
		"Somewhere inside this wood there are rings, only a few, one for each year since the planting. A farmhouse in Elwynn might have older beams.",
		"A druid gave me the tree's age the way you'd give a child's: proudly, and in years you could count on your fingers.",
	},
	["dar.muse.w23.grain.005"] = {
		"admires the way a kaldorei crafter turns a pale offcut in long fingers, reading its grain the way others read a letter, before setting it down untouched by any tool.",
		"sees a crafter lay a palm along a length of fallen bough and slide it slowly, eyes half closed, feeling for something in the grain only the hand can find.",
	},
	["dar.muse.w23.grain.006"] = {
		"A gnome beside me rapped on a wall with his knuckles, listening for hollow. The wall gave nothing back. The gnome took it personally.",
		"Watched a gnome measure a doorway, twice, then glare at the numbers as though they'd lied. Nothing in this city is the same width top to bottom.",
		"A gnome on the stair had a little brass level out and was frowning at the bubble. It never settled. I don't think it ever will, here.",
	},
	["dar.muse.w23.grain.007"] = {
		"Where the floor once split, the tree has grown a ridge across the crack, like a scar on a knuckle. Nobody patched it. It patched itself, and kept the mark.",
		"A seam runs across the path where the wood once parted, closed now by a raised lip of new growth. I step over it carefully, the way you'd spare a sore spot.",
		"The tree mends its own cracks and doesn't hide them. I've seen worse habits in people.",
	},
	["dar.muse.w23.grain.008"] = {
		"lays a hand on a wall and finds, at the line where pale stone meets living wood, that one side is cool and the other faintly warm.",
		"notices where pale stone has been set into the living wood: the bark has crept over the stone's edge by a finger's width, as if to hold it in place.",
		"studies a block of white stone sunk in a wall of wood and sees the grain flowing around it on both sides, like a stream around a boulder.",
	},
	["dar.muse.w23.grain.009"] = {
		"This floor has a grain. Walk against it and the feet know, like stroking a cat backward.",
		"Touch the walls here. Go on. Smooth as a bowl, and not a tool mark anywhere.",
		"Even the floor has a direction in this city. I keep catching myself walking with it.",
	},
	["dar.muse.w23.grain.010"] = {
		"A druid explained to me how a wall is grown: you ask the wood, then wait, then ask again a little differently. She made it sound like courting.",
		"Ask a druid how long it took to shape a doorway and you'll hear a season for an answer, maybe two. Ask how it was done and you get the word 'listening', and nothing more.",
		"The druids don't build, they suggest. A doorway here is the wood's answer to a question asked very politely for a very long time.",
	},
	["dar.muse.w23.grain.011"] = {
		"traces a dark line in the pale grain of a doorframe and finds it isn't a stain but a vein of darker wood, running up and out of sight like a thread through cloth.",
		"notices that the grain on one side of an arch is tight and fine and on the other loose and wide, as if the wood had grown faster on the side that faces the water.",
		"brushes a fingertip over a pale knot in a pillar and sees the grain curl around it in rings, like ripples around a dropped stone.",
	},
	["dar.muse.w23.grain.012"] = {
		"In Stormwind we fell an oak to roof a house. Here they ask the tree to be the house, and it agrees. I'm still deciding which of us is being rude.",
		"Every beam in Stormwind was a tree once, and died to become one. Here the beams are still trees. A mason from home would need a long sit-down.",
	},
	["dar.muse.w23.grain.013"] = {
		"Here on the Craftsmen's Terrace the workbenches are part of the floor, the grain running from bench top straight down into the boards. Nobody will ever move them, and nobody means to.",
		"The tables on this terrace grow out of the floor. I set my pack on one and felt, absurdly, that I ought to have asked first.",
		"On this terrace even the workbenches are rooted. The crafters lean on them the way you lean on an old friend's shoulder.",
	},
	["dar.muse.w23.grain.014"] = {
		"Not a splinter in the whole city. I've checked. With my hands, mostly by accident.",
		"You could run barefoot on these floors. I'm told some people do.",
	},
	["dar.muse.w23.grain.015"] = {
		"sits on a step of living wood and, after a moment, shifts a little to the side: the first spot had a knot exactly where nobody wants a knot.",
		"settles on a ledge of pale wood, finds it fits rather well, and suspects it was shaped for someone with much longer legs.",
		"lowers {g:himself|herself} onto a curved seat grown out of the wall and finds {g:his|her} feet don't quite reach the floor.",
	},
	["dar.muse.w23.grain.016"] = {
		"drops a coin, hears it ring dully on the wooden floor, and watches it roll away in a long curve, following the grain rather than the slope.",
		"follows a dropped button as it rolls across the floor, bending gently along the grain as if it knew the way, and stop at the feet of a kaldorei who hands it back without a word.",
	},
	["dar.muse.w23.grain.017"] = {
		"Look at this grain. Like water frozen mid-run.",
		"You could read this wall like a map, if anyone ever taught you the language.",
		"Every swirl in this wood went somewhere once. I'd love to know where.",
	},
	["dar.muse.w23.grief.001"] = {
		"Across the water, Darkshore is full of elven towns gone to moss and broken arches. Up here they build new arches in the same curves, and I wonder whether that's remembering or refusing to.",
		"The ruins along Darkshore's coast and the terraces of Darnassus share the same lines, the same curling roofs. One is what was. The other is the kaldorei drawing it again, carefully, from memory.",
	},
	["dar.muse.w23.grief.002"] = {
		"watches an elf set a single leaf on the surface of a stream and follow it with her eyes until it is gone, then walk on as if nothing had happened.",
		"sees a kaldorei pause on a bridge, let a pale flower drop into the current below, and stand there without moving until the water has carried it out of sight.",
	},
	["dar.muse.w23.grief.003"] = {
		"Ten thousand years without funerals, and then the Third War made the kaldorei learn mourning in a hurry. Their grief has an awkwardness to it that I find very moving.",
		"For an immortal people, death was mostly something that happened to others. Now it happens to them, and they grieve like learners: earnestly, a little stiffly, without the old formulas other races lean on.",
	},
	["dar.muse.w23.grief.004"] = {
		"There's a look the kaldorei get when a name comes up that nobody has said in a while. They don't look down. They look slightly up and to the left, as if the person were standing just behind them.",
		"Nobody here bows their head when a lost name is spoken. They glance aside instead, toward an empty spot, as if politely making room for someone.",
	},
	["dar.muse.w23.grief.005"] = {
		"Somewhere across the strait, the kaldorei towns of Darkshore crumble into the surf. Nobody here asks to go back and rebuild them. Perhaps you don't rebuild a grave.",
		"I've walked among the drowned and broken towns of Darkshore. The elves of this city know every one of them by name, and I have never heard one of them suggest going home to it.",
	},
	["dar.muse.w23.grief.006"] = {
		"Whole city's in mourning, and they still find time to give a stranger directions. Humbling.",
		"These people have buried more than I'll ever know, and they still hold a door for me.",
	},
	["dar.muse.w23.grief.007"] = {
		"Keepsakes were never a kaldorei habit. Why keep a lock of hair from someone who would always be there? Now I see elders with little pouches at their belts, and I don't ask what's inside.",
		"Small pouches worn close to the belt are new in Darnassus, a crafter told me. Mementos. A people who never needed to keep anything of the dead have started keeping something.",
	},
	["dar.muse.w23.grief.008"] = {
		"stands aside as a priestess sings a few low words over a small lamp at the edge of the temple, then pinches the flame out with two fingers and bows to the dark wick.",
		"keeps a respectful distance as a priestess lights a small lamp for someone who is not there, speaks a short phrase over it, and leaves it burning among a row of others just like it.",
	},
	["dar.muse.w23.grief.009"] = {
		"Some of the young trees in the gardens here were planted for the dead of the Third War, I was told. Nobody marks which. You are meant to treat them all gently, just in case.",
		"A gardener here said that a seedling goes into the earth for each kaldorei lost at Hyjal and in Ashenvale. She didn't point any out. She didn't need to; the gardens are full of them.",
	},
	["dar.muse.w23.grief.010"] = {
		"Nothing is forgotten here, and kaldorei grief knows it. A loss here doesn't fade with the years; it settles, like silt in a still pool, and stays.",
		"Short lives forget, and forgetting is a mercy. The elves here don't get that mercy. They carry each loss with them, perfectly clear, for as long as they live.",
	},
	["dar.muse.w23.grief.011"] = {
		"They don't cry here. They just go very quiet, and for a long time.",
		"Kaldorei grief makes no noise. I almost wish it did.",
	},
	["dar.muse.w23.grief.012"] = {
		"Since Hyjal I know the faces of my elders will change, and leave. I look at them longer now, the way you'd memorize a coastline from a departing ship.",
		"I have started to study the faces of the old ones in this city. Not with sorrow, exactly. With the care of someone copying a page before the ink fades.",
	},
	["dar.muse.w23.grief.013"] = {
		"A kaldorei apology for something done four thousand years back: I overheard one on a bridge. The other party accepted it graciously and said they'd been waiting.",
		"Two old elves just made up over a quarrel that started before the Sundering. Grudges last a while, here. So, apparently, does tact.",
	},
	["dar.muse.w23.grief.014"] = {
		"happens upon a Sentinel standing beside a weeping druid, saying nothing at all, her shoulder against his until he is ready to walk on.",
		"watches one kaldorei rest a hand flat between another's shoulder blades, wordless and unmoving, while the other stares out at the water for a long while.",
	},
	["dar.muse.w23.grief.015"] = {
		"Every great tree the kaldorei have planted, they planted after losing something. Nordrassil after the Sundering, Teldrassil after Hyjal. It is a strange thing to live inside a people's grief and find it this green.",
		"I'm walking around in the crown of a mourning gesture. Teldrassil was planted after the loss of Hyjal's blessing, and the city grew out of that sorrow like a leaf out of a bud.",
	},
	["dar.muse.w23.grief.016"] = {
		"My people have always known we'd die, and we've had plenty of time to make jokes about it. The kaldorei are new at it. I'm tempted to offer lessons, and I know I mustn't.",
		"Where I come from, death gets a few good jokes. The kaldorei haven't found theirs yet. I've learned not to try mine out on them.",
	},
	["dar.muse.w23.grief.017"] = {
		"Rain sifting down through the boughs, and a priestess walking slowly along the path without a hood, letting it fall on her face. I don't think she's praying. I think she's letting it do the crying.",
		"In this rain the kaldorei go out instead of in. An old Sentinel stands by the water with her face turned up, and I understand I shouldn't be watching.",
	},
	["dar.muse.w23.grief.018"] = {
		"For all that this people has lost, I haven't once heard a kaldorei call the world ruined. Hurt, yes. Smaller, yes. But still a world worth planting in.",
		"Grief here never turns to bitterness, as far as I can tell. They lost their home, their queen, their forever, and they still go on putting seeds in the ground.",
	},
	["dar.muse.w23.grief.019"] = {
		"My worst memories are ten years old. Theirs are ten thousand. I'll stop complaining.",
		"Bad day? Talk to a kaldorei about a bad millennium.",
	},
	["dar.muse.w23.grief.020"] = {
		"falls quiet beside an old kaldorei who has stopped mid-step and turned as if someone had called her name; she stands very still, listening to a voice that has not spoken in a long time.",
		"notices an elder look up sharply at a laugh from across the water, the way one does at a voice one knew, and then slowly remember, and lower her eyes.",
	},
	["dar.muse.w23.grief.021"] = {
		"We never needed many words for the dead. We are inventing them now, one funeral at a time, and every new word feels borrowed from someone else's grief.",
		"My elders taught me every name of every star and none for mourning. I have had to borrow those from the humans, and they fit badly, like a stranger's boots.",
	},
	["dar.muse.w23.grief.022"] = {
		"Even their gardens look like they're remembering someone.",
		"Pretty city. Sad city. They hide the second part well.",
	},
	["dar.muse.w23.guest.001"] = {
		"Watch a kaldorei with a visiting dwarf: kind in every word, and not one step closer than courtesy needs. Warmth, kept at arm's length.",
		"Kaldorei kindness to guests keeps its distance perfectly well. Nobody is cold, and nobody stands any nearer than the conversation requires.",
	},
	["dar.muse.w23.guest.002"] = {
		"I've been on my best behavior for so long my shoulders ache. Good manners are harder work than they look.",
		"Being a model guest in Darnassus is a full-time trade. My neck is stiff from holding my head up this straight.",
		"Mind the voice, mind the elbows, mind the flowerbeds. Courtesy here is a workout.",
	},
	["dar.muse.w23.guest.003"] = {
		"notices that {g:his|her} boots have left a faint trail of road dust on the pale stone, and spends a moment trying to scuff it away with the other boot.",
		"glances down at {g:his|her} travel-stained clothes, then at two immaculate kaldorei walking by, and quietly brushes off a sleeve.",
		"tucks a frayed strap out of sight and straightens {g:his|her} collar, as if the city itself had asked.",
	},
	["dar.muse.w23.guest.004"] = {
		"The elf who sold me a spool of thread may remember forests where there is open water now. She counted out my change with great care all the same.",
		"Someone in this crowd walked under trees that went into the deep before any human kingdom had a name. And still they stop to give strangers directions.",
	},
	["dar.muse.w23.guest.005"] = {
		"Darnassus never says keep out, and nobody here would. Guests learn the shape of a kaldorei welcome by where the conversation stops.",
		"No sign, no gate, no warning. The doors that are closed to visitors are closed with a pause and a change of subject.",
	},
	["dar.muse.w23.guest.006"] = {
		"I've been bowed at four times since the bank. I'm running out of ways to bow back.",
		"Is there a rule for how many bows a walk takes? I've lost count, and I suspect they haven't.",
		"My neck has done more bowing since I got here than in the rest of the year.",
	},
	["dar.muse.w23.guest.007"] = {
		"A kaldorei shopkeeper called the Second War 'recent' to a human customer. She wasn't joking. The human took a moment to recover.",
		"To a merchant on the terrace, the founding of Stormwind is news that hasn't quite settled. The human she said it to has gone very quiet.",
		"'Not long ago,' an elf told a dwarf, and went on to describe something from before Ironforge was dug. The dwarf nodded as if he'd been there.",
	},
	["dar.muse.w23.guest.008"] = {
		"lowers {g:his|her} voice without meaning to while asking the way, and the kaldorei who answers lowers hers to match, as if by some quiet agreement.",
		"asks a passing elf for directions and receives them so slowly and so completely that walking off before the end would be unthinkable.",
	},
	["dar.muse.w23.guest.009"] = {
		"In most cities a visitor worries about thieves. Here I worry about my volume, my hurry and the dust I've brought in.",
		"Other capitals make me watch my purse. Darnassus makes me watch my elbows, my voice and the noise my boots make.",
	},
	["dar.muse.w23.guest.010"] = {
		"Their old cities lie in ruins across the water, and they still make room for guests in the new one. I'm not sure I'd be so generous after losing that much.",
		"A people who lost a whole homeland, opening the last high place they have to strangers. Someone up at the temple made a hard choice to allow it.",
	},
	["dar.muse.w23.guest.011"] = {
		"I've hardly touched a thing since I came up. The place feels like a house whose owner stepped out a moment ago and trusted me to wait.",
		"Darnassus has the feel of someone else's room: lovely, open, and full of things I'd rather not knock over.",
		"I keep my hands to myself here, the way I would in a stranger's parlor. Nobody asked me to. The city just has that effect.",
	},
	["dar.muse.w23.guest.012"] = {
		"Humans used to looking down at dwarves look up in Darnassus, and you can watch them adjust their dignity as they go.",
		"Next to the kaldorei even a tall human looks like somebody's apprentice. The gnomes, sensibly, gave up comparing long ago.",
	},
	["dar.muse.w23.guest.013"] = {
		"Ironforge's halls are ancient to a human. To the kaldorei they're fairly recent work. Every guest in this city is young, whatever the beard says.",
		"Old by any other measure is middling here. The grayest dwarf on the bridge is likely younger than the woman selling him herbs.",
	},
	["dar.muse.w23.guest.014"] = {
		"There's a rest in being a guest. Nothing in Darnassus is mine to mend, guard or worry over.",
		"A guest has one duty here: to be no trouble. After so many places that needed something from me, it's a relief to be asked so little.",
	},
	["dar.muse.w23.guest.015"] = {
		"Farewells to visitors are gentle here, and brief. When you outlive most of the people you meet, perhaps you learn to hold every guest lightly.",
		"How many guests has a kaldorei grown fond of, only to see them gray and gone? Maybe that's why the welcome here is warm but never close.",
	},
	["dar.muse.w23.guest.016"] = {
		"Visitors are the only folk in Darnassus who keep asking the hour. The kaldorei answer, but you can see them working it out.",
		"Ask a kaldorei what hour it is and you'll get an answer, after a pause, as if you'd asked about somebody else's customs.",
	},
	["dar.muse.w23.guest.017"] = {
		"I told a kaldorei I'd see her soon. She asked, very seriously, which soon I meant. I hadn't known there was more than one.",
		"'Back in a little while,' I told the merchant. The merchant nodded as if a little while might mean a year, and folded the cloak away to keep.",
	},
	["dar.muse.w23.guest.018"] = {
		"What do you bring a host who has already seen every gift there is? I've settled on clean boots and a low voice.",
		"A guest ought to bring something. But what could I offer a people this old that they haven't had, lost and grown again? My manners will have to do.",
	},
	["dar.muse.w23.guest.019"] = {
		"Here on the Tradesmen's Terrace you can tell guest from host by the purse. Visitors clutch theirs. The kaldorei carry theirs as if no one in the world would think of taking it.",
		"The visitors on this terrace count their coins twice and glance around before opening a purse. The kaldorei just pay, and seem faintly puzzled by the fuss.",
	},
	["dar.muse.w23.heartwood.001"] = {
		"Under the moss and the stone the trunk keeps going, down and down to the sea. I think of it the way you think of a house's foundations: almost never, and then all at once.",
		"The whole of Darnassus is the top of a column of living wood that stands in the sea. Every so often I can't stop knowing it.",
		"Beneath every terrace there's the trunk, and beneath the trunk the sea. I only remember it when I set something heavy down.",
	},
	["dar.muse.w23.heartwood.002"] = {
		"Heartwood is the oldest wood in a tree, the dead core that holds the living part up. Teldrassil's can't be more than a few years old. A whole city stands on something younger than its youngest Sentinel.",
		"The core of an old oak is centuries deep. The core of this tree is younger than the merchant who just sold me a loaf. I keep turning that over.",
		"Most trees hold their oldest wood at the center. This one's oldest wood was a sapling when the city's elders were already ancient.",
	},
	["dar.muse.w23.heartwood.003"] = {
		"Some of the older druids, when they think no one is listening, say the tree was planted in a hurry and without asking anyone who should have been asked. Then they go back to tending it, very carefully.",
		"A Sentinel told me Nordrassil was planted with the blessing of great powers, and Teldrassil with the hope of one Arch Druid. She said it flatly, and then she would not say anything more.",
	},
	["dar.muse.w23.heartwood.004"] = {
		"notices an elder kaldorei stop on the path, lay a hand on the ground, and stay bent there a moment, like someone checking a sleeping child's brow.",
		"sees a druid stop mid-stride, crouch, and set both palms on the living floor, frowning slightly, before rising and walking on as if nothing had been asked or answered.",
		"watches a Sentinel, at the end of her round, rest her knuckles briefly against a pillar of the trunk before she turns back, the way one might touch a doorframe for luck.",
	},
	["dar.muse.w23.heartwood.005"] = {
		"Almost everywhere, the ground is older than anyone standing on it. Here it's the other way round: the people are ancient, and the floor under them barely knows its own name.",
		"Ancient people, young ground. In Darnassus the elders are older than the floor they walk on by a few thousand years, at the very least.",
		"In other cities the stones remember more than the people do. Here it's the people who remember, and the wood that is still learning.",
	},
	["dar.muse.w23.heartwood.006"] = {
		"Somebody planted this. I'd give a good deal to have seen the hole.",
		"Imagine watering it. Imagine the first year, when it came up to your knee.",
		"One seed, a lot of druids, and look at it now. Makes a vegetable patch seem unambitious.",
	},
	["dar.muse.w23.heartwood.007"] = {
		"Nordrassil gave us forever, and we spent it at Hyjal. Teldrassil gives us a city and a canopy and asks nothing back. I am trying to be grateful for a smaller gift.",
		"The druids say this tree will never be what Nordrassil was. I touch its bark anyway, each time I pass, the way you'd take the hand of someone who is trying very hard.",
	},
	["dar.muse.w23.heartwood.008"] = {
		"The kaldorei don't seem to worry about the tree falling over. I asked one. She looked at me with pity and said trees don't fall, they lie down, and this one has no reason to.",
		"I asked a druid what holds the tree up in the sea. 'Roots,' he said, the way you'd say 'legs' to someone asking how a person stands.",
		"A Sentinel told me, quite seriously, that the trunk goes down further than the sea is deep. I didn't ask how she knew. I didn't want to know how she knew.",
	},
	["dar.muse.w23.heartwood.009"] = {
		"There must be hollows deep in a trunk this size. A Sentinel said there are, and that the druids know them all by name. She didn't offer to introduce me.",
		"I wonder what the inside of a tree this size sounds like. Not the bark: the middle. Probably like the inside of a bell, long after it's been struck.",
	},
	["dar.muse.w23.heartwood.010"] = {
		"steps over a long hump in the path where some deep part of the tree pushes up through the floor, and notices that every kaldorei ahead stepped over it too, though it would have been easy to tread on.",
		"notices a ridge of living wood rising across the path and, like the kaldorei around {g:him|her}, steps over it instead of on it, without quite knowing why.",
	},
	["dar.muse.w23.heartwood.011"] = {
		"I come from a people who build with dead wood and cut stone. Living inside something alive takes getting used to. I keep apologizing to doorframes.",
		"Where I come from, a house that moves is a house about to fall down. Here a doorway that shifts a little is just the tree getting comfortable, and I'm the only one who flinches.",
	},
	["dar.muse.w23.heartwood.012"] = {
		"The temple floor is living wood under pale stone, and the priestesses walk on it barefoot as often as not. Far beneath, the core of the tree carries all of it and says nothing.",
		"In the Temple of the Moon I find myself stepping softly as much for the tree's sake as for the goddess's.",
		"Here in the temple the stone is laid over the wood like a cloth over a table, and the table, I suspect, is the older guest of the two in this room.",
	},
	["dar.muse.w23.heartwood.013"] = {
		"Here in the Enclave the druids treat the living walls like a colleague: they lean on them, talk past them, consult them with a hand and get back to work.",
		"Someone in the Enclave left a cup on a ledge of living wood, and the wood has begun, very slowly, to grow a lip around it.",
		"Nobody in the Enclave knocks on wood for luck. They lay a palm on it instead, and wait, as if it might have an opinion.",
	},
	["dar.muse.w23.heartwood.014"] = {
		"Some druids say a tree remembers every hand laid on it. If that's true, Teldrassil knows a great many strangers by now, and has been patient with every one of them.",
		"If the tree does remember hands, as the druids claim, then mine is in there somewhere now, between a Sentinel's and a gnome's.",
	},
	["dar.muse.w23.heartwood.015"] = {
		"With the mist in the lower boughs, the trunk vanishes beneath the city and Darnassus simply floats. It has never seemed less certain that anything is holding it up.",
		"Fog below the terraces, fog in the lower branches. For once the tree keeps its height to itself, and the city seems set down on a cloud.",
	},
	["dar.muse.w23.heartwood.016"] = {
		"Young tree, ancient people, and it's the tree doing all the lifting.",
		"This tree's barely older than my oldest boots, and it's carrying a capital.",
		"Strange city. Old folk, new floor.",
	},
	["dar.muse.w23.heartwood.017"] = {
		"lingers to watch a druid teach two younger ones to lay their hands on the trunk, adjusting a wrist, a finger, and nodding only when they go still.",
		"sees an elder druid press a student's palm flatter against the bark and say a single word, very quietly, that makes the student smile.",
	},
	["dar.muse.w23.heartwood.018"] = {
		"How far down does the trunk go? All the way to the sea? All the way. Right. Good. Fine.",
		"A whole tree under my boots. I keep forgetting, and then I don't.",
		"Everyone keep walking normally. The floor is a tree and the tree is very tall. Normally, I said.",
	},
	["dar.muse.w23.heartwood.019"] = {
		"I'd knock on wood for luck, but in this city it feels like knocking on someone's door.",
		"Knock on wood? Here? I'd only be waking somebody.",
	},
	["dar.muse.w23.hush.001"] = {
		"My pack jingles with every step: buckles, a tin cup, loose coin. In any other city it's nothing. Here I sound like a tinker's cart.",
		"I've wrapped my tin cup in a sock so it stops knocking against the buckles. Darnassus makes me do strange things.",
	},
	["dar.muse.w23.hush.002"] = {
		"stands in a quiet line when {g:his|her} stomach growls, loud and long, and two kaldorei turn with polite interest.",
		"presses a hand to {g:his|her} stomach as it rumbles into the silence, and pretends very hard to be studying the carvings.",
	},
	["dar.muse.w23.hush.003"] = {
		"catches {g:himself|herself} whistling a tavern tune halfway across a bridge, and stops so suddenly the last note hangs there alone.",
		"begins to hum without meaning to, notices, and lets the tune trail off into nothing.",
	},
	["dar.muse.w23.hush.004"] = {
		"I never thought I'd miss the creak of a cart wheel. Up here I'd pay good silver to hear one go past.",
		"Quiet like this makes city folk nervous. Without carts and shouting to mark the hours, I can't tell what my day is doing.",
	},
	["dar.muse.w23.hush.005"] = {
		"In the places I know, a room goes this quiet just before someone throws a chair. Here it simply stays quiet, and I stay braced.",
		"Every instinct I own says silence this deep means trouble is coming. Darnassus keeps proving every one of them wrong.",
	},
	["dar.muse.w23.hush.006"] = {
		"Is it rude to whisper here? Because it feels ruder not to.",
		"I keep whispering and nobody asked me to. This city just has that effect.",
	},
	["dar.muse.w23.hush.007"] = {
		"Two kaldorei are talking across the water, and I can follow every word, though I understand none of them. Sound goes a long way when nothing gets in its path.",
		"With so little noise about, voices carry from one terrace to the next. I've overheard a whole bargain without seeing either side of it.",
	},
	["dar.muse.w23.hush.008"] = {
		"walks with one boot that squeaks at every step, and before long stops to rub a little grease into the leather.",
		"tries three different ways of setting down a squeaking boot, and every one of them squeaks.",
	},
	["dar.muse.w23.hush.009"] = {
		"lets a handful of coins fall back into the purse and winces as the clink carries across half the terrace.",
		"counts out some silver for a stall and, hearing how far the sound goes, finishes the counting with the coins cupped in {g:his|her} palm.",
	},
	["dar.muse.w23.hush.010"] = {
		"I've caught myself talking aloud to no one twice now. In a louder city nobody would hear. Here a Sentinel looked over, very gently, as if I might need help.",
		"I muttered something about my boots, and a priestess passing by murmured back what sounded like sympathy.",
	},
	["dar.muse.w23.hush.011"] = {
		"clears {g:his|her} throat before speaking to a merchant, and the small sound seems to go on for some time.",
		"sets a tin cup down on a stone ledge, and the little clack seems to travel out over the water for a long while.",
	},
	["dar.muse.w23.hush.012"] = {
		"Stormwind has its bells and Ironforge its hammers. Darnassus has the sound you hear when you stop expecting either.",
		"My ears keep reaching for a noise that isn't coming: a hammer, a bell, a cart. They'll learn, or I'll leave first.",
	},
	["dar.muse.w23.hush.013"] = {
		"The quiet keeps fooling me into thinking I'm alone. Then I turn, and there's an elf a few steps away who has been there all along.",
		"Silence here doesn't mean nobody is near. I've learned that by turning round, more than once, to find someone standing very still close by.",
	},
	["dar.muse.w23.hush.014"] = {
		"Could somebody drop a pot? Just one. For my nerves.",
		"What I wouldn't give for a dog barking somewhere. Any dog. Any bark.",
		"One loud noise. Anything. A goat would do.",
	},
	["dar.muse.w23.hush.015"] = {
		"tells a joke to a kaldorei merchant and gets a laugh made almost entirely of shoulders and eyes.",
		"says something that makes a nearby elf laugh, and hears no sound at all; only the shoulders shake once and settle.",
	},
	["dar.muse.w23.hush.016"] = {
		"The first hour, the quiet here grates. The second, it settles. By the third I'm the one frowning at a loud visitor.",
		"It takes a while to stop fighting the quiet. After that I find I'm walking more slowly and resenting anyone who doesn't.",
	},
	["dar.muse.w23.hush.017"] = {
		"raises a fist to knock out of habit, finds only an open, curving archway, and lowers the hand with a sheepish look.",
		"looks for a door to knock on at the entrance of a hall, finds only an open arch, and hovers at the threshold until someone waves {g:him|her} in.",
	},
	["dar.muse.w23.hush.018"] = {
		"In any other city I'd shout across the square to someone I know. Here I wave, and wave harder, and finally walk the whole way over.",
		"Calling out across a terrace would be like banging a gong at a funeral. So I wave instead, like someone shipwrecked.",
	},
	["dar.muse.w23.hush.019"] = {
		"The inn here on Craftsmen's Terrace must be the liveliest room in Darnassus. I could still hear someone turn a page across it.",
		"Even the inn is quiet. Somewhere behind the herbs and hides of this terrace, travelers are drinking without a single clink.",
	},
	["dar.muse.w23.hush.020"] = {
		"I came into the temple to ask a priestess something, and the silence was so complete I've forgotten what it was.",
		"In the temple I lower my voice, then lower it further, and in the end decide the question can wait for somewhere noisier.",
	},
	["dar.muse.w23.hush.021"] = {
		"Where I come from, a street this quiet means everyone's hiding from something. Here it's just how the street is.",
		"Every elf here could hear a pin drop. I just heard my own knees creak, and so, I fear, did they.",
	},
	["dar.muse.w23.hyjal.001"] = {
		"To stop Archimonde at Hyjal, the kaldorei gave up forever. Watching an elder here rub an aching wrist, I realize she is only lately learning what it is to hurt and not heal.",
		"Only lately have some elves in this city met their first gray hair. You can tell by the way they touch it, as if it were a stranger's.",
	},
	["dar.muse.w23.hyjal.002"] = {
		"At Hyjal, they say, a demon lord climbed the mountain to swallow the World Tree, and the night elves let the tree's whole strength go to stop him. Nobody here calls it a victory without pausing first.",
		"Archimonde reached the foot of Nordrassil and got no farther. The price was the tree's blessing and the elves' own forever. They paid it on the spot.",
	},
	["dar.muse.w23.hyjal.003"] = {
		"watches a kaldorei elder lower herself onto a step one joint at a time, and the young Sentinel beside her pretend, very carefully, not to notice.",
		"sees an old elf pause halfway up a stair to rest a hand on a knee, with the faintly puzzled look of someone whose body has started making new rules.",
	},
	["dar.muse.w23.hyjal.004"] = {
		"Nordrassil was planted with the blessing of the great dragons, the druids say. About Teldrassil they say other things, more slowly, and only to each other.",
		"When a druid compares Teldrassil to Nordrassil, there's a little silence where something should go. I've heard that silence three times now, and never filled.",
	},
	["dar.muse.w23.hyjal.005"] = {
		"A herbalist in this city sells salves for stiff joints to people who never had a stiff joint in ten millennia. Business, I'm told, has never been better.",
		"Before Hyjal, nobody in Darnassus needed a remedy for aching knees. Now the herbalists can't keep enough on the shelf. Mortality has its markets.",
	},
	["dar.muse.w23.hyjal.006"] = {
		"They traded forever to save the world. I'd say thank you, but I don't know whom to say it to.",
		"A whole people gave up living forever at Hyjal. The least I can do is wipe my boots.",
	},
	["dar.muse.w23.hyjal.007"] = {
		"When Archimonde fell, the druids say, it was the spirits of the kaldorei ancestors that pulled him down, thousands of small lights at once. The wisps in this city get very gentle treatment, and now I know why.",
		"A Sentinel told me the wisps that tore down Archimonde were the dead of her people, called up all at once. She said it the way one mentions that a grandparent helped build the house.",
	},
	["dar.muse.w23.hyjal.008"] = {
		"Very slightly, the kaldorei have started to hurry. A few more strides a minute than the elders. It's the smallest change in the world, and it is what losing immortality looks like from the outside.",
		"The younger kaldorei walk a shade faster than their elders, and I don't think they know it. Somewhere at Hyjal a clock started, and their feet heard it first.",
	},
	["dar.muse.w23.hyjal.009"] = {
		"passes a pair of priestesses binding a scraped knee on a little kaldorei, slowly and with great seriousness, as if the whole art of healing small hurts were still new to them.",
		"follows, with quiet interest, a priestess cleaning a child's scraped palm with grave attention, the child bearing it with the same gravity, both of them learning something.",
	},
	["dar.muse.w23.hyjal.010"] = {
		"A people who planned in millennia now have to plan in lifetimes. You can see the arithmetic going on behind their eyes when they plant a tree.",
		"Ten millennia of 'there will be time' ended at Hyjal. I've seen a kaldorei crafter set down a half-finished piece and stare at it, doing the new sums.",
	},
	["dar.muse.w23.hyjal.011"] = {
		"Since Nordrassil gave its strength, I count. Years, mostly. I never counted anything before, and I find I don't care for the habit.",
		"Before Hyjal, forever was simply the shape of things. Now I catch myself counting my years, the way the short-lived do, and I'm ashamed of how frightened it makes me.",
	},
	["dar.muse.w23.hyjal.012"] = {
		"Humans, orcs and night elves held one mountain together against Archimonde. Then they all went home and resumed hating each other. That's history, I suppose.",
		"For a few desperate weeks on Hyjal, orcs and elves fought side by side. The kaldorei mention it with an expression I can only call deeply puzzled.",
	},
	["dar.muse.w23.hyjal.013"] = {
		"Saved the world at Hyjal, gave up living forever, and they still sweep the steps as if nothing happened. Remarkable.",
		"Imagine stopping a demon lord, then coming home to find you've got knees now.",
	},
	["dar.muse.w23.hyjal.014"] = {
		"The druids here speak of a horn Malfurion sounded on Hyjal, and of the answer that came from every root and wisp on the mountain. They don't describe the sound. They just go quiet where it would be.",
		"In the Enclave the druids remember Hyjal by the horn: one long call, they say, and the whole forest rising. Every time someone tells it, the telling stops at the same place.",
	},
	["dar.muse.w23.hyjal.015"] = {
		"A Sentinel told me she used to think of every friendship as a long walk with no end in sight. Since Hyjal, she said, she has started saying goodbye properly.",
		"Since the immortality went, a priestess said, the kaldorei have learned the habit of farewell. They're still clumsy at it, she added, and smiled as if that were a kindness.",
	},
	["dar.muse.w23.hyjal.016"] = {
		"notices that whenever a priestess speaks the word Hyjal she turns her head a little to the south, the way one inclines toward a grave in passing.",
		"catches an elder Sentinel touching two fingers to her brow at the mention of Hyjal, a small gesture the younger ones nearby copy a moment late.",
	},
	["dar.muse.w23.hyjal.017"] = {
		"An elder here asked me, very seriously, how long a sprained ankle usually takes. All those millennia and she had never needed to know.",
		"A kaldorei asked me for advice about a head cold. I've been asked for directions, for coin, for help with a fight, but never to explain a sniffle to someone older than Stormwind.",
	},
	["dar.muse.w23.hyjal.018"] = {
		"I can still smell Hyjal burning when the incense in the temple is lit too strong. My sisters say they don't. I think they're being kind.",
		"There is a particular silence among us when the fires of Hyjal come up. Nobody looks away. Nobody speaks. We simply wait together until it passes.",
	},
	["dar.muse.w23.hyjal.019"] = {
		"Nordrassil still stands on Hyjal, scarred and quiet, the druids say. They speak of it as of an elder who gave all of their strength to the family and now sits by the fire.",
		"The druids visit Nordrassil, I'm told, the way you'd visit an old grandparent who doesn't speak much anymore. They come back gentle and say very little.",
	},
	["dar.muse.w23.hyjal.020"] = {
		"Hyjal held. Remember that, whenever things look hopeless.",
		"They broke a demon lord on that mountain. Whatever I'm facing, it's smaller.",
	},
	["dar.muse.w23.hyjal.021"] = {
		"The first generation of kaldorei to grow old is learning it from the races that always did. I've seen a dwarf explaining to an elf how to rub liniment into a shoulder, with enormous patience on both sides.",
		"Mortality has made the kaldorei curious about the short-lived. An elder asked me what it's like to know you'll die. I said 'busy', and she wrote it down.",
	},
	["dar.muse.w23.hyjal.022"] = {
		"is brushed by a drifting wisp, and sees the old Sentinel beside the path turn her head to follow it with an odd tenderness, as if it might be someone she knew.",
		"sees an elder stop to let a wisp pass and murmur something to it, very low, the way one greets a neighbor across a fence.",
	},
	["dar.muse.w23.isle.001"] = {
		"Across the lake it's a stone's throw. Around it, half an hour of polite paths. I am seriously considering swimming.",
		"The far shore is right there. The bridges go out of their way to visit every island first. Swimming starts to look like the honest road.",
		"Every bridge in this city is a detour with a view. I'd trade the view for a ferry.",
	},
	["dar.muse.w23.isle.002"] = {
		"eyes the lake between here and the far shore, then the long way round by the bridges, and visibly weighs the cost of wet boots against the walk.",
		"stands at the water's edge measuring the swim to the other side with a practiced eye, while a passing Sentinel, in turn, studies the scene.",
	},
	["dar.muse.w23.isle.003"] = {
		"Out on one of the little islands a lone tree leans over the water as if reading its own reflection. Nobody ever seems to go out there. I'd like to know who planted it.",
		"Some of the islands in the lake are no bigger than a room: a patch of moss, a stone, a lean young tree. They look kept, but I have never seen the keeper.",
	},
	["dar.muse.w23.isle.004"] = {
		"counts the islands from the shore and gets a different number each time, because some are only a rock with a fringe of reeds and some hide behind others.",
		"tries to count the islands in the lake, loses track among the small ones that are hardly more than a stone and a tuft of green, and gives it up.",
	},
	["dar.muse.w23.isle.005"] = {
		"A people who watched their land sink under the sea, and in the heart of their new city they made a lake with small, safe islands in it. I wonder whether that was a choice or a habit.",
		"Little islands that nobody can drown. Perhaps that's what the lake is for, for those who remember the world breaking.",
	},
	["dar.muse.w23.isle.006"] = {
		"Every island out there has one tree, one rock and one smug dragonfly. I envy all three.",
		"If I ever retire, I want one of those little islands. A rock, a tree, water all round. Nobody could ask me for directions.",
	},
	["dar.muse.w23.isle.007"] = {
		"Voices carry over the lake strangely. Two kaldorei talking quietly on the far shore sound as if they were standing at my elbow.",
		"Water carries sound like a tray carries cups. A word spoken softly on an island arrives at the bank whole and clear.",
		"Out on the water a laugh, very small and clear, crosses the whole lake without losing a note.",
	},
	["dar.muse.w23.isle.008"] = {
		"passes a kaldorei fishing from the lakeshore, line in the water, so motionless that a dragonfly has settled on the rod.",
		"stops a few paces behind an elf fishing at the water's edge and waits, without quite meaning to, to see whether anything will bite. Nothing does. Neither of them minds.",
		"lingers as a kaldorei fisher draws in an empty line, studies the bare hook for a long while, and sends it back into the water without a trace of disappointment.",
	},
	["dar.muse.w23.isle.009"] = {
		"How deep is that lake, do you think? No, don't tell me. I'd only want to find out.",
		"Asked a Sentinel how deep the lake goes. She said 'deep enough'. I think that was a warning.",
		"I could ask how deep the lake is. Or I could keep a little mystery in my life.",
	},
	["dar.muse.w23.isle.010"] = {
		"leans over a bridge rail, considers spitting into the lake for no reason at all, glances at the nearest Sentinel, and thinks better of it.",
		"lets a long idle moment pass on a bridge, chin on the rail, then catches {g:his|her} own reflection pulling a face and straightens up at once.",
	},
	["dar.muse.w23.isle.011"] = {
		"Look straight down from a bridge for long enough and the mirrored leaves start to pull. For a moment it feels as if I could fall upward into the lake.",
		"Below the rail, the lake shows the boughs in reverse, deep and green. Stare at it and the city tilts; I hold the rail and wait for it to stop.",
		"The mirrored canopy is so deep and still that the bridge seems to hang between two forests, one of them upside down.",
	},
	["dar.muse.w23.isle.012"] = {
		"watches a druid wade knee-deep in the shallows near an island, robes knotted at the hip, pull something out of the water by the roots and frown at it.",
		"notices a druid standing in the shallows of the lake with robes hitched up, inspecting a handful of dripping weed with the face of a healer reading a wound.",
	},
	["dar.muse.w23.isle.013"] = {
		"Coin changing hands this close to running water. One fumble and somebody's silver takes the long way to the sea.",
		"Counting money next to a stream makes me nervous. One slip and my savings go sightseeing down the trunk.",
	},
	["dar.muse.w23.isle.014"] = {
		"However far I wander, the sound of this water settles something in me. Not home as a place. Home as a sound.",
		"No fountain anywhere else in the world sounds like the ones here. I'd know them with my eyes shut, in my sleep, after a hundred years.",
	},
	["dar.muse.w23.isle.015"] = {
		"watches two Sentinels cross a bridge side by side, their reflections walking upside down beneath them, step for step, without a ripple.",
		"sees a priestess cross a footbridge so smoothly that her reflection below never wavers once.",
	},
	["dar.muse.w23.isle.016"] = {
		"The lake up here is so calm it's hard to believe the same world holds the sea around the roots, gnawing at the bark. Two waters, one tree, and they never look at each other.",
		"Calm lake above, restless sea below, and the whole height of Teldrassil between them. The tree keeps the two waters apart like a patient host seating rivals at opposite ends of the table.",
	},
	["dar.muse.w23.isle.017"] = {
		"That little island has a bridge all to itself, and nothing on it but moss. I respect a city that builds a bridge just to visit moss.",
		"A whole bridge, to reach one patch of moss. In Darnassus that's not extravagance, it's courtesy.",
	},
	["dar.muse.w23.kaldorei.001"] = {
		"hears a druid in cat shape stop on the path, become an elf again just long enough to finish a sentence to a friend, and drop back onto four paws to go on.",
		"overhears a conversation between two elves in which one of them is, for a while, a large cat, and nobody involved finds this worth remarking on.",
		"notices a cat padding beside a Sentinel, and only when it stops to sneeze in a very elven way realizes it was a druid all along.",
	},
	["dar.muse.w23.kaldorei.002"] = {
		"A druid who scratches behind one ear as an elf does the very same thing as a bear. Some habits go deeper than shape.",
		"I watched a druid fidget with her sleeve, change into a bear, and keep fidgeting, with a paw, at a sleeve that wasn't there anymore.",
	},
	["dar.muse.w23.kaldorei.003"] = {
		"Where do a druid's clothes go when she becomes a cat? I asked one. She said it was a very rude question, and smiled.",
		"Nobody will tell me where a druid's boots go while he's a bear. I've asked three times and been given three different smiles.",
	},
	["dar.muse.w23.kaldorei.004"] = {
		"notices that the druid ahead walks barefoot on the stone, toes curling a little at each step, as though reading the path with them.",
		"glimpses a druid stop to slip off her sandals before stepping onto the grass, and carry them the rest of the way.",
		"comes upon a druid halted on the path, pressing a palm flat to the grass the way one checks a sleeping child's brow, then walking on satisfied.",
	},
	["dar.muse.w23.kaldorei.005"] = {
		"A Sentinel told me, very dryly, that the druids slept through most of history and still take a nap whenever they can. She did not sound like she was joking.",
		"There's a small, old joke among the Sentinels about druids and sleep. I've heard it twice, told in exactly the same words, and both times the teller didn't smile.",
	},
	["dar.muse.w23.kaldorei.006"] = {
		"Here in the Enclave the druids keep their own hours. One is deep in study, another flat on the grass with eyes shut, and it is impossible to tell which works harder.",
		"Nobody in the Enclave seems to be doing anything, and everyone is busy. A druid lying in the grass with eyes closed was described to me as 'in a meeting'.",
	},
	["dar.muse.w23.kaldorei.007"] = {
		"A kaldorei leatherworker measures, waits, measures again, and then waits some more. The cut, when it comes, is a single stroke.",
		"I watched someone at a workbench study a hide for so long that I drifted off. When I came back the work was done, and done perfectly, in what must have been a moment.",
		"Kaldorei craft is mostly waiting. Then a single movement, exactly right, and back to the waiting.",
	},
	["dar.muse.w23.kaldorei.008"] = {
		"pauses beside a fletcher trimming feathers with a tiny knife, each cut matched to the last so closely that the arrows look like copies of one another.",
		"stands a while by a workbench where a kaldorei is fixing feathers to shafts, holding each one in place long past the moment any glue could need.",
	},
	["dar.muse.w23.kaldorei.009"] = {
		"I offered to buy a cloak off a kaldorei tailor's table. Not finished, I was told. It looked finished. It will apparently go on looking finished for another season or two.",
		"Some of the work on the crafters' tables isn't for sale yet, and 'yet', in this city, can mean a very long time.",
	},
	["dar.muse.w23.kaldorei.010"] = {
		"looks on as a leatherworker here on the terrace works oil into a hide with the heel of one hand, slow circles, the same circle for a very long time.",
		"stops on the terrace by a craftswoman winding thread back onto a spool after a mistake no one else would have noticed, undoing a long stretch of work without a sigh.",
	},
	["dar.muse.w23.kaldorei.011"] = {
		"The kaldorei mend everything. A torn strap gets new stitches, not a new strap. When your things have to last centuries, I suppose you learn to love a needle.",
		"I've never seen a kaldorei throw anything away. Cracked bowls get bound, worn soles get new leather. Things here are expected to grow old alongside their owners.",
		"My boots were resoled by a kaldorei cobbler while I waited. Then resoled again, because the first attempt was merely 'adequate'.",
	},
	["dar.muse.w23.kaldorei.012"] = {
		"Take your time. No, really, I can see you're going to.",
		"Is it finished? Don't answer. I can tell by your face that it's a philosophical question.",
		"Beautiful work. How long did it take? No, don't tell me. I'd only feel lazy.",
	},
	["dar.muse.w23.kaldorei.013"] = {
		"Some kaldorei have started to walk a little faster since Hyjal. Not much. A Sentinel told me it's because the years finally count.",
		"Impatience is new among the kaldorei, a priestess said. Since immortality was given up at Hyjal, a few of the young have caught it the way you catch a chill.",
	},
	["dar.muse.w23.kaldorei.014"] = {
		"Kaldorei remember faces. A merchant greeted me by name after a single visit, months apart. I can't decide whether that's flattering or alarming.",
		"Meet a kaldorei once and they'll know you the next time, and the time after that. Their memories seem to have a great deal of room in them.",
	},
	["dar.muse.w23.kaldorei.015"] = {
		"The kaldorei are good at being alone in company. Three of them can share a patch of grass without a word and look like the best of friends.",
		"Silence between kaldorei isn't awkward. Two of them stood by me a long while saying nothing, and only I felt it needed filling.",
	},
	["dar.muse.w23.kaldorei.016"] = {
		"Deep in the night the workbenches are busier than they were by day. The kaldorei craft best when the light is low, or so a leatherworker told me without looking up.",
		"The city's hands are busiest in the dark. Needles, awls and mortars all going quietly, as if the work had only been waiting for the sun to leave.",
	},
	["dar.muse.w23.kaldorei.017"] = {
		"notices a Sentinel on watch with her eyes narrowed against the bright day, the only sign she gives that this is not her hour.",
		"catches a priestess drawing her hood a little forward against the glare of the day, as though the sun were a guest who talks too loudly.",
	},
	["dar.muse.w23.kaldorei.018"] = {
		"The kaldorei don't hurry for the rain. They walk through it at the same pace, hoods down, as if getting wet were simply part of the walk.",
		"Rain, and not one kaldorei breaks into a run. A Sentinel stood out in it at her post with water running off her chin, looking almost pleased.",
	},
	["dar.muse.w23.kaldorei.019"] = {
		"The visitors watch us as if we were slow. We are not slow. We were simply never late for anything before.",
		"Strangers think we dawdle. We were taught by people who had forever, and we have not unlearned it. Perhaps we shouldn't.",
	},
	["dar.muse.w23.kaldorei.020"] = {
		"Every Sentinel I pass could have been at Hyjal. Some of them were. I nod to all of them the same, because I cannot tell which.",
		"I bow to the Sentinels a little deeper than outsiders do. They kept the forests while the rest of us dreamed or forgot. It is the least owed.",
	},
	["dar.muse.w23.kaldorei.021"] = {
		"Slow down. The city isn't going anywhere, and neither are we.",
		"Walk with me a while. There's no hurry here, not for us.",
	},
	["dar.muse.w23.kaldorei.022"] = {
		"Every Sentinel here has a glaive and a long memory. I keep my eyes down and my manners perfect.",
		"I've learned to walk slowly in this city. Nothing marks a stranger faster than hurry, and I can't afford for anyone to look twice.",
	},
	["dar.muse.w23.kaldorei.023"] = {
		"Excuse me, are you a druid or a very calm bear? I'd like to address you properly.",
		"If that cat answers me, I'm going to need to sit down.",
		"That cat just nodded at me. I'm nodding back. I've decided not to think about it.",
	},
	["dar.muse.w23.kaldorei.024"] = {
		"watches a druid in bear shape wait very patiently in line at a merchant's stall, then become an elf at the front just long enough to pay.",
		"turns in time to see a druid shift from cat to elf in the middle of a step, and finish the step on two feet as though nothing whatever had changed.",
		"stands behind a bear in the queue for a stall, and is only mildly surprised when it reaches the counter, stands up into a druid, and asks for thread.",
	},
	["dar.muse.w23.manner.001"] = {
		"A kaldorei described an old quarrel as 'quite recent'. It had started, as far as I could tell, before anyone in Stormwind could read.",
		"'Not long ago,' says a kaldorei, and I've learned to ask: not long ago for whom? The answer is usually a few centuries.",
		"'Lately', from a kaldorei, is a mountain's word. I've stopped asking for dates.",
	},
	["dar.muse.w23.manner.002"] = {
		"Kaldorei leave a gap after you stop speaking, in case you weren't done. I'm rarely done. It's making me say more than I meant to.",
		"Nobody here interrupts. Finish a sentence and there's a polite little silence, waiting to see whether another one is coming. I keep filling it.",
		"Speak to a kaldorei and you'll get your whole say, every time, and then a small pause, in case you'd like to take any of it back.",
	},
	["dar.muse.w23.manner.003"] = {
		"drops a glove on the path and has it handed back by a passing kaldorei, held out across both palms as though it were something precious.",
		"lets a coin slip and roll, and a kaldorei passer-by stops it with a foot, picks it up and returns it with a small bow, as if apologizing to the coin for the trouble.",
		"brushes a kaldorei's sleeve in passing, apologizes, and receives in return an apology twice as long.",
	},
	["dar.muse.w23.manner.004"] = {
		"Ask a kaldorei how old they are and they'll answer in round numbers. Very round.",
		"I asked an elf her age. She gave me a century, plus or minus one. I didn't ask which century.",
		"How old? No, don't tell me. I'd only lose count.",
	},
	["dar.muse.w23.manner.005"] = {
		"I keep seeing kaldorei touch a doorpost on their way in, lightly, with two fingers. Nobody has explained it, and I haven't liked to ask.",
		"Two fingers to the doorframe going in, every time, from Sentinels and merchants alike. Maybe a courtesy to the wood. Maybe just habit. I've started doing it too.",
	},
	["dar.muse.w23.manner.006"] = {
		"A kaldorei trader told me to come back 'when the new stock is in'. She meant in about three years, and she meant it kindly.",
		"Come back later, said the merchant. With a kaldorei, I've learned to ask: later this season, or later this century?",
	},
	["dar.muse.w23.manner.007"] = {
		"watches two kaldorei meet on the path and stand a long moment with their foreheads almost touching, saying nothing, before going their separate ways.",
		"sees two old friends meet on the path: no embrace, no clasped hands, just a long look and a slow shared nod, as though picking up a talk left off long ago.",
		"observes two kaldorei grip each other's forearms for the space of a few words, then let go at the same instant, as if by agreement.",
	},
	["dar.muse.w23.manner.008"] = {
		"Everyone here moves like they're carrying something full to the brim.",
		"I've seen faster glaciers. Prettier ones, no.",
		"Pardon me, I'll just overtake you. Slowly. Respectfully. Over the next while.",
	},
	["dar.muse.w23.manner.009"] = {
		"Thank you. No, slower. Thank you.",
		"Thank you, truly. There, I said it slowly. I'm learning.",
		"Thank you. I mean it, even if I said it fast.",
	},
	["dar.muse.w23.manner.010"] = {
		"I repeated myself to a kaldorei once, to be sure. She looked puzzled and said she had heard me the first time. It wasn't a rebuke. It was a fact.",
		"Repeat yourself to a kaldorei and you get a patient look, as if you'd handed over the same coin twice. They listen hard, and expect to be listened to the same way.",
	},
	["dar.muse.w23.manner.011"] = {
		"asks a passing kaldorei the way and receives, after a pause long enough to wonder, an answer complete down to the number of turns.",
		"puts a quick question to a kaldorei and waits through a silence that seems to be weighing it carefully, before a full, careful answer arrives.",
		"asks a kaldorei something simple and gets the answer, plus the reason for it, plus a short and courteous warning about the second turning.",
	},
	["dar.muse.w23.manner.012"] = {
		"Kaldorei don't point. They turn the whole hand, palm up, toward where you should go, as if presenting the path to you.",
		"Directions here come with an open hand, offered like a gift you can walk along. I've yet to see a kaldorei point a finger at anything.",
		"I've noticed the kaldorei never point at a person. Not once. A Sentinel looked at me sideways when I did it, and I've stopped.",
	},
	["dar.muse.w23.manner.013"] = {
		"I've heard Elune's name in the middle of a haggle, a scolding and a joke, said each time as easily as you'd say a friend's.",
		"The goddess turns up in ordinary kaldorei talk the way a neighbor's name does elsewhere: a word in passing, never a sermon.",
	},
	["dar.muse.w23.manner.014"] = {
		"observes a kaldorei take leave of a friend: a word, a turn, and no glance back, the parting finished as cleanly as a knot.",
		"notices that kaldorei friends part without lingering, one quiet word and two backs turned, as if both are sure there will be time enough to meet again.",
	},
	["dar.muse.w23.manner.015"] = {
		"Kaldorei goodbyes are short, as if another meeting were certain. For most of their history it was. Since Hyjal, I wonder whether the habit has started to hurt.",
		"For people who never had to fear running out of time, a farewell didn't need to be long. They lost that at Hyjal, but the short farewells stayed.",
	},
	["dar.muse.w23.manner.016"] = {
		"I've started bowing to shopkeepers. Help.",
		"I just apologized to a door for bumping it. This city is getting to me.",
		"I said 'excuse me' to a tree. In my defense, it might have been listening.",
	},
	["dar.muse.w23.manner.017"] = {
		"Kaldorei speak Common like people handling borrowed glassware: precisely, a little stiffly, and with great care not to drop a word.",
		"Their Common is better than mine, and slower. Every word set down on purpose, nothing slurred, nothing swallowed. Listening, I feel sloppy.",
		"Kaldorei Common has edges I never noticed in my own mouth. Every consonant gets its full due.",
	},
	["dar.muse.w23.manner.018"] = {
		"A kaldorei's glance lasts about one beat longer than anyone else's. Not rude. Just thorough.",
		"They hold a look a little past the point where most folk would glance away. I've learned to hold it back. It feels like losing a slow game either way.",
	},
	["dar.muse.w23.manner.019"] = {
		"notices the kaldorei listening to {g:him|her} with ears angled forward, the way a cat's turn toward a sound, and tries to say something worth the attention.",
		"sees the long ears of a kaldorei merchant dip slightly while the price is discussed, and suspects they say more than the merchant does.",
		"catches a kaldorei's ear flicking toward a distant voice in the middle of their talk, and waits politely while the rest of the elf catches up.",
	},
	["dar.muse.w23.manner.020"] = {
		"Watch the ears, a Sentinel told me, if you want to know what a kaldorei really thinks. She said it with her ears perfectly still.",
		"I've been told kaldorei ears give them away. The one who told me kept hers so still that it must have been a lesson in that too.",
	},
	["dar.muse.w23.manner.021"] = {
		"Wrapped in a leaf and a twist of grass, folded so neatly I almost didn't want to open it: that's how a kaldorei merchant hands over a purchase.",
		"My purchase came wrapped in cloth, tied with a knot I couldn't undo without a lesson. The merchant showed me. It took a while. Nobody minded.",
		"Even a handful of nails is wrapped like a gift in this city. The merchant folded the cloth, tucked the corners, and handed it over as if it held something rare.",
	},
	["dar.muse.w23.manner.022"] = {
		"Sorry. Too fast? I'll start over, slower.",
		"Was that rude? I can never tell with you lot. You're all so polite about it.",
		"Did I just say that too loudly? I can tell by the owls.",
	},
	["dar.muse.w23.manner.023"] = {
		"Here among the merchants of the terrace a sale is closed with a small mutual nod, never a handshake. I offered my hand once, and it was looked at with polite interest, like a curious seashell.",
		"On this terrace nobody shakes on a deal. A nod from each side, a little bow, and it's settled as surely as any contract.",
		"Prices on this terrace are named once, quietly, and not repeated. Haggling is allowed; raising your voice to do it is not.",
	},
	["dar.muse.w23.manner.024"] = {
		"Anywhere else I'd call it cold: a long look, a nod, and nothing more. Among the kaldorei, I've learned, that's practically an embrace.",
		"They don't hug, they don't slap backs, they don't ask after your health. The kaldorei show regard by remembering your name a year later.",
	},
	["dar.muse.w23.manner.025"] = {
		"For the directions, thank you. I'll get lost more slowly now.",
		"You've been very patient with me. I'll try to be worth it.",
		"That's the same question answered twice, and both times as if it were new. Thank you.",
	},
	["dar.muse.w23.manner.026"] = {
		"Could everyone speak up a little? No? No. Of course not.",
		"I've been whispering for an hour and nobody asked me to. It's catching.",
	},
	["dar.muse.w23.moss.001"] = {
		"Moss grows on everything here that holds still long enough. I've started shifting my weight now and then, just to be sure.",
		"Sit on a step in Darnassus for long enough and the moss starts measuring you. I got up before it could finish.",
	},
	["dar.muse.w23.moss.002"] = {
		"watches a snail make its way along the rail of a bridge, and realizes after a while that it is gaining on a pair of elderly druids walking the same way.",
		"follows the progress of a snail across a carved step, and loses interest only when it becomes clear the snail has a better sense of direction.",
		"sets a fallen leaf down in front of a snail as a bridge over a puddle, and the snail goes around it with perfect serenity.",
	},
	["dar.muse.w23.moss.003"] = {
		"The mushrooms among the roots glow, faint blue in the shade. In any other city I'd take that as a sign to stop eating whatever I'd just eaten.",
		"Little blue mushrooms shine at the foot of the walls, like lamps for creatures smaller than mice. Someone in this city lights everything, including the floor.",
	},
	["dar.muse.w23.moss.004"] = {
		"Don't step on the mushrooms. I don't know why. It just feels like the kind of city that would remember.",
		"Mind the mushrooms. Nobody told me to, but this place has a long memory, and I'd rather not be in it for that.",
	},
	["dar.muse.w23.moss.005"] = {
		"A fern by the path is unrolling a single frond, so slowly that I'd swear it hasn't moved, the way you'd open a letter you weren't sure you wanted to read.",
		"Young ferns curl beside the steps like the scrolls of violins. Come back after a few days and one of them has opened, very slightly, as if trying not to be noticed.",
	},
	["dar.muse.w23.moss.006"] = {
		"presses a palm into the moss beside the path and watches the print fill in again, slowly, until there is no sign that anyone was ever there.",
		"sinks a hand into a thick cushion of moss up to the knuckles, and draws it out cool and damp and faintly fragrant, as if from a basin.",
		"runs a thumb along the moss on a railing and finds it trimmed, very slightly, to an even height, like the beard of a careful old dwarf.",
	},
	["dar.muse.w23.moss.007"] = {
		"There's a little beetle here with a shell the exact color of a priestess's robe. Jewelers in Stormwind, I'm told, charge a fortune for less.",
		"A beetle crossed my boot with a back like polished violet glass. If the gnomes ever learn to make enamel that fine, they'll be insufferable.",
	},
	["dar.muse.w23.moss.008"] = {
		"The pale stone here is already gathering lichen in gray-green rings. A young city, everyone says. The lichen hasn't been told.",
		"Lichen has started on the railings, small gray rosettes spreading out from the corners. Give it a few centuries and Darnassus will look as old as its people.",
	},
	["dar.muse.w23.moss.009"] = {
		"Somebody should tell the moss this is a city. It thinks it's a forest with ambitions.",
		"The moss is winning. Nobody here seems to mind, so I won't either.",
	},
	["dar.muse.w23.moss.010"] = {
		"crouches to watch a line of ants carry crumbs along the edge of a step, the busiest folk on the whole terrace by a wide margin.",
		"stops for a file of ants hauling a crust of bread twice their size along a crack in the stone, and moves only once the last of them is past.",
	},
	["dar.muse.w23.moss.011"] = {
		"Under all the quiet there's a small, steady ticking in the moss: crickets, beetles, things I can't name, keeping time for a city that doesn't bother.",
		"Listen closely and the lawns are full of tiny noises: a click, a rasp, a whir of wings. Darnassus is quiet only because everything here speaks so small.",
	},
	["dar.muse.w23.moss.012"] = {
		"Where I come from, moss means damp walls and a landlord who won't fix the roof. Here they tend it like a lawn and would probably fine me for scuffing it.",
		"In most cities moss is what you scrape off. In Darnassus it's what you step around, carefully, apologizing under your voice.",
	},
	["dar.muse.w23.moss.013"] = {
		"steps around a ring of small pale mushrooms on the lawn, and notices that every elf passing makes the same small detour without seeming to think about it.",
		"notices a perfect circle of tiny mushrooms in the grass, and a druid walking past who lengthens one stride just enough to keep from setting foot inside it.",
	},
	["dar.muse.w23.moss.014"] = {
		"Under the dripping leaves the moss drinks and swells until every step sinks in a little, and the print fills with a small clear pool behind me.",
		"The rain reaches the moss at last, drop by fat drop, and the whole city starts to smell like the inside of a forest after a long wait.",
	},
	["dar.muse.w23.moss.015"] = {
		"Moss in Ironforge grows in the corners nobody sweeps. Here they'd sooner sweep me than the moss, and they'd do it politely.",
		"Back under the mountain, moss on the stonework means someone's slacking. Here it means someone's been working very hard. I'll never get used to it.",
	},
	["dar.muse.w23.moss.016"] = {
		"stops in the Enclave beside a fallen branch left exactly where it dropped, now furred green and sprouting mushrooms, which the druids step over as if over a guest asleep.",
		"passes a fallen bough here in the Enclave that nobody has cleared away; moss has taken it, ferns have taken the moss, and a druid sits on the end of it, reading.",
	},
	["dar.muse.w23.moss.017"] = {
		"A caterpillar is eating its way across a leaf as big as a cloak, without any hurry. At this rate it will finish the crown in a few thousand years. It seems to know that.",
		"On one of the great leaves a green caterpillar is chewing a neat crescent out of the edge. It has the whole tree in front of it and the manners of a guest at a long dinner.",
	},
	["dar.muse.w23.moss.018"] = {
		"Dew stands on the moss at every hour here, beaded so fine it looks like frost until you touch it. Nothing in this city ever quite dries out.",
		"Kneel by any step in Darnassus and the moss is jeweled with tiny drops. I've never once seen it dry. I'm not sure the tree would allow it.",
	},
	["dar.muse.w23.moss.019"] = {
		"This moss is softer than any bed I've ever paid for. I'm trying not to make a matter of principle of it.",
		"If I lie down on the moss, will someone fine me or tuck me in? In this city it could go either way.",
	},
	["dar.muse.w23.moss.020"] = {
		"That snail has passed me twice. I'm choosing to believe it's going in circles.",
		"Don't mind me. I'm racing a snail, and losing.",
	},
	["dar.muse.w23.owl.001"] = {
		"Half the arches in this city are carved with owls, and the real owls sit on top of them. I can't decide whether that's a tribute or a complaint.",
		"Over a doorway there's an owl perched on a stone owl, matching it in every line, except that one of them blinks.",
		"Carved owls on the railings, carved owls on the eaves, and a live one sitting on the carving, looking faintly superior to it.",
	},
	["dar.muse.w23.owl.002"] = {
		"watches an owl preen on a high ledge until one small soft feather comes loose and spirals all the way down to the path, where a passing elf steps carefully around it.",
		"looks up as a downy feather drifts out of the boughs, turning slowly, and traces it back to an owl grooming itself high above with great seriousness.",
		"sees a feather the length of a finger settle on the water of a stream, and an owl above watching it float away with mild regret.",
	},
	["dar.muse.w23.owl.003"] = {
		"That owl has followed me from roof to roof. Either I'm fascinating, or I owe it money.",
		"Same owl, third rooftop. I'm being tailed by something with better eyesight than any spy in Stormwind.",
	},
	["dar.muse.w23.owl.004"] = {
		"The owls here aren't ornaments. I watched one take a mouse off the edge of a grain sack, so neatly the crafter beside it never looked up.",
		"For all their solemn faces, the city's owls are working birds. A mouse grew too bold near the Craftsmen's Terrace, and an owl settled the matter in one silent drop.",
		"The Sentinels claim the city owls take only vermin and never the songbirds. I can't vouch for it, but the songbirds here are remarkably relaxed.",
	},
	["dar.muse.w23.owl.005"] = {
		"A Sentinel told me she can tell what an owl has been eating from what it leaves under its perch. I thanked her and did not ask for a demonstration.",
		"According to a Sentinel I spoke with, the little gray pellets under every owl's perch are a whole ledger of the city's mice. She found that fascinating. I walked around them.",
	},
	["dar.muse.w23.owl.006"] = {
		"notices a winged shape cross a gap in the canopy far overhead, a hippogryph by the cut of it, gone before the leaves close again.",
		"glimpses a hippogryph through a break in the great leaves, wings spread wide and unmoving, sliding across the green like a thought too large for the city.",
		"catches the brief dark of a hippogryph's shadow passing over the leaves above, and the faint dimming of the green light just after it.",
	},
	["dar.muse.w23.owl.007"] = {
		"Above the crown a hippogryph cries out, a sound like a hawk with a much bigger opinion. Nobody on the path even glances up.",
		"That shriek from over the leaves is a hippogryph, a Sentinel assured me. She said it the way you'd mention a neighbor's noisy goat.",
	},
	["dar.muse.w23.owl.008"] = {
		"An owl crossed the path at the height of my face and I heard nothing, not the faintest stir of wings. I've known cats that were louder.",
		"Owl flight makes no sound at all. One went by close enough to touch, and I only knew because the lamp behind it went out for an instant.",
		"Something passed my ear like a thrown cloak, without a whisper. By the time I turned, the owl was already folding itself onto a rail.",
	},
	["dar.muse.w23.owl.009"] = {
		"I asked an owl for directions. It looked at me as if to say: and who are you? Fair question, some days.",
		"Excuse me, owl. The bank? No? Then stop looking at me as if I'm the one who doesn't know the way.",
	},
	["dar.muse.w23.owl.010"] = {
		"An owl on the temple eaves. The old Sentinels call them the goddess's other eyes, and I still find myself standing straighter when one is watching.",
		"Some of the older Sentinels say Elune keeps owls the way a captain keeps scouts. I've never asked if they mean it. I nod to the owls all the same.",
	},
	["dar.muse.w23.owl.011"] = {
		"stops to watch three small birds bathe in a carved stone basin, throwing up more water between them than seems possible.",
		"lingers by a stone basin where a handful of little brown birds take turns at their bath, each shaking itself out with enormous self-importance.",
		"watches a tiny bird perch on the lip of a basin, study its own reflection, and decide that the bath can wait after all.",
	},
	["dar.muse.w23.owl.012"] = {
		"Someone shaped the curve of an eave around a nest instead of clearing it away. The roof bends a little there, just enough, like a hand cupped around a candle.",
		"There's a nest tucked into the bend of a roof above the path, and the living wood has grown around it like a sleeve. Whoever tends that roof decided the birds were there first.",
		"A nest in the eaves, and the eave itself curved to hold it. In most cities somebody would have fetched a ladder and a broom.",
	},
	["dar.muse.w23.owl.013"] = {
		"Now and then a hippogryph passes low over the crown and the leaves shiver all at once. Everyone below goes on with their business, except me, standing there with my mouth open.",
		"The hippogryphs come over the canopy so low you can feel the wingbeats in your teeth. The kaldorei don't look up. I always look up.",
	},
	["dar.muse.w23.owl.014"] = {
		"The owls in this city have better posture than I do. And better manners.",
		"Look at that owl. Not a feather out of place. I've never been that composed in my life.",
	},
	["dar.muse.w23.owl.015"] = {
		"An owl is asleep on a railing in plain view of everyone, one eye open by the thinnest sliver. It's the most relaxed guard in Darnassus, and probably the most alert.",
		"That owl on the rail looks fast asleep, but the slit of one eye has followed me the whole length of the bridge.",
	},
	["dar.muse.w23.owl.016"] = {
		"watches an owl drop out of the dark of the boughs and skim the lake so low its wingtips nearly touch, then climb away with something small kicking in its grip.",
		"hears nothing at all, and then sees an owl rise from the lawn with its catch, a pale shape folding back into the dark between the branches.",
	},
	["dar.muse.w23.owl.017"] = {
		"A bird up in the boughs has learned the clink of a Sentinel's armor and repeats it perfectly. Twice now I've turned around to greet nobody.",
		"There's a bird above the path that does a fair imitation of a Sentinel's buckles. The Sentinels ignore it. I've stepped aside for it twice.",
	},
	["dar.muse.w23.owl.018"] = {
		"Here in the Temple Gardens the small birds have quite stopped fearing anyone. One just walked across my boot to reach a seed, and didn't apologize.",
		"The birds in these gardens hop right up to the path, bold as beggars at a feast. Nobody here has ever given them a reason to be afraid.",
		"In these gardens a sparrow perched on the rim of my cup as if it had been invited, and drank first.",
	},
	["dar.muse.w23.owl.019"] = {
		"pauses beneath a tree where two owls sit shoulder to shoulder on one branch, and gets the distinct impression of having interrupted a conversation.",
		"walks under a pair of owls perched side by side, both of whom stop whatever they were doing to watch {g:him|her} go by, in perfect unison.",
	},
	["dar.muse.w23.owl.020"] = {
		"Who taught the owls in this city to look so disappointed? I'd like a word with them.",
		"Every owl here looks at me like a tutor handed back a poor essay.",
	},
	["dar.muse.w23.owl.021"] = {
		"If one more hippogryph shakes the leaves down onto my head, I'm sending the bill to Rut'theran.",
		"Leaves falling on my head? Just a hippogryph going over. Up here that passes for news.",
	},
	["dar.muse.w23.pool.001"] = {
		"waits while a priestess leans over a still pool and lifts out a single fallen leaf with two fingers, as if removing a hair from someone's sleeve.",
		"pauses while a kaldorei woman fishes a drifting leaf out of a basin, shakes it once, and lays it on the grass beside the water.",
		"stops beside a basin as an elderly kaldorei scoops a few floating petals out with a cupped palm and scatters them, gently, back among the flowers.",
	},
	["dar.muse.w23.pool.002"] = {
		"That pool looks ankle-deep. I'd bet good silver it isn't.",
		"Clear water lies about its depth. Test it with a stick, friend, not a boot.",
		"Rule for Darnassus: if you can see the bottom, the bottom is farther down than you think.",
	},
	["dar.muse.w23.pool.003"] = {
		"The priestesses say the moonwell keeps what it sees. I stand at its edge a little straighter, just in case.",
		"Here in the temple the well's water never seems to stir. A priestess told me nobody drinks from it without asking first; she didn't say whom.",
		"The priestesses walk around the moonwell, never across its edge, never with their backs to it for long. I copy them without knowing why.",
	},
	["dar.muse.w23.pool.004"] = {
		"kneels by the rim of a basin and finds the pale stone still crisp at its edges, not yet worn by the hands that will lean here for centuries.",
		"runs a thumb along the lip of a pool and feels how sharp the carving still is, a new city's stone that nobody has yet had time to smooth.",
		"rests a palm on the edge of a basin where the stone is still crisp and new, and seems to picture the hollow a thousand years of hands will wear into it.",
	},
	["dar.muse.w23.pool.005"] = {
		"Not a scum of green on any pool, not one floating feather, no smell of standing water at all. Somebody tends these. I have never once caught them at it.",
		"Still water ought to go stale. In Darnassus it simply doesn't, and nobody I ask seems to find that worth explaining.",
		"Every basin in the city is clean enough to drink from, and I have never seen anyone scrub one. Either the water cleans itself or someone gets up very early.",
	},
	["dar.muse.w23.pool.006"] = {
		"Not a single coin at the bottom of any pool in this city. Either nobody here wishes for anything, or they know better than to pay for it.",
		"Clean pools, empty bottoms. Most places, people toss copper into fountains. Here they'd fish it out and hand it back.",
		"Not one coin in any of these fountains. I've half a mind to start the custom myself. I'd probably be arrested.",
	},
	["dar.muse.w23.pool.007"] = {
		"Put a wrist in a basin to cool it and the cold climbs straight to the elbow. Whatever feeds these pools comes from somewhere deep.",
		"The water in the basins is colder than the air has any right to make it. Dip a hand and it aches before it gets used to it.",
		"Cold enough to numb the fingers, these pools. Pretty to look at; I wouldn't sit in one for a purse of gold.",
	},
	["dar.muse.w23.pool.008"] = {
		"watches a Sentinel bend over a quiet pool to settle her hair and straighten a strap, using the water as a mirror, then walk on as if nothing were more natural.",
		"notices a kaldorei crafter checking the set of a circlet in the still surface of a basin, turning the head a little left, a little right.",
		"observes a Sentinel stoop at a still basin to check a smudge on her cheek in the water, wipe it off with a thumb, and straighten up as if she had never stopped.",
	},
	["dar.muse.w23.pool.009"] = {
		"Lean over a still pool here and the face that looks back is very clear and rather tired. The water doesn't flatter, and it doesn't lie either.",
		"My own reflection in a basin, sharp as a portrait. I look like someone who has walked a long way, which is fair.",
		"These pools are honest mirrors. I'd forgotten that particular crease between my eyes.",
	},
	["dar.muse.w23.pool.010"] = {
		"Priestesses carry water from the city's pools in shallow bowls, both hands, eyes on the surface, never spilling. I've seen soldiers carry less care into a battle.",
		"A priestess passes with a bowl of water held level in both palms, slow as a procession of one. Not a drop leaves the rim.",
		"Water for the temple is never carried at a run. I watched a priestess take the long path around the lake rather than risk a spill on the short one.",
	},
	["dar.muse.w23.pool.011"] = {
		"Some of the eldest among us never sit by the lake. They remember another water, very deep and very bright, and what came up out of it.",
		"Clear water to the bottom, everywhere in this city. I think some of us need to see all that water holds. The Well taught us that, long ago, and at a terrible price.",
	},
	["dar.muse.w23.pool.012"] = {
		"A Sentinel told me the pools are for looking at and the running water is for drinking. She said it as if any child would know it.",
		"Drink from the streams, not the basins: that's what a Sentinel told me when she saw me kneel. She didn't say why, and I didn't ask twice.",
		"Drink from what moves, look into what's still. That was a Sentinel's advice, given in passing, as though she gave it every day.",
	},
	["dar.muse.w23.pool.013"] = {
		"drops a leaf into a basin to see which way the water goes, and watches it turn one slow circle and stay exactly where it fell.",
		"sets a leaf afloat on a quiet pool and waits for it to drift somewhere; after a while it becomes clear the leaf has no plans.",
		"flicks a fallen petal onto a still basin and waits for it to go anywhere at all. It sits on the surface, perfectly content, going nowhere.",
	},
	["dar.muse.w23.pool.014"] = {
		"Here in the Gardens the water is part of the planting. Streams run between the beds on purpose, and every flower seems to lean toward the nearest one.",
		"The gardeners here water nothing by hand. The channels do it, threading between the beds at a pace the flowers seem to have agreed on.",
		"Every little pool in the Gardens seems to have been placed for one particular flower.",
	},
	["dar.muse.w23.pool.015"] = {
		"Each still pool in the city has a moon of its own. I counted seven on one short walk, and the one above was the palest of them.",
		"The moon is up there somewhere beyond the leaves, but the lake has caught it whole, and holds it so still it looks set in silver.",
	},
	["dar.muse.w23.pool.016"] = {
		"Every pool in this city is a mirror. Hard to keep a borrowed face when the water keeps showing you the real one.",
		"Too much still water in Darnassus. I keep catching my own reflection and flinching, as if it might give me away to the next Sentinel.",
	},
	["dar.muse.w23.pool.017"] = {
		"The kaldorei build pools the way other people build walls: one at every corner, just to be sure.",
		"A city of pools. Wherever there was room for a bench, they put a basin of water instead, and then a bench beside it anyway.",
		"I've stopped counting the basins in Darnassus. It was that or start naming them.",
	},
	["dar.muse.w23.pool.018"] = {
		"I've been told not to wash my socks in the pools. I hadn't even asked.",
		"A Sentinel saw me eyeing that basin with my boots off. She didn't say a word. The boots went back on.",
	},
	["dar.muse.w23.pool.019"] = {
		"If I fall in, tell them I was admiring the reflection.",
		"Lovely pool. If you hear a splash, I was studying the depth. Scientifically.",
	},
	["dar.muse.w23.pool.020"] = {
		"Many doorways in this city have a basin beside them. The kaldorei glance into it on the way past, the way other folk check the sky before setting out.",
		"A little pool by a threshold, and everyone who goes in looks into it first. I don't know what they're checking for. I've started doing it too.",
	},
	["dar.muse.w23.priestess.001"] = {
		"passes a priestess of Elune sweeping fallen petals from a stair with long, unhurried strokes, as if the sweeping were the prayer and the clean stair only a side effect.",
		"sees a priestess clearing leaves from a step with a soft broom, never quite finishing, beginning again at the top whenever a few more drift down.",
		"stops for a priestess raking a gravel path into slow curves, then watches her rake over the place where {g:his|her} own boots have just been.",
	},
	["dar.muse.w23.priestess.002"] = {
		"The priestesses wear small silver at the wrist and throat, and it makes no sound at all when they walk. I suspect that takes practice.",
		"I've never heard a priestess's jewelry chime. Silver on every wrist, and not a clink. Either they move perfectly or the silver is in on it.",
	},
	["dar.muse.w23.priestess.003"] = {
		"I heard a priestess laugh on the path, quite loudly, at something her companion said. The city didn't fall. It seemed rather pleased.",
		"A pair of priestesses went by giggling like apprentices over some private joke. Devotion, it turns out, leaves room for that.",
		"Somewhere I'd picked up the notion that priestesses of Elune never laugh. A loud one on the path just cured me of it, over what sounded like a story about a goat.",
	},
	["dar.muse.w23.priestess.004"] = {
		"A priestess told me they pray with open hands, never clasped: what Elune gives, she said, you can't catch with a fist.",
		"Open hands, palms up, when the priestesses pray. One of them explained that a closed hand can only hold what it already has.",
	},
	["dar.muse.w23.priestess.005"] = {
		"follows with {g:his|her} eyes an older priestess correcting a younger one's posture with two fingers on the shoulder blade, then on the chin, and then simply stepping back.",
		"stops to watch a priestess straighten a novice's stance with the lightest touches, shoulder, chin, wrist, and step away to let her find the rest alone.",
		"lingers to see a novice priestess repeat one small gesture over and over while her teacher shakes her head, patiently, each time.",
	},
	["dar.muse.w23.priestess.006"] = {
		"The priestesses carry bows as well as blessings. The goddess they serve, I'm told, has never asked them to choose.",
		"Those robes hide archers. Ask a priestess about the old wars and you'll hear about prayer, and then, quietly, about aim.",
		"A priestess with a bow across her back went by on her way to the temple. I'd taken the bow for ceremony until I saw how worn the grip was.",
	},
	["dar.muse.w23.priestess.007"] = {
		"If I'm standing somewhere holy, priestess, just point. I'll move.",
		"Is it all right to talk here? Nobody's told me, and nobody's stopped me.",
		"Forgive me, priestess. I was told to lower my voice near the temple, and nobody said how far.",
	},
	["dar.muse.w23.priestess.008"] = {
		"The Sisterhood keeps its calendar by Elune's changing face, a priestess said. Ask one when something will happen and she may answer in phases, not days.",
		"Ask a priestess for a date and she may count it out in turns of the goddess's face rather than in weeks. A different way to keep time, and a slower one.",
	},
	["dar.muse.w23.priestess.009"] = {
		"spots a priestess of Elune in the queue at the bank, robes immaculate, hands folded, waiting her turn exactly like everyone else.",
		"is faintly comforted to see a priestess counting coins into her palm at a merchant's stall, frowning a little at the total like any mortal shopper.",
		"watches a priestess haggle, very gently and very firmly, over the price of thread, and win.",
	},
	["dar.muse.w23.priestess.010"] = {
		"Here in the temple the priestesses speak to visitors in Common and to each other in something older, and both sound like prayer.",
		"Inside the temple the priestesses move in no hurry and no particular order, yet nobody collides. A dance learned so long ago they've forgotten it is one.",
		"Carrying a full basin, a priestess here stops to let me pass first. I'm the guest; she's the one with the basin. That is the order of things in this temple.",
	},
	["dar.muse.w23.priestess.011"] = {
		"The priestesses tend the sick more than they used to, I've heard. Since Hyjal their people can fall ill, and they are still learning what to do with that.",
		"Since Hyjal the kaldorei can run a fever like anyone. A priestess told me nursing colds was never part of her training, once. It is now.",
	},
	["dar.muse.w23.priestess.012"] = {
		"I tried to walk like a priestess. I tripped over the hem of a robe I'm not even wearing.",
		"How do they glide like that? I've checked. They have feet.",
		"I've seen priestesses carry full basins up a stair without spilling a drop. I spill soup at a table.",
	},
	["dar.muse.w23.priestess.013"] = {
		"watches two priestesses pause where the moon shows through a gap in the leaves, press a palm to the brow, and walk on.",
		"sees a priestess halt mid-step under the open moon, lift her chin toward it for the space of a word, and carry on as though nothing had happened.",
	},
	["dar.muse.w23.priestess.014"] = {
		"Here in the gardens a priestess is tying a drooping stem to a stake with thread, then speaking to it briefly, the way you'd tell a child to stand up straight.",
		"In these gardens a priestess goes from bed to bed with a small knife, cutting nothing, only looking, and puts the knife away again at the end.",
	},
	["dar.muse.w23.priestess.015"] = {
		"passes a priestess reading aloud from a slim book to three Sentinels sitting on the grass, their glaives laid beside them, all listening like students.",
		"stops at the edge of a small gathering where an elder speaks slowly to a ring of listeners, and finds that nobody turns round, though all of them have surely noticed {g:him|her}.",
	},
	["dar.muse.w23.quip.001"] = {
		"This city is perfect for walking. That's the whole problem.",
		"Darnassus: built for strolling, by people who have never once been late.",
	},
	["dar.muse.w23.quip.002"] = {
		"Not far, to an elf, is a unit of distance I'm still learning to convert.",
		"When a kaldorei says it's not far, add an hour and a bridge.",
	},
	["dar.muse.w23.quip.003"] = {
		"Everything here is lovely. I'd trade a little lovely for a signpost.",
		"One signpost. That's all I ask. They can carve leaves on it if they like.",
	},
	["dar.muse.w23.quip.004"] = {
		"If I'm ever late, blame the bridges. There are more of them than there are places to go.",
		"I've crossed a great many bridges in this city, and as far as I can tell most of them were the same one.",
	},
	["dar.muse.w23.quip.005"] = {
		"I tried to be patient like the locals. I lasted about as long as a candle stub.",
		"I've been practicing kaldorei patience. So far I can manage nearly a minute.",
	},
	["dar.muse.w23.quip.006"] = {
		"I wanted a quick errand. Darnassus doesn't stock them.",
		"Quick and Darnassus don't belong in the same sentence. I've tried.",
		"In and out, I said. Darnassus only heard the in.",
	},
	["dar.muse.w23.quip.007"] = {
		"Should I tip a Sentinel for directions? She looks like she'd find the idea fascinating and faintly offensive.",
		"I'd thank the Sentinel properly, but I think she's already moved on to watching someone more suspicious.",
	},
	["dar.muse.w23.quip.008"] = {
		"I'm keeping a list of things in Darnassus that are close by. It's a short list. It's this spot.",
		"The nearest thing to anything in this city is wherever you're standing. Everything else is a walk.",
	},
	["dar.muse.w23.quip.009"] = {
		"I've decided to stop asking where things are and just be wherever I happen to be. It's working about as well as you'd think.",
		"New plan: wherever I end up is where I meant to go.",
	},
	["dar.muse.w23.quip.010"] = {
		"I've been told to take my time. I'd love to. Where do they keep it?",
		"Everyone keeps telling me there's no hurry. My purse and my bags disagree.",
	},
	["dar.muse.w23.quip.011"] = {
		"Every stair here is a gentle slope, and every gentle slope goes on forever.",
		"No steep climbs in Darnassus. Just long, kind, endless ones.",
	},
	["dar.muse.w23.quip.012"] = {
		"Is the auction house this way? Don't answer. I'll find out the long way. I always do.",
		"I'll find the auction house eventually. It's in a tree. How far can it be?",
	},
	["dar.muse.w23.quip.013"] = {
		"Somewhere in this city is the trainer I'm looking for, sitting very still, waiting to be found. It's hide-and-seek with an expert.",
		"Finding a trainer here is a game of hide-and-seek, and the trainers have had centuries to practice.",
	},
	["dar.muse.w23.quip.014"] = {
		"Where was I going? It was important. It had a roof.",
		"I had somewhere to be. It's probably still there. I'm the one who moved.",
	},
	["dar.muse.w23.quip.015"] = {
		"I've passed that fountain four times. If it could talk, it would give me directions out of pity.",
		"Hello, fountain. Yes, it's me. No, I don't know either.",
		"Fountain, my old friend. Which way this time?",
	},
	["dar.muse.w23.quip.016"] = {
		"I'm not lost. I'm sightseeing with great determination.",
		"Lost? No. I'm taking the long way on purpose. All of the long ways.",
		"I know exactly where I am. Roughly. Give or take a terrace.",
	},
	["dar.muse.w23.quip.017"] = {
		"Darnassus has everything a traveler needs. Spread out very generously.",
		"Bank, inn, trainers, stalls: all here, all lovely, and every one of them a long, pleasant walk from the rest.",
	},
	["dar.muse.w23.quip.018"] = {
		"I could live up here, if someone carried me.",
		"Beautiful city. I'd see more of it if I weren't always halfway to the bank or back.",
	},
	["dar.muse.w23.quip.019"] = {
		"I've overtaken three elves on this path and somehow they all got there before me.",
		"Everyone here walks slowly and arrives first. I'd like to know how.",
	},
	["dar.muse.w23.quip.020"] = {
		"A dwarf could walk Ironforge end to end in the time it takes to find the bank here. And there'd be ale on the way.",
		"Give me a city with a proper forge in the middle and everything else in a ring round it. Trees, honestly.",
	},
	["dar.muse.w23.reed.001"] = {
		"passes close to the water and a frog drops off the bank with a single plop, leaving a ring and a strong sense of disapproval.",
		"startles a frog at the edge of a pool; it lands in the water with one indignant plop and does not come back up.",
	},
	["dar.muse.w23.reed.002"] = {
		"The frogs here croak in turns, one after another, never over each other. Somebody must have explained the rules to them.",
		"The frogs of this city take turns. One speaks, the others wait, then the next. I've sat through louder council meetings.",
		"Even the frogs keep their voices down. One croak, a long pause, an answer from across the water. Practically a conversation.",
	},
	["dar.muse.w23.reed.003"] = {
		"Reeds along the shore lean together and part again with a dry whisper, the only sound in the city that isn't water or soft voices.",
		"The reeds at the lake's edge rattle faintly against each other, a dry little noise among so much wet.",
		"When something stirs the reeds, the whole shore hisses softly, then settles, as if embarrassed.",
	},
	["dar.muse.w23.reed.004"] = {
		"watches small rings bloom across the lake where fish rise to take something off the surface, never in the same place twice.",
		"spots a fish rising under a bridge to snatch a floating speck, and leave a ring that widens until it meets the stone pilings.",
	},
	["dar.muse.w23.reed.005"] = {
		"There are fish in this lake as long as my arm, and not a single kaldorei with a net. Criminal.",
		"Look at the size of that one. In any other city it'd be supper by now.",
		"Is fishing allowed in this lake? Asking for my stomach.",
	},
	["dar.muse.w23.reed.006"] = {
		"The fish under the bridge drift toward my shadow on the water, hopeful. Someone feeds them. Someone with a lot of patience and a lot of crumbs.",
		"Lean over the rail and the fish gather, nose up, waiting. They know exactly what a person on a bridge is for.",
	},
	["dar.muse.w23.reed.007"] = {
		"crouches to watch a few long-legged insects skate over a still pool, each footstep a tiny dimple, the water giving but never breaking under them.",
		"leans close to a quiet basin where water striders stand on the surface as if it were a floor, and they flick away when {g:his|her} shadow falls across them.",
	},
	["dar.muse.w23.reed.008"] = {
		"Round green pads float in the quiet corners of the lake, each one tilted just so, a dragonfly on one in three. It looks arranged. It probably was.",
		"The water lilies here are spaced like seats at a table. I wouldn't put it past the kaldorei to have counted them.",
	},
	["dar.muse.w23.reed.009"] = {
		"stands still while a dragonfly the color of the lamps hovers in front of {g:his|her} face, considers, and darts back over the water.",
		"follows a blue dragonfly along the shore for a few steps until it settles on a reed tip and refuses to be followed any further.",
	},
	["dar.muse.w23.reed.010"] = {
		"A snail has made it halfway up the stone rim of a pool, trailing silver. I'd guess it set out before I reached the city. It may still be going when I leave.",
		"Snails on every wet stone by the water, each one going somewhere at the local pace. They fit in better here than I do.",
	},
	["dar.muse.w23.reed.011"] = {
		"A tailor on the Craftsmen's Terrace told me the softest thread she knows is spun from a lake reed. I looked at the reeds differently after that.",
		"Someone among the crafters said the reeds by the shore give the finest fiber for weaving, if you have the patience to soak them for a season. I believe the patience part.",
	},
	["dar.muse.w23.reed.012"] = {
		"watches a frog hop onto the boot of a motionless Sentinel by the water and sit there; the Sentinel looks down, and lets it stay.",
		"sees a frog climb onto the toe of a Sentinel standing watch by a pool. She glances at it once, gravely, and goes back to her watch.",
	},
	["dar.muse.w23.reed.013"] = {
		"I suppose someone had to bring the fish up here. Every frog and minnow in this lake came, I'd guess, from a forest that burned or a coast that's gone. Refugees, the lot of them.",
		"Nothing in this lake was born to live in a tree. Someone carried the fish, the frogs, the reeds up here, I suppose, from places the war reached. I look at them more kindly for it.",
	},
	["dar.muse.w23.reed.014"] = {
		"follows the hands of a druid here in the Enclave as they tip a little water onto the roots of a seedling, then wait, cupped, as if for an answer.",
		"turns to see a druid of the Enclave crouch by running water, lift a struggling beetle out of a channel and set it in the grass, with a word too low to hear.",
	},
	["dar.muse.w23.reed.015"] = {
		"hears the frogs along the shore start up all at once as the rain thickens, as if they had been waiting for it all along.",
		"notices the frogs come out onto the wet stones by the lake in the rain, perfectly pleased with the weather, the only ones in the city who are.",
	},
	["dar.muse.w23.reed.016"] = {
		"That fall would turn a fine waterwheel. Grind grain, work a bellows, light half a terrace. I'm not going to suggest it. I've seen how they look at gears here.",
		"So much falling water and not one wheel on it. In Gnomeregan that would have been a scandal. Here it's a philosophy.",
	},
	["dar.muse.w23.reed.017"] = {
		"Near the lake the air smells of wet stone and reed, cool and green. Further in, it's moss and flowers. I could tell where I am by my nose.",
		"The shore has a smell all its own: cold stone, crushed reed, a hint of fish. It's the least elegant smell in Darnassus, and I like it best.",
	},
	["dar.muse.w23.reed.018"] = {
		"crouches at the edge of a shallow pool full of tadpoles, all wriggling the same way at once, then the other way, like a crowd that can't agree.",
		"spots a cloud of tadpoles in the shallows, dark commas that scatter at {g:his|her} shadow and drift back together a moment later.",
	},
	["dar.muse.w23.reed.019"] = {
		"That dragonfly's been circling my head for a while. I think it's adopted me.",
		"A dragonfly just landed on my sleeve and stayed. Nobody move. It chose me.",
	},
	["dar.muse.w23.rill.001"] = {
		"steps over a narrow channel cut into the path, where a thread of water runs along beside the walkers as if it too had errands on another terrace.",
		"follows a shallow rill set into the stone of the walkway for a dozen steps before it ducks under a slab and disappears.",
		"steps carefully over a thin silver runnel crossing the path, the kind of small water that seems to have wandered off from a larger one.",
	},
	["dar.muse.w23.rill.002"] = {
		"Each stream here has its own note. One is high and quick, another low, almost a hum. I could find my way by ear, if I trusted my ears.",
		"I've started telling the streams apart by sound. A chatter means the narrow channels; a deep mutter means a fall is near.",
		"Water talks differently on every terrace. If I shut my eyes, I think I could name half of them by it.",
	},
	["dar.muse.w23.rill.003"] = {
		"Between two terraces the sound of running water just stops, and the silence is sudden enough that I look round to see what went wrong.",
		"There's one stretch of path where no water can be heard at all. In this city, that quiet feels like a door left ajar.",
	},
	["dar.muse.w23.rill.004"] = {
		"Where does the water go when it spills off the edge of the city? Down the trunk, a druid told me, all the long way to the sea, and the tree drinks twice on the way.",
		"A druid told me the falls here don't really end. The water runs down Teldrassil's bark to the sea, and the tree, she said, takes its share going past.",
	},
	["dar.muse.w23.rill.005"] = {
		"crouches at a running channel and lets the water pour over {g:his|her} fingers until they ache with the cold, then shakes them dry and walks on.",
		"dips both hands into a quick little stream and holds them there, watching the current part around each knuckle.",
	},
	["dar.muse.w23.rill.006"] = {
		"Stand by the falls and you could shout all you like. Only place in this city you'd get away with it.",
		"If I ever need to curse out loud in Darnassus, I'm doing it next to a waterfall.",
		"The falls are the only thing here allowed to be loud. I'm jealous.",
	},
	["dar.muse.w23.rill.007"] = {
		"pauses near a fall and feels its spray settle on {g:his|her} sleeves as fine silver beads, too small to wet anything, too many to brush away.",
		"stands close enough to a waterfall that a cool haze of spray drifts over, and the beads it leaves catch the violet lamps in every fold of cloth.",
		"walks close past a fall and comes away with a fine dew of spray across the shoulders, glittering until it dries.",
	},
	["dar.muse.w23.rill.008"] = {
		"There's a stair where a rill runs down beside the steps, making a tiny waterfall at every one. It takes the stairs faster than I do and makes far more fuss about it.",
		"Water comes down the stairs alongside me, a small fall at each step. It gets to the bottom first, every time, and I swear it gloats.",
	},
	["dar.muse.w23.rill.009"] = {
		"Running water makes good company for thinking. It says the same thing over and over, and never needs an answer.",
		"I've done more honest thinking beside these streams than in a month of roads. The water keeps talking so I don't have to.",
		"Sit by a stream with a knot of a problem and the water starts working at it, like a thumb on a stiff strap.",
	},
	["dar.muse.w23.rill.010"] = {
		"falls still as a kaldorei stops at a stream on the way toward the temple, wets both hands, touches them to the brow, and continues without a word.",
		"sees a Sentinel pause at running water, rinse her fingers and press them briefly to her eyelids before going on toward the Temple of the Moon.",
	},
	["dar.muse.w23.rill.011"] = {
		"Here in the Enclave the water doesn't keep to channels. It finds its own way between the roots, and the druids step over it rather than tell it where to go.",
		"The streams in the Enclave run wherever they please: under roots, across paths, through somebody's herb bed. Nobody here seems to think water should ask permission.",
	},
	["dar.muse.w23.rill.012"] = {
		"Sweet water, in the crown of a tree, in the middle of a salt sea. I tasted it to be sure. Not a grain of salt in it.",
		"Every drop up here is fresh and soft on the tongue, and the nearest water below is the sea. The tree, I suppose, has done the sorting.",
	},
	["dar.muse.w23.rill.013"] = {
		"Cold, clear, and they just let it run off the edge of the city. Somebody in a desert would weep.",
		"All this sweet water, and half of it pours off the side of the tree for nobody at all.",
	},
	["dar.muse.w23.rill.014"] = {
		"lingers by a fountain in the Temple Gardens, where water rises, hangs for an instant at the top of its leap, and falls back into its own basin without a sound.",
		"sits on the rim of a fountain among the hedges of the Gardens and watches the water climb and fall, climb and fall, like something rehearsing a part.",
	},
	["dar.muse.w23.rill.015"] = {
		"Even here, where hides are soaked and bowls are rinsed, the water leaving the terrace looks as clean as the water coming in. I'd like to know how.",
		"The crafters here use the streams for soaking leather and rinsing mortars, and still the channel downstream runs clear. Somebody has thought hard about that.",
	},
	["dar.muse.w23.rill.016"] = {
		"In rain the streams change their voice. Every channel runs fuller and quicker, and the falls drop a note lower.",
		"Rain on the crown, and a little later every rill in the city is talking faster. The lake takes it all and doesn't rise a finger.",
	},
	["dar.muse.w23.rill.017"] = {
		"Hear the falls? No, that's thunder. No, wait, it's both.",
		"Thunder up top and the falls down here, arguing over who's louder. The falls are winning.",
	},
	["dar.muse.w23.rill.018"] = {
		"Stormwind's canals run straight between stone walls, all business. These streams wander about like guests at a garden party, and get there anyway.",
		"The canals in Stormwind are working water, deep and walled and going somewhere. Here the water seems to have retired.",
	},
	["dar.muse.w23.rill.019"] = {
		"Never thought I'd say it, but I'm topping up my waterskin out of sheer greed. It's that good.",
		"Best-tasting water in Kalimdor, and nobody charges for it. Every skin I own is getting filled.",
	},
	["dar.muse.w23.rill.020"] = {
		"hops across a stream on three flat stepping stones set exactly a stride apart, as if whoever placed them had measured a kaldorei leg.",
		"crosses a brook by its stepping stones, finds them spaced a little too far for a comfortable step, and makes the last one with an undignified hop.",
	},
	["dar.muse.w23.rill.021"] = {
		"In Ashenvale, the Sentinels say, the streams run thick with sawdust below the Warsong camps. Up here the water runs clean, and they look at it as if it were something to defend.",
		"The Sentinels say the rivers in Ashenvale run brown below the Warsong lumber camps. They wash their hands in these streams very gently, as if the water could be hurt.",
	},
	["dar.muse.w23.rill.022"] = {
		"I asked an elf what this stream is called. She looked at me as if I'd asked the name of a cloud.",
		"Do the streams here have names? I asked. The answer was a smile and a very long silence.",
	},
	["dar.muse.w23.ripple.001"] = {
		"stands under the curve of a bridge and watches the water throw a net of moving light up across the pale stone overhead.",
		"looks up at the underside of an arch near the water, where reflected light runs over the stone in shivering bright threads.",
		"lingers beneath a bridge where the water's reflected glimmer crawls over the stone, never still, like something alive under the arch.",
	},
	["dar.muse.w23.ripple.002"] = {
		"Every pebble in a stream looks like a jewel under an inch of water. Lift one out and it's a gray stone again, drying in the palm.",
		"The stones on the bottom shine like polished things. Take one out and it goes dull before your fingers close.",
		"Underwater, the gravel here is all amber and green and violet. Out of it, it's gravel. The water does all the work.",
	},
	["dar.muse.w23.ripple.003"] = {
		"The moss along the lake's stone edge stops at one exact line, the same height all the way round. The water here doesn't rise and doesn't fall. I don't know what to make of a lake with no moods.",
		"There's a dark band on the stone at the waterline, even as a ruler. No floods, no dry spells. The lake keeps one level the way a Sentinel keeps one posture.",
		"The lake never seems higher or lower than the last time I looked. Water that can't make up its mind is ordinary; water that never has to is unsettling.",
	},
	["dar.muse.w23.ripple.004"] = {
		"watches the reflected towers in the lake break into pieces as something swims beneath, then knit themselves back together, stone by stone.",
		"catches a ring spreading over the lake, and the white walls mirrored in it wobble, fold, and settle back into place as if nothing had touched them.",
	},
	["dar.muse.w23.ripple.005"] = {
		"A bridge over still water is never half a bridge here. The arch and its reflection close into a ring, and walking over it feels like stepping through something.",
		"Each curved bridge meets its own reflection and makes a full circle. I keep wanting to walk through the middle of one.",
		"Arch above, arch below, and a ring of stone and water between. The bridges here are built to be seen twice.",
	},
	["dar.muse.w23.ripple.006"] = {
		"Dropped a copper off a bridge. It took so long to sink, I had time to regret it twice.",
		"Clear water's a cruel thing. You can watch your coin settle on the bottom, right there, completely out of reach.",
		"That's the clearest water I've ever lost money in.",
	},
	["dar.muse.w23.ripple.007"] = {
		"Near the water the light changes. It comes up from below as well as down from the leaves, and faces on the shore look lit from inside.",
		"Stand by the lake long enough and you notice it: the light here comes from two directions, the leaves above and the water below, and nothing has a hard edge.",
		"Faces by the lake look kinder. The water lights them from below and softens every hard line.",
	},
	["dar.muse.w23.ripple.008"] = {
		"A drop from a leaf, a ring on the pool, the ring touching the stone rim and coming back smaller. I watched four of them and lost count of everything else.",
		"One drop off a leaf and the whole pool answers: a ring outward, a fainter one back. It is the slowest conversation in the city.",
		"A single drop lands in a still basin and the rings go out so slowly I could count them. I did count them. Seven.",
	},
	["dar.muse.w23.ripple.009"] = {
		"The stone where the water runs is already rounding off. The city is young, but the streams have started their own slow carving, and they have all the time the kaldorei used to have.",
		"Water wears stone, given enough years. Here it has barely begun. One day these sharp new channels will look ancient, and whoever is left will think they were always like that.",
	},
	["dar.muse.w23.ripple.010"] = {
		"Every surface in this city is a mirror. I've seen my own hair more in an hour here than in a month on the road.",
		"Pools everywhere, all of them perfectly still. Hard to avoid your own face in Darnassus. Mine could use a wash.",
	},
	["dar.muse.w23.ripple.011"] = {
		"In the temple even the water is careful. The fountain falls into its basin without a splash, as if someone had taught it manners.",
		"In the Temple of the Moon the fountain's fall is so smooth it looks like a pillar of glass. The priestesses walk past it without looking; I can't stop looking.",
	},
	["dar.muse.w23.ripple.012"] = {
		"notices a small, faint arc of colors standing in the spray of a fall where a shaft of sunlight comes down through the leaves, and steps sideways to keep it in view.",
		"finds a sliver of color hanging in a waterfall's spray where the sun reaches through the canopy, and watches it fade as soon as the leaves shift.",
	},
	["dar.muse.w23.ripple.013"] = {
		"At dusk the lake goes dark before the paths do, a pool of ink with lamps floating in it.",
		"As the light goes, the water darkens first. For a little while the lake is the deepest thing in the city, darker than the shade under the boughs.",
	},
	["dar.muse.w23.ripple.014"] = {
		"In Ironforge the water knows its place: in a pipe, in a trough, in a tankard. Here they let it wander about in the open, cold, collecting leaves.",
		"Under the mountain we'd have all this in pipes by now, with a valve for every channel. The kaldorei would rather let it go where it likes. Elves.",
	},
	["dar.muse.w23.ripple.015"] = {
		"You can tell how far a fall's spray reaches by the moss: a perfect green fan on the stone, ending exactly where the drops give out.",
		"Every fall in the city has drawn its own map in moss on the stone around it, thick where the spray lands, thinning to bare rock where it doesn't.",
	},
	["dar.muse.w23.ripple.016"] = {
		"Sit by still water long enough and old roads come floating up, one by one, the way leaves surface after a stir. I let them drift.",
		"A quiet pool is a poor place to forget anything. Whatever I'd set aside rises and turns slowly on the surface.",
		"Faces from the road float up out of a still pool if I let them. I don't call them. They come anyway, and go.",
	},
	["dar.muse.w23.ripple.017"] = {
		"Look how still that is. I don't think I've been that still in my life.",
		"Not a ripple on it. I'd like to know the trick.",
	},
	["dar.muse.w23.ripple.018"] = {
		"From where I stand I can count four waters: a trickle at my feet, a stream across the path, a fall somewhere behind the trees, and under it all the slow, almost soundless lake.",
		"Close by, a drip. Further, a stream. Further still, a fall. The water of this city comes in layers, like voices in a long hall.",
	},
	["dar.muse.w23.saber.001"] = {
		"notices the tail of a resting nightsaber hanging over a ledge, its very tip twitching, the only part of the great cat still awake.",
		"passes beneath a ledge where a nightsaber lies stretched out of sight except for its tail, which hangs down and flicks lazily at nothing.",
	},
	["dar.muse.w23.saber.002"] = {
		"A nightsaber's ears swiveled toward a stand of trees a full moment before anything rustled there. Whatever the city is saying, the cats hear it first.",
		"Watch the ears of a resting nightsaber and you learn what's coming down the path before you see it. They turned twice while I stood there; both times, a Sentinel.",
		"Nightsabers sleep with their ears awake. One dozed through a whole troupe of chattering visitors and only opened its eyes when a Sentinel stopped speaking.",
	},
	["dar.muse.w23.saber.003"] = {
		"A Sentinel rode past on a white cat striped in pale gray. A frostsaber, someone told me, from Winterspring in the far north. It moved through the green like a visitor too polite to complain of the heat.",
		"Among all the dark cats of the city, one white frostsaber, and every head on the path turned to follow it. Even here, a rarity is a rarity.",
		"The frostsaber's coat looked made for a climate Darnassus never sees. It kept to the shade of the boughs, every step, as if it knew.",
	},
	["dar.muse.w23.saber.004"] = {
		"That cat just yawned at me. I've walked through smaller doorways.",
		"Big cat. Calm cat. I'm walking very slowly, cat, and you're going to let me.",
		"Did that nightsaber just sigh at me? I think I've been judged and found boring.",
	},
	["dar.muse.w23.saber.005"] = {
		"watches a Sentinel check each of her nightsaber's paws in turn, the great cat lifting them for her one by one like a patient horse at the smith.",
		"stops to watch a Sentinel run her thumb between the pads of her cat's forepaw, hunting for a thorn, while the nightsaber looks off into the distance, enduring it.",
		"catches a Sentinel leaning her whole weight on her nightsaber's flank while she fixes a boot strap, and the cat bracing itself without being asked.",
	},
	["dar.muse.w23.saber.006"] = {
		"When a nightsaber purrs, you feel it through the boards of the bridge before you hear it. A low, slow rumble, like a cart going by in another street.",
		"I sat down near a dozing nightsaber and it started to purr. Not at me, I think. Just at the world in general, which apparently pleased it.",
	},
	["dar.muse.w23.saber.007"] = {
		"A deer was grazing by the path, ten steps from a Sentinel and her cat, and none of the three seemed to find that strange. I did.",
		"Deer graze the lawns here as if the nightsabers were furniture. Perhaps, to a well-fed cat in a city, they are.",
		"A deer stood on a bridge long enough to hold up a merchant's cart, and the merchant waited, patient as a post, until it had finished looking at the water.",
	},
	["dar.muse.w23.saber.008"] = {
		"slows as a doe and her fawn cross the path ahead, unhurried, the fawn stopping to stare until its mother noses it along.",
		"stands aside for a doe leading a spotted fawn across the lawn; the fawn halts in the middle of the path to study {g:him|her}, then bounds off after its mother.",
	},
	["dar.muse.w23.saber.009"] = {
		"Up here on the Warrior's Terrace the hunters' animals lie about like a second, sleepier garrison: cats, bears, a wolf with a torn ear, all watching their people drill.",
		"On this terrace the trainers keep their students, and the students keep their animals, and the animals keep an eye on everyone. A bear just yawned at a sparring pair as if marking them out of ten.",
	},
	["dar.muse.w23.saber.010"] = {
		"Pass a resting nightsaber and you notice the eyes last: two coins of lamp-colored light that follow you without the head moving at all.",
		"In the green shade under a bough, a nightsaber was invisible except for its eyes, two small violet glints that turned to keep me in view.",
	},
	["dar.muse.w23.saber.011"] = {
		"The Sentinels' cats know me for kaldorei, I think; they don't even lift their heads when I pass. A guest gets a long yellow look. I get a yawn, and I take it as welcome.",
		"A nightsaber on the terrace sniffed my sleeve, decided I smelled of home, and went back to sleep on my foot. I stood there a good while rather than wake it.",
	},
	["dar.muse.w23.saber.012"] = {
		"Every nightsaber I pass gives me a long, measuring look, the same one its rider gave me earlier. I suspect they compare notes afterward.",
		"The cats here look at outsiders the way the Sentinels do, slowly and from the boots up. I'd like to think I pass inspection. The cats keep their verdict to themselves.",
	},
	["dar.muse.w23.saber.013"] = {
		"Every one of these cats could smell the Horde on me through any disguise, I'm sure of it. They only let me pass because nobody has asked them yet.",
		"A nightsaber lifted its head as I went by and kept it lifted. Its Sentinel didn't notice. The cat did, and the cat has no reason to keep my secret.",
	},
	["dar.muse.w23.saber.014"] = {
		"notices a rabbit nibbling clover a few strides from a dozing nightsaber, and the cat watching it through one lazy eye, plainly off duty.",
		"keeps an eye on a rabbit grazing its way closer and closer to a sleeping nightsaber, until the cat flicks one ear and the rabbit reconsiders its whole life.",
		"spots a rabbit asleep in the curl of a sleeping nightsaber's tail, and decides that some arrangements in Darnassus are best left unquestioned.",
	},
	["dar.muse.w23.saber.015"] = {
		"Here in the Enclave a stag walked between the druids as if he had business with them. Maybe he did. Nobody asked to see his papers.",
		"A stag is standing among the roots of the Enclave, chewing thoughtfully, while two druids talk beside him. He seems to be following the argument better than I am.",
	},
	["dar.muse.w23.saber.016"] = {
		"I swear that deer just bowed to me. Or it was looking at my boots. Either way, I bowed back.",
		"A deer nodded at me. I nodded at the deer. I think that makes us acquainted.",
	},
	["dar.muse.w23.saber.017"] = {
		"steps off the path for a nightsaber limping on a bound foreleg, its Sentinel walking slowly at its side and matching the limp step for step.",
		"stays at a respectful distance as a scarred nightsaber lowers itself onto the grass with great care, and its Sentinel kneels beside it, saying nothing, one hand resting on its neck.",
	},
	["dar.muse.w23.saber.018"] = {
		"Two nightsabers met on a bridge and neither would give way. In the end they both sat down in the middle of it, and the whole bridge had to wait.",
		"A pair of cats blocked a bridge for a good while, staring at each other with great dignity. Nobody tried to move them. I wouldn't have either.",
	},
	["dar.muse.w23.saber.019"] = {
		"lingers while a nightsaber drinks from a stream, lapping so delicately that the water hardly stirs, then shakes its head and scatters drops over a startled passer-by.",
		"pauses as a nightsaber pads down to the water's edge, tests it with one paw like a cautious bather, and only then bends its head to drink.",
	},
	["dar.muse.w23.saber.020"] = {
		"If that nightsaber wants the bench, the bench is its. I don't argue with anything that has more teeth than I have coins.",
		"That cat is lying across the only shady spot on the terrace. I've decided I prefer standing.",
	},
	["dar.muse.w23.saber.021"] = {
		"A fawn just sniffed my hand and bolted. Honestly, that's how most of my introductions go.",
		"That fawn looked at me as if I were the strangest thing in Darnassus. In fairness, it may be right.",
	},
	["dar.muse.w23.sap.001"] = {
		"lays a hand on a railing, lifts it again with a faint tacky sound, and studies the bead of amber sap now stuck to {g:his|her} palm.",
		"finds a sticky bead of sap on one sleeve, picks at it, and only manages to spread it further.",
		"rubs a thumb against a forefinger, tacky with sap from some rail or other, and gives up trying to get them clean.",
	},
	["dar.muse.w23.sap.002"] = {
		"In a fold of bark by the path, a drop of sap has caught a small green fly and is slowly closing over it. A few thousand years from now, someone will hold that up to the light.",
		"A bead of sap on the bark with a tiny beetle sealed inside, legs still spread as if it meant to finish its walk. The tree keeps everything, it seems, even mistakes.",
		"There's a gnat in the amber on that post, perfect down to the wings. Teldrassil is young, but it has already started keeping things.",
	},
	["dar.muse.w23.sap.003"] = {
		"Near the Enclave I saw a pruned bough, the cut dressed with clay and moss like a wound. Two druids sat beside it a long while, saying nothing, the way you sit with someone who's been hurt.",
		"Where a limb had been cut back, the sap had run and dried in long amber tears. A druid was cleaning it with a soft cloth, unhurried, as if washing a face.",
		"I watched a druid smooth fresh clay over a pruning cut and murmur to it under her voice. Whatever she said, she said it like an apology.",
	},
	["dar.muse.w23.sap.004"] = {
		"An old druid said, half to herself, that the sap of Teldrassil runs quicker than any tree's should. Then she noticed me listening and found another subject.",
		"I heard two druids disagree, very softly, about the sap. One called it vigor. The other used a word I didn't catch and didn't like the sound of.",
		"'Too eager,' a druid said of the tree, as a teacher might of a bright pupil, and then looked as if she wished she hadn't said it aloud.",
	},
	["dar.muse.w23.sap.005"] = {
		"Mind the railings. Half of them are still oozing sap, and the other half are thinking about it.",
		"Who knew a city could be sticky? An hour here and it's already clinging to me.",
		"If I hold still long enough, I suspect the tree will just keep me.",
	},
	["dar.muse.w23.sap.006"] = {
		"The sap here doesn't smell like pine. It's sweeter, closer to pears forgotten in a cellar, with something green under it I can't name.",
		"Bend close to the bark and there's a smell like honey gone a little wild. I keep catching it on my own hands long afterward.",
		"Resin, pear, crushed stems: that's what the bark smells of when you lean near. Nothing like the pitch on a ship's hull, and I've been trying to decide why.",
	},
	["dar.muse.w23.sap.007"] = {
		"follows a thin line of ants up the bark toward a knot weeping sap; each one comes back down slower than it went up.",
		"crouches to follow a file of ants up a pale trunk to a glistening seam of sap, where they crowd like guests round a fountain.",
		"spends a while watching ants work at a bead of sap on a post, as busy as market porters, while the kaldorei walk past without a glance.",
	},
	["dar.muse.w23.sap.008"] = {
		"Put an ear to the trunk where it's thick and there's a faint ticking, like a house cooling. A druid told me it's the sap climbing. I'd have guessed something smaller and busier.",
		"I leaned my head against a pillar of living wood and heard, very faintly, a sound like grain trickling inside a wall. 'The sap,' a passing druid said, without stopping.",
	},
	["dar.muse.w23.sap.009"] = {
		"Teldrassil's sap smells the way the old forests of Hyjal did. The tree is new; the smell is not. I stand in it longer than I need to.",
		"Sap on my fingers, and for a moment I am somewhere much older than this city. I don't wipe it off right away.",
		"Our new tree, our old smell. Whatever else the druids got wrong or right, they got the sap right.",
	},
	["dar.muse.w23.sap.010"] = {
		"watches a visitor try to pry a lump of amber sap off a railing with a knife, until a druid appears beside him so quietly that the knife goes back in its sheath almost on its own.",
		"sees a dwarf scraping sap into a little tin, very pleased with himself, until a Sentinel's shadow falls across the tin and he remembers urgent business elsewhere.",
	},
	["dar.muse.w23.sap.011"] = {
		"Rain draws the sap out of the bark. A few minutes of it and the whole city smells of resin, sweet and heavy, like a cellar of jam.",
		"With the rain, every trunk begins to shine and smell sweeter. The tree seems to open its pores to the wet.",
	},
	["dar.muse.w23.sap.012"] = {
		"Smell that? Resin. Somewhere in this tree, something is always mending.",
		"No nails, no glue. They just let the sap do it.",
		"That sweet smell's the tree. Not a bakery. I checked.",
	},
	["dar.muse.w23.sap.013"] = {
		"Sap on the boots, sap on the cuffs, sap on the coin I just handed over at a stall. I apologized. Nobody seemed to think it needed an apology.",
		"Every coin I've spent here comes back to me faintly sticky. Darnassus marks its money, apparently.",
	},
	["dar.muse.w23.sap.014"] = {
		"The sap here sets into amber in a few seasons, a crafter told me. I asked whether anyone sells it. She asked whether I'd sell a friend's tears. I took that as a no.",
		"Asked at a stall if there was amber for sale. The look I got could have sealed a fly in place.",
		"Amber from Teldrassil would fetch a fortune anywhere else. Nobody here will even talk about it, and I've stopped asking.",
	},
	["dar.muse.w23.sap.015"] = {
		"notices a priestess stop to wipe a weeping seam of sap from a doorpost with the corner of her sleeve, as gently as a mother wiping a chin.",
		"glimpses a kaldorei pausing by a doorpost glistening with fresh sap, touch the bead with a fingertip, and go on, as if greeting someone in passing.",
		"watches an elder wait for a slow drop of sap to fall from a lintel, catch it on a fingertip, and press it back into the bark.",
	},
	["dar.muse.w23.sap.016"] = {
		"Don't lean on that. It's weeping. No, not like that: sap. Still don't lean on it.",
		"Careful, that post's fresh. Fresh sap, I mean. Not paint. They don't paint anything here.",
	},
	["dar.muse.w23.sentinel.001"] = {
		"Sentinels look at a stranger's hands before the face. I've caught myself doing it too, which says something about the roads I've walked.",
		"Hands first, then the face: that's the order a Sentinel reads you in. I noticed only because she was so quick about it.",
		"Being looked over by a Sentinel starts at the hands. Nothing personal; it's simply where trouble usually begins.",
	},
	["dar.muse.w23.sentinel.002"] = {
		"passes a Sentinel at a railing who is drawing each of her arrows through two fingers to test the feathers, one after another, without once looking down.",
		"notices a Sentinel feeling along the fletching of every shaft in her quiver, slow and blind, the way someone counts coins in a dark pocket.",
		"follows the hands of a Sentinel at her post as she rolls a single arrow between finger and thumb, sights down its length, and returns it to the quiver with something close to approval.",
	},
	["dar.muse.w23.sentinel.003"] = {
		"I asked a Sentinel for directions and got four words and a lifted chin. Every one of the four was necessary. I checked.",
		"Sentinels give directions the way they shoot: one try, no spare words, and somehow it lands.",
		"Asked a Sentinel where the inn was. She raised her chin a quarter inch in one direction. I found it.",
	},
	["dar.muse.w23.sentinel.004"] = {
		"watches a Sentinel officer walk down a short line of her warriors, tugging once at each strap and buckle, and moving on without a word when nothing gives.",
		"sees an older Sentinel pass along a row of her sisters-in-arms, testing a buckle here, a strap there, and saying nothing at all so long as each one holds.",
		"takes in a line of Sentinels standing inspection without a murmur; the officer finds one strap a hair too loose, and the whole line seems to tighten with it.",
	},
	["dar.muse.w23.sentinel.005"] = {
		"That Sentinel has looked at me three times now. I think I'm being memorized.",
		"She hasn't blinked once. I've blinked enough for the both of us.",
		"Yes, it's me. No, I'm not up to anything. You can stop memorizing me now.",
	},
	["dar.muse.w23.sentinel.006"] = {
		"The Sentinels' armor isn't new. Every plate has been dented, hammered straight and oiled again, and they wear the mending as plainly as the metal.",
		"Look closely at a Sentinel's gear: patched leather, a buckle replaced, a plate beaten flat after some blow. Nothing thrown away that can still stand a watch.",
		"Nothing a Sentinel wears is new, and nothing is shabby. Mended, oiled, mended once more: even her kit looks patient.",
	},
	["dar.muse.w23.sentinel.007"] = {
		"overhears a Sentinel scolding her great cat in a low, patient voice, and the cat listening with the exact expression of someone who will do it again.",
		"catches a Sentinel murmuring to her saber-cat as she tightens its harness, the tone half order, half old joke between the two of them.",
		"looks on as a Sentinel crouches to check her cat's paws one by one, as a smith checks horseshoes, while the great beast endures it with its eyes shut.",
	},
	["dar.muse.w23.sentinel.008"] = {
		"Even at ease, a Sentinel keeps her weight a little back, ready to step either way. Centuries of that, and it has become simply how they stand.",
		"Watch a Sentinel's feet rather than her face: never planted square, always half a step from moving. Rest, for them, seems to be a lighter kind of readiness.",
		"Sentinels never quite settle. Even leaning on a railing, one of them keeps a foot free, as if the railing might need defending.",
	},
	["dar.muse.w23.sentinel.009"] = {
		"May nothing interesting happen on your watch, Sentinel. I mean that kindly.",
		"Long watch? I won't ask how long. I suspect the answer has centuries in it.",
		"Don't mind me, Sentinel. I'm only admiring how still you can stand.",
	},
	["dar.muse.w23.sentinel.010"] = {
		"notices how a Sentinel on the path draws herself up as a priestess passes, and how the priestess answers with a dip of the head no deeper than the Sentinel's.",
		"sees a Sentinel and a priestess cross on the path and exchange the same short nod, exactly as deep on both sides, like a debt settled long ago.",
	},
	["dar.muse.w23.sentinel.011"] = {
		"A Sentinel on watch was eating a piece of fruit, and managed it without once taking her eyes off the path. I've seen soldiers do worse with both hands free.",
		"Even a Sentinel's meal is eaten at attention: small bites, eyes up, the core tucked away in a pouch instead of tossed.",
		"Sentinels eat standing, in small bites, eyes on the path. I've never seen one finish a meal; I suspect they never quite start one.",
	},
	["dar.muse.w23.sentinel.012"] = {
		"Sentinels wear their hair bound tight and close, nothing loose for a branch or an enemy to catch. Even their vanity has been drilled.",
		"Every Sentinel's hair is braided back the same careful way. Practical, I'm told, and yet each braid ends a little differently, as if that last inch were her own.",
	},
	["dar.muse.w23.sentinel.013"] = {
		"Here on the terrace the Sentinels drill with their glaives in pairs, slow first, then faster, until the steel is a blur and neither of them has moved her feet.",
		"A pair of Sentinels running the same glaive drill over and over, slowly enough to see every turn of the wrist. Speed, on this terrace, is something you earn last.",
		"The Sentinels here repeat one throw a hundred times, and the hundredth is watched as closely as the first.",
	},
	["dar.muse.w23.sentinel.014"] = {
		"I straightened my collar without being asked. Sentinels have that effect.",
		"One look from a Sentinel and my back goes straight. I don't even serve under her.",
		"Something about Sentinels makes me check my buckles. All of them. Twice.",
	},
	["dar.muse.w23.sentinel.015"] = {
		"hears the slow scrape of a whetstone and finds a Sentinel drawing it along a glaive's edge, stopping now and then to listen to the steel as if it might answer.",
		"pauses at a soft, steady rasp and finds a Sentinel honing her glaive, each stroke the same length, the stone wetted between strokes with a fingertip.",
	},
	["dar.muse.w23.stranger.001"] = {
		"watches a dwarf start a hearty laugh on a bridge, notice every head turning, and finish it in a whisper that shakes his whole beard.",
		"hears a dwarf catch his own booming laugh halfway out and fold the rest into a cough, while two Sentinels pretend not to have heard.",
	},
	["dar.muse.w23.stranger.002"] = {
		"A gnome at the bank counter, up on tiptoe, conducting business with the clerk's chin. Neither of them seemed to find it strange, so I did my best not to either.",
		"The counters here were cut for kaldorei. I watched a gnome hold coins up to the clerk like a petition raised to a balcony, perfectly dignified about it.",
	},
	["dar.muse.w23.stranger.003"] = {
		"The gnomes in Darnassus are guests twice over: guests of Ironforge since Gnomeregan fell, and guests of this tree. They seem to have got very good at it.",
		"A gnome on the terrace told a druid, quite cheerfully, that she hadn't had a city of her own in years. The druid said nothing for a long while, then sat down beside her.",
	},
	["dar.muse.w23.stranger.004"] = {
		"A human courier came through at a jog, letters under his arm, and the whole terrace followed him with their eyes the way you'd follow a moth that has flown in through a window.",
		"You can spot the Stormwind folk at a glance: they walk as though the city shuts at a certain hour. Darnassus doesn't seem to shut at all.",
	},
	["dar.muse.w23.stranger.005"] = {
		"notices a human murmuring a short grace to the Light over a meal by the water, and a priestess of Elune nearby listening with polite, unhurried interest.",
		"sees a visiting human bow his head to the Light before eating, and a passing priestess slow her steps out of courtesy until he has finished.",
	},
	["dar.muse.w23.stranger.006"] = {
		"Every courteous nod in this city is meant for someone they think I am. I keep my head down and my hands where they can be seen.",
		"If a Sentinel looks at me a moment too long, it's over. I've never been so politely terrified.",
		"Every courtesy I return is a lie with good manners. The kaldorei deserve better, and I deserve to get out of here unseen.",
	},
	["dar.muse.w23.stranger.007"] = {
		"Each passer-by murmurs Ishnu-alah, and I nod back like a local. The less I speak the better; one word in my own accent would empty the terrace.",
		"An enemy city, gentle as a garden. The worst of it is how much I'd like to sit down by the water and stop pretending.",
	},
	["dar.muse.w23.stranger.008"] = {
		"A dwarf in red and gold crossed the terrace, and for a moment Darnassus looked like a painting someone had signed in the wrong ink.",
		"Visitors stand out here by color alone. Among all the violet and silver, a gnome in orange is practically a signal fire.",
	},
	["dar.muse.w23.stranger.009"] = {
		"hesitates before a carved seat beside the path, unsure whether it is meant for anyone at all, and in the end stands next to it instead.",
		"stops at a low wall that might be for sitting or might be sacred, and decides, after some thought, to lean on nothing.",
		"lingers at the edge of a lawn where kaldorei sit at their ease, unsure whether the grass is for guests too, and settles for admiring it from the path.",
	},
	["dar.muse.w23.stranger.010"] = {
		"Does anyone else feel they're tracking mud through a temple? Just me, then.",
		"I keep wanting to wipe my boots before I step anywhere. On what, I couldn't tell you.",
		"Is there somewhere a guest is allowed to be clumsy? I'd like to go there for a bit.",
	},
	["dar.muse.w23.stranger.011"] = {
		"Two dwarves met on a bridge and greeted each other like long-lost kin, though I'd wager they'd never set eyes on each other before. A city this soft makes visitors glad of anyone loud.",
		"Strangers from the same far place find each other quickly here. I watched two humans from Westfall become old friends in the time it took to walk around the lake.",
	},
	["dar.muse.w23.stranger.012"] = {
		"notices a lone human sitting at the edge of the lake well apart from everyone: the only visitor who seems to have stopped trying to fit in, and the only one who looks at ease.",
		"passes a weathered dwarf asleep on the moss with his boots off, snoring very softly; the kaldorei step around him with something close to affection.",
	},
	["dar.muse.w23.stranger.013"] = {
		"The dwarves bring the smell of the forge with them, and up here, among moss and blossom, it hangs about them like a cloak they've forgotten to take off.",
		"You can tell where a visitor has come from by the smell: forge-smoke on a dwarf, oil and brass on a gnome, horse and road on a human. The kaldorei smell of nothing but the tree.",
	},
	["dar.muse.w23.stranger.014"] = {
		"In Darnassus I'm the strange creature. The owls, the great cats, the glowing water: all perfectly ordinary. Me, with my short years and loud boots, I'm the curiosity.",
		"Somewhere a young kaldorei will remember me as the odd, short-lived visitor who stared at everything. Fair enough. I'll remember them too.",
	},
	["dar.muse.w23.stranger.015"] = {
		"You look as lost as I feel. Pick a path; I'll follow and apologize to anyone on it.",
		"A fellow visitor! Tell me honestly: does your own voice sound too loud to you here as well?",
		"A guest as well? Then you'll understand why I've been standing on this bridge pretending to admire the view.",
	},
	["dar.muse.w23.stranger.016"] = {
		"I've apologized to a druid, a Sentinel and a fountain. The fountain was the most forgiving.",
		"I've said 'excuse me' more times in this city than in the rest of my life put together.",
		"Sorry, pardon, after you. My mouth seems to have forgotten how to form any other words.",
	},
	["dar.muse.w23.stranger.017"] = {
		"shares a quiet stretch of path with a visiting gnome, the two of them pointing things out to each other in whispers, like pupils on a tour of a temple.",
		"falls into step for a while with a human visitor, and the pair of them stop together at every carved railing, guests comparing notes in low voices.",
	},
	["dar.muse.w23.stranger.018"] = {
		"unfolds a creased map on a low wall, and within moments an elf has stopped, turned it the right way up without a word, and walked on.",
		"peers at a hand-drawn map of the terraces until a passing kaldorei leans over, taps one spot lightly, and is gone before any thanks can follow.",
		"stands at a fork turning a map round and round until an elf, without a word, points along the left-hand way and waits to see it taken.",
	},
	["dar.muse.w23.stranger.019"] = {
		"I asked how long the bank's been here. 'Not long,' she said. I've learned not to ask what that means.",
		"Everyone so tall and so calm. I feel like a pebble that rolled into a hall of statues.",
		"If I stand very still, will they take me for a local? No? It's the boots, isn't it.",
	},
	["dar.muse.w23.stranger.020"] = {
		"Somebody tell that gnome the fountain isn't a machine. He's been looking for the crank for ages.",
		"There goes a human at a run. Somebody ought to tell him: nothing here is going anywhere.",
		"That human has been bowing to a statue for some time now. Who's going to tell him?",
	},
	["dar.muse.w23.stranger.021"] = {
		"tries sitting cross-legged on the grass the way the kaldorei nearby do, holds it for a while with great dignity, and then quietly unfolds.",
		"lowers {g:himself|herself} onto the moss to match the elves sitting there, and finds that their ease does not come with the posture.",
	},
	["dar.muse.w23.stranger.022"] = {
		"is stared at, frankly and at length, by a very young kaldorei, the only one in the city who stares, until an elder murmurs a word and the stare becomes a careful little bow.",
		"catches a kaldorei child studying {g:his|her} boots with open fascination; a soft word from someone older, and the child looks up instead, and bows.",
	},
	["dar.muse.w23.stranger.023"] = {
		"The Sentinels are courteous to every visitor, but their eyes go a little harder when a stranger they can't place walks by. The war in Ashenvale taught them that.",
		"Courtesy to guests, yes, but the Sentinels never stop measuring them. A people at war in Ashenvale has learned that not everyone who visits comes as a friend.",
	},
	["dar.muse.w23.stranger.024"] = {
		"The druids here in the Enclave look at visitors the way they'd look at an unfamiliar seedling: interested, patient, and not yet sure what it will grow into.",
		"A druid in the Enclave asked a dwarf, very politely, to stop knocking on the wall to see whether it was hollow. The dwarf apologized to the druid and then, after a moment, to the wall.",
	},
	["dar.muse.w23.stranger.025"] = {
		"watches a visiting dwarf practice at the targets beside the Sentinels, loud, cheerful and accurate enough, while the elves around him say nothing in a way that is somehow very complimentary.",
		"pauses to watch a human soldier spar with a kaldorei trainer here, all borrowed courtesy and genuine bruises.",
	},
	["dar.muse.w23.sundering.001"] = {
		"There was a city where the sea is now, and a whole people asleep in it. The kaldorei who survived the Sundering talk about the ocean the way you'd talk about a grave you can't visit.",
		"The water that surrounds Teldrassil covers what the elves once called their capital. Some of them can't look at a calm sea without seeing roofs under it.",
	},
	["dar.muse.w23.sundering.002"] = {
		"Kalimdor was one land before the Well went under, the druids say, and every coast in the world is the edge of that wound. I'll never look at a cliff the same way.",
		"A druid told me the shorelines of the world are all scars of one single ruin. Every beach I've ever sat on, then, was once somewhere inland.",
	},
	["dar.muse.w23.sundering.003"] = {
		"follows the gaze of an old kaldorei toward the far edge of the canopy, where the sea lies, and realizes she is not looking at the water but at where a coast used to be.",
		"stands beside an elder who looks out between the boughs toward the open water and murmurs a name, too softly to catch, that no map has carried for a very long time.",
	},
	["dar.muse.w23.sundering.004"] = {
		"Of all the places to plant a tree after your homeland sank into the sea, they chose the sea. Either that's grief or the stubbornest joke in Azeroth.",
		"They lost their world to the water, and then built their new capital surrounded by it. I can't decide if that's defiance or a very old people's sense of humor.",
	},
	["dar.muse.w23.sundering.005"] = {
		"The Highborne who would not give up their magic were sent across the sea, east, and never welcomed back. It's an old exile, and still nobody in this city likes to be asked who was right.",
		"Exile was the kaldorei answer to the ones who clung to the arcane after the Sundering: a ship, a horizon, and no road home. A druid told me this and then changed the subject twice.",
	},
	["dar.muse.w23.sundering.006"] = {
		"The high elves of the east are the grandchildren of kaldorei exiles, a Sentinel said, and added nothing. I have rarely heard so much said with so little.",
		"Ask about the elves across the eastern sea and the kaldorei go quiet in a very particular way: not hostile, not fond. Like hearing news of a cousin who left in a slammed door.",
	},
	["dar.muse.w23.sundering.007"] = {
		"watches a child drop a pebble into a pool and an old elf gently close the child's hand before the second one, without a word of explanation.",
		"sees an elder kneel beside a little one splashing at a pool's edge and, with great patience, teach the child to touch the water without disturbing it.",
	},
	["dar.muse.w23.sundering.008"] = {
		"The water in the temple's well is the only water in Darnassus the priestesses will let you look into for a long time. All the rest, I notice, they keep moving.",
		"In the temple the water lies still and blessed. Everywhere else in the city it runs, splashes, falls. It occurs to me that the kaldorei may not trust water that stops.",
	},
	["dar.muse.w23.sundering.009"] = {
		"Their old capital is at the bottom of the sea. Puts my complaints about the inn in perspective.",
		"Lost a continent, built a tree. I lost a glove last week and sulked for days.",
	},
	["dar.muse.w23.sundering.010"] = {
		"Every kaldorei over a certain age carries a place in their head that no longer exists anywhere else. Not a ruin: nothing at all, not even rubble, just water.",
		"Humans mourn ruined towns because the ruins stay. The elves who outlived the Sundering mourn places that left no stone to put a hand on.",
	},
	["dar.muse.w23.sundering.011"] = {
		"A druid swore to me that on certain still hours, out past the roots of Teldrassil, you can hear bells under the water. I asked if she had heard them. She said she preferred not to.",
		"There's a story the boatmen at the roots tell, a Sentinel told me: bells below the waves where the old capital sank. She told it lightly, and didn't laugh at the end.",
	},
	["dar.muse.w23.sundering.012"] = {
		"After the world broke, they say, the survivors stood on a new shore with nothing, and the first thing they did was plant something. That instinct is still all over this city.",
		"The kaldorei answer to catastrophe seems to be gardening. They did it after the Sundering, they did it after Hyjal, and every flowerbed here says they'd do it again.",
	},
	["dar.muse.w23.sundering.013"] = {
		"notices a carving of a coastline worn into a railing, its line breaking off in the middle, and the smooth patch where countless fingers have stopped at the break.",
		"runs a thumb along a carved shoreline in an old panel and feels it end abruptly, the wood polished pale at that spot by many hands before.",
	},
	["dar.muse.w23.sundering.014"] = {
		"Somewhere out there is a shoreline a kaldorei elder used to walk to as a child, and now it's three days by ship in the wrong direction. Getting lost takes on a whole new meaning.",
		"For me the way home is a road. For some of the oldest elves here, the way home is straight down, under a great deal of water.",
	},
	["dar.muse.w23.sundering.015"] = {
		"Under the waves east of here lie the halls of the old capital. I wasn't born when they went down, and still the word for that sea catches in my throat.",
		"The elders have a word for the sea that means grave and cradle at once. When I was small I thought it was poetry. Now I hear it as a plain description.",
	},
	["dar.muse.w23.sundering.016"] = {
		"Lose a whole land and still keep your manners. I don't think I could.",
		"They lost everything to the sea and still say please. Some people are better than me.",
	},
	["dar.muse.w23.sundering.017"] = {
		"When the city's waterfalls get loud, the oldest kaldorei glance up for a moment, then go back to what they were doing. A reflex older than most kingdoms.",
		"I saw an elder flinch at the rush of a falling stream, then smile at himself for it. Whatever his ears remember, it was louder than this.",
	},
	["dar.muse.w23.sundering.018"] = {
		"The druids in the Enclave mention, very quietly, that a second well was found after the first one died. They say it as if confessing a debt, and they don't say where.",
		"Here among the druids I heard that not all the Well's waters were lost. The one who told me looked at the grass for a long moment afterward, as if it might be listening.",
	},
	["dar.muse.w23.sundering.019"] = {
		"The great whirlpool where the Well went down still turns somewhere far out in the ocean, sailors say. The kaldorei never name it. They just steer around the subject.",
		"There is a place at the heart of the sea where the water has never stopped turning since the Well collapsed. Ask an elf about it here and you'll be offered tea instead.",
	},
	["dar.muse.w23.sundering.020"] = {
		"They don't drop things in the water here. Given how the last big splash went, I understand.",
		"Never tell a kaldorei the sea looks peaceful. Trust me.",
	},
	["dar.muse.w23.sundering.021"] = {
		"Under the open sky the old ones sometimes stand and look east for a long while. Toward the sea, toward the exiles, toward whatever is left of that night. Nobody disturbs them.",
		"At this hour I've seen elders stop on the paths and face east, where the Highborne went. They never wave. They just stand there and remember who left.",
	},
	["dar.muse.w23.sundering.022"] = {
		"pauses beside a kaldorei crafter grinding a pale shell into powder for a dye; the shell, she remarks to no one, comes from a beach that was a hilltop once.",
		"stops by a workbench where a dyer crushes seashells into a fine violet dust, and hears her murmur that her grandmother's grandmother picked flowers where these shells were found.",
	},
	["dar.muse.w23.tongue.001"] = {
		"Ishnu-alah. Did I say it right? Don't answer; let me keep the hope.",
		"To you, Ishnu-alah. I've been practicing on the owls, and they never correct me.",
	},
	["dar.muse.w23.tongue.002"] = {
		"The priestesses part with Elune-adore. I heard one explain to a human that it means Elune be with you. Said softly, it sounds less like a farewell than a door eased shut.",
		"Elune-adore, at every parting. It asks the goddess to keep you company, a Sentinel told a gnome on the bridge. A kinder goodbye than most.",
	},
	["dar.muse.w23.tongue.003"] = {
		"Visitors learn to answer Andu-falah-dor without ever learning what it means. I watched a dwarf say it back with total confidence and a slight bow.",
		"The elf says Andu-falah-dor; the human answers Andu-falah-dor, carefully, like someone signing a paper he hasn't read.",
	},
	["dar.muse.w23.tongue.004"] = {
		"passes two kaldorei talking in their own tongue and hears them slip into Common for a sentence as {g:he|she} goes by, then back again, like someone stepping aside on a path.",
		"catches the soft run of Darnassian from a pair of elves on a bridge; they switch to Common mid-sentence for the passer-by's sake, and back once the way is clear.",
		"hears a Sentinel finish a sentence in Darnassian, notice who is standing near, and say the last of it once more in Common, in case it might be useful.",
	},
	["dar.muse.w23.tongue.005"] = {
		"Darnassian has no hard edges. Even an argument in it sounds like someone reading a long letter aloud.",
		"Guests who know no Darnassian still learn its moods: long vowels for courtesy, short clipped ones when a Sentinel has noticed something.",
		"A quarrel in Darnassian sounds like a recitation. I only know it was a quarrel because both elves walked off in opposite directions.",
	},
	["dar.muse.w23.tongue.006"] = {
		"Kaldorei Common is careful and a little antique: words I've only met in very dusty books, used correctly and without a trace of showing off.",
		"A druid apologized for her Common and then spoke it better than any herald in Stormwind. Nobody near her dared to open their mouth after that.",
	},
	["dar.muse.w23.tongue.007"] = {
		"overhears a gnome trying Ishnu-alah on a Sentinel three different ways, and the Sentinel, gravely, approving the third.",
		"watches a human mouth a Darnassian greeting silently all the way across a bridge, then lose his nerve at the far end and say hello.",
	},
	["dar.muse.w23.tongue.008"] = {
		"Three words of Darnassian, that's my whole store: Ishnu-alah, Elune-adore, Andu-falah-dor. I spend them like borrowed coins, in case they're worth more than I think.",
		"I know a greeting, a farewell and one phrase I can't translate. With those I've been understood here better than with all my Common.",
	},
	["dar.muse.w23.tongue.009"] = {
		"I heard a Sentinel explain to a dwarf that Ishnu-alah means good fortune to you. He's been saying it to everyone since, like a man handing out coins at a fair.",
		"A priestess said Ishnu-alah to a gnome, then translated it: good fortune to you. Then she said it once more, slower, so it would keep.",
	},
	["dar.muse.w23.tongue.010"] = {
		"I'm grateful for your patience with me. Elune-adore.",
		"Andu-falah-dor. Your kindness has been noticed, even if my manners haven't kept pace with it.",
		"I'll leave you in peace now. Elune-adore, and good fortune.",
	},
	["dar.muse.w23.tongue.011"] = {
		"listens as an elf repeats a set of directions more slowly, choosing simpler words each time, until the meaning lands and is met with a relieved nod.",
		"asks a question and watches the kaldorei who answers search for the plainest word in Common, the way one picks the smoothest stone to hand across a stream.",
	},
	["dar.muse.w23.tongue.012"] = {
		"Some of the words I hear on these terraces were spoken before the world broke apart, if the priestesses are right. Ordinary words now, about bread and boots.",
		"The druids say their tongue has barely changed in all the long ages. Imagine asking for bread in the same words as someone who saw the Sundering.",
	},
	["dar.muse.w23.tongue.013"] = {
		"A kaldorei laughed at something said in passing. A short, surprised laugh, quickly folded away again. Whoever earned it will be living on that for a while.",
		"It takes time to make a kaldorei laugh, and visitors rarely have their sort of time. A smile, though, can be had, and it's worth keeping.",
	},
	["dar.muse.w23.vigil.001"] = {
		"For centuries the druids slept in the Emerald Dream and the Sentinels kept the forests alone. The druids say thank you for it often. The Sentinels never seem to know what to answer.",
		"Druids dreaming, Sentinels standing watch, generation on generation. When a druid thanks a Sentinel for it now, I've noticed, she only nods, like someone handed back a borrowed cloak.",
	},
	["dar.muse.w23.vigil.002"] = {
		"watches two Sentinels hand over a post with a phrase so worn by use that it comes out as a single soft word, and a touch of the wrist that clearly means more.",
		"notices that when Sentinels change places they press wrists briefly, a gesture so practiced and so small that it must be older than the city around them.",
	},
	["dar.muse.w23.vigil.003"] = {
		"The orcs of the Warsong cut the old forest of Ashenvale for timber, and the Sentinels go down the tree to stop them, again and again. Up here they talk about it the way farmers talk about a flood that comes every year.",
		"Ashenvale bleeds a little more every season, and Darnassus sends Sentinels to stand in front of the axes. Nobody in this city mentions the Warsong without a hardness coming into their face.",
	},
	["dar.muse.w23.vigil.004"] = {
		"The Sentinels drilling on this terrace hold their positions far longer than any drill needs. A trainer told me it's not about the strike; it's practice for centuries of standing.",
		"Here the young Sentinels learn stillness before they learn anything else. An instructor said, without a smile, that waiting is the first weapon of her order.",
	},
	["dar.muse.w23.vigil.005"] = {
		"Their druids slept for centuries and they stood guard the whole time. I'd want an apology in writing.",
		"Imagine napping for a few hundred years while the Sentinels cover for you. Nobody here thinks that's funny but me.",
	},
	["dar.muse.w23.vigil.006"] = {
		"Cenarius himself fell in Ashenvale, struck down by Grom Hellscream. The kaldorei say the name of the demigod softly and the name of the orc not at all.",
		"The forest's own demigod was slain in Ashenvale by an orc warlord. Sentinels speak of it without shouting. That quietness is far more frightening than shouting would be.",
	},
	["dar.muse.w23.vigil.007"] = {
		"sees a Sentinel with a fresh scar along her forearm buckling on her gear by the path, unhurried and silent, plainly on her way back down to Ashenvale.",
		"catches sight of a Sentinel testing a stiff, newly mended shoulder in slow circles before she takes up her pack and starts toward the edge of the city without a backward look.",
	},
	["dar.muse.w23.vigil.008"] = {
		"A Sentinel said the hardest part of the long watch was not the enemies. It was the centuries with nobody to tell anything to, because the ones who would have listened were dreaming.",
		"What did the Sentinels talk about, all those years with the druids asleep? Each other, one of them told me. And then, for a long time, nothing at all.",
	},
	["dar.muse.w23.vigil.009"] = {
		"Now the druids are awake, and the Sentinels still give them directions as if they might doze off on the way.",
		"Sentinels have a certain tone for druids. Fond, brisk, faintly suspicious: the tone of someone who has watched you sleep through a few centuries of trouble.",
	},
	["dar.muse.w23.vigil.010"] = {
		"From Darnassus you can't see Ashenvale, but you can see the Sentinels who just came back from it. Their faces are the map.",
		"Nobody here needs a messenger from the south. When the Sentinels come back up the tree quieter than they went down, the whole city reads the news.",
	},
	["dar.muse.w23.vigil.011"] = {
		"watches an older Sentinel adjust a younger one's stance with two fingers at the elbow and a single word, and the young one hold the new position as if carved.",
		"sees a veteran Sentinel walk the line of trainees, pausing at each one only long enough to straighten a wrist or a chin, saying almost nothing.",
	},
	["dar.muse.w23.vigil.012"] = {
		"I watched a Sentinel and a druid pass on a bridge, exchange a look, and continue. Centuries of history in it: debt, fondness, a little reproach. All in one glance.",
		"For a moment, before the courtesy settles in, Sentinels look at druids in a particular way. It's the look of an old soldier at a friend who missed the war.",
	},
	["dar.muse.w23.vigil.013"] = {
		"The Sentinels kept faith with Elune all through the long vigil, a priestess said, with nobody to hear their prayers but each other. It explains why they still pray so briefly: they learned to keep it short on watch.",
		"A priestess told me the Sentinels pray in few words because they once prayed on watch for centuries, with eyes open. Even now, she said, they don't close them.",
	},
	["dar.muse.w23.vigil.014"] = {
		"Those Sentinels have stood guard longer than most kingdoms have had names. Mind your step around them.",
		"Whatever you think of patience, those guards have centuries on you. Show some respect.",
	},
	["dar.muse.w23.vigil.015"] = {
		"Every Sentinel who goes down to Ashenvale is one of ours walking into the axes. When the lists of the fallen come up the tree, I read them twice, and hope the second reading will be different.",
		"We used to bury no one. Now Ashenvale teaches us how, a few names at a time. I have learned the rites better than I ever wanted to.",
	},
	["dar.muse.w23.vigil.016"] = {
		"The long vigil ended, a Sentinel told me, not with a battle but with a druid waking, yawning, and asking what he had missed. She was still, I think, deciding how she felt about it.",
		"The way one Sentinel tells it, the druids came back from the Dream stretching and asking for news. 'Centuries of it,' she said. 'Where would you have started?'",
	},
	["dar.muse.w23.vigil.017"] = {
		"notices a Sentinel at rest with her back to a trunk, eyes open, perfectly at ease, and realizes she is sleeping, or doing whatever the long watch taught her in place of it.",
		"passes a Sentinel sitting on a root with her eyes half open and unmoving, so deep in some old watchful rest that a moth settles on her knee undisturbed.",
	},
	["dar.muse.w23.vigil.018"] = {
		"Every Sentinel in this city has a sister dead in Ashenvale and a good guess who swung the axe. I keep my hood low and my opinions about lumber to myself.",
		"They speak of the Warsong here the way my side speaks of the Scourge. Standing among them, I understand both a little too well for comfort.",
	},
	["dar.muse.w23.vigil.019"] = {
		"At this hour the Sentinels seem more themselves, their eyes catching the faint glow of the lamps. They kept the long watch through countless such hours, and you can tell they never stopped liking them.",
		"The dark suits the Sentinels. They move through it with the ease of people who kept watch in it for centuries while everyone else they loved was dreaming.",
	},
	["dar.muse.w23.vigil.020"] = {
		"I tried standing guard like a Sentinel. Lasted about as long as it takes to need a snack.",
		"Ten centuries on watch. I can't do ten minutes without fidgeting.",
	},
	["dar.muse.w23.vigil.021"] = {
		"The Sentinels speak of the trees of Ashenvale as if they were wounded comrades. 'They took three more by the river,' one said, and I needed a moment to understand she meant trunks.",
		"When a Sentinel counts the losses in Ashenvale, she counts trees along with sisters, in the same list, without a pause. I've stopped finding that strange.",
	},
	["dar.muse.w23.vigil.022"] = {
		"notices a Sentinel's gaze sweep the path out of pure habit, find nothing, and settle again, the way a hand pats a pocket to be sure.",
		"notes how a Sentinel glances down every path in turn, unhurried and thorough, a sweep so automatic she keeps talking to her companion straight through it.",
	},
	["dar.muse.w23.vigil.023"] = {
		"Their sisters are dying in Ashenvale and they still bow to strangers up here. Kind people. Hard people.",
		"Sentinels coming home from Ashenvale and going straight back. I'd at least sit down first.",
	},
	["dar.muse.w23.wander.001"] = {
		"My rule for finding things here was to follow the water. The water, it turns out, mostly leads to more water.",
		"Follow the stream, I thought, it must go somewhere useful. It went somewhere lovely instead, which is not the same.",
	},
	["dar.muse.w23.wander.002"] = {
		"takes the left-hand curve with great confidence and, some minutes later, walks out of it exactly where {g:he|she} went in.",
		"chooses a path, follows it patiently all the way round, and arrives at the very fork where the choosing began.",
	},
	["dar.muse.w23.wander.003"] = {
		"I asked a Sentinel the way. She pointed, and somehow even her arm managed to curve.",
		"Directions from a Sentinel: one long look, one gesture, and me too proud to ask her to repeat it.",
	},
	["dar.muse.w23.wander.004"] = {
		"From the bank to the Warrior's Terrace is about two tunes hummed through, if I don't stop to stare. I always stop to stare.",
		"Distances in Darnassus aren't measured in steps. They're measured in how many times you tell yourself it must be just round here.",
	},
	["dar.muse.w23.wander.005"] = {
		"hesitates at a fork, then falls in a few steps behind a druid who walks as if the way were obvious, and hopes for the best.",
		"stops where three paths part, waits for someone who looks certain, and follows a priestess at a respectful distance.",
	},
	["dar.muse.w23.wander.006"] = {
		"I followed a dwarf who walked with tremendous purpose. Three bridges later he stopped, looked around and asked me the way.",
		"A gnome has been walking very decisively ahead of me for some time. I'm beginning to suspect she's as lost as I am.",
	},
	["dar.muse.w23.wander.007"] = {
		"The paths are soft and wide and kind to the feet, so you never notice how far you've come until your knees present the bill.",
		"You can cross the whole of Darnassus without one climb worth complaining about. Then you sit down and find out what you've done.",
	},
	["dar.muse.w23.wander.008"] = {
		"passes the same stall for the third time, and the merchant behind it gives a slightly deeper nod each time.",
		"walks by the same flowerbed once more, until the gardener kneeling there looks up and greets {g:him|her} like an old acquaintance.",
	},
	["dar.muse.w23.wander.009"] = {
		"In other cities you get lost among walls and swear at them. Here you get lost among willows and moss, and there's nothing to swear at.",
		"It's hard to stay cross about being lost when every wrong turn ends at something worth looking at.",
	},
	["dar.muse.w23.wander.010"] = {
		"cuts across a lawn to save a long curve of path, feels the gaze of an old kaldorei sitting nearby, and finishes the shortcut on tiptoe.",
		"starts to take a shortcut over the grass, meets the calm eyes of a Sentinel, and goes back to the path without a word.",
	},
	["dar.muse.w23.wander.011"] = {
		"Two terraces apart, as the crow flies. I am not a crow.",
		"It's close, they said. As the crow flies, perhaps.",
		"Short walk, the Sentinel said. Sentinels walk to Ashenvale.",
	},
	["dar.muse.w23.wander.012"] = {
		"I'm learning the city by its smells. Leather and dye means I've gone wrong toward the crafters; incense means I've gone wrong toward the temple.",
		"Tanning vats one way, flowers and incense the other, steel and straw somewhere beyond. My nose knows Darnassus better than my feet do.",
	},
	["dar.muse.w23.wander.013"] = {
		"sketches the way to the bank on a scrap of paper, studies it, and turns it a quarter round, then another quarter, with mounting suspicion.",
		"draws a quick map in the margin of a notebook, and watches it become, line by line, a spiral.",
	},
	["dar.muse.w23.wander.014"] = {
		"Some days I don't ask the way at all. I pick a path and let it decide, and it has never taken me anywhere I regret.",
		"Getting lost in Darnassus has become a small pleasure. There's always someone to ask, and I almost never ask.",
	},
	["dar.muse.w23.wander.015"] = {
		"Past the water, round the tree, over the bridge. Every direction in this city seems to be the same direction.",
		"Let me guess. Over the bridge, along the water, and then a bit more. That's what everyone says about everything.",
	},
	["dar.muse.w23.wander.016"] = {
		"I tried counting my steps from the inn to the bank. I lost count somewhere near a fountain, at a number I didn't like.",
		"Somewhere past four hundred paces I stopped counting the way to the bank. Knowing would only have made it worse.",
	},
	["dar.muse.w23.wander.017"] = {
		"turns a full circle where several paths meet, then takes the one a passing cat chose, on the theory that it knows.",
		"stands at a crossing of paths, turning slowly on the spot like a weathervane waiting for an opinion.",
	},
	["dar.muse.w23.wander.018"] = {
		"I asked where the trainer was and got a history of the terrace. Lovely history. Still no idea where the trainer is.",
		"Every time I ask for directions here, I learn something. Never the directions.",
	},
	["dar.muse.w23.wander.019"] = {
		"From one terrace you can see the next, near enough to call across. Reaching it is another matter: down, round, over, up, and a good while gone.",
		"Everything in this city is within sight of everything else, and nothing is within reach of anything.",
	},
	["dar.muse.w23.wander.020"] = {
		"In this fog I can't even get lost properly. I can't see far enough to know which way is wrong.",
		"Fog over the city. I didn't know where I was before; now at least I have an excuse.",
	},
	["dar.muse.w23.wander.021"] = {
		"goes looking for a trainer among the overgrown halls of the Enclave, and is gently pointed three different ways by three different druids.",
		"climbs a ramp in the Enclave, then another, and comes out on a quiet landing with no clear memory of which ramp it was.",
	},
	["dar.muse.w23.wander.022"] = {
		"Visitors stop me on every path to ask the way. I give the directions slowly and carefully, and still watch half of them turn wrong at the bridge.",
		"Being kaldorei, I'm assumed to know every path in Darnassus. I know most of them. The rest I bluff with great dignity.",
	},
	["dar.muse.w23.welcome.001"] = {
		"A kaldorei welcome isn't a feast or a speech. It's room: room on the path, room in the conversation, room to stay as long as you like.",
		"Nobody here throws an arm round a guest's shoulders. The welcome is quieter than that: a place left free for you, and no one hurrying you out of it.",
	},
	["dar.muse.w23.welcome.002"] = {
		"Not so long ago, by kaldorei reckoning, outsiders who strayed into their forests met Sentinels, not greetings. Now dwarves sell maps on the terrace. A quick change, for them.",
		"The kaldorei kept the world out for ages. Letting outsiders walk their terraces must have taken more nerve than any battle.",
	},
	["dar.muse.w23.welcome.003"] = {
		"is greeted by a passing Sentinel with a single word of Darnassian and an open palm, and is left to work out the rest alone.",
		"receives a soft word of welcome from an elf watering the flowers, who does not stop watering them.",
		"is bidden welcome in Common by a druid who plainly had to reach for the words, and finds the reaching more touching than the words.",
	},
	["dar.muse.w23.welcome.004"] = {
		"Thank you for having me in your city. I'll leave it as I found it.",
		"Your city is generous to strangers. I won't forget it.",
		"I'll walk softly and touch nothing. It's the least a guest can do.",
	},
	["dar.muse.w23.welcome.005"] = {
		"Someone at the inn has set out a couple of lower stools, plainly for dwarves and gnomes. Nobody mentions them. That's the welcome, in one piece of furniture.",
		"Small mercies for short guests: a lower bench by the inn's fire. Somebody here thought about dwarves and gnomes, and told no one.",
	},
	["dar.muse.w23.welcome.006"] = {
		"Guests may walk into the Temple of the Moon, I'm told, so long as they walk quietly. That so private a people leave their holiest place open says more than any greeting.",
		"Nobody stopped me on the temple steps. The priestesses glanced up, saw someone passing through, and went back to their work. I took it as the deepest courtesy in the city.",
	},
	["dar.muse.w23.welcome.007"] = {
		"looks on as a Sentinel explains something to a cluster of visiting dwarves with great patience and many gestures toward the flowerbeds. The dwarves nod gravely and step off the grass.",
		"sees a party of dwarves steered gently off a lawn by a Sentinel who never once raises her voice; on the way, they apologize to the grass.",
	},
	["dar.muse.w23.welcome.008"] = {
		"Our guests tiptoe through Darnassus as if the tree might wake and object. I want to tell them it's only a tree, but that wouldn't be quite true.",
		"Dwarves on our bridges, gnomes at our bank, humans asking our Sentinels the way. Not long ago I'd not have believed it. I'm learning to like the noise.",
	},
	["dar.muse.w23.welcome.009"] = {
		"I said Elune-adore to a departing dwarf, and he said it back, badly and with enormous care. I haven't heard it said so well in a long while.",
		"A gnome thanked me with an Ishnu-alah she had plainly practiced on the way up. I answered in our tongue first, then in hers.",
	},
	["dar.muse.w23.welcome.010"] = {
		"If I were a Sentinel I'd have tired of 'where is the bank' by the third century. They answer it as if it were a fine question every time.",
		"The Sentinels must hear 'which way to the auction house' a hundred times a watch. The answer always comes with the same calm, as if nobody had ever asked before.",
	},
	["dar.muse.w23.welcome.011"] = {
		"Allies, they call us now. The word still sits a little stiffly on both sides, like a new coat. Give it time; the kaldorei have plenty.",
		"The Alliance has the kaldorei now, and the kaldorei have the Alliance. Neither seems sure yet which did the other the favor.",
	},
	["dar.muse.w23.welcome.012"] = {
		"is handed, without explanation, a small sprig of something fragrant by a young druid, who walks on before any thanks can be offered.",
		"finds a sprig of a pale, sweet-smelling plant pressed into {g:his|her} hand by a passing elf, who is gone before {g:he|she} can ask what it is for.",
		"is given a single pale blossom by a gardener, passed across a hedge like a coin of welcome, and is left holding it with no idea what comes next.",
	},
	["dar.muse.w23.welcome.013"] = {
		"No one here asks how the road was. I think it would seem an odd thing to ask: the road is behind you, and you're here.",
		"In Ironforge they want every detail of your journey. In Darnassus nobody asks a thing; having come is answer enough.",
	},
	["dar.muse.w23.welcome.014"] = {
		"Leaving a kaldorei conversation takes as long as starting one. There's a proper way down from it, like a stair, and you don't jump.",
		"Saying goodbye here is a small ceremony. I've learned to start leaving a good while before I actually mean to go.",
	},
	["dar.muse.w23.welcome.015"] = {
		"Peace to your terraces, and patience with your guests.",
		"Good fortune to this city, and to all who keep it.",
		"Keep well. I'll try to deserve the courtesy I've been shown here.",
	},
	["dar.muse.w23.welcome.016"] = {
		"observes a kaldorei walk a lost human the whole way to the bank rather than point, bow at the door, and walk the whole way back.",
		"notices an elf leave a stall unattended to guide a bewildered gnome across two bridges, and return later as if nothing had been missed.",
	},
	["dar.muse.w23.welcome.017"] = {
		"sees the merchant quietly round the price down after one look at {g:his|her} travel-worn gear, and decides it would be rude to object.",
		"pays what is asked and is handed back a coin, for reasons explained only by a small, closed smile.",
	},
	["dar.muse.w23.welcome.018"] = {
		"The inn on this terrace is where the guests end up, and you can hear it: Common spoken a little too loudly, laughter quickly hushed, a dwarf asking for something stronger.",
		"A visiting human tailor leans over a kaldorei worktable here, studying stitches too small to see, with the face of someone who has just been humbled and doesn't mind.",
	},
	["dar.muse.w23.wisp.001"] = {
		"A wisp hangs among the roots here in the Enclave, pulsing as slowly as a sleeper. The druids walk around it the way you'd step around a dozing cat.",
		"A wisp is drifting at knee height through this part of the Enclave, and the druids give it room without looking at it, as you would an old friend lost in thought.",
	},
	["dar.muse.w23.wisp.002"] = {
		"A priestess told me that wisps are what remains of the kaldorei who have gone on. Since then I keep my voice down near them, in case one is listening.",
		"Some say a wisp is a kaldorei soul that hasn't finished its business. Watching one hover by a doorway, I wondered what business it was, and whether it minded my staring.",
	},
	["dar.muse.w23.wisp.003"] = {
		"stops as a wisp drifts across the path at knee height, and waits for it to pass, the way one waits for an elder to finish crossing a room.",
		"halts in mid-step to let a wisp go by, and only walks on once the small pale light has slipped away behind a hedge.",
		"draws aside for a wisp floating past at eye level, and feels, absurdly, that a bow might be in order.",
	},
	["dar.muse.w23.wisp.004"] = {
		"Is that a wisp, or a very lost lamp?",
		"Something just glowed at me and floated off. In any other city I'd be worried. Here I'll call it a greeting.",
	},
	["dar.muse.w23.wisp.005"] = {
		"As the light goes, the fireflies rise out of the lawns one and two at a time, as if the grass were remembering sparks.",
		"The fireflies come up out of the grass now, slow and scattered, and for a while the lawns look like a sky that fell and didn't mind.",
	},
	["dar.muse.w23.wisp.006"] = {
		"spots a kaldorei child carrying a firefly in cupped hands to the edge of the water and letting it go, very solemnly, as if releasing a prisoner of war.",
		"comes upon a small elf crouched in the deep shade under a bough, hands cupped around a firefly, peering in between the fingers with enormous care.",
	},
	["dar.muse.w23.wisp.007"] = {
		"The moths here have taken the city's colors: violet on the wings, a little blue at the edges. Either they chose to match, or Darnassus painted them while they slept.",
		"Even the moths are dressed for Darnassus. I caught one on my sleeve, wings the exact violet of a priestess's robe, and it seemed to know how good it looked.",
		"A moth landed on a lamp and for an instant the two were the same color. Then the moth moved, and I couldn't find it again.",
	},
	["dar.muse.w23.wisp.008"] = {
		"follows with {g:his|her} eyes a big pale moth that flutters in past the bank's counter, makes one slow circuit of the room as if checking its balance, and leaves again unsatisfied.",
		"sees a moth settle on the edge of an open ledger, and the clerk write carefully around it rather than disturb it, letter by letter.",
	},
	["dar.muse.w23.wisp.009"] = {
		"The lamps aren't all one color. Walk slowly and you see them pass from violet to blue and back again, like a thought someone keeps changing their mind about.",
		"No two of the city's lamps burn quite the same shade. One is nearly lilac, the next as blue as deep water, and the path between them takes a little of each.",
		"Nearly every lamp in the city sits in a little cage of carved wood, each one shaped differently: a seed pod, a curled leaf, a bud about to open. I've stopped looking for two alike.",
	},
	["dar.muse.w23.wisp.010"] = {
		"The light under the great leaves is green, the green of a bottle held up to a window. I've given up guessing the hour by it.",
		"Everything down here is lit through leaves: faces, stone, water, my own hands. After a while the green stops being a color and becomes the air itself.",
		"Under these leaves even white stone turns faintly green. I rinsed my hands in a fountain and they came out looking like someone else's.",
	},
	["dar.muse.w23.wisp.011"] = {
		"tracks a pale patch of light as it slides across the moss with the shifting of the leaves high above, and stays to see where it will settle.",
		"follows a drifting spot of brightness across the lawn with {g:his|her} eyes, as the boughs overhead move and let it wander from stone to stone.",
	},
	["dar.muse.w23.wisp.012"] = {
		"Even the insects in this city glow. I feel badly lit.",
		"The beetles glow, the moths glow, the water glows. I'm the only thing here that came unlit.",
	},
	["dar.muse.w23.wisp.013"] = {
		"The druids say wisps by the thousand rose against the Legion at Hyjal. Watching one drift past a flowerbed, small and slow, I find that hard to picture, and harder to forget.",
		"I've heard that at Hyjal the wisps came out of the forest like a tide of lamps. This one is fussing over a hedge. I suppose even soldiers keep gardens.",
	},
	["dar.muse.w23.wisp.014"] = {
		"Between two lamps a spider has strung its web, and the glow catches every thread. It's the finest piece of work on the whole terrace, and the maker is the size of my thumbnail.",
		"A web hung across a lamp's glow, each strand lit blue from behind. Every crafter in the city would envy that stitching, if they ever stopped to look.",
	},
	["dar.muse.w23.wisp.015"] = {
		"Wisps don't frighten me. Some of them, the priestesses say, were people who walked these paths before me. I nod to them as I pass, the way I'd nod to anyone.",
		"When a wisp drifts close I stand still and let it look. If the priestesses are right, it may be someone of ours, come to see what we made of the tree.",
	},
	["dar.muse.w23.wisp.016"] = {
		"reaches out to a drifting point of light without thinking, and it slips between {g:his|her} fingers like a seed on the air.",
		"lifts a hand toward a small glow floating at shoulder height; the glow considers the hand, then rises just out of reach and stays there.",
		"makes a slow grab at a passing glimmer, misses by a hand's width, and pretends to have been reaching for a strap all along.",
	},
	["dar.muse.w23.wisp.017"] = {
		"Nothing here throws a hard shadow. The light comes from the lamps, the water, the leaves themselves, so softly that my own shadow looks unsure of where to fall.",
		"My shadow in Darnassus is a faint, uncertain thing, pulled three ways by three soft lights. I keep glancing down to make sure it's still following me.",
	},
	["dar.muse.w23.wisp.018"] = {
		"A moth has spent the whole time I've been sitting here trying to get inside a lamp. I admire the persistence. I'd admire it more if it had a plan.",
		"One moth circles the same lamp over and over, never landing, never leaving. I recognize the technique. It's how I look for the bank.",
	},
	["dar.muse.w23.wisp.019"] = {
		"Little light, if you're someone's ancestor, I apologize for nearly walking through you.",
		"Pardon me. I didn't see you there. Well, I did. You glow.",
	},
	["dar.muse.w23.wisp.020"] = {
		"Everything here is green. My hands are green. Are my hands green? Don't answer that.",
		"In this light everyone looks as if they've eaten something doubtful. Me too, I expect.",
	},
	["dar.npc_meet.w23.asker.001"] = {
		"The request begins with a history. Then some context. Then a pause to make sure I've followed. I suspect the task itself will be the shortest part.",
		"Before telling me what's needed, the one asking tells me why, and before why, a little of how things came to be this way. I settle in.",
		"A kaldorei request has a shape: a long root, a slow trunk, and at the very top, the small thing they actually want done.",
	},
	["dar.npc_meet.w23.asker.002"] = {
		"is looked over carefully by {other} before a single word of the request is spoken, as if the asking depended on an answer nobody has voiced.",
		"waits while the kaldorei across from {g:him|her} decides, visibly and without hurry, whether to ask at all.",
	},
	["dar.npc_meet.w23.asker.003"] = {
		"You look like you've been waiting to ask someone something. Will I do?",
		"I'm listening. Take all the time you need; I gather that's a lot.",
		"{other}? You have the look of someone with a favor to ask. Go on.",
	},
	["dar.npc_meet.w23.asker.004"] = {
		"Asking for help costs something here. It's in the stiff courtesy, in the eyes that settle on my shoulder rather than my face.",
		"There's pride in the way the request is put, carefully, as if it pains the speaker a little to need anyone at all. I know the feeling.",
	},
	["dar.npc_meet.w23.asker.005"] = {
		"listens to the request with {g:his|her} hands folded, the way the one asking has folded theirs, and only lets them fall when the last word is said.",
		"mirrors the stillness of the one asking without meaning to, and finds that it makes the listening easier.",
	},
	["dar.npc_meet.w23.asker.006"] = {
		"Three courtesies, a remark about the tree, and a long look. I still don't know what's wanted, but I know I'm going to say yes.",
		"The preamble alone would fill a meal. I'm hungry, but I'm also curious, which is worse.",
		"Somewhere in this careful speech there's a request. I'll find it if I keep listening, like a coin at the bottom of a deep pool.",
	},
	["dar.npc_meet.w23.asker.007"] = {
		"is beckoned closer and then, oddly, asked to sit before anything else is said, as though the request were too heavy to be heard standing.",
		"accepts an invitation to sit, a cup of water, a moment of quiet, and only then the first words of what is needed.",
	},
	["dar.npc_meet.w23.asker.008"] = {
		"I'm not sure why the kaldorei ask outsiders for help so readily these days. Too few of their own to spare, perhaps, with Ashenvale taking so many.",
		"An elf asking someone like me for help. It says something about how thin their numbers are stretched, and they know I've noticed.",
	},
	["dar.npc_meet.w23.asker.009"] = {
		"Before you start: is this going to be a long story? I only ask so I can find somewhere to lean.",
		"Don't tell me yet. Let me guess: it matters, it's delicate, and nobody else has the time.",
	},
	["dar.npc_meet.w23.asker.010"] = {
		"The one asking speaks evenly, but a name slips into the preamble once and never comes up after. I think that's the real reason for the request.",
		"Something grief-shaped sits under the courtesy. I don't ask. If it's mine to know, it'll come out in the telling.",
	},
	["dar.npc_meet.w23.asker.011"] = {
		"catches the moment {other} decides to trust {g:him|her}: a small easing of the shoulders, and the voice dropping a little lower.",
		"notices the one asking glance once toward the Temple of the Moon before beginning, as if for leave.",
		"sees the asking begin with a long look at {g:his|her} hands, as though they were the real references being checked.",
	},
	["dar.npc_meet.w23.asker.012"] = {
		"Whatever it is, ask plainly. I'll answer the same way.",
		"You needn't be so careful with me. I'll hear you out either way.",
	},
	["dar.npc_meet.w23.asker.013"] = {
		"Some requests in this city, I've learned, wait years for the right listener. This one has the dust of patience on it.",
		"The asking is careful, as if the matter had been turned over for a long season before anyone was trusted with it.",
	},
	["dar.npc_meet.w23.hearth.001"] = {
		"The innkeeper's eyes go over me once, boots to shoulders, and I'd swear the length of my sleep has just been decided for me.",
		"One unhurried look, and the innkeeper has worked out whether I need food, a bed or just a place to stop moving. I suspect all three.",
	},
	["dar.npc_meet.w23.hearth.002"] = {
		"is handed a shallow bowl of water to rinse {g:his|her} hands before a single word about rooms or prices is spoken.",
		"receives, before anything else, a small basin of cool water and a cloth, and understands that the talking will start once {g:his|her} hands are clean.",
	},
	["dar.npc_meet.w23.hearth.003"] = {
		"{other}, is it? A room, please, the quietest you have. Which I suppose is any of them.",
		"Any bed will do. I'll be asleep before I've finished admiring it.",
		"Do you have a room that creaks? I've stopped trusting places without a single creak.",
	},
	["dar.npc_meet.w23.hearth.004"] = {
		"No questions about where I've been or where I'm going. Only one: do I sleep light or deep. I didn't know the answer until I was asked.",
		"Not a word about my business here. The innkeeper asks only how lightly I sleep, and it's the most thoughtful question I've heard in a long while.",
	},
	["dar.npc_meet.w23.hearth.005"] = {
		"sets down {g:his|her} pack by the counter and is gently steered to move it a hand's width to the left, out of the way of whoever comes next.",
		"drops {g:his|her} things in a heap and watches them quietly rearranged, without comment, into a tidier pile.",
	},
	["dar.npc_meet.w23.hearth.006"] = {
		"How many travelers has this innkeeper put to bed? Kaldorei count such things in centuries. I'm a very small entry in a very long book.",
		"Somewhere in the innkeeper's memory there may be guests from before Stormwind had walls. I'll try not to be the one remembered for snoring.",
	},
	["dar.npc_meet.w23.hearth.007"] = {
		"A bed, if you have one, and nothing to be woken for.",
		"Just a place to sit for a while, and no news. Can you manage that?",
	},
	["dar.npc_meet.w23.hearth.008"] = {
		"The innkeeper took one look at me and set out a plate of fruit and flat bread without being asked. I must look hungrier than I thought.",
		"Bread before I'd asked for anything. Either I'm wearing my hunger on my face, or kaldorei innkeepers can smell it.",
	},
	["dar.npc_meet.w23.hearth.009"] = {
		"sees {other} lay two fingers lightly on the counter, a quiet gesture that seems to mean: rest is here, ask for it.",
		"watches the innkeeper tap the counter twice, softly, and glance toward the rooms, which is apparently the whole of the welcome, and plenty.",
	},
	["dar.npc_meet.w23.hearth.010"] = {
		"I started to haggle over the room out of habit and got such a puzzled, kindly look that I paid the asking price and apologized.",
		"Nobody haggles with an innkeeper in Darnassus, it seems. I tried, and was gently made to feel I'd asked the price of the tree.",
	},
	["dar.npc_meet.w23.hearth.011"] = {
		"mentions sore feet in passing and is answered with a small jar of something green and a single word of instruction.",
		"lets slip a complaint about the long paths and gets back a sympathetic look and a cushion for the seat.",
	},
	["dar.npc_meet.w23.hearth.012"] = {
		"Whatever room you have. Any bed in our city sleeps better than the road.",
		"The room nearest the water, if it's free. Some habits of home I keep.",
	},
	["dar.npc_meet.w23.hearth.013"] = {
		"Innkeepers anywhere get used to goodbyes. One who might keep this post for centuries must have a whole craft of them, light and practiced and never quite careless.",
		"Every guest leaves. An innkeeper who could outlive all of them has had to make peace with that, and the peace shows in how gently a room is handed over.",
	},
	["dar.npc_meet.w23.hearth.014"] = {
		"counts coins onto the counter for a room and has one slid gently back: too much, by exactly that one.",
		"overpays for the room by a copper and watches the copper travel back across the counter, nudged by a single patient finger.",
	},
	["dar.npc_meet.w23.hearth.015"] = {
		"Is there a rule about boots in the rooms? I'd hate to offend the floor.",
		"I'll be quiet, I promise. Quieter than I've ever been anywhere, which isn't saying much.",
		"Wake me if the tree falls over. Otherwise, don't.",
	},
	["dar.npc_meet.w23.hearth.016"] = {
		"The innkeeper hums while wiping the counter, a tune too slow to follow and too old to name. I find myself leaning in to catch it.",
		"There's a low, unhurried humming behind the counter. Whatever the tune is, it was old before anyone I know was born.",
	},
	["dar.npc_meet.w23.hearth.017"] = {
		"is looked over by the innkeeper with an expert eye, the eye of someone who can tell a long road from a short one by the way a traveler sits down.",
		"sits, and is read at once: the innkeeper takes in the set of {g:his|her} shoulders and brings water, not wine.",
	},
	["dar.npc_meet.w23.tutor.001"] = {
		"Before teaching me anything, the trainer asked me to show what I already knew, then watched in silence long enough for me to start doubting all of it.",
		"Show me, the trainer said, and nothing else. I showed. The silence afterward taught me more than the lesson did.",
		"The real test isn't the lesson; it's how I wait for it. I fidget. The trainer notices, and says nothing, which is worse.",
	},
	["dar.npc_meet.w23.tutor.002"] = {
		"has {g:his|her} wrist turned a fraction by the trainer's fingertip, a correction so small it can't possibly matter, and then it does.",
		"feels a light tap at the elbow, then another at the shoulder, and understands only afterward that {g:his|her} whole posture has been rewritten.",
		"is corrected without a word: a hand raised, a palm tilted, and the trainer waiting for {g:him|her} to see it.",
	},
	["dar.npc_meet.w23.tutor.003"] = {
		"How long does this usually take to learn? No, wait. Don't tell me in kaldorei years.",
		"I'm a quick study. By your standards, I'm a blur.",
		"Is that a nod of approval, or are you just being patient with me?",
	},
	["dar.npc_meet.w23.tutor.004"] = {
		"The trainer mentions a teacher of their own, in passing, in a tone that makes it plain the teacher has been gone a very long time and is still being obeyed.",
		"Somewhere behind every lesson here is an older lesson, and an older teacher. I can hear them in the pauses.",
	},
	["dar.npc_meet.w23.tutor.005"] = {
		"bows to {other} before the lesson, and receives a bow of exactly the same depth, which feels like the first thing taught.",
		"inclines {g:his|her} head to the trainer and gets back a precise answering nod, neither deeper nor shallower: a lesson in itself.",
	},
	["dar.npc_meet.w23.tutor.006"] = {
		"I got a single word of praise. In this city, from this trainer, I suspect that's a parade.",
		"Good, the trainer said. Just that. I'll be living on it for a week.",
		"Praise here comes in very small coins. I've just been handed one, and I'm holding it carefully.",
	},
	["dar.npc_meet.w23.tutor.007"] = {
		"repeats the same small motion for the trainer five times, then a sixth, and on the sixth sees a faint nod.",
		"is asked to do it once more, and once more, and only at the end understands the trainer was counting not the attempts but the differences between them.",
	},
	["dar.npc_meet.w23.tutor.008"] = {
		"The trainer teaches me as kaldorei teach kaldorei: no extra patience, no softening. It is very good to be expected to keep up.",
		"No allowances for me here, and no slowness put on for show. Among our own, a lesson is a lesson.",
	},
	["dar.npc_meet.w23.tutor.009"] = {
		"Teach me what you'd teach anyone. I'd rather be corrected than spared.",
		"I'm listening. And watching. And trying not to fidget, which is the hard part.",
	},
	["dar.npc_meet.w23.tutor.010"] = {
		"I was told to practice, and to come by when it feels easy. Not when I'm tired of it. Not when I think I've got it. When it feels easy.",
		"Practice it until it bores you, the trainer said, and then a little more, because that is where it starts to be yours.",
		"The advice is always the same, gently given: slower. Not better, not harder. Slower. I'm beginning to think it's the whole secret.",
	},
	["dar.npc_meet.w23.tutor.011"] = {
		"tries to hurry the lesson along with an eager question and is answered, kindly, with a longer silence than before.",
		"asks whether that's all, and sees the trainer's eyebrow rise by a hair, which apparently means far from it.",
		"nods as if {g:he|she} understood, and is asked, very gently, to explain it back.",
	},
	["dar.npc_meet.w23.tutor.012"] = {
		"Odd: the trainer barely looks at my hands. It's my face that gets watched, as if the mistakes start there and the hands only finish them.",
		"Most teachers watch what you do. This one watches where I'm looking. Twice I was corrected before I'd moved at all.",
	},
	["dar.npc_meet.w23.tutor.013"] = {
		"Thank you. I'll practice it the way you showed me, not the way I'd rather.",
		"I'll remember that correction. Probably at the worst possible moment, but I'll remember it.",
	},
	["dar.npc_meet.w23.tutor.014"] = {
		"waits while the trainer finishes with a kaldorei pupil, who leaves with the same faintly stunned look {g:he|she} will probably be wearing shortly.",
		"stands aside as another student is dismissed with a nod, and recognizes the expression: someone who has just learned how much is left to learn.",
	},
	["dar.npc_meet.w23.tutor.015"] = {
		"The trainer asked nothing about where I've trained before or with whom. Only watched me move, and seemed to read the whole list from that.",
		"Whoever taught me before is written all over how I stand, apparently. It was read in a glance, and the unpicking began at once.",
	},
	["dar.npc_meet.w23.vault.001"] = {
		"The banker looks up my name with the gravity of someone consulting a very old map, and finds me, it seems, on a minor tributary.",
		"My account is a few lines in a very large book. The banker turns to them as respectfully as if they were a chapter.",
		"I'm sure my account is the least interesting thing in this vault. Nobody behind the counter would ever let me know it.",
	},
	["dar.npc_meet.w23.vault.002"] = {
		"hands over a small bundle for safekeeping and watches it wrapped, labeled in fine script and carried off as if it held something precious.",
		"deposits a few odds and ends and sees each one listed separately, down to a chipped button.",
		"asks for an item out of storage and waits while it is fetched, unwrapped and presented with a faint air of ceremony.",
	},
	["dar.npc_meet.w23.vault.003"] = {
		"Careful with that pouch. It's mostly sentimental value and lint.",
		"{other}, I'm leaving more than usual. Don't look so pleased; it's mostly odds and ends.",
		"Put it somewhere safe, please. Somewhere I can forget about it properly.",
	},
	["dar.npc_meet.w23.vault.004"] = {
		"There's a strange comfort in handing my things to someone who will very likely still be at this counter long after I'm gone. My odds and ends may outlive me in good company.",
		"Whatever I leave here will be looked after by someone with centuries to spare. It's the nearest thing to permanence I own.",
	},
	["dar.npc_meet.w23.vault.005"] = {
		"sees the banker wipe a smudge off a coin before entering it in the ledger, and suddenly finds {g:his|her} own coins rather grubby.",
		"watches a tarnished copper turned over twice, examined, and accepted with an expression of great generosity.",
	},
	["dar.npc_meet.w23.vault.006"] = {
		"The banker remembered what I'd left last time, unasked, down to the order I'd handed it over in. I'm not sure I like being that legible.",
		"Before I'd said a word, the right drawer was already open. Either kaldorei bankers are very good, or I'm very predictable.",
	},
	["dar.npc_meet.w23.vault.007"] = {
		"Everything in, please, except the coin. The coin and I aren't finished with each other.",
		"Just the one bag, please. The rest can keep each other company.",
	},
	["dar.npc_meet.w23.vault.008"] = {
		"I wonder what the kaldorei themselves leave in this bank. Not coin, I'd guess. Things saved from cities that lie under the waves now, perhaps.",
		"My deposits sit somewhere in here beside things far older and dearer than I can guess. Heirlooms of a people who lost most of theirs.",
	},
	["dar.npc_meet.w23.vault.009"] = {
		"signs the ledger where a long finger indicates, and notices {g:his|her} own name looks clumsy beside the flowing columns above it.",
		"adds {g:his|her} mark to the bank's book and leaves a small blot, which the banker regards for a moment and then, graciously, ignores.",
	},
	["dar.npc_meet.w23.vault.010"] = {
		"I've never been thanked so sincerely for depositing a handful of silver. I might start doing it just for the courtesy.",
		"The banker treats my small savings with exactly the same care as anyone's fortune. It's either very kind or very tactful, and I'm not sure there's a difference.",
		"In other cities the bank reminds me how little I have. This one trusts me with its courtesy, which is somehow worse for the purse.",
	},
	["dar.npc_meet.w23.vault.011"] = {
		"waits at the counter behind a dwarf depositing an alarming quantity of ore, and admires the banker's complete lack of surprise.",
		"stands in line behind a gnome whose deposit takes some time to list, and notes that the pen across the counter never once speeds up.",
	},
	["dar.npc_meet.w23.wares.001"] = {
		"Whatever I buy gets wrapped in a broad leaf and tied off with a twist of grass. It all looks like a gift from someone very patient.",
		"The wrapping takes longer than the sale. Leaf, fold, tie, a small smoothing pass of the palm. I've never seen so much ceremony over a few coppers.",
		"I tried to say there was no need to wrap it. The look I got suggested that wasn't really a choice.",
	},
	["dar.npc_meet.w23.wares.002"] = {
		"names a price a little too quickly and watches the merchant consider it, then consider {g:him|her}, then decline both with a smile.",
		"offers a counter-price and receives a long, interested look, as though the merchant were wondering where such a custom came from.",
	},
	["dar.npc_meet.w23.wares.003"] = {
		"How much? No, that's fair. I just like asking.",
		"Don't tell me the price yet. Let me admire it a moment first; that seems to be how it's done here.",
		"{other}, I'll take it. Before I think about it as long as you would.",
	},
	["dar.npc_meet.w23.wares.004"] = {
		"The merchant can name the maker of every piece laid out, and the year it was made. For some of them the year is a very long way back.",
		"Each thing for sale comes with a short history: who made it, what it was for, who owned it last. I only wanted a strap.",
		"I asked about one item and learned about its maker, its maker's teacher, and the grove the wood came from. I bought it out of respect.",
	},
	["dar.npc_meet.w23.wares.005"] = {
		"pays and watches the coins sorted into three small wooden bowls by metal, each one set down without a sound.",
		"hands over the coins and sees them go not into a purse but into a carved dish, laid side by side like seeds in a row.",
	},
	["dar.npc_meet.w23.wares.006"] = {
		"In two whole conversations the merchant has not once called anything a bargain. It's unsettling. How am I supposed to know what to distrust?",
		"No merchant in this city has told me I'm getting a good deal. I keep waiting for it, the way you wait for the other boot to drop.",
	},
	["dar.npc_meet.w23.wares.007"] = {
		"Show me whatever lasts longest. I'm hard on things.",
		"What do you have for someone who wears through boots faster than an elf wears through years?",
	},
	["dar.npc_meet.w23.wares.008"] = {
		"Among the wares, half hidden, a cup of old silver worked with patterns I've only seen on Darkshore's broken stones. Not for sale, I'm told gently, and it's covered again.",
		"One thing at the back of the cloth is never offered: a small, worn bowl in an older style. I didn't ask. The care in how it was moved said enough.",
	},
	["dar.npc_meet.w23.wares.009"] = {
		"reaches for a trinket at the same moment as a kaldorei customer, and both withdraw their hands so politely that the merchant ends up offering it to neither.",
		"hesitates so long over two nearly identical pouches that the merchant, very kindly, puts one of them away.",
		"asks what something is for, gets a slow and thorough answer, and still has no idea, but nods anyway.",
	},
	["dar.npc_meet.w23.wares.010"] = {
		"The prices are fair and fixed and written in a hand nicer than any I'll ever own. Haggling would feel like scribbling on it.",
		"Everything here is marked, in small careful script, and nothing about the merchant suggests the marks are a starting point.",
	},
	["dar.npc_meet.w23.wares.011"] = {
		"Is this made from the tree? Should I apologize to it?",
		"I'll buy it. Please don't wrap it in anything prettier than I am.",
		"You've arranged these so nicely I feel bad taking one.",
	},
	["dar.npc_meet.w23.wares.012"] = {
		"watches a small brass scale settle, then settle once more, the merchant waiting for it to be perfectly still before naming the sum.",
		"stands by while a handful of something is weighed out, one grain added, removed, and added back.",
		"waits as the scale is read twice, once from each side, and the price pronounced like a verdict nobody minds.",
	},
	["dar.npc_meet.w23.wares.013"] = {
		"The merchant is perfectly courteous, and a shade slower with me than with the elf before me, as if making sure each word lands. I can't decide whether to be touched or offended.",
		"I get the same goods at the same price as the kaldorei in front of me, only explained twice as carefully. I'll take it as kindness.",
	},
	["dar.npc_meet.w23.wares.014"] = {
		"This stall can't be more than a few years old; the whole city is barely older. But the one behind it sells like someone who has kept a counter in a dozen cities that no longer stand.",
		"New city, old trade. The merchant's patter is gentle and polished, worn smooth by a great many more years than Teldrassil has had.",
	},
	["dar.npc_meet.w23.wares.015"] = {
		"completes a purchase and receives it in both of the merchant's hands, as if the thing were being entrusted rather than sold.",
		"takes the goods held out across the counter on two open palms, and very nearly bows without meaning to.",
	},
	["dar.npc_meet.w23.wares.016"] = {
		"I need something sturdy, not something beautiful. Though I see that's hard to find here.",
		"Just the plain one, please. I'm not sure I'm worthy of the carved one.",
	},
	["dar.npc_meet.w23.wares.017"] = {
		"Out of reflex I counted my change. Correct to the copper, of course, and the merchant watched me do it with the faint pity owed to people from louder cities.",
		"I checked the coins twice. They were right both times, and I felt a little foolish, and a little homesick for markets where they wouldn't be.",
	},
	["dar.npc_meet.w23.watch.001"] = {
		"Her armor has been mended in three places, each by a different hand. I can read a few campaigns in that stitching without being told a word of them.",
		"Patched leather at the shoulder, a newer plate at the hip, an old dent nobody bothered to hammer out. This Sentinel's armor has been places.",
		"The mending on her armor is neat and recent. Whatever tore it, she has clearly decided it isn't worth mentioning.",
	},
	["dar.npc_meet.w23.watch.002"] = {
		"asks a Sentinel the way and gets it in six words and one raised finger, which turns out to be exactly enough.",
		"asks for directions and receives them from a Sentinel without a wasted syllable: a glance down the path, a turn of the wrist, done.",
	},
	["dar.npc_meet.w23.watch.003"] = {
		"Her eyes went to my hands first, then my belt, then my face. A whole inspection in the time it took me to say hello, and I passed, apparently.",
		"Hands, belt, face: that's the order a Sentinel looks at you in. I only noticed because I've started doing it back.",
	},
	["dar.npc_meet.w23.watch.004"] = {
		"I'll keep my hands where you can see them, Sentinel. Habit, not guilt.",
		"No need to watch me that closely. The most dangerous thing I'll do here is drop a coin in the lake.",
		"Relax, Sentinel. Whatever you're braced for, it isn't me.",
	},
	["dar.npc_meet.w23.watch.005"] = {
		"offers a Sentinel a polite greeting and hears it handed back word for word, weighed and returned at full value.",
		"greets a Sentinel and gets the very same words back, in the same order, as if courtesy here were a coin that must not be short-changed.",
	},
	["dar.npc_meet.w23.watch.006"] = {
		"Somewhere behind her composure there's a tiredness she won't let reach her shoulders. I don't ask. I doubt she'd tell me who she stood beside last.",
		"Her face gives nothing away, but the eyes are older than the face, and tired in a way the posture refuses to show.",
	},
	["dar.npc_meet.w23.watch.007"] = {
		"notices a Sentinel's glaive resting an inch to the left of where it was a moment ago, and cannot for the life of {g:him|her} say when she moved it.",
		"looks away from a Sentinel for a moment and looks back to find her glaive at a slightly different angle, with no movement seen in between.",
	},
	["dar.npc_meet.w23.watch.008"] = {
		"Sentinels don't salute anyone that I've seen. They lower the chin, once, and lift it again. I've caught myself doing the same, and I couldn't say when I started.",
		"A dip of the chin, no more. That's how a Sentinel acknowledges you, and somehow I've picked the habit up without meaning to.",
		"She lowered her chin a hair's breadth as I passed. I lowered mine. Neither of us mentioned it, which seems to be the custom.",
	},
	["dar.npc_meet.w23.watch.009"] = {
		"May I ask your name, Sentinel? No? Your post, then. That will do.",
		"I asked your name and you told me your post. Fair enough. I'll remember the post.",
	},
	["dar.npc_meet.w23.watch.010"] = {
		"steps out of a Sentinel's path before she has asked, then wonders what exactly in her bearing gave the order.",
		"moves aside for a Sentinel without being told, and only afterward realizes that nothing was said at all.",
		"finds {g:himself|herself} yielding the path to a Sentinel out of pure instinct, the way water gives way to a stone.",
	},
	["dar.npc_meet.w23.watch.011"] = {
		"She greets the kaldorei who pass with a word in their own tongue, and me with a nod. Fair enough; the nod is the part I understand.",
		"Two elves get a quiet phrase in Darnassian; I get a nod. I'm not offended. I'd only have mangled the reply.",
	},
	["dar.npc_meet.w23.watch.012"] = {
		"The Sentinel answers my greeting in our own tongue, briefly, the way one speaks to a neighbor. Under these branches that is enough to feel known.",
		"Ishnu-alah, she says, and I say it back. A small exchange, and the watch over our city feels a little less like a wall.",
	},
	["dar.npc_meet.w23.watch.013"] = {
		"Her eyes pass over me and move on. I keep my pace exactly as it was and don't let my shoulders ask for anything.",
		"A Sentinel's gaze, unhurried and complete. Mine stays on the path. In this city the best disguise is having nothing to say.",
	},
	["dar.npc_meet.w23.watch.014"] = {
		"That armor has seen some hard miles, Sentinel. Ashenvale, I'd guess. I'm glad you're up here for a while.",
		"Ashenvale left its marks on that armor, I think. Rest your eyes when you can, Sentinel.",
	},
	["dar.npc_meet.w23.watch.015"] = {
		"straightens without meaning to under a Sentinel's look, shoulders back and chin level, like a soldier caught slouching.",
		"stands a little taller as the Sentinel's gaze arrives, and sags again, faintly embarrassed, once it has moved on.",
	},
	["dar.npc_meet.w23.watch.016"] = {
		"When she looks at me I have the odd feeling of being measured against everyone she has ever let pass. A long line, that, and I'm somewhere near the end of it.",
		"This Sentinel may have kept watches since before the oldest city I know was founded. I try to look like something worth a moment of all that.",
		"Hard to guess her age. Easier to guess how many travelers have walked past her post: all of them, more or less, since the tree was planted.",
	},
	["dar.npc_meet.w23.watch.017"] = {
		"meets the gaze of a great cat lying beside a Sentinel's post; the cat decides first, and lowers its head onto its paws.",
		"earns a long yellow stare from the saber lying at a Sentinel's feet, and a short, dismissive flick of its tail.",
	},
	["dar.npc_meet.w23.watch.018"] = {
		"Elune-adore, Sentinel. I hope I said that right.",
		"I tried the greeting in Darnassian just now. If that was wrong, please pretend it wasn't.",
	},
	["dar.npc_meet.w23.watch.019"] = {
		"I tried a joke on her. She waited until I had quite finished, then nodded as if I'd reported something minor and true.",
		"Humor doesn't bounce off a Sentinel. It goes in, gets considered, and is filed somewhere I'll never see.",
		"My best quip got a slow blink. I think that was a kindness.",
	},
	["dar.npc_meet.w23.watch.020"] = {
		"notices a pale moth resting on a Sentinel's pauldron and says nothing; a moment later she brushes it off without looking, as if she had known all along.",
		"sees a moth settle on a Sentinel's shoulder guard; her hand rises, shoos it gently, and drops back, her eyes never leaving the path.",
	},
	["dar.npc_meet.w23.watch.021"] = {
		"I'd bet a gold piece she'll know my face the next time I pass, and the time after, and long after I've forgotten hers.",
		"Sentinels remember faces, a dwarf told me at the bank. Judging by the look this one gives me, she's already put mine somewhere safe.",
	},
	["dar.npc_meet.w23.watch.022"] = {
		"Is there anything you haven't seen, Sentinel? No, don't tell me. I'd rather not know where I rank.",
		"You must hear a lot of questions from visitors. Here's an easy one: is it rude to stare at the tree?",
	},
	["dar.quest_complete.w23.afterward.001"] = {
		"tucks the reward away and stays a moment longer than needed, as if the place might have something to add.",
		"puts the payment out of sight, then lingers, half expecting one more word that never comes.",
	},
	["dar.quest_complete.w23.afterward.002"] = {
		"The worst part of finishing is the minute after, when my hands have nothing to carry and keep reaching for it anyway.",
		"Empty-handed, and my fingers keep closing on a strap that isn't there anymore.",
		"Strange, the lightness. I keep patting my side for something I handed over.",
	},
	["dar.quest_complete.w23.afterward.003"] = {
		"walks away from the turn-in slowly, matching without meaning to the pace of the kaldorei on the path.",
		"leaves the business behind at an unhurried walk, and only halfway along notices that the city has set the pace.",
	},
	["dar.quest_complete.w23.afterward.004"] = {
		"The thanks are over and I'm still standing there nodding. Somebody should teach me how to leave a conversation with an elf.",
		"Thanks given, coin taken, and I'm the one who can't end it. The kaldorei simply stop talking. It's a gift.",
		"I said goodbye twice. The elf said nothing at all, and somehow won.",
	},
	["dar.quest_complete.w23.afterward.005"] = {
		"steps aside for two priestesses in white, and by the time they have passed, the errand already feels like something from earlier.",
		"makes room on the path for a pair of robed priestesses, and when they are gone the finished task has shrunk to its proper size.",
	},
	["dar.quest_complete.w23.afterward.006"] = {
		"Odd how quiet a finished thing is. All that fuss to get it done, and now it doesn't make a sound.",
		"A job, once handed over, goes silent at once. It wouldn't leave me alone, and now not a whisper.",
	},
	["dar.quest_complete.w23.afterward.007"] = {
		"adjusts the straps of {g:his|her} pack, lighter by one errand, and the weight settles differently on the shoulders.",
		"hitches the pack higher; it carries no less than before, yet somehow sits easier.",
	},
	["dar.quest_complete.w23.afterward.008"] = {
		"I always want to look back once at whoever gave me the work. Here, when I do, they're already looking at something else: a leaf, the water, nothing. It isn't unkind.",
		"I glanced back. The one who paid me had already gone still, eyes on the water, the matter put away somewhere I'll never see.",
	},
	["dar.quest_complete.w23.afterward.009"] = {
		"slows at the first bend after the turn-in and simply looks at the city for a while, owing nothing to anyone for the moment.",
		"stops at the next turn of the path with no errand pulling anywhere, and lets the city be just a city for a little while.",
		"lets {g:his|her} feet idle at a bend in the path, with nobody waiting and nothing due, and takes in the city like a stranger with an afternoon off.",
	},
	["dar.quest_complete.w23.afterward.010"] = {
		"stops to fix a loose buckle that has been bothering {g:him|her}, now that there is finally no reason not to.",
		"kneels to retie a bootlace, a small chore saved for the moment the bigger one was done.",
	},
	["dar.quest_complete.w23.afterward.011"] = {
		"The ache I ignored all through the task has decided now is a good time. Thank you, knees.",
		"My shoulders held out until the thanks were said. Now they want a word.",
		"The body waits politely for the reward, then sends in its complaints all at once.",
	},
	["dar.quest_complete.w23.afterward.012"] = {
		"tucks one coin of the reward into a different pocket, a habit of the road, then moves off along the terrace.",
		"splits the payment between two pouches out of old caution, even here, and walks on.",
	},
	["dar.quest_complete.w23.afterward.013"] = {
		"I could have asked nothing for it. Among our own, help is not sold. But the coin is kindly meant, and I'll find someone who needs it more.",
		"Paid by one of my own people for helping my own people. It sits oddly in the purse.",
	},
	["dar.quest_complete.w23.afterward.014"] = {
		"rubs at a stiff wrist now the work is handed over, the small ache arriving late, like a guest who missed the feast.",
		"flexes cramped fingers once the hand-over is done, the stiffness only now admitting itself.",
	},
	["dar.quest_complete.w23.afterward.015"] = {
		"There's a moment after every job when I don't know who I am until the next one. Up here, that moment stretches, and it isn't unpleasant.",
		"Between one task and the next I'm nobody in particular. Darnassus seems to like me best that way.",
	},
	["dar.quest_complete.w23.afterward.016"] = {
		"Don't trouble yourselves showing me the way. I'll wander off under my own steam, more or less.",
		"I'll find my own way out. Eventually.",
		"No, no, don't get up. I'll get lost on my own.",
	},
	["dar.quest_complete.w23.afterward.017"] = {
		"My voice still has the shape of the thanks I gave back. Soft. It'll be a while before I can shout at a mule.",
		"I've caught their way of speaking: low, unhurried. It'll wear off by the time I reach the roots.",
	},
	["dar.quest_complete.w23.afterward.018"] = {
		"Pardon me, coming through. Very slowly, as is the custom.",
		"Excuse me. Just leaving. At a respectful pace.",
		"Mind if I squeeze past? I promise not to hurry.",
	},
	["dar.quest_complete.w23.afterward.019"] = {
		"I'll just stand here a moment and look accomplished.",
		"Give me a moment. I'm admiring my own work, quietly, the local way.",
		"Nobody mind me. I'm basking. Discreetly.",
	},
	["dar.quest_complete.w23.afterward.020"] = {
		"watches the giver turn back to some slow, careful task, and understands that the errand has already been folded into a much longer story.",
		"sees the one who set the task already bent over other work, unhurried, and the errand slips into place among a great many like it.",
	},
	["dar.quest_complete.w23.afterward.021"] = {
		"walks off into the dusk with the work behind {g:him|her}, the path ahead going soft and blue at the edges.",
		"turns away from the turn-in as the light goes, the day's work fitting neatly into the end of it.",
	},
	["dar.quest_complete.w23.afterward.022"] = {
		"walks away from the turn-in into the fog, and within a dozen steps the place behind {g:him|her} has gone soft and gray, as if the matter were already history.",
		"lets the mist close behind {g:him|her} after the thanks, and the whole business fades with the voices into the white.",
	},
	["dar.quest_complete.w23.afterward.023"] = {
		"That's off my list. The list is still long, but it's shorter by one, and I'll take it.",
		"One line crossed out. Only the rest of the list to go.",
	},
	["dar.quest_complete.w23.afterward.024"] = {
		"So. What does one do in this city with the work finished? Sit, by the look of it.",
		"And now what? Everybody around here seems to do nothing beautifully. I'll watch and learn.",
	},
	["dar.quest_complete.w23.boon.001"] = {
		"The purse came with its strings tied in a knot I didn't know, neat as a seed. I almost didn't want to undo it.",
		"Even the pouch was tied with care, in a knot so tidy I spent longer admiring it than looking inside.",
	},
	["dar.quest_complete.w23.boon.002"] = {
		"is offered the reward on a flat, open palm and left to take it, with nothing pressed into {g:his|her} hand.",
		"finds the reward simply held out and left there, waiting to be taken whenever {g:he|she} is ready.",
	},
	["dar.quest_complete.w23.boon.003"] = {
		"I was paid with the air of someone settling a debt between equals, not tipping a servant. It's the same silver. It spends better somehow.",
		"Paid as one settles with an equal, not as one tips a porter. I didn't know payment could have manners.",
	},
	["dar.quest_complete.w23.boon.004"] = {
		"That's generous. Or it's the usual amount and you just hand it over generously. Hard to tell here.",
		"Thank you. I can't tell if that's a lot, or just given beautifully.",
	},
	["dar.quest_complete.w23.boon.005"] = {
		"The reward wasn't tacked onto the thanks as an afterthought. It went the other way round: thanks first, fully, and the purse almost apologetic behind it.",
		"Thanks first, and whole. Then the reward, offered almost shyly, as if money were the impolite part of the business.",
	},
	["dar.quest_complete.w23.boon.006"] = {
		"tucks the reward away while the one who gave it looks politely elsewhere until it is stowed.",
		"stows the payment as the kaldorei across the way studies the nearest carving, tactfully, until the pouch is shut.",
		"pockets the payment, and the giver's attention drifts courteously to a passing owl until the pocket is buttoned.",
	},
	["dar.quest_complete.w23.boon.007"] = {
		"To someone who measures in centuries, what's a purse? Yet it was paid out exactly, not a coin rounded off. Precision is its own kind of respect.",
		"Exactly what was promised, to the last copper. A people with that much time could afford to be vague. They choose not to be.",
	},
	["dar.quest_complete.w23.boon.008"] = {
		"I'll take it, and gladly. But I'd have done it for less.",
		"More than I'd have asked. Thank you.",
		"You're kind. I'd have done the work regardless.",
	},
	["dar.quest_complete.w23.boon.009"] = {
		"weighs the reward in one hand, finds it heavier than expected, and quickly pretends that was the expected weight all along.",
		"lifts the purse, raises both eyebrows, and lowers them again at once, as if this were an entirely ordinary purse.",
	},
	["dar.quest_complete.w23.boon.010"] = {
		"Honestly: the thanks were lovely, and the coin is what I'll remember next time I'm hungry.",
		"Graceful thanks, fine manners, and silver. I'm grateful for all three, in roughly reverse order.",
		"I'll remember the bow fondly. I'll remember the silver at the inn, which is where gratitude goes to be useful.",
	},
	["dar.quest_complete.w23.boon.011"] = {
		"Paid by my own people for work done for my own people. The coin feels heavier than its weight, the good kind of heavy.",
		"Taking a reward from kin always feels a little odd. I'd have done it for the tree alone. I'll keep the coin anyway.",
	},
	["dar.quest_complete.w23.boon.012"] = {
		"I'm going to spend this somewhere very loud, just to balance things out.",
		"Kindly given. I'll try to spend it just as quietly.",
		"I promise to spend this with appropriate dignity. Mostly.",
	},
	["dar.quest_complete.w23.boon.013"] = {
		"The reward hung a moment between the two of us, neither hand letting go, before it became mine. A small thing. It felt like a handshake made of silver.",
		"For a moment we both held it. Then the other hand opened, and it was mine. I've been paid many ways; never quite like that.",
	},
	["dar.quest_complete.w23.boon.014"] = {
		"slips the reward into a pocket without looking at it, the way one does in a city where nobody would dream of watching.",
		"puts the reward away unexamined, as if checking it on the spot would be a small rudeness.",
		"closes the pouch on the reward without a glance, as one does after learning that nobody here gives short change.",
	},
	["dar.quest_complete.w23.boon.015"] = {
		"Somewhere in this city there must be a kaldorei who haggles. I've yet to be paid by one.",
		"Nobody here has ever tried to shave a coin off what was promised. I keep waiting for it, like a draft from a door that never opens.",
		"A whole city, and not one kaldorei willing to argue over a coin. It's restful. It's also making me lazy.",
	},
	["dar.quest_complete.w23.boon.016"] = {
		"accepts the reward with the slightly formal thanks one ally gives another, and gets back the same formality, warmed a little at the edges.",
		"takes the payment as one Alliance hand from another, and the nod that follows is a shade warmer than the first.",
	},
	["dar.quest_complete.w23.boon.017"] = {
		"Thank you. This will go further than you'd think.",
		"Fair, and more than fair. I won't forget who paid it.",
		"I'll make good use of it. That's a promise, not a courtesy.",
	},
	["dar.quest_complete.w23.boon.018"] = {
		"Whatever this reward is worth at the bank on Tradesmen's Terrace, it was handed over as if it mattered. That's the part I'll actually carry.",
		"A banker would put a number on it. The way it was given fits in no ledger, and that's the part I'm keeping.",
	},
	["dar.quest_complete.w23.boon.019"] = {
		"opens {g:his|her} hand for the reward a moment before it is offered, closes it again, and waits, which turns out to be correct.",
		"reaches for the payment too soon, withdraws the hand, and lets it come in its own time. It comes.",
	},
	["dar.quest_complete.w23.boon.020"] = {
		"Thanked, paid, and sent off into the rain with a bow as unhurried as if it were dry. I bowed back faster. One of us is getting wet.",
		"Nobody here hurries a hand-over for rain. The thanks took their usual time; I just dripped politely through them.",
	},
	["dar.quest_complete.w23.boon.021"] = {
		"Your thanks mean more than the coin. Don't tell the coin.",
		"Kind words. I'll keep them, and the silver too, if it's all the same.",
		"Words to keep, coin to spend. A fair division.",
	},
	["dar.quest_complete.w23.boon.022"] = {
		"Generous. I'll try not to spend it all on one terrace.",
		"I'll be careful with it, believe me; the auction house in this city looks hungry.",
	},
	["dar.quest_complete.w23.gratitude.001"] = {
		"Three words of thanks. In Ironforge it would have been thirty and a round of ale. These three will last longer.",
		"The whole of the thanks fit in one short sentence. Somehow nothing in it needed adding.",
	},
	["dar.quest_complete.w23.gratitude.002"] = {
		"hears 'Ishnu-alah' spoken low at the close of the business, and answers with a careful nod.",
		"is sent off with a soft 'Ishnu-alah', the old good wish of the kaldorei, and inclines {g:his|her} head to it.",
	},
	["dar.quest_complete.w23.gratitude.003"] = {
		"The thanks were so brief I thought I'd missed the rest. Then I understood there was no rest. That was the whole of it, and it was plenty.",
		"I waited for the second half of the thanks. There wasn't one. A single sentence, fully meant, and the matter closed.",
	},
	["dar.quest_complete.w23.gratitude.004"] = {
		"No, the thanks are mine. Elune-adore.",
		"Elune-adore. The honor is mine.",
		"Your thanks are well received. Go gently.",
	},
	["dar.quest_complete.w23.gratitude.005"] = {
		"I think I was thanked. There was a look, a slight lowering of the eyes, and a word I didn't catch. I've decided to take it as glowing praise.",
		"Was that gratitude? It was quiet enough to be almost anything. I'm choosing gratitude.",
		"A look, a lowered gaze, one soft word. Either I've been thanked or I've been forgiven. Both are welcome.",
	},
	["dar.quest_complete.w23.gratitude.006"] = {
		"is thanked with an open hand laid briefly against the giver's chest, a gesture that asks no reply.",
		"receives the thanks as a hand pressed for an instant over a kaldorei heart, and answers with a small bow, for want of anything better.",
	},
	["dar.quest_complete.w23.gratitude.007"] = {
		"When a kaldorei says thank you, you hear everything they've had to be thankful through. It's not a light word in that mouth.",
		"Gratitude from people who've buried so much has a weight to it. I felt it settle, small and solid, and I mean to carry it carefully.",
	},
	["dar.quest_complete.w23.gratitude.008"] = {
		"No need for more than that. I heard you.",
		"That's thanks enough. Truly.",
		"You don't have to say anything else. I understood.",
	},
	["dar.quest_complete.w23.gratitude.009"] = {
		"A long, level look after the thanks, as if fixing me in place among a great many faces. I stood still for it. It seemed polite.",
		"I was looked at a while after the thank you. Not unkindly. Like a book being set on the right shelf.",
	},
	["dar.quest_complete.w23.gratitude.010"] = {
		"keeps a polite half-smile ready for the rest of the thanks, and holds it a while before it becomes clear that the thanks are over.",
		"lingers, smiling, for a second round of gratitude that does not come, and eventually takes the hint.",
		"waits on for the rest of the thanks with good grace, until a gentle stillness makes it plain that there is no rest.",
	},
	["dar.quest_complete.w23.gratitude.011"] = {
		"In Stormwind they'd have shaken my hand until it ached and told the whole tavern. Here: a nod, a quiet word. I miss the tavern a little. Only a little.",
		"A Stormwind clerk would have stamped something and called for the next in line. This was gentler. Slower too, but gentler.",
	},
	["dar.quest_complete.w23.gratitude.012"] = {
		"Thanked without a single drink offered. I'll have to remind myself it's the custom here and not an insult.",
		"Not a mug in sight for the thanks. A fine people, the kaldorei, but someone should show them how a job's properly closed.",
	},
	["dar.quest_complete.w23.gratitude.013"] = {
		"And thank you, for trusting me with it.",
		"You trusted me with it. That's thanks enough on its own.",
	},
	["dar.quest_complete.w23.gratitude.014"] = {
		"The thanks came in Darnassian, and I didn't ask for a translation. Some words are clearer left whole.",
		"A word of thanks I didn't know, said once, never repeated. I've decided it meant exactly what it needed to.",
	},
	["dar.quest_complete.w23.gratitude.015"] = {
		"accepts the thanks without a word of {g:his|her} own, which seems, in this city, to be exactly the right answer.",
		"answers the thanks with silence and a short bow, and the silence is plainly understood.",
	},
	["dar.quest_complete.w23.gratitude.016"] = {
		"I'm learning to receive thanks the way they give it: without shuffling, without waving it off. Harder than it sounds.",
		"My instinct is to say it was nothing. Here that would be rude; it wasn't nothing, and they said so. I'm practicing just nodding.",
		"Being thanked well is a skill. Thanking well, too. In this city I'm a student at both.",
	},
	["dar.quest_complete.w23.gratitude.017"] = {
		"That's the warmest thank you I've ever had at that volume.",
		"I'll take that as wild applause, adjusted for local customs.",
		"Careful. Any more enthusiasm and someone might hear you.",
	},
	["dar.quest_complete.w23.gratitude.018"] = {
		"The priestesses fold Elune's name into their thanks, I've noticed, the way others fold in a person's name. It makes even a small errand sound as if it was seen.",
		"Thanks heard around the Temple of the Moon tend to carry Elune in them somewhere. I've stopped minding being included.",
	},
	["dar.quest_complete.w23.gratitude.019"] = {
		"There was something tired under the gratitude. Not with me. With having to ask anyone for help at all, maybe. I didn't take it personally.",
		"Grateful, and a little rueful about needing to be. Proud people wear that look whenever help is needed at all.",
	},
	["dar.quest_complete.w23.gratitude.020"] = {
		"It was a pleasure. Not a word I use lightly, in a city that weighs its words.",
		"Glad to be of use. Send word whenever there's more.",
	},
	["dar.quest_complete.w23.gratitude.021"] = {
		"catches, at the very end of the thanks, the faintest of smiles, there and gone like a fish turning in deep water.",
		"sees the thanks end on a smile so small it might have been a trick of the lamps, and returns one rather larger.",
	},
	["dar.quest_complete.w23.gratitude.022"] = {
		"You don't need to bow that low for me. Really.",
		"Please, no need for all that. A nod would do.",
		"That bow was deeper than the work deserved. I'll try to deserve it next time.",
	},
	["dar.quest_complete.w23.handover.001"] = {
		"It went from my hands into slender ones that turned it over twice, slowly, the way a jeweler turns a stone.",
		"Looked over from every side without a word, like a gem under a jeweler's glass. Then one small nod: acceptable.",
		"Turned over twice, slowly, by fingers that seemed to read it. Then a nod, and it was no longer mine to worry about.",
	},
	["dar.quest_complete.w23.handover.002"] = {
		"holds out what was asked for and waits, until long fingers lift it free without once brushing {g:his|her} own.",
		"offers the finished work on an open palm, and it is taken off so lightly that the hand hardly feels the weight go.",
		"extends the work and stays perfectly still while it is lifted away, as one holds still for a bird on the wrist.",
	},
	["dar.quest_complete.w23.handover.003"] = {
		"Elsewhere a turn-in is a transaction. Here it has a shape: hand out, a pause, hand back, eyes meeting at the end. I keep forgetting the pause.",
		"Giving things back follows an order in this city, I'm learning. You offer, you wait to be relieved of it, and you do not speak first. I spoke first.",
	},
	["dar.quest_complete.w23.handover.004"] = {
		"Here. I checked it twice myself, but please, a third look never hurt anyone.",
		"All yours. Examine it as long as you like; I've nowhere urgent to be. Probably.",
	},
	["dar.quest_complete.w23.handover.005"] = {
		"Druids take a thing as if checking whether it's still alive. Priestesses, as if they'd known it was coming. Sentinels, as if counting what it cost. I'm learning to tell them apart by the hands alone.",
		"You learn a giver by how they receive. A druid weighs it, a priestess blesses it with a glance, a Sentinel counts it. This one did a little of all three.",
	},
	["dar.quest_complete.w23.handover.006"] = {
		"The bow that came with it was the small one they give each other, not the deeper one for guests. I noticed. I'm not sure I was meant to.",
		"A slight bow, the kind I've seen pass between kaldorei of the same terrace. Not the formal one. I'll value that above the purse.",
	},
	["dar.quest_complete.w23.handover.007"] = {
		"puts it into the waiting hands and does not let go at once, until a quiet word gives leave.",
		"keeps hold a moment too long, out of a habit learned in rougher cities, and lets go when a slender hand closes gently over the top.",
		"releases the work only when the other hand is fully beneath it, and the care of that small moment is returned with a nod.",
	},
	["dar.quest_complete.w23.handover.008"] = {
		"It's done, and here it is. Whole, as promised.",
		"As you asked. Nothing missing, nothing skimped.",
		"Everything you set me to. It's in your keeping now.",
	},
	["dar.quest_complete.w23.handover.009"] = {
		"I held it out like an offering, because everything here seems to call for it. It was taken like a parcel. Good: I can stop performing.",
		"All that ceremony I'd rehearsed in my head, and it was taken from me as plainly as a baker takes back a tray. I never even got to do the bow I'd practiced.",
	},
	["dar.quest_complete.w23.handover.010"] = {
		"lowers {g:his|her} eyes as the work is received, the way one learns to in this city, and raises them only when the thanks are done.",
		"keeps a respectful gaze on the stone underfoot while the matter is looked over, and lifts it at the first word of acceptance.",
		"studies the grain of the floor while the work is weighed, a show of patience that is, in this city, simply manners.",
	},
	["dar.quest_complete.w23.handover.011"] = {
		"My name was said back to me as if it were a word worth keeping. Nobody has said it that carefully in a long while.",
		"My name, repeated once, slowly, every sound in its place. A small thing. It made the hand-over feel signed.",
	},
	["dar.quest_complete.w23.handover.012"] = {
		"waits while the work is inspected, then waits a little more, then begins, very discreetly, to study the carving on the nearest arch.",
		"stands through an inspection so unhurried that there is time to count the leaves on the nearest vine, twice.",
		"outlasts a moth's visit to the nearest lamp during the inspection, and of the two, the moth seems the more patient.",
	},
	["dar.quest_complete.w23.handover.013"] = {
		"The hands that took it may well be older than most kingdoms. They held it the way you'd hold anything new: with interest, and no hurry at all.",
		"Those fingers may once have held things from before the world broke apart. They held my work just as carefully, which I choose to find flattering.",
	},
	["dar.quest_complete.w23.handover.014"] = {
		"There you are. Careful, it's... no, of course you're careful.",
		"Here it is. Mind the... ah. You've done this before.",
		"Take it. Gently, I'd have said, but I see there's no need.",
	},
	["dar.quest_complete.w23.handover.015"] = {
		"Elsewhere, people grab. Here they receive. It's only a difference of speed, but it makes me feel I've brought something finer than I did.",
		"Nobody snatched it. Nobody even reached. It was simply received, and I stood there feeling I'd delivered something far grander.",
		"It was received, not taken. I didn't know there was a difference until just now.",
	},
	["dar.quest_complete.w23.handover.016"] = {
		"offers a bow at the hand-over, a little stiff in the knees, and is answered with one that politely pretends not to notice.",
		"bows as the work changes hands, a fraction deeper than needed, and receives a bow in return that kindly matches it.",
		"attempts the bow, misjudges the depth of it, and watches the reply adjust itself by just the same amount, out of kindness.",
	},
	["dar.quest_complete.w23.handover.017"] = {
		"It was received the way people receive things who have lost a great deal: carefully, as if even a small gain might be taken back.",
		"There's a tenderness in how they take even the plainest thing from you. A people who've lost this much handle nothing carelessly.",
	},
	["dar.quest_complete.w23.handover.018"] = {
		"Before you say anything: yes, I know it could be neater. It's done, though.",
		"It's not pretty, but it's finished. Pretty costs extra.",
		"I'll admit it's a bit rough at the edges. The middle is excellent.",
	},
	["dar.quest_complete.w23.handover.019"] = {
		"touches two fingers to {g:his|her} brow at the hand-over, and the same gesture comes straight back, between two kaldorei, needing no words.",
		"exchanges a quiet nod with the one who set the task, the nod of two kaldorei with nothing to explain to each other.",
	},
	["dar.quest_complete.w23.handover.020"] = {
		"My hands are always a little clumsy at this part. Theirs never are. Between the two of us it gets done.",
		"I fumbled the hand-over. Of course I did. It was caught without a glance, by someone who has had centuries to practice catching things.",
	},
	["dar.quest_complete.w23.handover.021"] = {
		"begins to explain every detail of the work, meets the patient look it earns, and stops after the first sentence.",
		"starts on a full account of the matter, notices the gentle stillness that greets it, and trims the story to a single word: done.",
		"gets three words into an explanation, sees that none is needed, and leaves the rest unsaid.",
	},
	["dar.quest_complete.w23.handover.022"] = {
		"There. And before you ask: no, it was no trouble. Well. Some trouble.",
		"Here you are. Don't worry, it was a pleasure. For the most part.",
	},
	["dar.quest_complete.w23.handover.023"] = {
		"Done as well as I know how. I hope it's enough.",
		"It's finished. I hope it's what you were hoping for.",
	},
	["dar.quest_complete.w23.handover.024"] = {
		"hears the thanks come out of the drifting mist before the face does, and answers toward the voice.",
		"bows to a figure half-softened by the fog, and the bow that comes back looks almost like a reflection.",
	},
	["dar.quest_complete.w23.jest.001"] = {
		"I know, I walked in too fast. I'll walk out slower to even it up.",
		"Too brisk? I'll leave at half speed. The terrace can have its calm back.",
	},
	["dar.quest_complete.w23.jest.002"] = {
		"Do I get a receipt? No? A long meaningful look, then. That'll do.",
		"No written record? Fine. I'll take the look you just gave me as proof.",
	},
	["dar.quest_complete.w23.jest.003"] = {
		"I came in fast enough to startle a Sentinel. I'll leave slowly enough to bore one.",
		"Made a Sentinel blink on the way in. On the way out I'm aiming to make one yawn.",
	},
	["dar.quest_complete.w23.jest.004"] = {
		"Too quick? I can go out and hand it over again, more slowly, if that's the custom.",
		"Shall I do it over at the proper pace? I'll step out and come back in like a sensible person.",
	},
	["dar.quest_complete.w23.jest.005"] = {
		"Please don't thank me all at once. Spread it out. You've the time for it.",
		"Thank me in installments, if you like. I'll be around for a while, and you'll be around for longer.",
	},
	["dar.quest_complete.w23.jest.006"] = {
		"I said 'finished' so fast the word got here before I did.",
		"Finished! I shouted it at the door and only caught up with it now.",
	},
	["dar.quest_complete.w23.jest.007"] = {
		"Ah, the pause. Everyone here does the pause. Take it. I'm getting better at standing in one.",
		"There it is, the kaldorei pause before an answer. I'll just stand here and age gracefully.",
	},
	["dar.quest_complete.w23.jest.008"] = {
		"Someone in this city must be in a hurry. Point them out to me. They and I would get along.",
		"Is there one person in Darnassus who rushes? I'd like to shake their hand. Or nod at them.",
	},
	["dar.quest_complete.w23.jest.009"] = {
		"I may be the quickest thing to happen on this terrace in a month. Don't mind me.",
		"Sorry for the bustle. I know a bustle is rare up here. I'll take it away with me.",
	},
	["dar.quest_complete.w23.jest.010"] = {
		"Fine work, if I say so myself. And I do, since waiting for modesty would take too long.",
		"I did that rather well. I'd let someone else say so, but nobody here speaks fast enough.",
	},
	["dar.quest_complete.w23.jest.011"] = {
		"You pay so gracefully I almost want to hand it back. Almost.",
		"Such a lovely way to be paid. Do it once more so I can watch properly. No? Worth asking.",
	},
	["dar.quest_complete.w23.jest.012"] = {
		"Nobody's cheering. Right. I'll do my own cheering, very quietly, somewhere over there.",
		"No crowd, no trumpets. I'll celebrate on my own, softly, behind a tree. There are plenty.",
	},
	["dar.quest_complete.w23.jest.013"] = {
		"I was told never to rush a kaldorei. Nobody said anything about rushing past one.",
		"Rule one up here, they told me: don't hurry an elf. So I'll hurry around you instead.",
	},
	["dar.quest_complete.w23.jest.014"] = {
		"Don't mind me. I'm just admiring how calm everyone is about my triumph.",
		"A triumph, and the whole terrace carries on as before. I respect that. I resent it a little, but I respect it.",
	},
	["dar.quest_complete.w23.jest.015"] = {
		"If I'd known you'd be this pleased, I'd have taken longer and let you enjoy the waiting.",
		"Had I known, I'd have dawdled. You'd have liked the suspense, I think.",
	},
	["dar.quest_complete.w23.jest.016"] = {
		"Paid in full, and the purse makes a cheerful noise. The only cheerful noise for a mile.",
		"Listen to that purse. Loudest thing in Darnassus, and I'm not even sorry.",
	},
	["dar.quest_complete.w23.jest.017"] = {
		"Shall I wait while you decide whether to smile? I've nowhere to be. Well, I have, but go on.",
		"Take a moment. Take two. I'll just stand here being finished.",
	},
	["dar.quest_complete.w23.jest.018"] = {
		"Somewhere a clerk is stamping papers twice as fast as anyone here has ever moved. I miss him a little.",
		"Elsewhere they'd have handed me a form. Here I get a nod and a silence. I prefer the silence.",
	},
	["dar.quest_complete.w23.jest.019"] = {
		"You thanked me so softly I'll have to take it on trust. I'm choosing to believe it was effusive.",
		"Was that thank-you, or did a leaf fall? I'll count it as thanks either way.",
	},
	["dar.quest_complete.w23.jest.020"] = {
		"Right on time, by my reckoning. By yours I'm probably a little early, by a decade or so.",
		"Early? By kaldorei measure I suppose anything short of a century counts as early.",
	},
	["dar.quest_complete.w23.jest.021"] = {
		"My voice sounded like a market crier's in that quiet. Gentler next time, or at least shorter.",
		"Every word I said seemed to bounce off the pale walls twice. I'll bring a smaller voice next visit.",
	},
	["dar.quest_complete.w23.jest.022"] = {
		"I wanted to whoop. I did not whoop. Nobody in Darnassus will ever know how close it was.",
		"There was a cheer right behind my teeth. I kept it there. Most heroic thing I've done all week.",
	},
	["dar.quest_complete.w23.jest.023"] = {
		"Everything I said in there came out at twice the speed of everything they said. I sounded like a squirrel making a report.",
		"Next to that slow kaldorei voice I sounded like a sparrow reporting to an oak.",
	},
	["dar.quest_complete.w23.jest.024"] = {
		"If you'd like to add anything, I'll wait. I brought a snack.",
		"Take whatever time the answer needs. There's bread in my pack and I'm in no rush.",
	},
	["dar.quest_complete.w23.jest.025"] = {
		"Am I talking too fast? I can't tell anymore. Everything I say up here sounds like a sneeze.",
		"Too quick? Every sentence I speak in this city sounds as if I'm running from a fire.",
		"Slow me down if I gabble. I'm told I gabble.",
	},
	["dar.quest_complete.w23.jest.026"] = {
		"I'd make a speech, but I suspect you'd listen to all of it.",
		"No speech from me. In this city someone might actually listen, and then where would I be?",
	},
	["dar.quest_complete.w23.jest.027"] = {
		"Should I knock next time? Everyone here arrives without a sound, and I came in like a bucket down a well.",
		"Next time I'll enter on tiptoe. That entrance had more clatter than this terrace hears in a year.",
	},
	["dar.quest_complete.w23.jest.028"] = {
		"I've heard kaldorei thanks can take a while to arrive. I'll wait right here with a smile on.",
		"Is the gratitude on its way? No hurry. I'll keep my smile warm.",
		"Thanks pending, I gather. I'll stand here looking grateful in advance.",
	},
	["dar.quest_complete.w23.jest.029"] = {
		"One more favor between allies. Somebody write it down; the Alliance keeps terrible accounts.",
		"Put it on the Alliance's tab. It's a long tab. Nobody ever reads it.",
	},
	["dar.quest_complete.w23.jest.030"] = {
		"Thank you! Sorry. Thank you, slower. Gnomes come wound a bit tight.",
		"That's all of it! Too fast? I'll say it again at kaldorei speed. Thaaank youuu.",
	},
	["dar.quest_complete.w23.jest.031"] = {
		"Done, and dripping. Pay me quickly, before the rain gets its share.",
		"Here's your business settled. Mind the drips; the rain up here takes the scenic route.",
	},
	["dar.quest_complete.w23.nod.001"] = {
		"touches two fingers to {g:his|her} brow, a gesture brought from somewhere else, and hopes it reads as courteous here.",
		"raises a hand to {g:his|her} forehead in a small salute from another city's manners, and watches to see if it lands.",
	},
	["dar.quest_complete.w23.nod.002"] = {
		"bows, sees the kaldorei bow back a fraction lower, and bows again to even things out.",
		"answers a bow with a bow, then a slightly deeper one with a slightly deeper one, until it threatens to go on for good.",
	},
	["dar.quest_complete.w23.nod.003"] = {
		"starts to say something clever, thinks better of it, and settles for a plain word of thanks.",
		"opens {g:his|her} mouth on a joke, closes it again, and offers a simple thank-you instead.",
	},
	["dar.quest_complete.w23.nod.004"] = {
		"laughs at {g:his|her} own joke, alone, and turns it into a polite smile before anyone notices.",
		"makes a small joke about the reward and watches it travel slowly, very slowly, across the kaldorei's face, then land.",
	},
	["dar.quest_complete.w23.nod.005"] = {
		"rocks on {g:his|her} heels while the kaldorei takes a long moment to answer, and stops rocking the moment it's noticed.",
		"shifts from foot to foot through the long silence before the reply, then goes still, caught at it.",
	},
	["dar.quest_complete.w23.nod.006"] = {
		"hands the matter over with a little flourish that looks out of place among such sparing people, and shrugs at it.",
		"concludes with a sweep of the arm that would suit a crowded market, and lets it drop, sheepish, in the quiet.",
	},
	["dar.quest_complete.w23.nod.007"] = {
		"says that it's done and then, because nobody moves, says it once more, softer.",
		"announces the work finished, waits, and repeats it at half the volume, which seems to be the right one.",
	},
	["dar.quest_complete.w23.nod.008"] = {
		"lowers {g:his|her} voice halfway through a word, as if the city had tapped {g:him|her} on the shoulder.",
		"catches {g:his|her} own voice rising and brings it down mid-sentence, the way one steadies a cup.",
	},
	["dar.quest_complete.w23.nod.009"] = {
		"starts to stride off, remembers where {g:he|she} is, and finishes the step at half the pace.",
		"sets off at a brisk clip, then eases into the slower gait of everyone else on the path.",
	},
	["dar.quest_complete.w23.nod.010"] = {
		"nods three times, quick ones, to the giver's single slow nod, and smiles at the arithmetic.",
		"returns one unhurried kaldorei nod with several brisk ones of {g:his|her} own, then decides that the score is settled.",
	},
	["dar.quest_complete.w23.nod.011"] = {
		"pats the purse twice, as if to reassure it, and throws a last word of thanks over {g:his|her} shoulder.",
		"gives the purse a fond little tap and adds one more thank-you on the way out, almost to the doorframe.",
	},
	["dar.quest_complete.w23.nod.012"] = {
		"offers a hand to shake, sees it studied with polite interest, and turns the gesture into a vague wave.",
		"puts out a hand, finds it regarded like a curious leaf, and quietly takes it back to scratch {g:his|her} ear.",
	},
	["dar.quest_complete.w23.nod.013"] = {
		"repeats the kaldorei word of thanks {g:he|she} just heard, carefully, and earns a small approving tilt of the head.",
		"tries the elven thanks back on the one who gave it, syllable by syllable, and is answered with the ghost of a smile.",
	},
	["dar.quest_complete.w23.nod.014"] = {
		"whistles two notes on turning away, then stops, embarrassed by how far they carry.",
		"hums a bar of something cheerful, hears it ring off the pale walls, and lets it die halfway.",
	},
	["dar.quest_complete.w23.nod.015"] = {
		"lays a hand flat over {g:his|her} chest and inclines {g:his|her} head, a gesture that seems to be understood.",
		"presses a palm to {g:his|her} chest with a short bow, and receives the same gesture, slower, in return.",
	},
	["dar.quest_complete.w23.nod.016"] = {
		"grins, wide and unguarded, and the kaldorei across from {g:him|her} answers with the smallest curve of the mouth.",
		"smiles with all {g:his|her} teeth and gets back the barest kaldorei smile, which somehow weighs the same.",
	},
	["dar.quest_complete.w23.nod.017"] = {
		"thanks the kaldorei a second time on the way out, in case the first went unheard, and gets a look that says it was heard perfectly.",
		"turns back to say thanks once more and is met by an expression that makes it plain the first one was quite enough.",
	},
	["dar.quest_complete.w23.nod.018"] = {
		"copies, a beat late, the way the kaldorei folds both hands at the close of the business, and gets it nearly right.",
		"mirrors the small closing gesture of the kaldorei, hands meeting at the waist, and is pleased to have kept up.",
	},
	["dar.quest_complete.w23.nod.019"] = {
		"begins a long account of the work, sees the listener settle in as if for a season, and wraps it up in a sentence.",
		"launches into the whole tale, notices the kaldorei getting comfortable for the long haul, and loses heart at once.",
	},
	["dar.quest_complete.w23.nod.020"] = {
		"weighs the reward in one palm without looking at it, and tucks it away with a nod that serves as a receipt.",
		"takes what is offered, closes a hand on it, and nods once: the nearest thing to a signature this city seems to want.",
	},
	["dar.quest_complete.w23.nod.021"] = {
		"tries to look as composed as the kaldorei across the way, and manages it for nearly as long as it takes to turn around.",
		"keeps a perfectly serene face all through the thanks, then grins like a cat the instant {g:his|her} back is turned.",
	},
	["dar.quest_complete.w23.nod.022"] = {
		"drops the formal phrase halfway, laughs at it, and finishes in plain words that are taken just as kindly.",
		"abandons a stiff little speech mid-clause and says, simply, thank you; it goes over better.",
	},
	["dar.quest_complete.w23.nod.023"] = {
		"stands a moment longer than needed, unsure whether the business is over, until a slight tilt of the head says it is.",
		"lingers, unsure if more is expected, and is released by a single courteous blink.",
		"waits for some sign that it's finished, gets one so small {g:he|she} nearly misses it, and goes.",
	},
	["dar.quest_complete.w23.nod.024"] = {
		"murmurs 'good, good' to no one in particular, the way people do when a thing has gone right.",
		"says 'there, then' softly to the air, the small words people keep for a job closed.",
	},
	["dar.quest_complete.w23.nod.025"] = {
		"answers a question about the work with a shrug and a grin, which seem to say more than the question wanted.",
		"is asked how it went and answers with one raised thumb, which is considered with real interest.",
		"replies to the courteous inquiry with a cheerful 'fine, fine', and watches it be weighed as if it were a full report.",
	},
	["dar.quest_complete.w23.nod.026"] = {
		"glances up through a gap in the leaves at the moon before answering, as the kaldorei just did, and finds the gesture fits.",
		"follows the kaldorei's eyes up to the moon above the canopy, then back down, and says thank you in the same low voice.",
	},
	["dar.quest_complete.w23.onward.001"] = {
		"Feet, decide. The bank, the inn on Craftsmen's Terrace, or that bench I keep promising myself. I'll let them choose.",
		"Three directions, all of them curving. I'll take the one that smells of bread.",
		"Left for the bank, right for the inn. My stomach votes right.",
	},
	["dar.quest_complete.w23.onward.002"] = {
		"stands at a fork in the path, weighing one curve against the other, and takes the left for no reason at all.",
		"pauses where two paths part, and lets a passing Sentinel's direction decide which to follow.",
	},
	["dar.quest_complete.w23.onward.003"] = {
		"Now, the trainer. Somewhere. Up a tree, presumably.",
		"Trainer next. If anyone sees me pass this spot twice, say nothing.",
	},
	["dar.quest_complete.w23.onward.004"] = {
		"Where now? The auction house, to see if the reward fetches more than it's worth to me. Probably not. Probably I'll keep it.",
		"I could sell it at the auction house. Or keep it, and remember the face that gave it. I'm getting sentimental up here.",
	},
	["dar.quest_complete.w23.onward.005"] = {
		"sets off with a clear purpose, takes three wrong turns among the terraces, and arrives somewhere pleasant that was not the plan.",
		"heads off at a brisk clip toward the next errand, and within twenty paces the city has gently slowed the stride.",
	},
	["dar.quest_complete.w23.onward.006"] = {
		"No one waiting on me for anything. I could go anywhere in this city. I think I'll go to the water and stand there like a heron.",
		"Nothing owed, nowhere I'm expected. A rare thing. I'll spend it slowly, the way they do here.",
		"For once nobody needs me anywhere. I mean to waste that properly.",
	},
	["dar.quest_complete.w23.onward.007"] = {
		"Food. That's where my feet are taking me, and I'm not arguing.",
		"Somewhere to eat: that's my next errand. The most honest one I've had.",
		"Supper first. Everything else in this city can wait, and happily will.",
	},
	["dar.quest_complete.w23.onward.008"] = {
		"The world is waiting at the foot of the tree. It can wait a little longer; I want one more walk up here.",
		"Down there, the next road. Up here, a little while with nothing to do. Easy choice.",
	},
	["dar.quest_complete.w23.onward.009"] = {
		"drifts toward the sound of a craftsman's mallet with no business there, only curious where the next small thing might be found.",
		"follows the smell of cut herbs down the path, letting the nose pick the next stop.",
		"wanders after a pair of chattering apprentices for no better reason than that they seem to know where they're going.",
	},
	["dar.quest_complete.w23.onward.010"] = {
		"The kaldorei will take a week to decide whether they need anything else from me. I'll check in. In a week.",
		"If there's more work, nobody here will tell me in a hurry. Plenty of time to wander first.",
	},
	["dar.quest_complete.w23.onward.011"] = {
		"Anyone heading toward the bank? I'll walk with you, if you know the way.",
		"Which way to the trainers, please? And is it as far as it looks?",
		"Inn, then bank, then bed. If the paths cooperate.",
	},
	["dar.quest_complete.w23.onward.012"] = {
		"gives the purse a last look, nods to no one in particular, and goes looking for whatever the city has next.",
		"pats the pack, settling the reward among the rest, and turns toward the busier terraces.",
	},
	["dar.quest_complete.w23.onward.013"] = {
		"Down the tree to my own sort of city soon: noise, smoke, straight streets. I'll miss this more than I'll admit.",
		"Somewhere across the sea there's a city that shouts. I'll be there soon enough, wishing for this quiet.",
	},
	["dar.quest_complete.w23.onward.014"] = {
		"glances up at the branches overhead to get a bearing, finds none, and picks a direction anyway.",
		"looks to the great boughs for a landmark, gets only leaves, and sets off by guesswork.",
	},
	["dar.quest_complete.w23.onward.015"] = {
		"takes the long way on purpose, past the water, as a small reward on top of the reward.",
		"chooses the slower path along the reeds, an extra pleasure added to the payment.",
	},
	["dar.quest_complete.w23.onward.016"] = {
		"I want to tell someone. The kaldorei don't gossip, though, so I'll have to save it for a tavern somewhere loud.",
		"This deserves a good telling, and this city is the wrong audience. I'll carry it down to someone who interrupts.",
	},
	["dar.quest_complete.w23.onward.017"] = {
		"The trainer will want coin, the vendor will want coin, and the purse will be thin before I'm through. Still, it was fat for a while.",
		"The reward already has three claims on it, and none of them is my pocket.",
	},
	["dar.quest_complete.w23.onward.018"] = {
		"Does anyone else need a pair of willing legs? These are warmed up.",
		"Anyone else? I'm on a roll, and in this city that may never happen twice.",
		"Who's next? I've got momentum, and up here that's a rare commodity.",
	},
	["dar.quest_complete.w23.onward.019"] = {
		"Now, where did I put the rest of my errands?",
		"Next. There's always a next. Where is it hiding?",
		"Right foot, left foot, somewhere useful. That's the whole plan.",
	},
	["dar.quest_complete.w23.onward.020"] = {
		"To the inn, I think. Unless someone has a better idea and a shorter path.",
		"Off to sell what I don't need. The auction house won't wait. Oh, it will. Everything here does.",
	},
	["dar.quest_complete.w23.onward.021"] = {
		"I don't have to decide anything for a little while. I'll walk until the path ends, which in Darnassus may be never.",
		"No plan, and for once that feels like a luxury rather than a problem.",
	},
	["dar.quest_complete.w23.onward.022"] = {
		"Broad daylight, coin in hand, and the kaldorei half asleep around me. I'm the only one awake at a party that hasn't started.",
		"Sun through the leaves and nothing left to do. Even the Sentinels look drowsy. I may join them.",
	},
	["dar.quest_complete.w23.reckon.001"] = {
		"I did what I said I would. That's the whole of it, and it's enough to straighten my back a little.",
		"Promised, and kept. It's a small, square feeling, the only straight thing in this curving city.",
	},
	["dar.quest_complete.w23.reckon.002"] = {
		"Every task finished is one less reason to be here. I find I don't like that arithmetic.",
		"Done, and the city owes me nothing now. Strange how that makes it feel a little farther away.",
		"Each errand I close here loosens my reason to stay. Curious, how little I want it loosened.",
	},
	["dar.quest_complete.w23.reckon.003"] = {
		"smiles to {g:himself|herself}, briefly, at nothing anyone else can see, and walks on.",
		"allows {g:himself|herself} a small private nod, the kind kept for a job well closed, and goes on with a lighter step.",
	},
	["dar.quest_complete.w23.reckon.004"] = {
		"I keep waiting for the catch. In other cities the reward comes with a second request. Here: a nod, and silence. Suspicious.",
		"No 'and while you're at it'. No favor tacked on the end. I don't trust it, and I love it.",
	},
	["dar.quest_complete.w23.reckon.005"] = {
		"What did I learn? That patience pays, mostly, and that I have less of it than the person who paid me.",
		"Lesson of the job: the kaldorei never rush you, which somehow makes you rush yourself.",
	},
	["dar.quest_complete.w23.reckon.006"] = {
		"counts nothing, checks nothing, and simply allows a moment with the work behind and the city ahead.",
		"lets the small satisfaction settle, the way one lets tea cool before drinking.",
	},
	["dar.quest_complete.w23.reckon.007"] = {
		"Nobody saw me do it, and nobody here will brag for me. The only witness is me, and I'm fairly impressed.",
		"No crowd, no herald. Just the knowing, private as a coin in a boot.",
	},
	["dar.quest_complete.w23.reckon.008"] = {
		"Good. That's one good thing in the world that wasn't there before.",
		"There. The world's a fraction better. A small fraction.",
	},
	["dar.quest_complete.w23.reckon.009"] = {
		"Darkshore lies in ruins across the water, and here I am pleased with myself over a small job. Maybe that's right. Maybe small jobs are how ruins stop spreading.",
		"So much broken across the sea, and I mended one small thing up here. It's not a balance. It's a start.",
	},
	["dar.quest_complete.w23.reckon.010"] = {
		"hums a few notes, then hears how far they carry in this quiet city and lets the tune trail off.",
		"starts to whistle, thinks better of it, and settles for a satisfied little nod at the path ahead.",
	},
	["dar.quest_complete.w23.reckon.011"] = {
		"One more thing set right in our own city. The war takes so much; it's good to give something to the tree for once.",
		"Small work for my own people. The Sentinels in Ashenvale give far more; still, this counted too.",
	},
	["dar.quest_complete.w23.reckon.012"] = {
		"I'll think about this one later, I suspect, on some loud road far from here. That's when the quiet moments catch up with me.",
		"Some jobs I forget by the next town. This one I think I'll keep, for no reason I can name.",
	},
	["dar.quest_complete.w23.reckon.013"] = {
		"I think of the Sentinels holding the line in Ashenvale while I run errands up here. Then I think: someone has to keep the city running behind them.",
		"Small work, set beside the war in Ashenvale. But in the end that's what the war is for: so there's a city still standing behind it.",
	},
	["dar.quest_complete.w23.reckon.014"] = {
		"I'd call that a tidy bit of work. Somebody here would call it a fair beginning.",
		"Neatly done, if I say so myself. And up here, nobody else will say it loudly.",
	},
	["dar.quest_complete.w23.reckon.015"] = {
		"There's a kind of tired that only comes from finishing. It's a good tired. It sits well under these leaves.",
		"Finished-tired, not road-tired. The difference is everything.",
		"Tired, but the clean kind, the kind with a reason attached.",
	},
	["dar.quest_complete.w23.reckon.016"] = {
		"sits on a low step for a moment after the thanks, elbows on knees, enjoying the rare and simple thing of being pleased.",
		"settles on the edge of a planter of moss once the purse is stowed, and lets the moment be complete.",
	},
	["dar.quest_complete.w23.reckon.017"] = {
		"Good work deserves a quiet moment. Lucky me: this city is made of them.",
		"Earned, that one. I'll sit with it a minute.",
	},
	["dar.quest_complete.w23.reckon.018"] = {
		"Thanks for the trust. I know nobody here hands it out lightly.",
		"It mattered to you. That's enough for me.",
		"I'm glad it fell to me.",
	},
	["dar.quest_complete.w23.reckon.019"] = {
		"Huh. That went well.",
		"Nicely handled, if nobody minds me saying so.",
		"No complaints, no mishaps. I'll mark it in the good column.",
	},
	["dar.quest_complete.w23.reckon.020"] = {
		"Finished in the dark, with the kaldorei around me at their busiest. I want my bed; the city wants its day to begin.",
		"The moon's up through the leaves and I've nowhere to be. Best kind of finish.",
	},
	["dar.quest_complete.w23.reckon.021"] = {
		"Paid, and the rain has found me. Good: it washes the job off, and I'm in no hurry to be dry.",
		"Work done, coin in my pocket, rain on my collar. I'll let it soak in a little; both feel earned.",
	},
	["dar.quest_complete.w23.reckon.022"] = {
		"The elves don't trust gadgets, but they trusted me with this. I'll count that as progress for gnomekind.",
		"Not one of them asked what I'd invent with the reward. Restraint, or fear. Either is flattering.",
	},
	["dar.quest_complete.w23.reckon.023"] = {
		"Small satisfaction, clean and complete. Nobody will sing about it, and that's exactly the right size.",
		"A small thing done well. It fits in the hand. I'd rather have a dozen of those than one great deed I can't carry.",
	},
	["dar.quest_complete.w23.reckon.024"] = {
		"There. Let it rest now; it's in good hands.",
		"Off my hands and into better ones.",
	},
	["dar.quest_complete.w23.reckon.025"] = {
		"That felt good. Odd, how rarely I say that out loud.",
		"Pleased with that. There, I said it, and nobody shushed me.",
	},
	["dar.quest_complete.w23.spoken.001"] = {
		"Thank you. I'll say it once, and slowly, since that seems to be how it's done.",
		"My thanks. I picked the words with care before I came in; I hope they hold up.",
		"Thanks, then. Just the one word, and I'll let it do the work.",
	},
	["dar.quest_complete.w23.spoken.002"] = {
		"Is it rude to count it in front of you? It feels rude. I'll count it behind that pillar.",
		"I won't count it here. Over there, where nobody kaldorei can watch me move my lips.",
	},
	["dar.quest_complete.w23.spoken.003"] = {
		"Ishnu-alah. Did I say it right? Your face says almost.",
		"To you, Ishnu-alah. I've only ever tried it on a fountain, and the fountain never corrected me.",
	},
	["dar.quest_complete.w23.spoken.004"] = {
		"How does one say 'you're welcome' in your tongue? I'd like to have it ready for next time.",
		"Teach me the word for 'my pleasure'. I keep answering your thanks in Common and it sounds so plain.",
	},
	["dar.quest_complete.w23.spoken.005"] = {
		"Was that bow too deep? I can never tell with the kaldorei. Too shallow, then? Somewhere in the middle.",
		"Shall I bow, or is a nod enough? I'll do both, and you can keep whichever fits.",
	},
	["dar.quest_complete.w23.spoken.006"] = {
		"Sorry, that came out louder than I meant. What I said was: it's done.",
		"It's DONE. Sorry. It's done. That second one was the version for this city.",
	},
	["dar.quest_complete.w23.spoken.007"] = {
		"Please, don't get up. I can see myself out. Slowly, I promise.",
		"No need to stand. I know the way out, more or less, and I won't rush it.",
	},
	["dar.quest_complete.w23.spoken.008"] = {
		"It was an honor. That isn't a word I spend often.",
		"An honor, truly. I keep that word for rare occasions, and this was one.",
		"Let it be counted done, and done well.",
	},
	["dar.quest_complete.w23.spoken.009"] = {
		"You look relieved. Kaldorei relief, I mean: one eyebrow, very slightly.",
		"Was that a smile? It was there and gone so fast I'll have to take your word for it.",
	},
	["dar.quest_complete.w23.spoken.010"] = {
		"I'd shake your hand, but I've noticed nobody here does. A nod, then. A good firm one.",
		"Hands to myself, yes, I've learned that much. Here's my best nod instead.",
	},
	["dar.quest_complete.w23.spoken.011"] = {
		"My pleasure. Well, my pleasure and a fair bit of bother. Mostly pleasure.",
		"Glad to help. Truly. My feet are less glad, but they don't get a vote.",
	},
	["dar.quest_complete.w23.spoken.012"] = {
		"Is there anyone else I ought to tell? It feels like news someone should hear.",
		"Should I tell someone else, too? A priestess, a Sentinel, a passing owl?",
	},
	["dar.quest_complete.w23.spoken.013"] = {
		"I could tell you how it went. No? A wise choice; most of it was walking.",
		"Would you like the whole account? Your silence says no, and your silence is very eloquent.",
	},
	["dar.quest_complete.w23.spoken.014"] = {
		"Keep it somewhere safe, would you? I'd hate to do it twice.",
		"Put it away carefully. Once was plenty, and I say that with all respect.",
	},
	["dar.quest_complete.w23.spoken.015"] = {
		"Peace to you, and to your work.",
		"May your work go gently from here on.",
		"Peace on whatever you put your hands to next.",
	},
	["dar.quest_complete.w23.spoken.016"] = {
		"Elune-adore. I've heard it said at partings; I hope it fits this one.",
		"If I may borrow the words: Elune-adore. Someone at the bank said them to me, and I liked the sound.",
	},
	["dar.quest_complete.w23.spoken.017"] = {
		"Your city is very easy to be polite in. It does half the work for me.",
		"Manners come cheap in a place like this. I barely had to try. Thank you.",
	},
	["dar.quest_complete.w23.spoken.018"] = {
		"No thanks needed. Well. A little thanks. That was the right amount. Thank you for it.",
		"Oh, you needn't. All right, you did, and it was nice. That's plenty.",
	},
	["dar.quest_complete.w23.spoken.019"] = {
		"Was there a part where I was meant to kneel? Nobody mentioned kneeling.",
		"Do I kneel now? I'll kneel. Tell me before my knees decide for me.",
	},
	["dar.quest_complete.w23.spoken.020"] = {
		"Settled, then. If it ever comes undone, you know my face.",
		"That's that. Should it unravel, come find me; I'll know whose fault it is.",
	},
	["dar.quest_complete.w23.spoken.021"] = {
		"May I ask what that carving above the door means? No? Another visit, perhaps.",
		"One question before I go: who carved all those leaves? Ah. A long answer. Next time.",
	},
	["dar.quest_complete.w23.spoken.022"] = {
		"I said thank you three different ways in a row. One of them must have been right.",
		"My thanks, thank you, much obliged: I used them all. Surely one landed.",
	},
	["dar.quest_complete.w23.spoken.023"] = {
		"I talked too much. The kaldorei listened to every word, which was worse.",
		"I rambled. Elsewhere someone would have cut me off. Here they let me finish, every last word, and that was the punishment.",
	},
	["dar.quest_complete.w23.spoken.024"] = {
		"Next time I'll let the pause run its course. Whatever a kaldorei says after a silence that long is worth hearing.",
		"I filled the silence too soon. If I'd waited, I think more would have been said. A lesson for the next turn-in.",
	},
	["dar.quest_complete.w23.spoken.025"] = {
		"Was there anything else? Ask now, while I'm standing still; it doesn't happen often.",
		"Anything more you need? Speak up while I've stopped moving.",
	},
	["dar.quest_complete.w23.spoken.026"] = {
		"I've done what was asked. No more, no less, and gladly.",
		"What you asked for, I've done. The rest I leave to your judgment.",
		"It's finished as you wanted it. If it falls short anywhere, I'd rather hear it from you.",
	},
	["dar.quest_complete.w23.spoken.027"] = {
		"Thank you for the patience. I know I'm not the restful sort of visitor.",
		"Kind of you to bear with me. I fidget; I'm aware.",
	},
	["dar.quest_complete.w23.spoken.028"] = {
		"I nearly said 'see you soon'. To a kaldorei, I've no idea what 'soon' means. I said 'farewell' instead.",
		"'Until next time,' I said, and wondered how far off a kaldorei hears 'next time'.",
	},
	["dar.quest_complete.w23.spoken.029"] = {
		"Go gently, and may the work keep. Elune-adore.",
		"Andu-falah-dor. It is done, and done for our own.",
	},
	["dar.quest_complete.w23.spoken.030"] = {
		"I'll never say thank you the way a kaldorei does, but I'll keep trying until someone smiles.",
		"My thanks, in my plain way. Your people make it sound like a song; mine just say it.",
	},
	["dar.quest_complete.w23.token.001"] = {
		"Besides the reward, a single leaf, offered without explanation. I'll ask a druid what it means. Or I won't, and keep it anyway.",
		"Someone tucked a leaf in with the payment. No note. I've laid it between the pages of my journal, which I suppose is an answer.",
	},
	["dar.quest_complete.w23.token.002"] = {
		"feels a light hand rest on {g:his|her} shoulder for a moment after the thanks, and then lift away.",
		"is touched once on the shoulder as the matter closes, a brief weight, gone before it can be answered.",
		"is given a brief touch on the arm as the business ends, light as a falling leaf and gone as quickly.",
	},
	["dar.quest_complete.w23.token.003"] = {
		"I was offered a cup of water once the hand-over was done. Just water, cold and clean. Hospitality, the kaldorei way, fits in a cup.",
		"A cup of water, held out once the business was closed. Nothing more. In this city it felt like being asked to stay for supper.",
	},
	["dar.quest_complete.w23.token.004"] = {
		"Is the bow part of the payment? Because I'll happily take more of those.",
		"I'll accept the bow in place of a receipt.",
		"I'll count that bow as a bonus.",
	},
	["dar.quest_complete.w23.token.005"] = {
		"That last look wasn't for the work. It was for me, measuring, the way they must have measured visitors through every age of the world. I hope I measured well.",
		"The look at the end lasted long enough to be a decision. Whatever it decided, I was let go with a nod.",
	},
	["dar.quest_complete.w23.token.006"] = {
		"is walked a few paces toward the path by the one who set the task, a courtesy that ends without a word at the first turning.",
		"finds a companion at {g:his|her} side for a short way after the thanks, and then the footsteps part, without a word.",
	},
	["dar.quest_complete.w23.token.007"] = {
		"There was a gesture at the end, two fingers to the brow, I think. I did it back. I may have just agreed to something.",
		"I copied the gesture I was given, because not copying it seemed rude. Judging by the pause, I got it almost right.",
	},
	["dar.quest_complete.w23.token.008"] = {
		"Keep your thanks somewhere safe. I'll keep mine.",
		"I'll remember this courtesy. And the one who showed it.",
	},
	["dar.quest_complete.w23.token.009"] = {
		"No reward is the whole of it in this city. There's always some small extra: a word, a nod held a beat longer, a step taken alongside. I've started looking for it.",
		"I've learned to watch for the little thing after the payment. There's nearly always one. This time it was simply being asked my name.",
	},
	["dar.quest_complete.w23.token.010"] = {
		"presses {g:his|her} palms together briefly in answer to the thanks, a gesture picked up from watching others here, and it is received kindly.",
		"answers with joined hands and a short bow, half-remembered from the temple steps, and the borrowed courtesy is accepted without comment.",
	},
	["dar.quest_complete.w23.token.011"] = {
		"We used to have all the time in the world for courtesies. Now we have less, and we still make time for them. I find that braver than it looks.",
		"Since Hyjal our years are numbered, and still a hand-over gets its full bow. Spending time on courtesy is a choice now. We keep choosing it.",
	},
	["dar.quest_complete.w23.token.012"] = {
		"A bow for a bow. Until next time.",
		"Same to you, and more.",
	},
	["dar.quest_complete.w23.token.013"] = {
		"In this city the thanks come with a gesture, the gesture comes with a look, and the look comes with a silence I'm meant to understand. I understood about half.",
		"Thanks, gesture, look, silence. I'm told it's a complete sentence. I caught the first word.",
	},
	["dar.quest_complete.w23.token.014"] = {
		"is handed, with the reward, a pressed flower of a violet so deep it is nearly blue, and turns it over a while before putting it away.",
		"receives a small pressed blossom alongside the payment, the sort of token no merchant would think to give, and tucks it away with care.",
	},
	["dar.quest_complete.w23.token.015"] = {
		"Kaldorei gratitude doesn't follow you out the door. It's given whole, in the moment, and then it's yours to carry. Nobody will mention it again, and nobody will forget it.",
		"They don't thank you twice. Once, fully, and then the matter rests. I find I like knowing where a thing ends.",
	},
	["dar.quest_complete.w23.token.016"] = {
		"meets the giver's eyes at the end of it all and holds them steadily, since looking away first seems, in this city, the lesser courtesy.",
		"returns the quiet look the matter ends with, and does not glance aside until the other does.",
	},
	["dar.quest_complete.w23.token.017"] = {
		"A nod at the end that meant, unless I'm wrong, come back if you're needed. I'd like to be needed here.",
		"The farewell left a door open. Not said aloud, of course. Nothing important is said aloud in this city.",
	},
	["dar.quest_complete.w23.token.018"] = {
		"receives the thanks with moonlight on the stone between them, and the bow that follows is lit silver along its whole slow length.",
		"takes the reward under a moon bright enough to show every line of the kaldorei face lowering in thanks.",
	},
	["dar.quest_complete.w23.token.019"] = {
		"Was that a bow or a farewell? Both? Both. Good.",
		"Ah, the nod. I know that one now. Thank you too.",
	},
	["dar.quest_complete.w23.token.020"] = {
		"And thank you for the courtesy. Not every city has so much of it to spare.",
		"Your manners have shamed mine into improving. Thank you for that too.",
	},
	["dar.quest_complete.w23.token.021"] = {
		"You'll notice I'm keeping my voice down. I'm learning the place.",
		"I'd thank you properly, but I'd be louder than half the terrace.",
	},
	["dar.quest_complete.w23.vow.001"] = {
		"You have my word: if it ever needs doing again, I'm the one to ask.",
		"Ask for me next time. By name, if you can remember it. You will, I suppose.",
	},
	["dar.quest_complete.w23.vow.002"] = {
		"Call on me again. I'll come, and I'll try very hard not to jog.",
		"Send for me whenever. I'll arrive at a dignified stroll, out of respect for the house.",
	},
	["dar.quest_complete.w23.vow.003"] = {
		"Wherever I go next, I'll speak well of Darnassus. It's earned that much from me.",
		"I owe this city a few good words. I'll spend them on every road I take.",
	},
	["dar.quest_complete.w23.vow.004"] = {
		"Next time you need someone, ask me first. I like being asked first.",
		"Keep me in mind, would you? Near the top of the list. I'm told I'm reliable.",
	},
	["dar.quest_complete.w23.vow.005"] = {
		"I don't make many promises, so hear this one: if you call, I'll come.",
		"A promise, then, and I keep the few I make. Call, and I'll answer.",
	},
	["dar.quest_complete.w23.vow.006"] = {
		"I'll remember the face that thanked me here. It seems only fair; it will remember mine far longer.",
		"Whoever said thank you just now will carry my face around for centuries. I owe it the courtesy of keeping theirs a while.",
	},
	["dar.quest_complete.w23.vow.007"] = {
		"I said I'd come back if they needed me. I meant it, which surprised me a little.",
		"A promise slipped out at the end there. I heard myself make it and found I had no wish to take it back.",
	},
	["dar.quest_complete.w23.vow.008"] = {
		"If it ever needs mending, send for me before anyone else touches it.",
		"Should it need tending later, it's mine to tend. Remember that.",
	},
	["dar.quest_complete.w23.vow.009"] = {
		"I told them I'd be around if needed. In this city 'around' could mean a long while. I hope they take it kindly.",
		"'Call on me anytime,' I said. To someone who counts in centuries, that's a large promise. I'll stand by it.",
	},
	["dar.quest_complete.w23.vow.010"] = {
		"A favor for my own people, under my own boughs. The thanks sounded different. Closer.",
		"Work for strangers is one thing. Doing it for my own kind, here, I found I had less to say and meant more of it.",
	},
	["dar.quest_complete.w23.vow.011"] = {
		"The Alliance stands together, or so the banners say. Here's one small proof of it.",
		"Allies help allies. It sounds simple in a treaty. It feels better done by hand.",
	},
	["dar.quest_complete.w23.vow.012"] = {
		"Paid by the kaldorei, and not one of them looked twice at me. Hood up, words few, and out.",
		"I thanked an elf in my best Common and kept my voice small. If they knew whose coin purse that went into, they'd count it differently.",
	},
	["dar.quest_complete.w23.worth.001"] = {
		"A century from now someone here may still use what I brought, never knowing who brought it. I find I don't mind.",
		"Long after me, some kaldorei hand will pick this up and never wonder who carried it. That's fine. That's what work is for.",
		"Whatever I handed over will outlast my name by a long way in this city. Good. Names are the least useful part.",
	},
	["dar.quest_complete.w23.worth.002"] = {
		"I rushed. I rushed for a people who consider a decade a short pause. I should have stopped for lunch.",
		"All that haste, delivered to someone who'd have waited a hundred years without a frown.",
		"Hurried every step, for someone who measures a delay in decades.",
	},
	["dar.quest_complete.w23.worth.003"] = {
		"What is my work against their ages? A pebble against a mountain. Yet they weighed it as carefully as if it were gold.",
		"Next to their lifetimes, my effort is a grain of sand. Still, they turned the grain over and looked at it properly.",
		"Set beside ten centuries, my labor barely registers. Nobody here treated it that way, and I noticed.",
	},
	["dar.quest_complete.w23.worth.004"] = {
		"receives a slight bow in farewell, and carries it away like a thing of value, which in this city it may well be.",
		"walks away keeping the elf's bow of farewell in mind longer than the coin, sensing which of the two was rarer.",
	},
	["dar.quest_complete.w23.worth.005"] = {
		"A kaldorei used to be able to wait on anything. Since Hyjal their years run out like everyone's. I hope I didn't waste any of them.",
		"Their years have an end now, like mine. Whatever time they spent waiting on me, I hope the work repaid it.",
	},
	["dar.quest_complete.w23.worth.006"] = {
		"Worth it? Ask me in a few centuries. Ask them, actually; they'll still be around.",
		"Was it worth the trouble? Someone here will know. In about three hundred years.",
		"Time will tell if that mattered. Here, time tells very, very slowly.",
	},
	["dar.quest_complete.w23.worth.007"] = {
		"The coin is honest and the thanks were real. Some days that's the whole of what a person can ask.",
		"Fair pay and a sincere word. I've been paid worse in prettier cities. Well, maybe not prettier.",
	},
	["dar.quest_complete.w23.worth.008"] = {
		"I wonder if this will be told some day, a century on, with me as a passing figure: a stranger who helped once. There are worse ways to be remembered.",
		"In some kaldorei tale a hundred years from now, I'll be 'a traveler who helped.' No name. I like that better than I expected.",
	},
	["dar.quest_complete.w23.worth.009"] = {
		"weighs the purse in one palm, looks at the patient faces of the city, and puts it away as if a little embarrassed by its smallness.",
		"glances from the handful of coins to the unhurried elves on the path and seems to wonder, briefly, what money means to people with so much time.",
	},
	["dar.quest_complete.w23.worth.010"] = {
		"They joined the Alliance late, and carefully. Every honest job a stranger does for them is a small argument that it was the right choice.",
		"An ally who kept the bargain: that's all I was, just now. Not nothing, for a people still deciding what to make of the rest of us.",
	},
	["dar.quest_complete.w23.worth.011"] = {
		"May it last as long as the ones it serves.",
		"Let it outlast me. Here, that's an easy wish.",
	},
	["dar.quest_complete.w23.worth.012"] = {
		"My whole career, as far as these people are concerned, will fit between two of their naps.",
		"To them I'm a brief, helpful visitor, like a bird that stops on the railing. Here, useful, gone.",
	},
	["dar.quest_complete.w23.worth.013"] = {
		"A purse for me, a favor for you. I think you got the longer-lasting half.",
		"Fair pay. Though I suspect you'll get more years out of it than I will.",
		"Keep it well. You'll have it far longer than I'll have the coin.",
	},
	["dar.quest_complete.w23.worth.014"] = {
		"Glad to help. Tell your grandchildren. Or your grandparents; they're probably still around.",
		"Remember me kindly. You've got the time for it.",
		"If anyone asks in a hundred years, it was me. Just so the record's straight.",
	},
	["dar.quest_complete.w23.worth.015"] = {
		"Ask a kaldorei what a favor is worth and you get a long look, then a story about a forest that isn't there anymore. I'll keep my question small.",
		"Here a favor is measured against forests that burned and a well that drowned the world. My errand doesn't come close, and nobody holds it against me.",
	},
	["dar.quest_complete.w23.worth.016"] = {
		"pauses at the edge of the path to watch a priestess tend a lamp with slow care, and seems to measure the finished errand by the same patient yardstick.",
		"watches an elf sweep a single step with long, attentive strokes, and sets the errand just finished in its place beside that.",
	},
	["dar.quest_complete.w23.worth.017"] = {
		"Some work you do for the coin. This felt like work done for the place itself, and the place doesn't pay, so the coin will have to stand in.",
		"The purse says I was paid. The city, somehow, says I was thanked. Those aren't the same, and I prefer the second.",
	},
	["dar.quest_complete.w23.worth.018"] = {
		"In Stormwind they'd have shaken my hand and slapped my back. Here, a look and a bow, and somehow I feel more thanked.",
		"Human-quick work for an elven-slow city. I hope it didn't look rude.",
	},
	["dar.quest_complete.w23.worth.019"] = {
		"Paid in a treetop by folk who've never met a forge they liked. I'll drink to it anyway, once I find something stronger than tea.",
		"Good honest work, even up a tree. A dwarf's word holds anywhere, and now these elves know it.",
	},
	["dar.quest_complete.w23.worth.020"] = {
		"I'll never know what becomes of it. That's the trade: I do the work, and the ending belongs to them.",
		"The end of the story stays with them. I just get the middle and a purse.",
	},
	["dar.rest_enter.w23.abide.001"] = {
		"There's the inn on Craftsmen's Terrace, and a bed in it if I want one. There's also this patch of moss, which hasn't asked for a single coin.",
		"A room at the inn would be sensible. The grass by the water is closer, and sensible can wait.",
	},
	["dar.rest_enter.w23.abide.002"] = {
		"weighs the inn against the grass, the grass against a quiet arch, and in the end settles exactly where {g:he|she} stands.",
		"considers several fine places to rest, all of them a short walk away, and picks the one that involves no walk at all.",
		"starts toward the inn, passes a soft stretch of grass on the way, and gets no further.",
	},
	["dar.rest_enter.w23.abide.003"] = {
		"The kaldorei have time to spare. In their company, a little of it seems to rub off on me.",
		"For a people who count in centuries, an hour on the grass is nothing. I've decided to count the way they do, just for now.",
	},
	["dar.rest_enter.w23.abide.004"] = {
		"takes a low seat in the inn's curved room, and the soft talk around {g:him|her} goes on without missing a word.",
		"finds a corner of the inn where the lamps are dimmest and sinks into it as into deep water.",
	},
	["dar.rest_enter.w23.abide.005"] = {
		"An inn where nobody is singing, nobody is arguing over dice, and nobody has spilled anything. I almost miss the racket. Almost.",
		"A cup of something herbal appeared at my elbow without my asking. I don't know what it is, and I'm not going to ask either.",
	},
	["dar.rest_enter.w23.abide.006"] = {
		"A quiet corner and something warm to drink, if it's no trouble. Thank you.",
		"Is this seat taken? No? Then it is now, for an hour or three.",
	},
	["dar.rest_enter.w23.abide.007"] = {
		"From here, eyes shut, I can hear the leaves far above rubbing against one another, a dry, slow sound, like pages turned by someone in no hurry.",
		"The canopy makes a sound like a long sigh that never quite ends. It's the best thing to fall asleep to I've found in Kalimdor.",
	},
	["dar.rest_enter.w23.abide.008"] = {
		"drifts toward sleep under the great canopy, waking now and then to a falling drop or a passing moth before drifting off once more.",
		"dozes in the green shade, one hand on the pack, and does not stir when a deer picks its way past.",
	},
	["dar.rest_enter.w23.abide.009"] = {
		"Turning the day over, I find one thing I did well and three I'd do differently. That's a good day, by my count.",
		"What did I learn? Not much. Where to put my feet, who to trust with change. Small things. They pile up.",
	},
	["dar.rest_enter.w23.abide.010"] = {
		"The lamps along the paths are the only things awake besides me and the Sentinels. I'm about to drop out of that company.",
		"Late, and the city has gone even softer than usual. I'll match it, and be asleep within the hour.",
	},
	["dar.rest_enter.w23.abide.011"] = {
		"settles under a broad leaf that sheds the rain in a thin curtain to either side, dry in the middle of it all and in no hurry to leave.",
		"finds a spot beneath an overhang of living wood and listens to the rain drip off its edge, content to stay put.",
	},
	["dar.rest_enter.w23.abide.012"] = {
		"Daylight comes down through the leaves in pieces. One piece has landed on my knees, and I'm keeping it.",
		"A patch of sun has found its way through the canopy to my bit of grass. I'm lying in it like a cat, and I'm not ashamed.",
	},
	["dar.rest_enter.w23.abide.013"] = {
		"Mist has wrapped the terraces in wool. A good hour to stay exactly where I am and let the world go blurry.",
		"The fog has come up off the lake and swallowed the far shore. Whatever was over there can wait until it gives it back.",
	},
	["dar.rest_enter.w23.abide.014"] = {
		"rests within earshot of the temple, where a low voice is singing somewhere inside, and lets it go on without trying to catch the words.",
		"sits where the priestesses of Elune pass on their way to the temple, and answers each of their small nods without getting up.",
	},
	["dar.rest_enter.w23.abide.015"] = {
		"Someone handed me a pale fruit on the path without a word. I'm eating it slowly, because everything here seems to want that.",
		"A cup of something that tastes of flowers and green stems. I wouldn't order it twice in Stormwind, but here it's exactly right.",
	},
	["dar.rest_enter.w23.abide.016"] = {
		"sits so long in one place that the lamps nearby are tended and trimmed, and does not notice.",
		"stays put long enough for the passers-by to change entirely, one set of quiet faces giving way to the next.",
	},
	["dar.rest_enter.w23.abide.017"] = {
		"A kaldorei's short rest, I'm told, can last a season. I'll settle for an hour and call it ambition.",
		"A Sentinel told me she once rested up here for a month and called it a nap. I'm aiming lower.",
	},
	["dar.rest_enter.w23.abide.018"] = {
		"Don't mind me. I'm practicing your local custom of not moving.",
		"Go gently. I'll be right here, for quite some time.",
	},
	["dar.rest_enter.w23.abide.019"] = {
		"Later I'll make a plan. For now the plan is this patch of grass and whatever comes after it.",
		"There'll be time to decide where next. The kaldorei would say there's always time. For once I'm inclined to agree.",
	},
	["dar.rest_enter.w23.abide.020"] = {
		"counts the day's coin twice, loses track the second time, and decides the first count was good enough.",
		"spreads a crumpled map across {g:his|her} knees, looks at it a while without really reading it, and folds it away unread.",
	},
	["dar.rest_enter.w23.abide.021"] = {
		"Peace to this place, and to whoever keeps it.",
		"May your quiet keep, and mine along with it.",
	},
	["dar.rest_enter.w23.haven.001"] = {
		"Ashenvale burns on the far side of the water, and the Sentinels go down to it. Up here, for a little while, I'm allowed to stop listening for it.",
		"Whatever the orcs are doing to the old forests down there, it can't climb this high. Not while I'm resting, anyway.",
	},
	["dar.rest_enter.w23.haven.002"] = {
		"There's a Sentinel within sight of almost any spot in this city. For once that means I don't have to be the one watching.",
		"Someone else is keeping the watch. Someone with centuries of practice. I can close both eyes.",
	},
	["dar.rest_enter.w23.haven.003"] = {
		"reaches for the weapon at the first rustle in the leaves, finds only an owl settling, and lets the hand fall away, a little embarrassed.",
		"sits facing the open path out of old habit, then, after a while, turns {g:his|her} back to it on purpose.",
	},
	["dar.rest_enter.w23.haven.004"] = {
		"Walls give one kind of safety. Another comes from everyone around you being very old and very calm. This is the second kind.",
		"No gate, no portcullis, nothing barred. This city keeps itself safe with its people, and its people don't seem to doubt it.",
	},
	["dar.rest_enter.w23.haven.005"] = {
		"Safe as anywhere in Kalimdor, I'd say. Safer than most.",
		"Nobody's going to bother me up here. I can feel it in my shoulders.",
		"Not a single pickpocket in sight. I could get used to that.",
	},
	["dar.rest_enter.w23.haven.006"] = {
		"This whole city is a shelter built by people who'd lost theirs. Resting in it feels like being offered a seat by someone who was once left standing.",
		"The kaldorei know about needing a place to stop. They built one in a tree after the war, and they let strangers sit in it.",
	},
	["dar.rest_enter.w23.haven.007"] = {
		"leaves the purse lying on the grass, unguarded, and keeps glancing at it in disbelief at such daring.",
		"tucks the coin pouch under a knee out of habit, then, feeling foolish in such a place, takes it out. Then tucks it back.",
	},
	["dar.rest_enter.w23.haven.008"] = {
		"Under these boughs I don't sleep with one ear open. That's the whole difference between a camp and home.",
		"Out there I rest like a Sentinel. Here I can rest like anyone else of my people, and that is a rarer thing than it sounds.",
	},
	["dar.rest_enter.w23.haven.009"] = {
		"If anything comes for me here, it'll have to get past several thousand years of Sentinel first.",
		"Safest nap I'll take all season. Possibly the most closely watched, too.",
	},
	["dar.rest_enter.w23.haven.010"] = {
		"settles near a Sentinel off duty, who is working a comb through her long hair and offers a nod that asks for nothing.",
		"shares a stretch of grass with an off-duty Sentinel unbraiding her hair; no word passes between them, and none is needed.",
		"rests beside an off-duty Sentinel oiling the straps of her armor in slow, even strokes, and finds the rhythm of it soothing.",
	},
	["dar.rest_enter.w23.haven.011"] = {
		"A dwarf nearby is snoring with his boots still on, and nobody in this most refined of cities has dared to wake him. I respect them all.",
		"A gnome is asleep on a step with a book open across her chest. If she can do it here, so can I.",
	},
	["dar.rest_enter.w23.haven.012"] = {
		"Resting in the kaldorei's own city is like dozing in a very old friend's parlor: welcome, but feet off the cushions.",
		"They let me rest here as if I belonged. I don't, quite, and so I try to rest politely.",
	},
	["dar.rest_enter.w23.haven.013"] = {
		"We never used to tire like this, before Hyjal. Now I know what the younger races know: a seat under a familiar branch is a gift.",
		"Since Nordrassil, my people learn weariness like a new language. Under our own leaves, at least, I need no interpreter.",
	},
	["dar.rest_enter.w23.haven.014"] = {
		"My guard doesn't drop all at once. It comes down like armor, piece by piece, each one heavier than it looked.",
		"Vigilance is a muscle, and I've kept it clenched far too long. Here, at last, I let it go slack.",
	},
	["dar.rest_enter.w23.haven.015"] = {
		"inclines {g:his|her} head to the nearest Sentinel, as one might ask leave of a host, and only then sits down.",
		"catches a Sentinel's eye before settling, and gets the faintest nod, which feels very much like permission.",
	},
	["dar.rest_enter.w23.repose.001"] = {
		"My hands have stopped making fists. I hadn't noticed they were doing it until now.",
		"Somewhere in the last few steps my jaw unlocked. It must have been clenched for hours.",
		"My fingers uncurl one at a time, as if each had to be talked into it separately.",
	},
	["dar.rest_enter.w23.repose.002"] = {
		"sits down on the first low wall that offers itself and stays there a good while longer than intended.",
		"finds a seat, then a slightly better seat, and in the end takes neither, choosing the grass between them.",
	},
	["dar.rest_enter.w23.repose.003"] = {
		"Nobody in this city is going to ask me to hurry. Knowing it does more for my back than any bed.",
		"No one here will rush me anywhere. That alone loosens a knot halfway down my spine.",
	},
	["dar.rest_enter.w23.repose.004"] = {
		"I am now officially off duty. Whose duty, I couldn't tell you.",
		"Nobody mention anything important to me for at least an hour.",
		"Consider me closed for business. Try again much later.",
	},
	["dar.rest_enter.w23.repose.005"] = {
		"The day keeps replaying itself behind my eyes, in the wrong order, with the dull parts lingering longest.",
		"My mind won't sit down just because my legs did. It keeps walking the day over, stretch by stretch.",
	},
	["dar.rest_enter.w23.repose.006"] = {
		"lies back in the deep grass at a terrace's edge and lets a stalk tickle one ear without doing anything about it.",
		"stretches out full length on a soft slope, hands folded, watching the great boughs sway far overhead.",
	},
	["dar.rest_enter.w23.repose.007"] = {
		"My feet have opinions about this city's distances, and for once I'm letting them have the last word.",
		"Every terrace is a pleasant stroll from every other one. The pleasant strolls add up. I'm sitting.",
	},
	["dar.rest_enter.w23.repose.008"] = {
		"Stillness is where the things I outran catch up with me. Fine. Let them sit down too; there's room.",
		"It's when the body rests that the old aches of the mind come out, like cats from under a porch.",
	},
	["dar.rest_enter.w23.repose.009"] = {
		"eases down onto a low step one stiff knee after the other, with a long, low sound of relief.",
		"lowers {g:himself|herself} onto a ledge of pale stone with the care of someone carrying a great deal, which, in a way, {g:he|she} is.",
	},
	["dar.rest_enter.w23.repose.010"] = {
		"I keep hearing a thing I said earlier, and a better thing I could have said. It'll keep.",
		"There's a clever answer I thought of far too late. I'm going to sit here and enjoy it anyway.",
		"Half the day's talk drifts back to me in pieces. Most of it was fine. One sentence I'd like to unsay.",
	},
	["dar.rest_enter.w23.repose.011"] = {
		"Ah. That's better. That's a great deal better.",
		"Sitting down. Nobody stop me.",
		"There. Oh, there. That's the spot.",
	},
	["dar.rest_enter.w23.repose.012"] = {
		"A leaf for a ceiling, a root for a pillow. I've paid good silver for worse rooms.",
		"Sleeping under leaves here feels less like camping and more like being tucked in by someone very tall.",
	},
	["dar.rest_enter.w23.repose.013"] = {
		"kneels at a stream, washes the day off {g:his|her} hands and face, and sits back on {g:his|her} heels, dripping and unhurried.",
		"rinses {g:his|her} hands in a shallow basin of stone and watches the dust of the road cloud the water, then settle.",
	},
	["dar.rest_enter.w23.repose.014"] = {
		"When I stop, the faces come: people I passed, people I helped, one or two I couldn't. They don't stay long. They only want to be counted.",
		"Resting is when I take attendance of the day. Most of it answers. A few names don't.",
	},
	["dar.rest_enter.w23.repose.015"] = {
		"Thank you. Whoever is in charge of this quiet, thank you.",
		"Good place. A good, good place.",
	},
	["dar.rest_enter.w23.repose.016"] = {
		"falls asleep halfway through unlacing a boot, and wakes a good while later with the lace still in hand.",
		"nods off upright, jerks awake, looks around to see whether anyone noticed, and finds a kaldorei who very politely did.",
	},
	["dar.rest_enter.w23.repose.017"] = {
		"Lying still, I can feel the faintest sway, the whole terrace easing like a hammock. Either the tree is moving or I'm more tired than I thought.",
		"The ground here has the slightest give to it, like a floor laid over something alive. It makes an odd cradle, and a good one.",
	},
	["dar.rest_enter.w23.repose.018"] = {
		"Moss this thick shouldn't be allowed. I sank into it like a stone into a pond, and I'm staying sunk.",
		"The turf here is deep enough to lose a hand in. I've lost the rest of me in it too, gladly.",
	},
	["dar.rest_enter.w23.repose.019"] = {
		"It's so quiet I can hear my own knees complaining. They have a lot to say.",
		"Quiet enough to hear my stomach. It wants feeding, and then it wants a nap.",
	},
	["dar.rest_enter.w23.repose.020"] = {
		"unwraps a little bread and cheese, eats it slowly on the grass, and brushes the crumbs off for whatever small birds want them.",
		"eats a plain meal out of the pack, sitting cross-legged, and takes a very long time over the last bite.",
	},
	["dar.rest_enter.w23.slack.001"] = {
		"The elf on the next seat hasn't moved since I sat down. I've decided we're competing, and I intend to lose with dignity.",
		"I'm trying to rest the way the kaldorei do. Apparently it starts with forgetting you were ever in a hurry, and I'm stuck at the very beginning.",
	},
	["dar.rest_enter.w23.slack.002"] = {
		"attempts to do absolutely nothing, and keeps getting distracted by small useful tasks until {g:he|she} sits on {g:his|her} own hands.",
		"begins to tidy the pack, thinks better of it, and lies down beside it instead.",
	},
	["dar.rest_enter.w23.slack.003"] = {
		"I have a list of things to do. The list can rest too.",
		"Errands? Whoever I am in a few hours can have them.",
		"The bank isn't going anywhere. Neither, for a while, am I.",
	},
	["dar.rest_enter.w23.slack.004"] = {
		"My thoughts have wandered off without me, like children at a fair. I'll collect them later.",
		"Not thinking about anything in particular is harder than it sounds, and much nicer once it works.",
	},
	["dar.rest_enter.w23.slack.005"] = {
		"yawns so widely that a passing kaldorei glances over, considers it, and seems to approve.",
		"yawns, tries to hide it, fails, and gives up trying.",
		"yawns enormously, and an owl somewhere above seems to answer in kind.",
	},
	["dar.rest_enter.w23.slack.006"] = {
		"Some task is waiting for me somewhere, feeling neglected. Good. Let it learn patience from the locals.",
		"A small voice says I should be doing something. I've sent it for a walk around the lake. It'll be gone for hours.",
	},
	["dar.rest_enter.w23.slack.007"] = {
		"follows a single leaf turning slowly on a stream until it drifts out of sight, and doesn't look for another.",
		"sits with chin on one fist, watching nothing in particular with great attention.",
	},
	["dar.rest_enter.w23.slack.008"] = {
		"If I fall asleep, leave me. If I snore, deny all knowledge of me.",
		"Wake me only if it's important. Nothing is important.",
	},
	["dar.rest_enter.w23.slack.009"] = {
		"My knees have voted to stay down. My knees are in the majority.",
		"I promised my legs a short sit. My legs heard that and laughed.",
	},
	["dar.rest_enter.w23.slack.010"] = {
		"Nobody is going to award me anything for this pause. Good. Some things should be done for their own sake.",
		"There is no prize for resting well. If there were, I'd stand a fair chance.",
	},
	["dar.rest_enter.w23.slack.011"] = {
		"notices a Sentinel's great cat sprawled asleep in the shade, studies its technique, and does {g:his|her} best to copy it.",
		"lies down not far from a dozing striped cat, which opens one eye, judges the company acceptable, and shuts it.",
	},
	["dar.rest_enter.w23.slack.012"] = {
		"Is it rude to fall asleep in a city this beautiful? Asking for myself, very soon.",
		"I could look at all this a while longer, or I could close my eyes. I'll do both, in that order.",
	},
	["dar.rest_enter.w23.slack.013"] = {
		"hums a tuneless scrap of something, notices the quiet all around, and finishes it in a whisper.",
		"starts to whistle, catches a passing glance, and turns it into a long, sheepish silence.",
	},
	["dar.rest_enter.w23.slack.014"] = {
		"Someone else can be useful for a while. I've done my share.",
		"The world can turn without me for an hour. I've checked.",
	},
	["dar.rest_enter.w23.unbuckle.001"] = {
		"works a stubborn buckle loose with tired fingers and, when it finally gives, regards it as if they had settled an old quarrel.",
		"loosens strap after strap until the whole kit sags like a shed skin.",
		"tugs off one glove with {g:his|her} teeth, then the other with the freed hand, and flexes the fingers slowly.",
	},
	["dar.rest_enter.w23.unbuckle.002"] = {
		"The pack comes off and my shoulders rise like bread. I could swear I've gained an inch.",
		"Off goes the pack. My back makes a noise I choose not to investigate.",
	},
	["dar.rest_enter.w23.unbuckle.003"] = {
		"pulls off both boots, sets them side by side with great precision, and then simply stares at {g:his|her} own feet.",
		"unlaces {g:his|her} boots and sets bare soles on the cool green, toes curling slowly.",
	},
	["dar.rest_enter.w23.unbuckle.004"] = {
		"Every strap I loosen gives back an inch of me I'd lent to the road.",
		"Belt, then bracers, then the cloak pin that's been biting my collarbone for hours. One by one, I'm handing myself back to myself.",
	},
	["dar.rest_enter.w23.unbuckle.005"] = {
		"If anyone sees a buckle roll into the lake, it was mine, and I've decided I don't need it.",
		"Off, off, off. Everything that pinches comes off.",
	},
	["dar.rest_enter.w23.unbuckle.006"] = {
		"sets the gear out on the grass in a neat row, checks each piece by touch, and then stops checking and just sits.",
		"empties the pack onto the ground, shakes out the grit of the road, and lets the whole mess lie there awhile.",
	},
	["dar.rest_enter.w23.unbuckle.007"] = {
		"My ears are still ringing with the day's noise. Here it drains out of them slowly, like water from a boot.",
		"It takes a while for the din of the road to leave my head. The city waits for it to finish.",
	},
	["dar.rest_enter.w23.unbuckle.008"] = {
		"I loosen one strap. Only one. A Horde back in a kaldorei city does not get to unclench all the way.",
		"Rest, they call this. I'm sitting very still among people who'd see me dead if they knew. Close enough to rest.",
	},
	["dar.rest_enter.w23.unbuckle.009"] = {
		"My shoulders are lodging a formal complaint. Noted. Upheld, even.",
		"Boots off. Whoever invented boots owes me an apology.",
	},
	["dar.rest_enter.w23.unbuckle.010"] = {
		"An inventory: one sore heel, a shoulder that clicks, a knee with opinions. Nothing this city's calm can't outlast.",
		"Taking stock of the aches. The left hip wins, narrowly, over the small of the back.",
	},
	["dar.rest_enter.w23.unbuckle.011"] = {
		"presses both thumbs into the small of {g:his|her} back, arches, and holds the stretch with eyes shut.",
		"works the knots out of one calf with slow, patient hands, as if kneading bread.",
	},
	["dar.rest_enter.w23.unbuckle.012"] = {
		"hangs the cloak on a peg that seems to have grown out of the wall for that very purpose, and lingers a long moment on the edge of the low bed.",
		"sets the pack in a corner of the inn room, sits down on the bed, and does not get up for some time.",
	},
	["dar.rest_enter.w23.unbuckle.013"] = {
		"My hands don't know what to do with nothing in them. I've put them in my lap like guests who arrived early.",
		"Empty hands, for once. They keep twitching for a strap or a buckle, and finding only the grass.",
	},
	["dar.subzone_enter.w23.crafts.001"] = {
		"stops beside a leatherworker who is cutting a strap freehand, in one long pull, and does not once look down at the knife.",
		"slows to watch a pair of kaldorei hands take a strap from a hide in a single unbroken stroke, as straight as a ruled line.",
		"lingers at a cutting table long enough to see a whole belt come out of one hide, with not a sliver left over.",
	},
	["dar.subzone_enter.w23.crafts.002"] = {
		"The dyers on this terrace are easy to spot: purple to the wrist, every one of them, as if they had all been caught in the same jam pot.",
		"You can tell the dyers here by their hands. Stained violet to the knuckles and past, and not one of them seems to mind.",
		"Purple fingers everywhere on the Craftsmen's Terrace. Either the dyers are busy or the whole quarter raided the same berry bush.",
	},
	["dar.subzone_enter.w23.crafts.003"] = {
		"Baskets of herbs sorted by someone who seems to know each stem by name. The herbalists here don't pick, they harvest.",
		"The herbalist's baskets are sorted finer than any I've seen: not just by plant, but by how long ago each bunch was cut.",
		"Somebody on this terrace sorts herbs by smell alone, eyes half shut. I'd come away from that with a fistful of weeds.",
	},
	["dar.subzone_enter.w23.crafts.004"] = {
		"Craftsmen's Terrace. In here is a pair of boots that will take a season to make and outlast me by a good margin.",
		"Better not to ask a crafter here how long a cloak takes. The polite smile says enough.",
		"Good work takes time. Here, apparently, it takes generations.",
	},
	["dar.subzone_enter.w23.crafts.005"] = {
		"passes the inn's doorway as someone comes out yawning, still pulling on a boot, and squints at the terrace as if it had moved in the meantime.",
		"steps aside at the inn's door for a dwarf coming out with a crooked collar and the slow, careful walk of someone who slept well.",
	},
	["dar.subzone_enter.w23.crafts.006"] = {
		"The inn sits among the workshops, which seems right. A bed within earshot of honest work is a good kind of bed.",
		"Of course the inn is on the Craftsmen's Terrace. Everyone here makes something; whoever keeps the inn simply makes sleep.",
		"I like an inn that shares a terrace with tanners and tailors. It makes rest feel like something earned.",
	},
	["dar.subzone_enter.w23.crafts.007"] = {
		"notices that every saddlebag, every glove, every tooled belt on the racks carries the same small leaf, pressed in somewhere it would be easy to miss.",
		"runs an eye along a rack of finished leather and finds a leaf worked into each piece, tucked inside a cuff or under a buckle like a signature.",
	},
	["dar.subzone_enter.w23.crafts.008"] = {
		"A tanner told me once that they use only bark the tree has already let fall. True or a story for visitors, the vats smell of it: sharp, brown, a little sweet.",
		"The tanning vats here smell of bark, not of the usual rot. Someone said the kaldorei take only what the tree drops. I'm in no position to check.",
		"Tannin and bark-water instead of the stink I expected. Apparently the tree hands the tanners its bark when it is ready, and not before. That's the story, anyway.",
	},
	["dar.subzone_enter.w23.crafts.009"] = {
		"hears the terrace before seeing much of it: the dry snip of shears, a pestle grinding in a stone bowl, a needle tugged through stiff hide.",
		"pauses to listen: the rasp of a scraper on leather, a pestle going round and round, and under it all someone humming over their stitching.",
	},
	["dar.subzone_enter.w23.crafts.010"] = {
		"The alchemist's table is a small forest of glass. Something in one flask has been turning green for an hour and nobody seems worried, so I won't be either.",
		"Bubbling glass, a low blue flame, a smell like crushed mint and old coins. Alchemy here looks less like a trade than a garden kept in bottles.",
		"An alchemist's bench, every flask labeled in a careful hand I can't read. I'll trust the colors and keep my distance.",
	},
	["dar.subzone_enter.w23.crafts.011"] = {
		"Everything on this terrace is lovely and handmade and priced accordingly.",
		"I could buy a cloak here. Or I could keep eating. Decisions.",
	},
	["dar.subzone_enter.w23.crafts.012"] = {
		"watches an elder crafter correct a younger one's stitch without a word, just two fingers laid on the back of the hand until it slows.",
		"passes a bench where an older kaldorei guides a younger pair of hands through a knot, over and over, with no sign of impatience on either face.",
	},
	["dar.subzone_enter.w23.crafts.013"] = {
		"Someone here mentioned, quite casually, that a certain tailor is still considered promising. 'Promising', I'm told, means a century or two of sewing, give or take.",
		"A tanner here called a colleague 'still learning'. As far as I can tell, the colleague has been learning longer than some kingdoms have stood.",
	},
	["dar.subzone_enter.w23.crafts.014"] = {
		"edges past a dwarf haggling with a leatherworker over a pair of gloves; the dwarf talks a great deal, the kaldorei says almost nothing, and the price does not move.",
		"comes upon a gnome explaining an unusual order to a tailor with a great many gestures, and a tailor taking in all of it with grave, unhurried attention.",
	},
	["dar.subzone_enter.w23.crafts.015"] = {
		"The smell of the vats and the dyers' crushed leaves: this terrace smells of work my people have done for longer than anyone else remembers. It steadies me.",
		"Of all the city, our crafters' terrace feels most like home to me. Hands busy, voices low, nothing made in a hurry.",
		"Tanbark, thread, the green smell of cut stems. Whatever else we lost at Hyjal, we kept this.",
	},
	["dar.subzone_enter.w23.crafts.016"] = {
		"steps carefully around a bolt of pale cloth unrolled across the path to be measured, and earns a small nod from the tailor at the far end.",
		"waits while a length of cloth is carried across the terrace by two kaldorei, one at each end, held level and taut like something that must not touch the ground.",
	},
	["dar.subzone_enter.w23.crafts.017"] = {
		"Leather, herbs, and something an alchemist will swear is perfectly safe. Smells like a proper workshop.",
		"Ah. The smell of people making things properly. And of whatever's in that green flask.",
		"Tanned hide and crushed leaves. My nose knows where I am before I do.",
	},
	["dar.subzone_enter.w23.crafts.018"] = {
		"Better leather than anything sold in the Horde's markets, and I can't tell a soul where I saw it.",
		"These kaldorei cut and stitch as if it were prayer. Hood up, mouth shut, and my admiration kept strictly to myself.",
	},
	["dar.subzone_enter.w23.crafts.019"] = {
		"Finished work sits out on the benches with nobody minding it. Either the kaldorei trust everyone, or they know exactly who would dare.",
		"No one stands guard over the racks of finished goods. In most cities that would be an invitation. Here it feels like a test I'd rather not fail.",
	},
	["dar.subzone_enter.w23.crafts.020"] = {
		"runs a hand along a workbench whose wood is still pale and smooth, barely marked yet, as if the terrace had only lately finished growing.",
		"notices how little wear the workbenches show: few scorch marks, few knife scars, the wood still pale. The crafts are old; the terrace is not.",
	},
	["dar.subzone_enter.w23.enclave.001"] = {
		"walks into the Cenarion Enclave past a druid sorting seeds into little clay cups, one seed per cup, each held up and looked at first.",
		"comes into the Enclave as a druid tips a handful of seeds from palm to palm, sorting them by some rule {g:he|she} cannot guess.",
	},
	["dar.subzone_enter.w23.enclave.002"] = {
		"Wet loam and crushed leaves. The Enclave smells like a garden bed somebody has just turned over with their hands.",
		"The Cenarion Enclave smells of dug earth, which is a strange thing to smell at the top of a tree.",
		"Soil, rot, green sap. Of all the corners of Darnassus, the Enclave is the one that smells like work.",
	},
	["dar.subzone_enter.w23.enclave.003"] = {
		"Excuse me. Sorry. Pardon. Is anyone in this Enclave walking on two legs?",
		"A cat, a bear and something with antlers, all heading the same way. I'll just follow the druids, whichever they are.",
		"Pardon me, sir. Madam. Bear. Whoever you are, sorry.",
	},
	["dar.subzone_enter.w23.enclave.004"] = {
		"The druids of the Enclave leave a pause when they talk, a space shaped like someone who isn't there. Malfurion, I'd guess, asleep in the Dream.",
		"Every druid in the Cenarion Enclave seems to be keeping something for someone who will wake one day and want it exactly as it was.",
	},
	["dar.subzone_enter.w23.enclave.005"] = {
		"steps into the Enclave to the murmur of a young druid reciting the names of herbs to an older one, who corrects only every third word.",
		"passes a pair of druids at the edge of the Enclave, one naming leaves aloud, the other listening with eyes shut and nodding at the right ones.",
	},
	["dar.subzone_enter.w23.enclave.006"] = {
		"I'll keep my voice down. Something in this Enclave is clearly trying to grow, and I'd hate to interrupt.",
		"Shh. I think that moss is concentrating.",
		"Quiet, everyone. Well, everyone who isn't a tree.",
	},
	["dar.subzone_enter.w23.enclave.007"] = {
		"Somewhere above all this green sits Fandral Staghelm. The druids coming down from his seat all wear the same careful look, like students leaving a hard lesson.",
		"The Arch Druid's seat is up there somewhere. Down here, druids speak of Staghelm's orders the way farmers speak of a frost: with respect, and a glance upward.",
	},
	["dar.subzone_enter.w23.enclave.008"] = {
		"enters the Cenarion Enclave and steps around a large cat asleep across the path; it opens one eye, far too thoughtful for any cat, and closes it.",
		"comes into the Enclave past a dozing cat on the steps whose ears follow {g:him|her} with an attention no ordinary animal would bother with.",
		"slows at the edge of the Enclave to let a gray-muzzled cat cross first, which it does without hurry, with the air of an elder holding a door.",
	},
	["dar.subzone_enter.w23.enclave.009"] = {
		"Every hand I see in the Enclave has earth under the nails. In the rest of Darnassus that would be a scandal. Here it looks like a badge.",
		"Clean robes, filthy hands. That's how you tell a druid of the Enclave from everybody else in this tidy city.",
		"A druid shook my hand and left half a garden in it. I don't mind. It's the most honest handshake in the city.",
	},
	["dar.subzone_enter.w23.enclave.010"] = {
		"walks into the Enclave where a ring of druids sits around a sapling in a stone pot, saying nothing at all, as if waiting for it to finish a sentence.",
		"pauses at the edge of the Cenarion Enclave beside three druids crouched over a sickly sapling, speaking to it in turns, low and very patient.",
	},
	["dar.subzone_enter.w23.enclave.011"] = {
		"These druids slept for centuries in the Dream while the Sentinels held the forests. Watching them bustle about the Enclave, I think they're still making up for it.",
		"Whole ages of the world went by while the druids of this Circle dreamed. Perhaps that is why the Enclave feels so busy for a kaldorei place: lost time being paid back.",
	},
	["dar.subzone_enter.w23.enclave.012"] = {
		"Don't touch anything, don't pick anything, don't step on anything that might be a druid. Got it.",
		"Everything in this Enclave is either a plant, a druid, or a druid pretending to be a plant.",
		"If I stand still long enough in this Enclave, somebody's going to water me.",
	},
	["dar.subzone_enter.w23.enclave.013"] = {
		"comes into the Enclave as a druid binds a splint to a hare's hind leg with a strip of grass, the hare entirely calm about it.",
		"passes a druid on the Enclave steps setting a small bird's wing between two twigs, humming something too low to make out.",
	},
	["dar.subzone_enter.w23.enclave.014"] = {
		"Two druids at the Enclave's edge stop talking when I pass. One had a hand on the living wall and the look of a farmer who doesn't like the color of a field.",
		"In the Enclave they speak of Teldrassil with love, and now and then with something else. A druid told me the tree 'listens less than it should'. Then she changed the subject.",
		"One druid in the Enclave says Teldrassil grew proud. Another says that's not a thing trees do. Neither of them sounded sure.",
	},
	["dar.subzone_enter.w23.enclave.015"] = {
		"finds, just inside the Cenarion Enclave, a druid asleep upright against a root, with moss already making plans on one sleeve.",
		"steps quietly past an old druid dozing against the living wall of the Enclave, so still a small vine seems to be weighing up his shoulder.",
	},
	["dar.subzone_enter.w23.enclave.016"] = {
		"No hammers, no coin, no bargaining. The Enclave's sounds are all small and alive: rustling, scratching, a low grunt from something large that is probably a druid.",
		"What I hear in the Cenarion Enclave: leaves turning over, claws on wood, two voices disagreeing very slowly. Nothing that was made.",
		"Something in the Enclave is chewing, something is digging, and someone is explaining to both of them, softly, why they shouldn't.",
	},
	["dar.subzone_enter.w23.enclave.017"] = {
		"Ishnu-alah, druids. I'll mind my feet if you mind your roots.",
		"Smells of home in here. Loam, bark, and somebody's tea gone cold.",
	},
	["dar.subzone_enter.w23.enclave.018"] = {
		"enters the Enclave in time to see an elder druid watch a student coax a bud open, then close it with one finger and nod for her to start over.",
		"pauses by a mossy step of the Enclave where a student druid strains over a closed flower bud while her teacher, eyes half shut, waits for it to give.",
	},
	["dar.subzone_enter.w23.enclave.019"] = {
		"The druids here say 'soon' and mean a century. I asked one when a sapling would be ready and she said 'shortly', with total sincerity.",
		"In the Enclave, a thing done quickly means a thing done within my whole lifetime. I've stopped asking how long anything will take.",
		"A druid called the tree 'young' in front of me. It's taller than any tower I know.",
	},
	["dar.subzone_enter.w23.enclave.020"] = {
		"Smells like a forest after somebody's apologized to it.",
		"This whole Enclave feels like it's halfway through turning into something. I'll try not to be in the way when it does.",
		"I'd say this place was overgrown, but I think it's exactly as grown as it wants to be.",
	},
	["dar.subzone_enter.w23.gardens.001"] = {
		"steps into the Temple Gardens past a gardener tying a bent stem to a stake with one thread of grass, as carefully as a healer binding a finger.",
		"drifts into the Temple Gardens where a kaldorei gardener kneels over a single drooping flower, adjusting it by a hair, then sitting back to judge.",
		"turns into the gardens beside a bed where someone has propped up every leaning stalk with a twig, each twig cut to exactly the right length.",
	},
	["dar.subzone_enter.w23.gardens.002"] = {
		"Every weed in the Temple Gardens has been left exactly where it is. Either they're not weeds here, or the gardeners have reached an understanding with them.",
		"I can't find a single plant in these gardens that looks unwanted. Even the ones growing out of the path seem to have been asked.",
		"The gardeners here seem to pull nothing up. They persuade things to move instead, a little each season.",
	},
	["dar.subzone_enter.w23.gardens.003"] = {
		"I'm not picking anything. I'm just looking. Very closely. With my hands behind my back.",
		"Lovely gardens. I'll keep my hands in my pockets, just so everyone can relax.",
		"That flower just closed when I leaned in. I'm choosing not to take it personally.",
	},
	["dar.subzone_enter.w23.gardens.004"] = {
		"follows a path of the Temple Gardens around a hedge and comes face to face with the white flank of the temple, closer than it looked a moment before.",
		"slows among the hedges of the Temple Gardens as two priestesses pass in step, speaking so softly the words never reach the end of the path.",
	},
	["dar.subzone_enter.w23.gardens.005"] = {
		"Whoever planted these gardens once knew for certain they'd see them full grown. Since Hyjal, that certainty is gone. I wonder if the gardeners plant a little faster now.",
		"The kaldorei gave up forever at Hyjal, and then planted gardens anyway. I find that harder to look at than any ruin.",
	},
	["dar.subzone_enter.w23.gardens.006"] = {
		"comes upon a kaldorei in the Temple Gardens sweeping fallen petals off the path, who then scatters them over the beds by the handful instead of carrying them away.",
		"watches a gardener gather petals from the stones and tip them gently under the hedges, as if putting something back where it belongs.",
		"stops on a path of the Temple Gardens to let a gardener by with a basket of cuttings, each one wrapped in damp moss like something precious.",
	},
	["dar.subzone_enter.w23.gardens.007"] = {
		"I could sit here until somebody needs me. Then a while longer.",
		"If anyone's looking for me, tell them the gardens ate me. Politely.",
		"Give me ten minutes in these gardens. Or an hour. I'm not fussy.",
	},
	["dar.subzone_enter.w23.gardens.008"] = {
		"Some of the flowers in the Temple Gardens turn their faces toward the temple instead of the sky. I'm told that isn't the gardeners' doing.",
		"Certain blossoms here open only when someone nearby is praying, a priestess told me. I've been watching one for some time. Nobody seems to be.",
	},
	["dar.subzone_enter.w23.gardens.009"] = {
		"picks a careful way through the Temple Gardens around an elder asleep in the grass, hands folded, a petal resting on one sleeve like a bookmark.",
		"hears, entering the gardens, an old kaldorei murmuring to a flowerbed in a tone usually kept for a slow-learning student.",
		"comes across a kaldorei on the grass of the Temple Gardens, sketching one flower on a scrap of bark with great care and very little skill.",
	},
	["dar.subzone_enter.w23.gardens.010"] = {
		"A gardener in the Temple Gardens has been trimming one hedge the whole time I've stood here: a leaf, a pause, another leaf, a long think about the third.",
		"I've watched kaldorei gardeners at work for a while now and I still can't tell when they finish. Possibly they don't.",
		"The Temple Gardens look effortless. Nothing that looks this effortless ever is.",
	},
	["dar.subzone_enter.w23.gardens.011"] = {
		"follows a narrow channel of water into the Temple Gardens, keeping pace with a single petal floating along it, until the petal wins.",
		"steps beside a thin rill threading through the gardens and watches a petal ride it past {g:him|her} toward the temple, unhurried as everything else.",
	},
	["dar.subzone_enter.w23.gardens.012"] = {
		"To whoever tends these, Ishnu-alah. You've done beautifully.",
		"My compliments to the gardeners. All of them. Every century of them.",
	},
	["dar.subzone_enter.w23.gardens.013"] = {
		"Anywhere else, a garden this fine would have a wall, a locked gate and someone with a stick. The Temple Gardens have none of that, and need none of it.",
		"No fence, no gate, no warden. The kaldorei trust their visitors with every flower in these gardens. I'd hate to be the one who disappoints them.",
		"Not a single flower missing from the beds, and every visitor in the city walks through here. Someone in these gardens has a very effective glare.",
	},
	["dar.subzone_enter.w23.gardens.014"] = {
		"reaches the Temple Gardens as the daylight fails, and the pale flowers seem to brighten in answer, one bed after another.",
		"walks the gardens at dusk while kaldorei gardeners, waking to their own day, come out with their tools and nod good evening.",
	},
	["dar.subzone_enter.w23.gardens.015"] = {
		"Nothing in the Temple Gardens is in a hurry, and after a few steps neither am I. I'll blame the hedges.",
		"My shoulders come down a whole inch the moment I'm among these flowerbeds. I didn't know they'd been up.",
	},
	["dar.subzone_enter.w23.gardens.016"] = {
		"pauses at the edge of the Temple Gardens as a small bird makes off with a gardener's twine, and the gardener watches it go with something like approval.",
		"arrives among the flowerbeds just as a squirrel digs up a freshly planted bulb, and the kaldorei who planted it simply puts it in the ground once more, without a word to anyone.",
		"comes among the beds as a moth lands on {g:his|her} sleeve, sits a while, and leaves on its own schedule.",
	},
	["dar.subzone_enter.w23.gardens.017"] = {
		"The Temple Gardens are where the temple's quiet spills over. You can feel it thin out with every step away from the doors.",
		"Out among the flowers the temple's hush is diluted, like a strong tea with water added. Easier to take.",
	},
	["dar.subzone_enter.w23.gardens.018"] = {
		"These hedges are better groomed than I am. Than anyone I know, really.",
		"Somebody here clipped that hedge into a perfect curve. With what, patience?",
	},
	["dar.subzone_enter.w23.temple.001"] = {
		"enters the Temple of the Moon and finds the noise of the fountain doing all the talking; everyone else has left it to the water.",
		"comes up into the temple where the great fountain plays, and lowers {g:his|her} voice before anyone could ask.",
	},
	["dar.subzone_enter.w23.temple.002"] = {
		"I watch a priestess fold a cloth in the Temple of the Moon. Six folds, each pressed flat with the palm. Whatever she prays to, she prays with her hands too.",
		"A priestess in the temple straightens a single fallen petal on the stone, looks at it, then moves it back. I don't understand the rule, but I believe there is one.",
		"Past me goes a priestess carrying a bowl of water so full it should spill, and it doesn't. Faith, or very good wrists.",
	},
	["dar.subzone_enter.w23.temple.003"] = {
		"I'll whisper. Actually, I'll just not talk.",
		"Even my boots sound rude on this stone.",
		"Not a word from me. The fountain's got it covered.",
	},
	["dar.subzone_enter.w23.temple.004"] = {
		"steps into the Temple of the Moon, and the pale glow off the moonwell finds {g:his|her} face and makes it look, for a moment, as old as the kaldorei around.",
		"walks among the priestesses toward the moonwell, its silver glow catching on every buckle and strap {g:he|she} owns.",
	},
	["dar.subzone_enter.w23.temple.005"] = {
		"This temple is quiet, but it isn't idle. Sentinels come up from Ashenvale with wounds, and the priestesses send them back down. A field hospital that learned to whisper.",
		"Behind the hush of the Temple of the Moon there's a steady trade in mending: bandages, salves, a hand laid on a shoulder, a Sentinel walking out straighter than she came in.",
	},
	["dar.subzone_enter.w23.temple.006"] = {
		"arrives in the temple as a priestess guides a younger one's hands above a basin of water, adjusting a finger here, a wrist there, without a word.",
		"passes a pair of priestesses at a basin, the elder moving the younger's hands a hair's width, then another, until both seem satisfied.",
		"lingers at the edge of the Temple of the Moon to watch a priestess teach a pupil to stand still, and the pupil, with great effort, failing at it.",
	},
	["dar.subzone_enter.w23.temple.007"] = {
		"Water falls from the fountain into the well and makes the only sound in the Temple of the Moon that nobody here would ever ask to be quieter.",
		"The fountain in the temple was running before I arrived and will be running after I leave. It's the most patient voice in a patient city.",
		"Water falling into water, unhurried and unending. Of all the temple's voices, it is the one I trust most.",
	},
	["dar.subzone_enter.w23.temple.008"] = {
		"Elune-adore. I hope I said that right.",
		"Peace on this house, and on the ones who keep it.",
	},
	["dar.subzone_enter.w23.temple.009"] = {
		"glances up toward the temple's upper reaches, where the High Priestess is said to keep her seat, and meets instead the level gaze of a Sentinel on guard.",
		"lifts {g:his|her} eyes to the heights of the Temple of the Moon, wondering if Tyrande Whisperwind is up there, and finds a Sentinel on watch who has wondered nothing at all.",
	},
	["dar.subzone_enter.w23.temple.010"] = {
		"In the Temple of the Moon I find myself standing straighter without knowing why. Nobody asked. The place simply expects it, the way some elders do.",
		"Whatever anyone here believes or doesn't, the temple lets them stand at the edge and be quiet. That seems to count for something.",
		"Something in the Temple of the Moon makes me tidy my thoughts the way one tidies a coat before a visit.",
	},
	["dar.subzone_enter.w23.temple.011"] = {
		"slips into the Temple of the Moon past a priestess on her knees, wiping the fountain's rim with a soft cloth as gently as one would wash a sleeping face.",
		"finds a priestess polishing the stone lip of the moonwell in long slow strokes, a task plainly done every day and plainly never resented.",
		"comes upon a priestess trimming the wicks of small lamps one by one, careful as a jeweler, not a single flame allowed to smoke.",
	},
	["dar.subzone_enter.w23.temple.012"] = {
		"Sisters, Elune-adore. I'll keep my voice low and my thanks long.",
		"A moment at the well, that's all I have. Elune knows it's enough.",
	},
	["dar.subzone_enter.w23.temple.013"] = {
		"Since Hyjal, I'm told, the priestesses of this temple have begun to grow old like anyone else. They tend the well as calmly as before. I'm not sure I could.",
		"A priestess here said that before Hyjal nobody in the temple counted years. Now, she said, some of the sisters have started. She said it the way you'd mention a draft.",
	},
	["dar.subzone_enter.w23.temple.014"] = {
		"reaches the Temple of the Moon as a few voices somewhere within rise in a low hymn, so soft it seems to come up out of the water.",
		"hears, on entering the temple, priestesses singing under their voices, the sound thin and silver and gone before {g:he|she} can tell where it began.",
		"lingers on the temple's threshold while a single priestess sings a line under her voice and stops, as if she had been answered.",
	},
	["dar.subzone_enter.w23.temple.015"] = {
		"I tiptoed into the Temple of the Moon and a priestess smiled at me. Apparently tiptoeing was never required.",
		"Somebody in the temple dropped a bowl. Twenty heads turned, very slowly, and the bowl seemed to apologize all on its own.",
		"There's a way of walking the kaldorei use in their temple, heel down soft, weight forward. I tried it just now. Badly.",
	},
	["dar.subzone_enter.w23.temple.016"] = {
		"walks into the Temple of the Moon behind a Sentinel who leans her glaive against a pillar before going farther, as if it had no business there.",
		"follows a Sentinel up into the temple and notices she sets her glaive aside at the edge, then walks on with her hands open and empty.",
	},
	["dar.subzone_enter.w23.temple.017"] = {
		"Look long enough into the moonwell in this temple and the reflection seems a little late to follow. I stopped looking.",
		"The well's surface holds the light like a coin held in a fist. I keep wanting to reach in, and I know I mustn't.",
		"The silver in the well isn't a reflection of anything I can see. I've looked up twice to find what it mirrors. Nothing.",
	},
	["dar.subzone_enter.w23.temple.018"] = {
		"Nobody's told me to be quiet. Somehow that's worse.",
		"I could hear a pin drop. Mine, specifically. Sorry.",
		"Is there a quiet way to clear one's throat? Asking for a friend.",
	},
	["dar.subzone_enter.w23.temple.019"] = {
		"comes up into the Temple of the Moon past a dwarf standing just within with his helmet in his hands, as unsure as anyone has ever looked in a temple.",
		"notices, entering the temple, a human pilgrim at the edge of the pool, hands folded in the manner of the Light, and a priestess beside her who doesn't mind at all.",
	},
	["dar.subzone_enter.w23.temple.020"] = {
		"I can't tell where the Temple of the Moon begins. The quiet starts a few steps before the stone does.",
		"The temple asks nothing of visitors. That's what makes me want to give it something: a lowered head, a slower step, a moment.",
	},
	["dar.subzone_enter.w23.trades.001"] = {
		"pauses by a merchant's scales, carved wood and polished stone weights, and watches a handful of copper weighed as gravely as a verdict.",
		"watches a merchant set a small stone weight on a wooden scale, wait for the beam to settle, and only then name a price.",
		"stops at a stall where nothing is sold by guesswork: every sack goes on the scales, and the merchant watches the beam as if it might lie.",
	},
	["dar.subzone_enter.w23.trades.002"] = {
		"A merchant wraps each purchase in a broad leaf and ties it off with a twist of grass. The buyer walks away holding it like a gift.",
		"Even the parcels are grown here: a leaf folded round the goods, a stem for string. It makes paper seem a little rude.",
		"Nobody hands over goods bare on this terrace. Everything leaves folded in a leaf and knotted, as if a sale were a small courtesy.",
	},
	["dar.subzone_enter.w23.trades.003"] = {
		"Somewhere on this terrace is a better price than the one I'm about to accept.",
		"Tradesmen's Terrace. Where my purse comes to learn humility.",
		"Every stall here is a small, polite ambush.",
	},
	["dar.subzone_enter.w23.trades.004"] = {
		"A Sentinel once told me the kaldorei remember a debt longer than most nations last. On a terrace full of ledgers, that seems worth keeping in mind.",
		"What is a loan to someone who might see it repaid three generations after the borrower is gone? I'd rather owe nothing on this terrace.",
		"Ledgers kept by people who were alive for the War of the Ancients, or whose teachers were. I suspect no account here is ever quite closed.",
	},
	["dar.subzone_enter.w23.trades.005"] = {
		"squeezes past a dwarf and a gnome at the auction house who keep outbidding each other by a single copper, with growing and very quiet fury.",
		"steps around a gnome counting coins into neat stacks on a low wall, lips moving, entirely deaf to the terrace.",
		"hovers at the edge of the crowd by the auction house, where a human reads out prices from a list to a dwarf who keeps shaking his head.",
	},
	["dar.subzone_enter.w23.trades.006"] = {
		"Dwarven ale in a kaldorei stall, Stormwind cloth on a kaldorei rack. The boats at Rut'theran bring half the world up the tree, crate by crate.",
		"Half of what's sold here came up from the boats at Rut'theran: human linen, dwarven tools, gnomish odds and ends. The kaldorei sell it with the faint air of people handling a curiosity.",
		"Not everything here grew on the tree. Human cloth, dwarven iron, a gnomish thing that ticks: the rest of the world comes to market even in Darnassus.",
	},
	["dar.subzone_enter.w23.trades.007"] = {
		"watches a kaldorei merchant count out change twice, slowly, coin by coin, and the buyer accept it without once checking.",
		"lingers while a merchant counts coins back into a waiting palm, each one set down with a tiny click, none of them hurried.",
		"sees a coin dropped on the terrace handed back to its owner by a passing merchant, without fuss, before the owner had noticed it was gone.",
	},
	["dar.subzone_enter.w23.trades.008"] = {
		"Haggling doesn't work here. The merchant names a price once, then waits, and the waiting does all the arguing.",
		"Any counter-offer I made here would meet the same calm look, and I'd end up paying the first price anyway.",
		"Kaldorei merchants don't bargain; they wait. It's the most effective tactic I know, and there's nothing to be done about it.",
	},
	["dar.subzone_enter.w23.trades.009"] = {
		"Every people of the Alliance has a queue or a stall on this terrace. If anyone asks what holds us together, I'll point here: shopping.",
		"Our alliance, seen from the Tradesmen's Terrace: dwarves buying elven leather, elves eyeing gnomish gears, humans asking everyone the price of everything.",
	},
	["dar.subzone_enter.w23.trades.010"] = {
		"passes the bank and sees a banker turn a key in a carved drawer with both hands, the way some people close a book they mean to keep.",
		"glances into the bank in passing: a banker writing in a ledger with the pen held almost upright, adding each line as if carving it.",
		"notices how quiet the bank is: no rattle of coin, only the scratch of a pen and a drawer sliding shut on wooden runners.",
	},
	["dar.subzone_enter.w23.trades.011"] = {
		"Bags full, purse light. Let's see if this terrace can swap them round.",
		"Too much in my bags, too little in my purse. One of those is about to change.",
		"Let's see what the Tradesmen's Terrace will give me for the lot.",
	},
	["dar.subzone_enter.w23.trades.012"] = {
		"Full dark, and the terrace is as busy as ever. Of course: for the kaldorei, this is the sensible hour to buy and sell.",
		"Elsewhere the shutters would be down by now. Here the stalls are open and the merchants look, if anything, more awake under the moon.",
	},
	["dar.subzone_enter.w23.trades.013"] = {
		"drifts past a food stall: pale loaves, a wheel of blue-veined cheese, baskets of fruit so ripe the smell reaches the path first.",
		"slows at a grocer's stall where melons and dark berries are stacked into neat pyramids that nobody, apparently, ever knocks over.",
	},
	["dar.subzone_enter.w23.trades.014"] = {
		"Watching the auctioneer here is like watching a heron fish: perfectly still, then one quick note in the ledger, and some poor bid is swallowed whole.",
		"The auctioneer writes each bid down as if the ink were costly. It probably is. Everything in this city seems to have been grown, gathered, or waited for.",
	},
	["dar.subzone_enter.w23.trades.015"] = {
		"Everyone here trusts the scales and the ledgers and each other. I keep my hood low and my coin ready, and try very hard to look like someone from these parts.",
		"A whole terrace of Alliance coin changing hands, and me in the middle of it with the wrong colors under my cloak. Walk slowly. Buy nothing memorable.",
	},
	["dar.subzone_enter.w23.trades.016"] = {
		"Gold is gold, even up a tree. Let's see who's buying.",
		"Merchants, bankers, auctioneers. Every one of them patient, and every one of them after my coin.",
		"Mind the purse. Darnassus is polite, but it isn't free.",
	},
	["dar.subzone_enter.w23.trades.017"] = {
		"steps aside for a kaldorei carrying a stack of crates higher than her own head, balanced so well that none of them so much as tilts.",
		"makes room on the path for a load of sacks riding on someone's shoulders, set down at a stall with barely a sound and soon lifted elsewhere.",
	},
	["dar.subzone_enter.w23.trades.018"] = {
		"What does a people who have lived for centuries still need to buy? Judging by the queues: thread, fruit, and string for bows.",
		"I'd have guessed a people this old would own everything already. Yet here they are, buying thread and fruit and new soles for old boots, like anyone.",
		"The kaldorei shop like everyone else: they test the fruit, frown at the price, buy it anyway. I find that more comforting than any temple.",
	},
	["dar.subzone_enter.w23.warriors.001"] = {
		"watches a line of Sentinels move through the same drill together, turning and stepping to a count that none of them says aloud.",
		"halts beside a drill: a dozen Sentinels stepping, turning and kneeling as one, with no voice calling the time.",
		"stands aside while a column of Sentinels goes by at a trot, armor barely whispering, and wheels into place on the training ground with no order given.",
	},
	["dar.subzone_enter.w23.warriors.002"] = {
		"Every trainer on this terrace looks at the way I stand before they look at my face. The verdict is in, and I suspect it reads 'slightly crooked'.",
		"One glance from a trainer here and I can feel my posture being corrected from across the terrace.",
		"I straighten up the moment I set foot on this terrace. Nobody asked me to. The place just looks at you that way.",
	},
	["dar.subzone_enter.w23.warriors.003"] = {
		"hears a low, rising hum overhead and looks up in time to see a thrown glaive curve back into a Sentinel's waiting hand.",
		"gives a wide berth to a Sentinel working with a glaive, its edge tracing the same bright circle over and over in the air beside her.",
		"tracks a glaive as it leaves a Sentinel's hand, skims a long arc over the training ground, and returns to her as if on a leash.",
	},
	["dar.subzone_enter.w23.warriors.004"] = {
		"Some of the Sentinels drilling here wear fresh scars. Ashenvale isn't a story to them; it's where they go back to when the drill ends.",
		"This isn't practice for some far-off war. The Warsong are cutting Ashenvale right now, and some of these women will be on that front within the month.",
		"The training here has a hard edge to it. Everyone on this terrace knows someone who never came back from Ashenvale.",
	},
	["dar.subzone_enter.w23.warriors.005"] = {
		"Nobody watch my footwork. It's been a long road.",
		"Warrior's Terrace. Elbows in, chin up, and try not to trip in front of the Sentinels.",
		"Lovely. A whole terrace of people who can hit a target from farther off than I can see it.",
	},
	["dar.subzone_enter.w23.warriors.006"] = {
		"skirts a great cat sprawled across the path beside a hunter mending a bowstring; the cat opens one eye, judges, and closes it.",
		"slows for a bear sitting on its haunches at the edge of the training ground, patiently watching its hunter listen to a trainer.",
		"makes way for an owl riding a hunter's shoulder, which turns its head all the way round to follow {g:him|her} out of sight.",
	},
	["dar.subzone_enter.w23.warriors.007"] = {
		"The rogues train on this terrace too, I'm told. I keep looking for them and finding only shadows that may be just shadows.",
		"There's a corner of the Warrior's Terrace where people only become visible once they've decided to speak. I give it a wide, respectful berth.",
	},
	["dar.subzone_enter.w23.warriors.008"] = {
		"notices the training ground already worn into paths and hollows where feet have turned a thousand times, young as the city is.",
		"looks down at the training floor, scuffed pale in long arcs where a few years of drills have already left their mark.",
		"runs a thumb along a practice post already notched and splintered: a young terrace, an old trade.",
	},
	["dar.subzone_enter.w23.warriors.009"] = {
		"Most training grounds I know sound like a smithy falling downstairs. This one sounds like a bowstring and somebody thinking.",
		"Hardly a shout on the whole terrace. The fighters here save their voices, as if noise were a kind of wasted effort.",
		"Every drill here ends in silence instead of a cheer. I find myself wanting to applaud and not quite daring.",
	},
	["dar.subzone_enter.w23.warriors.010"] = {
		"passes an officer walking the line of a drill, tugging a strap here, tilting a helm there, saying nothing to anyone who has it right.",
		"sees a Sentinel officer stop before one of her charges, adjust a buckle with two fingers, and move on without a word or a frown.",
		"watches an officer halt a drill with one raised hand; the whole line freezes mid-step and waits, perfectly balanced, for the hand to drop.",
	},
	["dar.subzone_enter.w23.warriors.011"] = {
		"Nobody in this city hurries, except here. Good to know where they keep it.",
		"So this is where Darnassus hides its hurry.",
	},
	["dar.subzone_enter.w23.warriors.012"] = {
		"Our Sentinels drill as though Ashenvale were the next terrace over. For them, it nearly is.",
		"Watching the Sentinels train, I think of how long they kept watch alone while the druids slept. We owe them more than this terrace can hold.",
	},
	["dar.subzone_enter.w23.warriors.013"] = {
		"A dwarf is training beside the Sentinels, stamping twice as hard and moving half as quietly. Nobody here seems to mind. That's an alliance for you.",
		"Humans and dwarves sparring on a kaldorei terrace, and kaldorei trainers correcting them without a trace of scorn. Not so long ago, none of us would have believed it.",
	},
	["dar.subzone_enter.w23.warriors.014"] = {
		"pauses by a rack of practice staves worn dark at the grip, each one hung back in exactly its own place when a drill ends.",
		"comes upon a rack of practice staves, every grip darkened by hands, every one returned to its own hook with a care that looks almost like courtesy.",
		"notes the targets at the far end of the training ground, stitched and restitched by someone who evidently refuses to waste a good target.",
	},
	["dar.subzone_enter.w23.warriors.015"] = {
		"I could learn a great deal just by standing at the edge of this terrace and watching where the Sentinels put their weight.",
		"The best lesson on the Warrior's Terrace is free: watch the feet, never the hands.",
		"Everyone here moves as if the ground might shift. Considering it's a tree, maybe that's just good sense.",
	},
	["dar.subzone_enter.w23.warriors.016"] = {
		"passes a Sentinel sitting apart from the drill, binding a sore wrist with a strip of cloth and her teeth, eyes never leaving the practice.",
		"notices a Sentinel sitting out the drill on a low step, flexing a bruised hand and watching the others with plain impatience to rejoin them.",
		"slows beside a hunter rubbing liniment into a sore shoulder, wincing in perfect silence, as befits the Warrior's Terrace.",
	},
	["dar.subzone_enter.w23.warriors.017"] = {
		"A Sentinel's great cat lies by the training ground with its chin on its paws, following the drill with the bored expertise of a veteran.",
		"Even the Sentinels' great cats seem to be taking notes from the side of the training ground. One of them just yawned at my stance.",
	},
	["dar.subzone_enter.w23.warriors.018"] = {
		"If I'm going to be humbled on this terrace, it might as well be by experts.",
		"All right. Shoulders back. The Sentinels are watching, and so is my pride.",
	},
	["dar.weather_change.w23.fairsky.001"] = {
		"squints up as the cloud over the crown frays apart, and every gap between the leaves fills with clean, open sky.",
		"notices the gaps in the canopy sharpen as the clouds above break up and drift off toward the sea.",
		"glances up at a sudden crispness overhead: the clouds have torn open above Teldrassil, and the sky shows through the leaves in clean cut shapes.",
	},
	["dar.weather_change.w23.fairsky.002"] = {
		"The clouds have gone, but the tree hasn't heard. Water keeps slipping off the leaves for a long while yet, as if the crown were finishing a sentence.",
		"Clear above, and still dripping below. Up here the weather changes first at the top, and the leaves catch up when they feel like it.",
		"The sky opened some time ago. Teldrassil is still shaking the last of the damp off itself, leaf by leaf, in no hurry at all.",
	},
	["dar.weather_change.w23.fairsky.003"] = {
		"Clouds gone. I'd have missed it entirely if an elf hadn't looked up and smiled.",
		"Clear sky up there, so I'm told. From under these leaves I'll take the tree's word for it.",
		"The weather's turned fair. Somewhere above all this foliage, presumably.",
	},
	["dar.weather_change.w23.fairsky.004"] = {
		"watches a crafter fold back the oiled cloth over a bench of work now that the clouds have gone, smoothing it flat with long, patient strokes.",
		"sees an elf peel a waxed cover off a table of goods as the sky clears, shake it once, and fold it into a neat square.",
		"notices the covers coming off the stalls and workbenches one by one as the weather lifts, as if the city were opening its hands.",
	},
	["dar.weather_change.w23.fairsky.005"] = {
		"With the clouds gone, one gap in the leaves shows how much empty sky hangs over this city. It is a long way up, and then a long way further.",
		"A cleared sky makes the height plain. Through a break in the canopy there's nothing at all above, and the nothing goes on for a long while.",
		"Nothing between the leaves now but open sky, and so much of it. Under the canopy it's easy to forget how close this city sits to the top of everything.",
	},
	["dar.weather_change.w23.fairsky.006"] = {
		"hears the small birds of the canopy start up as the clouds clear, a dozen thin voices testing the air at once.",
		"catches a flutter in the boughs overhead: the birds that went quiet under the clouds are moving about, shaking out their wings.",
		"pauses as something winged drops from a high branch, circles once through the cleared air, and settles as if satisfied.",
	},
	["dar.weather_change.w23.fairsky.007"] = {
		"I pushed my hood back as the sky cleared, and promptly caught a cold drop down the collar from a leaf that hadn't been told.",
		"Hood down, clouds gone, and the tree saved one last drop for the back of my neck. A city with a sense of humor.",
		"The moment the sky cleared I lowered my hood. The canopy noticed, aimed, and did not miss.",
	},
	["dar.weather_change.w23.fairsky.008"] = {
		"spots a priestess of Elune stop on the path as the clouds part above the crown, tilt her face upward, and murmur something too low to catch.",
		"notices a pair of priestesses pause and look skyward as the cover breaks, as though checking that something they care for is still where they left it.",
		"follows with {g:his|her} eyes an old priestess who lifts one open hand toward the clearing sky, then lowers it and walks on as if nothing had happened.",
	},
	["dar.weather_change.w23.fairsky.009"] = {
		"The pale stone of the paths dries from the edges inward now that the clouds are gone, dark patches shrinking like spilled ink drawn back into the well.",
		"Clearing weather, and the white stone of the terraces is drying in islands. In a little while there'll be no sign anything was ever damp.",
		"Overhead the clouds have moved on, and the stone underfoot gives up its damp in slow pale blotches. Darnassus tidies itself without anyone lifting a finger.",
	},
	["dar.weather_change.w23.fairsky.010"] = {
		"There. The clouds have let go of the crown.",
		"Fair weather up top. Good. The paths will be dry by the time I've crossed the city.",
		"Clear skies over Teldrassil. Even the tree looks pleased.",
	},
	["dar.weather_change.w23.fairsky.011"] = {
		"The clouds break and the sun gets behind the big leaves overhead. Lit from above like that, each one shows its veins, green on green, like a map of rivers.",
		"Sunlight on the far side of the canopy turns the leaves to stained glass, green and gold, every vein drawn plain as ink.",
		"Bright and open above the crown. The leaves glow from behind, and their shadows on the path have edges again.",
	},
	["dar.weather_change.w23.fairsky.012"] = {
		"stops where the clouds have broken over the crown, and finds the shadows of the leaves printed sharp across the path, edged in silver by the moon.",
		"looks on as the clouds slide off the moon above the canopy, and the whole terrace suddenly gains shadows it did not have a moment ago.",
	},
	["dar.weather_change.w23.fairsky.013"] = {
		"An elf on the bridge folded her cloak away a good while before the clouds broke. Either she reads the sky through all those leaves, or the tree tells her.",
		"Someone here knew the weather would clear. I saw a druid set a bowl of seeds out on a wall long before the first gap opened overhead.",
		"The kaldorei were ready for the clear sky before it came. I've stopped asking how; the answers here are always longer than the question.",
	},
	["dar.weather_change.w23.fairsky.014"] = {
		"Sky's clear. Somebody tell the moss; it's still acting soaked.",
		"Fair weather, at last. My cloak and I are both drying out at a dignified kaldorei pace.",
	},
	["dar.weather_change.w23.mist.001"] = {
		"watches the mist rise in slow coils from somewhere far below the city, threading between the boughs until the nearest branches end in white.",
		"sees pale wisps of fog drift up between the terraces, cool and slow, smelling faintly of the sea that sent them.",
		"stands at the edge of a terrace as the fog comes up from below, and the great limbs of the tree fade one by one into it like boats putting out from a shore.",
	},
	["dar.weather_change.w23.mist.002"] = {
		"The mist settles on everything in fine beads: my sleeves, the railings, a spider's web strung between two leaves like a jeweler's display.",
		"Fog doesn't fall, it just arrives. One moment my cloak is dry, the next every thread of it is strung with tiny drops.",
		"There's a web on the rail beside me, and the fog has hung a bead on every strand. Nobody here would dream of brushing it away.",
	},
	["dar.weather_change.w23.mist.003"] = {
		"Fog. The Sentinels will see me long before I see them. Not that it's ever any different.",
		"Mist coming in. Speak up, whoever you are; all I can make out is your boots.",
	},
	["dar.weather_change.w23.mist.004"] = {
		"watches the fog on the lake take on the first color of dawn, a faint rose that seems to come from inside it rather than from the sky.",
		"sees the dawn arrive as a slow brightening of the mist, with no single point of light anywhere, as if the whole fog were waking.",
		"stands in a dawn fog so soft that the shores of the lake, the paths and the pale halls all blur into one gentle glow.",
	},
	["dar.weather_change.w23.mist.005"] = {
		"With the fog below and around, the city feels cut loose, a raft of moss and pale stone adrift on cloud. I half expect to feel it rock.",
		"The mist has hidden everything under the terraces. For all I can see, Darnassus is floating, and nothing at all holds it up.",
		"I know the trunk is down there, and the roots, and the sea. In this fog I'd need someone to remind me.",
	},
	["dar.weather_change.w23.mist.006"] = {
		"hears two Sentinels somewhere in the fog trade a short, low call, one on each side of the path, and then nothing more.",
		"passes a Sentinel standing at the edge of the mist with her head tilted, listening rather than looking, her glaive grounded beside her.",
	},
	["dar.weather_change.w23.shower.001"] = {
		"hears the rain begin long before it arrives: a soft hiss spreading across the crown far above, while the path below stays pale a while longer.",
		"lifts {g:his|her} head at a rustle passing over the canopy like a crowd murmuring; the rain has reached the top of the tree, and is taking its time with the rest.",
		"catches the first sound of rain up in the leaves and counts, idly, how long the first drop takes to find the stone at {g:his|her} feet.",
	},
	["dar.weather_change.w23.shower.002"] = {
		"Rain on a city that's already half water. The streams get a little louder, and that's about all anyone notices.",
		"It's raining, I think. Hard to say in Darnassus; everything was already running and trickling and splashing before it started.",
		"Rain, in a place built around pools and falls. It's like pouring a cup into the lake and calling it news.",
	},
	["dar.weather_change.w23.shower.003"] = {
		"sees a great cat lying by the path flatten its ears at the first drops of rain, rise with enormous dignity, and relocate under an arch.",
		"watches a Sentinel's big cat shake a spray of rain off its coat and glare at the sky as if it had been personally insulted.",
		"notices a striped cat curled on a wall tuck its nose under its tail as the rain comes on, and refuse to move one inch more than that.",
	},
	["dar.weather_change.w23.shower.004"] = {
		"The moss on the walls darkens as the rain soaks in, and for once it looks less like decoration and more like something alive and thirsty.",
		"Rain, and the flowers along the path close up one after another, folding their petals in as tidily as a merchant shutting a stall.",
		"The rain is good for something here: the moss swells, the ferns lift, and the whole green edge of the path seems to lean toward the sky.",
	},
	["dar.weather_change.w23.shower.005"] = {
		"Rain inside a tree. I'm not sure that's how it's supposed to work.",
		"Of course it rains up here. A city this high, I'd hoped it sat above the weather.",
		"Raining in the crown of a tree. Somewhere a dwarf is laughing at me.",
	},
	["dar.weather_change.w23.shower.006"] = {
		"comes upon a priestess setting a shallow silver bowl on a wall to catch the rain, then sitting beside it with her hands folded, waiting for it to fill.",
		"passes a priestess standing bareheaded in the rain with her eyes closed, letting it run down her face as though it were something she had asked for.",
		"lingers as two novices of the temple carry a covered basin out into the rain and lift the lid, without a word between them.",
	},
	["dar.weather_change.w23.shower.007"] = {
		"Odd thing: the rain makes this city easier for me. Under its patter my boots and my clumsy voice don't stand out so much.",
		"With rain drumming on everything I can finally walk at my own pace without feeling every elf on the path hear it.",
		"The rain is the first noise in Darnassus louder than I am. I owe it one.",
	},
	["dar.weather_change.w23.shower.008"] = {
		"notices the rain running off a curved roof into a carved stone channel shaped like the spine of a leaf, and from there, neatly, into the nearest stream.",
		"follows a trickle of rainwater along the edge of the path and finds it gathered into a little runnel cut in the stone, as if the city had always expected it.",
		"sees the rain sheet off the eaves in thin, even curtains, and realizes the roofs were shaped to do exactly this.",
	},
	["dar.weather_change.w23.shower.009"] = {
		"Every drop that misses me has a long way still to go: down through leaf after leaf, along the trunk, all the way to the sea. I don't envy it.",
		"Rain up here is only the start of its journey. Somewhere far below, it's still falling past the bark toward the waves.",
		"I think of the rain going on past this city, down a trunk too tall to picture, and landing at last in the sea it came from.",
	},
	["dar.weather_change.w23.shower.010"] = {
		"Room under this arch for one more, if you don't mind the drips.",
		"Come in out of the rain. Well, out of most of it.",
		"Plenty of leaf to go round. Get under before you're soaked.",
	},
	["dar.weather_change.w23.shower.011"] = {
		"sees a gnome trot along the path under an enormous leaf held up like a parasol, quite dry and very proud of it.",
		"spots a dwarf under a dripping arch muttering at the rain in his own tongue, while a kaldorei beside him seems to be listening to it with pleasure.",
		"notices a human visitor wringing out a sleeve by the water's edge, and the elf beside him politely pretending not to see.",
	},
	["dar.weather_change.w23.shower.012"] = {
		"In the rain the lamps along the path each wear a little halo, violet and soft, and the drops falling through it look like sparks that forgot to burn.",
		"Rain blurs the city's lamps into soft violet rings. Walking between them is like walking through someone else's dream.",
		"Each lamp I pass has rain falling through its glow, a thin bright veil that moves when nothing else does.",
	},
	["dar.weather_change.w23.tempest.001"] = {
		"looks up as lightning flares above the crown, and for one white instant every leaf overhead is printed black against the sky.",
		"sees the canopy lit from above by a flash, its whole vast lattice of boughs standing out sharp, then gone again into the dark.",
		"flinches at a flash high over the tree; in that blink the boughs overhead show every knot and fork, like a drawing made in a hurry.",
	},
	["dar.weather_change.w23.tempest.002"] = {
		"A thunderstorm, and I'm standing in the top of the tallest tree in the world. Every lesson I ever learned about lightning is shouting at me at once.",
		"Lightning likes tall things. I try not to think about how tall the thing under my boots is.",
		"Thunder overhead, and the kaldorei look calm. Either the druids have an arrangement with the sky, or nobody here has done the arithmetic.",
	},
	["dar.weather_change.w23.tempest.003"] = {
		"That one shook the bridge. Lovely. I'll be over here, near something short.",
		"Thunder up there. I'm told the tree's been struck before and didn't notice. I'd notice.",
	},
	["dar.weather_change.w23.tempest.004"] = {
		"notices that the hippogryphs that wheel above the canopy have all vanished as the thunder rolls in, and the sky over the leaves is left to the storm.",
		"sees an owl drop from an open branch into a hollow in the bark at the first long growl of thunder, and stare out from it with great disapproval.",
		"observes a pair of moths, driven down by the storm overhead, settle on a lamp and cling to it through every roll of thunder.",
	},
	["dar.weather_change.w23.tempest.005"] = {
		"A druid beside me listened to the thunder with her eyes shut, the way a healer listens at a sickbed. When I asked, she only said the tree was young to be weathering storms.",
		"Some druids here say a storm is how the sky tests a new tree. They don't say what happens to the ones that fail.",
		"The elders of the Enclave, I'm told, count the thunder over Teldrassil the way others count the days of a fever. Nobody tells me what the count is for.",
	},
	["dar.weather_change.w23.tempest.006"] = {
		"marks a Sentinel stopping mid-stride at a crack of thunder, glancing once at the sky like an officer noting a late arrival, and walking on.",
		"spots the Sentinels along the terrace lift their heads together at a long peal of thunder, then lower them together, as if they had agreed it was worth no more.",
	},
]==])
